  Modelica.Blocks.Logical.Or Or1 ;
  Modelica.Blocks.Logical.Pre Pre1 ;
equation
  connect(table2.y, Not1.u) ;
  connect(And1.y, Or1.u2) ;
  connect(table1.y, Or1.u1) ;
  connect(Not1.y, And1.u1) ;
  connect(Pre1.y, And1.u2) ;
  connect(Or1.y, Pre1.u) ;

end LogicalNetwork1;

