  parameter Real y_max = 3 "Maximum value of band for random values";
  inner Modelica.Blocks.Noise.GlobalSeed globalSeed(useAutomaticSeed = false) ;
  output Real uniformNoise_y = uniformNoise.y;
  output Real truncatedNormalNoise_y = truncatedNormalNoise.y;
  Integer n = if time < 0.5 then 12 else 2;
  Modelica.Blocks.Noise.UniformNoise uniformNoise(useAutomaticLocalSeed = false, fixedLocalSeed = 1, samplePeriod = samplePeriod, y_min = y_min, y_max = y_max) ;
  Modelica.Blocks.Noise.TruncatedNormalNoise truncatedNormalNoise(useAutomaticLocalSeed = false, fixedLocalSeed = 1, samplePeriod = samplePeriod, y_min = y_min, y_max = y_max) ;

end Distributions;

modelica://Modelica.Blocks/UniformNoiseP:
Modelica.Blocks: UniformNoiseProperties (model)

This example demonstrates statistical properties of the  Blocks.Noise.UniformNoise block using a uniform random number distribution. Block "noise" defines a band of 0 .. 6 and from the generated noise the mean and the variance is computed with blocks of package Blocks.Math . Simulation results are shown in the next diagram:          
 The mean value of a uniform noise in the range 0 .. 6 is 3 and its variance is 3 as well. The simulation results above show good agreement (after a short initial phase). This demonstrates that the random number generator and the mapping to a uniform distribution have good statistical properties.

Code:
model UniformNoiseProperties "Demonstrates the computation of properties for uniformly distributed noise"
  extends Modelica.Icons.Example;
  parameter Real y_min = 0 "Minimum value of band";
  parameter Real y_max = 6 "Maximum value of band";
  parameter Real pMean = (y_min + y_max) / 2 "Theoretical mean value of uniform distribution";
  parameter Real var = (y_max - y_min) ^ 2 / 12 "Theoretical variance of uniform distribution";
  parameter Real std = sqrt(var) "Theoretical standard deviation of uniform distribution";
  inner Modelica.Blocks.Noise.GlobalSeed globalSeed ;
  output Real meanError_y = meanError.y;
  output Real sigmaError_y = sigmaError.y;
  Modelica.Blocks.Noise.UniformNoise noise(samplePeriod = 0.001, y_min = y_min, y_max = y_max, useAutomaticLocalSeed = false) ;
  Modelica.Blocks.Math.ContinuousMean mean ;
  Modelica.Blocks.Math.Variance variance ;
  Modelica.Blocks.Math.MultiProduct theoreticalVariance(nu = 2) ;
  Modelica.Blocks.Math.Feedback meanError ;
  Modelica.Blocks.Sources.Constant theoreticalMean(k = pMean) ;
  Modelica.Blocks.Math.Feedback varianceError ;
  Modelica.Blocks.Sources.Constant theoreticalSigma(k = std) ;
  Modelica.Blocks.Math.StandardDeviation standardDeviation ;
  Modelica.Blocks.Math.Feedback sigmaError ;
equation
  connect(noise.y, mean.u) ;
  connect(noise.y, variance.u) ;
  connect(mean.y, meanError.u1) ;
  connect(theoreticalMean.y, meanError.u2) ;
  connect(theoreticalSigma.y, theoreticalVariance.u[1]) ;
  connect(theoreticalSigma.y, theoreticalVariance.u[2]) ;
  connect(variance.y, varianceError.u1) ;
  connect(theoreticalVariance.y, varianceError.u2) ;
  connect(noise.y, standardDeviation.u) ;
  connect(standardDeviation.y, sigmaError.u1) ;
  connect(theoreticalSigma.y, sigmaError.u2) ;

end UniformNoiseProperties;

