  end when;

end ImpureRandom;

modelica://Modelica.Blocks/MotorWithCurr:
Modelica.Blocks: MotorWithCurrentControl (model)

A synchronous machine with permanent magnets, current controller and measurement noise of ±0.01 rad accelerates a quadratic speed dependent load from standstill. The rms values of d- and q-current in rotor fixed coordinate system are converted to three-phase currents, and fed to the machine. The result shows that the torque is influenced by the q-current, whereas the stator voltage is influenced by the d-current.   
 Default machine parameters of model  SM_PermanentMagnet  are used.   
 This motor is used in the  Examples.Noise.ActuatorWithNoise  actuator example

Code:
model MotorWithCurrentControl "Synchronous machine with current controller and measurement noise"
  extends Modelica.Electrical.Machines.Icons.TransientMachine;
  constant Integer m = 3 "Number of phases";
  parameter Modelica.Units.SI.Voltage VNominal = 100 "Nominal RMS voltage per phase";
  parameter Modelica.Units.SI.Frequency fNominal = 50 "Nominal frequency";
  parameter Modelica.Units.SI.Frequency f = 50 "Actual frequency";
  parameter Modelica.Units.SI.Time tRamp = 1 "Frequency ramp";
  parameter Modelica.Units.SI.Torque TLoad = 181.4 "Nominal load torque";
  parameter Modelica.Units.SI.Time tStep = 1.2 "Time of load torque step";
  parameter Modelica.Units.SI.Inertia JLoad = 0.29 "Load's moment of inertia";
  Modelica.Electrical.Machines.BasicMachines.SynchronousMachines.SM_PermanentMagnet smpm(p = smpmData.p, fsNominal = smpmData.fsNominal, Rs = smpmData.Rs, TsRef = smpmData.TsRef, Lszero = smpmData.Lszero, Lssigma = smpmData.Lssigma, Jr = smpmData.Jr, Js = smpmData.Js, frictionParameters = smpmData.frictionParameters, wMechanical(fixed = true), statorCoreParameters = smpmData.statorCoreParameters, strayLoadParameters = smpmData.strayLoadParameters, VsOpenCircuit = smpmData.VsOpenCircuit, Lmd = smpmData.Lmd, Lmq = smpmData.Lmq, useDamperCage = smpmData.useDamperCage, Lrsigmad = smpmData.Lrsigmad, Lrsigmaq = smpmData.Lrsigmaq, Rrd = smpmData.Rrd, Rrq = smpmData.Rrq, TrRef = smpmData.TrRef, permanentMagnetLossParameters = smpmData.permanentMagnetLossParameters, phiMechanical(fixed = true), TsOperational = 293.15, alpha20s = smpmData.alpha20s, TrOperational = 293.15, alpha20r = smpmData.alpha20r) ;
  Modelica.Electrical.Polyphase.Sources.SignalCurrent signalCurrent(final m = m) ;
  Modelica.Electrical.Polyphase.Basic.Star star(final m = m) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Electrical.Machines.Utilities.DQToThreePhase dqToThreePhase(p = smpm.p) ;
  Modelica.Electrical.Polyphase.Basic.Star starM(final m = m) ;
  Modelica.Electrical.Analog.Basic.Ground groundM ;
  Modelica.Electrical.Machines.Utilities.TerminalBox terminalBox(terminalConnection = "Y") ;
  Modelica.Electrical.Machines.Sensors.RotorDisplacementAngle rotorDisplacementAngle(p = smpm.p) ;
  Modelica.Mechanics.Rotational.Sensors.AngleSensor angleSensor ;
  Modelica.Mechanics.Rotational.Sensors.TorqueSensor torqueSensor ;
  Modelica.Mechanics.Rotational.Sensors.SpeedSensor speedSensor ;
  Modelica.Electrical.Machines.Sensors.VoltageQuasiRMSSensor voltageQuasiRMSSensor ;
  Modelica.Electrical.Machines.Sensors.CurrentQuasiRMSSensor currentQuasiRMSSensor ;
  Modelica.Mechanics.Rotational.Components.Inertia inertiaLoad(J = 0.29) ;
  parameter Modelica.Electrical.Machines.Utilities.ParameterRecords.SM_PermanentMagnetData smpmData(useDamperCage = false) "Data for motor" ;
  Modelica.Blocks.Sources.Constant id(k = 0) ;
  Modelica.Blocks.Interfaces.RealInput iq_rms1 ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_b flange "Right flange of shaft" ;
  Modelica.Blocks.Interfaces.RealOutput phi(unit = "rad") "Absolute angle of flange as output signal" ;
  output Real phi_motor(unit = "rad", displayUnit = "deg") = angleSensor.phi "Rotational position";
  output Real w(unit = "rad/s") = speedSensor.w "Rotational speed";
  Modelica.Blocks.Math.Add addNoise ;
  Modelica.Blocks.Noise.UniformNoise uniformNoise(samplePeriod = 1 / 200, y_min = -0.01, y_max = 0.01) ;
equation
  connect(star.pin_n, ground.p) ;
  connect(rotorDisplacementAngle.plug_n, smpm.plug_sn) ;
  connect(rotorDisplacementAngle.plug_p, smpm.plug_sp) ;
  connect(terminalBox.plug_sn, smpm.plug_sn) ;
  connect(terminalBox.plug_sp, smpm.plug_sp) ;
  connect(smpm.flange, rotorDisplacementAngle.flange) ;
  connect(signalCurrent.plug_p, star.plug_p) ;
  connect(angleSensor.flange, rotorDisplacementAngle.flange) ;
  connect(angleSensor.phi, dqToThreePhase.phi) ;
  connect(groundM.p, terminalBox.starpoint) ;
  connect(smpm.flange, torqueSensor.flange_a) ;
  connect(voltageQuasiRMSSensor.plug_p, terminalBox.plugSupply) ;
  connect(starM.plug_p, voltageQuasiRMSSensor.plug_n) ;
  connect(starM.pin_n, groundM.p) ;
  connect(dqToThreePhase.y, signalCurrent.i) ;
  connect(speedSensor.flange, smpm.flange) ;
  connect(torqueSensor.flange_b, inertiaLoad.flange_a) ;
  connect(signalCurrent.plug_n, currentQuasiRMSSensor.plug_p) ;
  connect(currentQuasiRMSSensor.plug_n, voltageQuasiRMSSensor.plug_p) ;
  connect(inertiaLoad.flange_b, flange) ;
  connect(angleSensor.phi, addNoise.u2) ;
  connect(addNoise.y, phi) ;
  connect(uniformNoise.y, addNoise.u1) ;
  connect(id.y, dqToThreePhase.d) ;
  connect(iq_rms1, dqToThreePhase.q) ;

end MotorWithCurrentControl;

modelica://Modelica.Blocks/Controller:
Modelica.Blocks: Controller (model)

A simple position controller for a drive system. This controller is used in the  Examples.Noise.ActuatorWithNoise  actuator example

Code:
model Controller "Simple position controller for actuator"
  extends Modelica.Blocks.Icons.Block;
  Modelica.Blocks.Continuous.PI speed_PI(k = 10, T = 5e-2, initType = Modelica.Blocks.Types.Init.InitialOutput) ;
  Modelica.Blocks.Math.Feedback speedFeedback ;
  Modelica.Blocks.Continuous.Derivative positionToSpeed(initType = Modelica.Blocks.Types.Init.InitialOutput, T = 0.01) ;
  Modelica.Blocks.Interfaces.RealInput positionMeasured "Position signal of motor" ;
  Modelica.Blocks.Interfaces.RealInput positionReference "Reference position" ;
  Modelica.Blocks.Interfaces.RealOutput y1 "Connector of Real output signal" ;
  Modelica.Blocks.Continuous.PI position_PI(T = 5e-1, k = 3, initType = Modelica.Blocks.Types.Init.InitialState) ;
  Modelica.Blocks.Math.Feedback positionFeedback ;
  Modelica.Blocks.Continuous.FirstOrder busdelay(T = 1e-3, initType = Modelica.Blocks.Types.Init.InitialOutput) ;
equation
  connect(speedFeedback.y, speed_PI.u) ;
  connect(positionFeedback.u2, positionToSpeed.u) ;
  connect(positionReference, positionFeedback.u1) ;
  connect(positionFeedback.y, position_PI.u) ;
  connect(position_PI.y, speedFeedback.u1) ;
  connect(speed_PI.y, busdelay.u) ;
  connect(y1, busdelay.y) ;
  connect(positionMeasured, positionToSpeed.u) ;
  connect(positionToSpeed.y, speedFeedback.u2) ;

end Controller;

