  extends Modelica.Blocks.Interfaces.PartialRealMISO;
  parameter Real k[nu] = fill(1, nu) "Input gains";
equation
  if size(u, 1) > 0 then
    y = k * u;
  else
    y = 0;
  end if;

end MultiSum;

