  y = offset + (if time < startTime then 0 else amplitude * Modelica.Math.exp(-(time - startTime) * damping) * Modelica.Math.sin(2 * pi * f * (time - startTime) + phase));

end ExpSine;

modelica://Modelica.Blocks/Exponentials:
Modelica.Blocks: Exponentials (block)

The Real output y is a rising exponential followed by a falling exponential signal:

Code:
block Exponentials "Generate a rising and falling exponential signal"
  parameter Real outMax = 1 "Height of output for infinite riseTime" ;
  parameter Modelica.Units.SI.Time riseTime(min = 0, start = 0.5) "Rise time";
  parameter Modelica.Units.SI.Time riseTimeConst(min = Modelica.Constants.small) = 0.1 "Rise time constant; rising is defined as outMax*(1-exp(-riseTime/riseTimeConst))";
  parameter Modelica.Units.SI.Time fallTimeConst(min = Modelica.Constants.small) = riseTimeConst "Fall time constant";
  extends Modelica.Blocks.Interfaces.SignalSource;
protected
  Real y_riseTime;
equation
  y_riseTime = outMax * (1 - Modelica.Math.exp(-riseTime / riseTimeConst));
  y = offset + (if time < startTime then 0 else if time < startTime + riseTime then outMax * (1 - Modelica.Math.exp(-(time - startTime) / riseTimeConst)) else y_riseTime * Modelica.Math.exp(-(time - startTime - riseTime) / fallTimeConst));

end Exponentials;

modelica://Modelica.Blocks/Pulse:
Modelica.Blocks: Pulse (block)

The Real output y is a pulse signal:

Code:
block Pulse "Generate pulse signal of type Real"
  parameter Real amplitude = 1 "Amplitude of pulse" ;
  parameter Real width(final min = Modelica.Constants.small, final max = 100) = 50 "Width of pulse in % of period";
  parameter Modelica.Units.SI.Time period(final min = Modelica.Constants.small, start = 1) "Time for one period";
  parameter Integer nperiod = -1 "Number of periods (< 0 means infinite number of periods)";
  extends Modelica.Blocks.Interfaces.SignalSource;
protected
  Modelica.Units.SI.Time T_width = period * width / 100;
  Modelica.Units.SI.Time T_start "Start time of current period";
  Integer count "Period count";
initial algorithm
  count := integer((time - startTime) / period);
  T_start := startTime + count * period;
equation
  when integer((time - startTime) / period) > pre(count) then
    count = pre(count) + 1;
    T_start = time;
  end when;
  y = offset + (if time < startTime or nperiod == 0 or nperiod > 0 and count >= nperiod then 0 else if time < T_start + T_width then amplitude else 0);

end Pulse;

