block IntegerTable "Generate an Integer output signal based on a table matrix with [time, yi] values"
  parameter Real table[:, 2] = fill(0, 0, 2) "Table matrix (first column: time; second column: y)" ;
  parameter Modelica.Blocks.Types.Extrapolation extrapolation = Modelica.Blocks.Types.Extrapolation.HoldLastPoint "Extrapolation of data outside the definition range" ;
  parameter Modelica.Units.SI.Time startTime = -Modelica.Constants.inf "Output = 0 for time < startTime" ;
  parameter Modelica.Units.SI.Time shiftTime = 0 "Shift time of first table column" ;
  extends Modelica.Blocks.Interfaces.IntegerSO;
  Modelica.Blocks.Sources.CombiTimeTable combiTimeTable(final table = table, final smoothness = Modelica.Blocks.Types.Smoothness.ConstantSegments, final columns = {2}, final extrapolation = extrapolation, final startTime = startTime, final shiftTime = shiftTime) ;
  Modelica.Blocks.Math.RealToInteger realToInteger ;
protected
  function isValidTable "Check if table is valid"
  extends Modelica.Icons.Function;
  input Real table[:, 2] "Table matrix";
  protected
    Modelica.Units.SI.Time t_last;
  Integer n = size(table, 1) "Number of table points";
  algorithm
  if n > 0 then
    // Check whether time values are strict monotonically increasing
    t_last := table[1, 1];
    for i in 2:n loop
      assert(table[i, 1] > t_last, "Time values of table not strict monotonically increasing: table[" + String(i - 1) + ",1] = " + String(table[i - 1, 1]) + "table[" + String(i) + ",1] = " + String(table[i, 1]));
    end for;
