block TorqueGeneration "Torque generation"
  extends Modelica.Blocks.Icons.Block;
  parameter Real AFR = 14.6 "Air-fuel ratio";
  parameter Real sigma = 15.0 "Spark advance, BTDC";
  Modelica.Blocks.Interfaces.RealInput m_a(unit = "g") "Mass of air charge in cylinder (delayed of 180deg crankshaft rotation) (g)" ;
