modelica://Modelica.Clocked/RotationalCl:
Modelica.Clocked: RotationalClock (block)

For a simple example cf. the  rotational sampling example .

Code:
block RotationalClock "Event clock generating a clock tick each time an observed input angle changed for a rotational-interval given as variable input"
  extends Modelica.Clocked.ClockSignals.Clocks.Rotational.PartialRotationalClock;
  Modelica.Blocks.Interfaces.RealInput trigger_interval(unit = "rad") "Rotational-interval the input angle must be changed to trigger the next clock tick" ;
  Modelica.Clocked.ClockSignals.Clocks.EventClock y_clock(useSolver = useSolver, solverMethod = solverMethod) ;
  Modelica.Clocked.RealSignals.Sampler.SampleClocked update_offset ;
  Modelica.Clocked.RealSignals.Sampler.Hold angular_offset ;
  Modelica.Blocks.Math.Add sub(k2 = -1) ;
  Modelica.Blocks.Logical.Less less ;
  Modelica.Blocks.Math.Abs abs2 ;
  Modelica.Blocks.Math.Abs abs1 ;
  Modelica.Blocks.Math.Sign direction_sign(generateEvent = false) ;
  Modelica.Blocks.Math.RealToInteger cast ;
  Modelica.Clocked.IntegerSignals.NonPeriodic.IntegerChange changed ;
  Modelica.Clocked.RealSignals.Sampler.SampleClocked update_direction ;
algorithm
  assert(trigger_interval > 0 or trigger_interval < 0, "The rotational-interval of rotational clocks must be non-zero.");
equation
  connect(angle, update_offset.u) ;
  connect(y_clock.y, update_offset.clock) ;
  connect(update_offset.y, angular_offset.u) ;
  connect(angular_offset.y, sub.u2) ;
  connect(less.y, y_clock.u) ;
  connect(y_clock.y, y) ;
  connect(sub.y, abs1.u) ;
  connect(angle, sub.u1) ;
  connect(trigger_interval, abs2.u) ;
  connect(abs1.y, less.u2) ;
  connect(abs2.y, less.u1) ;
  connect(direction_sign.y, cast.u) ;
  connect(cast.y, changed.u) ;
  connect(y_clock.y, update_direction.clock) ;
  connect(update_direction.y, direction_sign.u) ;
  connect(sub.y, update_direction.u) ;
  connect(changed.y, direction_changed) ;
  connect(cast.y, direction) ;

end RotationalClock;

