modelica://Modelica.Clocked/PartialLogic:
Modelica.Clocked: PartialLogicalClock (block)

Code:
partial block PartialLogicalClock "Logical clock combining arbitrary many input clock signals according to a replaceable logical combinator"
  extends Modelica.Clocked.ClockSignals.Interfaces.PartialClock;
  parameter Integer nu = 2 "Number of input connections.";
  Modelica.Clocked.ClockSignals.Interfaces.ClockVectorInput u[nu] "Vector of Clock input signals." ;
  replaceable Modelica.Blocks.Interfaces.PartialBooleanMISO combinator constrainedby Modelica.Blocks.Interfaces.PartialBooleanMISO(nu = nu) "Replaceable logical combinator applied on vector of Clock input signals.
     Important: Must not be any kind of negation since such would result in
     infinite many ticks for an infinitesimal short time period." ;
  Modelica.Clocked.ClockSignals.Clocks.EventClock clock ;
  // Array of input trackers:
  Modelica.Clocked.BooleanSignals.NonPeriodic.ClockToBoolean input_ticked[nu] ;
  Modelica.Blocks.Logical.And forbidden_state[nu] ;
  Modelica.Blocks.Sources.BooleanConstant S_false[nu](each k = false) ;
  Modelica.Blocks.Logical.LogicalSwitch suppress_S[nu] ;
  Modelica.Blocks.Logical.RSFlipFlop input_memory[nu] ;
  // Resetter:
  Modelica.Clocked.BooleanSignals.NonPeriodic.ClockToBoolean reset_ticked ;
  Modelica.Blocks.Routing.BooleanReplicator splitter(nout = nu) ;
equation
  connect(clock.y, y) ;
  connect(combinator.y, clock.u) ;
  connect(suppress_S.y, input_memory.S) ;
  connect(input_memory.Q, combinator.u) ;
  connect(S_false.y, suppress_S.u1) ;
  connect(splitter.y, input_memory.R) ;
  connect(splitter.y, forbidden_state.u1) ;
  connect(forbidden_state.y, suppress_S.u2) ;
  connect(clock.y, reset_ticked.u) ;
  connect(reset_ticked.y, splitter.u) ;
  connect(input_ticked.y, suppress_S.u3) ;
  connect(forbidden_state.u2, input_ticked.y) ;
  connect(u, input_ticked.u) ;

end PartialLogicalClock;

