block ShiftSample "Shift the input clock by a fraction of the last interval and provide it as output clock"
  parameter Integer shiftCounter(min = 0) = 0 "Numerator of shifting formula" ;
  parameter Integer resolution(min = 1) = 1 "Denominator of shifting formula" ;
  Modelica.Clocked.ClockSignals.Interfaces.ClockInput u "Connector of clock input signal" ;
  Modelica.Clocked.ClockSignals.Interfaces.ClockOutput y "Connector of clock output signal" ;
equation
  y = shiftSample(u, shiftCounter, resolution);

end ShiftSample;

