modelica://Modelica.Electrical/CompareTr:
Modelica.Electrical: CompareTransformers (model)

This example is to demonstrate the behaviour of transformer models. The Basic.Transformer, which consists of mutual coupled inductors, is compared with the ideal transformer model. If the ideal model is used with considerMagnetization=true leakage inductances are taken into account, otherwise not. The example is constructed in such a way that the ideal transformer circuit with considerMagnetization=true shows the same behaviour as the basic transformer.  
Simulate until T=50 s with both considerMagnetization=false and considerMagnetization=true of the ideal transformer. Plot in separate windows for comparison: 
basicTransformer.p1.v and idealTransformer.p1.v 
basicTransformer.p1.i and idealTransformer.p1.i 
basicTransformer.p2.v and idealTransformer.p2.v basicTransformer.p2.i and idealTransformer.p2.i

Code:
model CompareTransformers "Transformer circuit to show the magnetization facilities"
  import Modelica.Constants.pi;
  extends Modelica.Icons.Example;
  parameter Modelica.Units.SI.Voltage Vdc = 0.1 "DC offset of voltage source";
  parameter Modelica.Units.SI.Voltage Vpeak = 0.1 "Peak voltage of voltage source";
  parameter Modelica.Units.SI.Frequency f = 10 "Frequency of voltage source";
  parameter Modelica.Units.SI.Angle phi0 = pi / 2 "Phase of voltage source";
  parameter Real n = 2 "Turns ratio primary:secondary voltage";
  parameter Modelica.Units.SI.Resistance R1 = 0.01 "Primary resistance w.r.t. primary side";
  parameter Modelica.Units.SI.Inductance L1sigma = 0.05 / (2 * pi * f) "Primary leakage inductance w.r.t. primary side";
  parameter Modelica.Units.SI.Inductance Lm1 = 10. / (2 * pi * f) "Magnetizing inductance w.r.t. primary side";
  parameter Modelica.Units.SI.Inductance L2sigma = 0.05 / (2 * pi * f) / n ^ 2 "Secondary leakage inductance w.r.t. secondary side";
  parameter Modelica.Units.SI.Resistance R2 = 0.01 / n ^ 2 "Secondary resistance w.r.t. secondary side";
  parameter Modelica.Units.SI.Resistance RL = 1 / n ^ 2 "Load resistance";
  final parameter Modelica.Units.SI.Inductance L1 = L1sigma + M * n "Primary no-load inductance";
  final parameter Modelica.Units.SI.Inductance L2 = L2sigma + M / n "Secondary no-load inductance";
  final parameter Modelica.Units.SI.Inductance M = Lm1 / n "Mutual inductance";
  output Modelica.Units.SI.Voltage v1B = resistor11.n.v "Primary voltage, basic transformer";
  output Modelica.Units.SI.Current i1B = resistor11.i "Primary current, basic transformer";
  output Modelica.Units.SI.Voltage v2B = resistor12.p.v "Secondary voltage, basic transformer";
  output Modelica.Units.SI.Current i2B = resistor12.i "Secondary current, basic transformer";
  output Modelica.Units.SI.Voltage v1I = resistor21.n.v "Primary voltage, basic transformer";
  output Modelica.Units.SI.Current i1I = resistor21.i "Primary current, basic transformer";
  output Modelica.Units.SI.Voltage v2I = resistor22.p.v "Secondary voltage, basic transformer";
  output Modelica.Units.SI.Current i2I = resistor22.i "Secondary current, basic transformer";
  Modelica.Electrical.Analog.Sources.SineVoltage sineVoltage1(V = Vpeak, phase = phi0, f = f, offset = Vdc) ;
  Modelica.Electrical.Analog.Basic.Ground ground11 ;
  Modelica.Electrical.Analog.Basic.Resistor resistor11(R = R1) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor12(R = R2) ;
  Modelica.Electrical.Analog.Basic.Resistor load1(R = RL) ;
  Modelica.Electrical.Analog.Basic.Ground ground12 ;
  Modelica.Electrical.Analog.Sources.SineVoltage sineVoltage2(V = Vpeak, phase = phi0, f = f, offset = Vdc) ;
  Modelica.Electrical.Analog.Basic.Ground ground21 ;
  Modelica.Electrical.Analog.Basic.Resistor resistor21(R = R1) ;
  Modelica.Electrical.Analog.Basic.Inductor inductor21(L = L1sigma) ;
  Modelica.Electrical.Analog.Basic.Inductor inductor22(L = L2sigma, i(start = 0, fixed = true)) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor22(R = R2) ;
  Modelica.Electrical.Analog.Basic.Resistor load2(R = RL) ;
  Modelica.Electrical.Analog.Basic.Ground ground22 ;
  Modelica.Electrical.Analog.Basic.Transformer basicTransformer(L1 = L1, L2 = L2, M = M) ;
  Modelica.Electrical.Analog.Ideal.IdealTransformer idealTransformer(n = n, Lm1 = Lm1, considerMagnetization = false) ;
initial equation
  basicTransformer.i1 = 0;
  basicTransformer.i2 = 0;
equation
  connect(sineVoltage1.n, ground11.p) ;
  connect(sineVoltage1.p, resistor11.p) ;
  connect(load1.n, ground12.p) ;
  connect(resistor12.n, load1.p) ;
  connect(sineVoltage2.n, ground21.p) ;
  connect(sineVoltage2.p, resistor21.p) ;
  connect(resistor21.n, inductor21.p) ;
  connect(inductor22.n, resistor22.p) ;
  connect(load2.n, ground22.p) ;
  connect(resistor22.n, load2.p) ;
  connect(ground11.p, basicTransformer.n1) ;
  connect(basicTransformer.n2, ground12.p) ;
  connect(basicTransformer.p1, resistor11.n) ;
  connect(basicTransformer.p2, resistor12.p) ;
  connect(ground21.p, idealTransformer.n1) ;
  connect(ground22.p, idealTransformer.n2) ;
  connect(idealTransformer.p1, inductor21.n) ;
  connect(idealTransformer.p2, inductor22.p) ;

end CompareTransformers;

