model ControlCircuit "Control circuit"
  extends Modelica.Icons.Example;
  parameter Modelica.Units.SI.Time T1 = 0.01 "Small time constant";
  parameter Modelica.Units.SI.Time T2 = 0.01 "Large time constant";
  parameter Modelica.Units.SI.Time Ti = T2 "Integral time constant";
  parameter Real kp = T2 / (2 * T1) "Proportional gain";
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Electrical.Analog.Sources.StepVoltage stepA(V = 10, startTime = 0.1) ;
  Modelica.Electrical.Analog.Examples.OpAmps.OpAmpCircuits.Feedback feedbackA(p1(i(start = 0))) ;
  Modelica.Electrical.Analog.Examples.OpAmps.OpAmpCircuits.PI PIA(v2(fixed = true), k = kp, T = Ti, opAmp(v_in(start = 0))) ;
  Modelica.Electrical.Analog.Examples.OpAmps.OpAmpCircuits.FirstOrder firstOrder1A(v2(fixed = true), T = T1, opAmp(v_in(start = 0))) ;
  Modelica.Electrical.Analog.Examples.OpAmps.OpAmpCircuits.Add addA(i1_2(start = 0), r(i(start = 0))) ;
  Modelica.Electrical.Analog.Sources.StepVoltage step1A(V = 1, startTime = 0.5) ;
  Modelica.Electrical.Analog.Examples.OpAmps.OpAmpCircuits.FirstOrder firstOrder2A(v2(fixed = true), T = T2, opAmp(v_in(start = 0))) ;
  Modelica.Blocks.Sources.Step stepB(height = 10, startTime = 0.1) ;
  Modelica.Blocks.Math.Feedback feedbackB ;
  Modelica.Blocks.Continuous.PI PIB(k = kp, T = Ti, initType = Modelica.Blocks.Types.Init.InitialOutput) ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder1B(T = T1, initType = Modelica.Blocks.Types.Init.InitialOutput) ;
  Modelica.Blocks.Math.Add addB ;
  Modelica.Blocks.Sources.Step step1B(height = 1, startTime = 0.5) ;
  Modelica.Blocks.Continuous.FirstOrder firstOrder2B(T = T2, initType = Modelica.Blocks.Types.Init.InitialOutput) ;
equation
  connect(stepA.n, ground.p) ;
  connect(feedbackA.p2, PIA.p1) ;
  connect(feedbackA.n2, PIA.n1) ;
  connect(PIA.p2, firstOrder1A.p1) ;
  connect(PIA.n2, firstOrder1A.n1) ;
  connect(stepB.y, feedbackB.u1) ;
  connect(feedbackB.y, PIB.u) ;
  connect(PIB.y, firstOrder1B.u) ;
  connect(firstOrder1B.y, addB.u1) ;
  connect(addB.y, firstOrder2B.u) ;
  connect(step1B.y, addB.u2) ;
  connect(firstOrder2B.y, feedbackB.u2) ;
  connect(stepA.p, feedbackA.p1_2) ;
  connect(firstOrder2A.p2, feedbackA.p1) ;
  connect(ground.p, feedbackA.n1) ;
  connect(ground.p, step1A.n) ;
  connect(firstOrder1A.n2, addA.n1) ;
  connect(firstOrder1A.p2, addA.p1) ;
  connect(step1A.p, addA.p1_2) ;
  connect(addA.p2, firstOrder2A.p1) ;
  connect(addA.n2, firstOrder2A.n1) ;

end ControlCircuit;

