Modelica.Electrical: VoltageFollower (model)

This is a voltage follower. It reproduces the input voltage at the output without loading the input voltage source with a stiff output.

Code:
model VoltageFollower "Reproduce input voltage"
  extends Modelica.Icons.Example;
  parameter Modelica.Units.SI.Voltage Vps = +15 "Positive supply";
  parameter Modelica.Units.SI.Voltage Vns = -15 "Negative supply";
  parameter Modelica.Units.SI.Voltage Vin = 5 "Amplitude of input voltage";
  parameter Modelica.Units.SI.Frequency f = 10 "Frequency of input voltage";
  parameter Modelica.Units.SI.Resistance Ri = 1 "Inner resistance of input voltage source";
  parameter Modelica.Units.SI.Resistance Rl = 1 "Load resistance";
  Modelica.Electrical.Analog.Ideal.IdealizedOpAmpLimited opAmp(Vps = Vps, Vns = Vns, v_in(start = 0)) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Electrical.Analog.Sources.TrapezoidVoltage vIn(V = 2 * Vin, rising = 0.2 / f, width = 0.3 / f, falling = 0.2 / f, period = 1 / f, nperiod = -1, offset = -Vin, startTime = -(vIn.rising + vIn.width / 2)) ;
  Modelica.Electrical.Analog.Sensors.VoltageSensor vOut ;
  Modelica.Electrical.Analog.Basic.Resistor ri(R = Ri) ;
  Modelica.Electrical.Analog.Basic.Resistor rl(R = Rl) ;
equation
  connect(ground.p, vIn.n) ;
  connect(opAmp.out, vOut.p) ;
  connect(ground.p, vOut.n) ;
  connect(opAmp.out, opAmp.in_n) ;
  connect(vIn.p, ri.p) ;
  connect(ri.n, opAmp.in_p) ;
  connect(opAmp.out, rl.p) ;
  connect(ground.p, rl.n) ;

end VoltageFollower;

