  connect(opAmp.in_n, ground.p) ;
  connect(opAmp.out, r2.n) ;
  connect(r2.p, opAmp.in_p) ;
  connect(r2.p, r1.n) ;
  connect(r1.p, vIn.p) ;

end SchmittTrigger;

modelica://Modelica.Electrical/LCOscilla:
Modelica.Electrical: LCOscillator (model)

This is an LC oscillator according to:  
U. Tietze and C. Schenk, Halbleiter-Schaltungstechnik (German), 11th edition, Springer 1999, Chapter 14.1

Code:
model LCOscillator "LC oscillator"
  extends Modelica.Icons.Example;
  import Modelica.Constants.pi;
  parameter Modelica.Units.SI.Voltage VAmp = 10 "Amplitude of output";
  parameter Modelica.Units.SI.Frequency f = 1000 "Desired frequency";
  parameter Real A = 1.001 "Amplification constant: A > 1 amplification, A = 1 pure sinusoidal oscillation, A < 0 damping";
  parameter Modelica.Units.SI.Inductance L = 0.001 "Arbitrary inductance > 0";
  parameter Modelica.Units.SI.Capacitance C = 1 / ((2 * pi * f) ^ 2 * L) "Calculated capacitance to reach frequency f";
  parameter Modelica.Units.SI.Resistance R = 10000.0 "Damping resistance";
  parameter Modelica.Units.SI.Resistance R1 = 10000.0 "Arbitrary high resistance";
  parameter Modelica.Units.SI.Resistance R2 = (A - 1) * R1 "Calculated resistance to reach amplification A";
  parameter Real gamma = (1 - A) / (2 * R * C) "Calculated characteristical parameter";
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Electrical.Analog.Ideal.IdealizedOpAmpLimited opAmp ;
  Modelica.Electrical.Analog.Basic.Resistor r(R = R) ;
  Modelica.Electrical.Analog.Basic.Resistor r2(R = R2, i(start = 0)) ;
  Modelica.Electrical.Analog.Basic.Resistor r1(R = R1) ;
  Modelica.Electrical.Analog.Basic.Capacitor c(C = C, v(start = VAmp, fixed = true)) ;
  Modelica.Electrical.Analog.Basic.Inductor l(L = L, i(fixed = true, start = 0)) ;
  Modelica.Electrical.Analog.Sensors.VoltageSensor vOut ;
equation
  connect(opAmp.out, r.p) ;
  connect(opAmp.out, r2.p) ;
  connect(r2.n, r1.p) ;
  connect(r2.n, opAmp.in_n) ;
  connect(r1.n, ground.p) ;
  connect(r.n, opAmp.in_p) ;
  connect(l.n, ground.p) ;
  connect(r.n, l.p) ;
  connect(c.p, l.p) ;
  connect(c.n, l.n) ;
  connect(ground.p, vOut.n) ;
  connect(r.n, vOut.p) ;

end LCOscillator;

