  Modelica.Blocks.Logical.Not not1 ;
  Modelica.Blocks.Logical.LogicalSwitch logicalSwitch ;
protected
  constant Modelica.Units.SI.Resistance oneOhm = 1 "Helping constant to satisfy unit check";
equation
  connect(IdealCommutingSwitch1.p, Capacitor.p) ;
  connect(Capacitor.n, IdealCommutingSwitch2.p) ;
  connect(IdealCommutingSwitch2.control, BooleanPulse.y) ;
  connect(Ground1.p, IdealCommutingSwitch1.n2) ;
  connect(Ground2.p, IdealCommutingSwitch2.n2) ;
  connect(IdealCommutingSwitch1.n1, p) ;
  connect(IdealCommutingSwitch2.n1, n) ;
  connect(p, p) ;
  connect(Resistance.y, lessEqualThreshold.u) ;
  connect(logicalSwitch.y, IdealCommutingSwitch1.control) ;
  connect(logicalSwitch.u3, BooleanPulse.y) ;
  connect(logicalSwitch.u1, not1.y) ;
  connect(not1.u, BooleanPulse.y) ;
