modelica://Modelica.Electrical/FCNiout_l:
Modelica.Electrical: FCNiout_limit (function)

Internal limitation function, designed for OpAmpDetailed, not for purpose of external usage.

Code:
function FCNiout_limit "Internal limitation function"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Voltage v_source;
  input Modelica.Units.SI.Voltage v_out;
  input Modelica.Units.SI.Resistance Rout;
  input Modelica.Units.SI.Current Imaxsi_val;
  input Modelica.Units.SI.Current Imaxso_val;
  output Modelica.Units.SI.Current result;
algorithm
  if v_out > v_source + Rout * Imaxsi_val then
    result := Imaxsi_val;
  elseif v_out < v_source - Rout * Imaxso_val then
    result := -Imaxso_val;
  else
    result := (v_out - v_source) / Rout;
  end if;
  return;

end FCNiout_limit;

modelica://Modelica.Electrical/FCNq_sum_:
Modelica.Electrical: FCNq_sum_limit (function)

Internal limitation function, designed for OpAmpDetailed, not for purpose of external usage.

Code:
function FCNq_sum_limit "Internal limitation function"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Voltage q_sum;
  input Modelica.Units.SI.Voltage q_sum_ltf;
  input Modelica.Units.SI.Voltage v_pos;
  input Modelica.Units.SI.Voltage v_neg;
  input Modelica.Units.SI.Voltage vcp;
  input Modelica.Units.SI.Voltage vcm;
  output Modelica.Units.SI.Voltage result;
algorithm
  if q_sum > v_pos - vcp and q_sum_ltf >= v_pos - vcp then
    result := v_pos - vcp;
  elseif q_sum < v_neg + vcm and q_sum_ltf <= v_neg + vcm then
    result := v_neg + vcm;
  else
    result := q_sum;
  end if;
  return;

end FCNq_sum_limit;

