Code:
model NPN "Simple NPN BJT according to Ebers-Moll with heating port"
  parameter Real Bf = 50 "Forward beta";
  parameter Real Br = 0.1 "Reverse beta";
  parameter Modelica.Units.SI.Current Is = 1e-16 "Transport saturation current";
  parameter Modelica.Units.SI.InversePotential Vak = 0.02 "Early voltage (inverse), 1/Volt";
  parameter Modelica.Units.SI.Time Tauf = 0.12e-9 "Ideal forward transit time";
  parameter Modelica.Units.SI.Time Taur = 5e-9 "Ideal reverse transit time";
  parameter Modelica.Units.SI.Capacitance Ccs = 1e-12 "Collector-substrate(ground) cap.";
  parameter Modelica.Units.SI.Capacitance Cje = 0.4e-12 "Base-emitter zero bias depletion cap.";
  parameter Modelica.Units.SI.Capacitance Cjc = 0.5e-12 "Base-coll. zero bias depletion cap.";
  parameter Modelica.Units.SI.Voltage Phie = 0.8 "Base-emitter diffusion voltage";
  parameter Real Me = 0.4 "Base-emitter gradation exponent";
  parameter Modelica.Units.SI.Voltage Phic = 0.8 "Base-collector diffusion voltage";
  parameter Real Mc = 0.333 "Base-collector gradation exponent";
  parameter Modelica.Units.SI.Conductance Gbc = 1e-15 "Base-collector conductance";
  parameter Modelica.Units.SI.Conductance Gbe = 1e-15 "Base-emitter conductance";
  parameter Real EMin = -100 "If x < EMin, the exp(x) function is linearized";
  parameter Real EMax = 40 "If x > EMax, the exp(x) function is linearized";
  parameter Boolean useTemperatureDependency = false "= true, if parameters Bf, Br, Is and Vt depend on temperature" ;
  parameter Modelica.Units.SI.Voltage Vt = 0.02585 "Voltage equivalent of temperature" ;
  parameter Modelica.Units.SI.Temperature Tnom = 300.15 "Parameter measurement temperature" ;
  parameter Real XTI = 3 "Temperature exponent for effect on Is" ;
  parameter Real XTB = 0 "Forward and reverse beta temperature exponent" ;
  parameter Modelica.Units.SI.Voltage EG = 1.11 "Energy gap for temperature effect on Is" ;
  parameter Real NF = 1.0 "Forward current emission coefficient";
  parameter Real NR = 1.0 "Reverse current emission coefficient";
  parameter Modelica.Units.SI.Voltage IC = 0 "Initial value of collector to substrate voltage" ;
  parameter Boolean UIC = false "Decision if initial value IC should be used";
  parameter Boolean useSubstrate = false "= false, if substrate is implicitly grounded";
  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort(useHeatPort = useTemperatureDependency);
  Modelica.Units.SI.Voltage vbc "Base-collector voltage";
  Modelica.Units.SI.Voltage vbe "Base-emitter voltage";
  Modelica.Units.SI.Voltage vcs "Collector-substrate voltage";
  Real qbk "Relative majority carrier charge, inverse";
  Modelica.Units.SI.Current ibc "Base-collector diode current";
  Modelica.Units.SI.Current ibe "Base-emitter diode current";
  Modelica.Units.SI.Capacitance cbc "Total base-collector capacitance";
  Modelica.Units.SI.Capacitance cbe "Total base-emitter capacitance";
  Modelica.Units.SI.Capacitance Capcje "Effective base-emitter depletion capacitance";
  Modelica.Units.SI.Capacitance Capcjc "Effective base-collector depletion capacitance";
  Modelica.Units.SI.Current is_t "Temperature dependent transport saturation current";
  Real br_t "Temperature dependent forward beta";
  Real bf_t "Temperature dependent reverse beta";
  Modelica.Units.SI.Voltage vt_t "Voltage equivalent of effective temperature";
  Real hexp "Auxiliary quantity temperature dependent exponent";
  Real htempexp "Auxiliary quantity exp(hexp)";
  Modelica.Units.SI.Voltage vS "Substrate potential";
  Modelica.Units.SI.Current iS "Substrate current";
  Modelica.Electrical.Analog.Interfaces.Pin C "Collector" ;
  Modelica.Electrical.Analog.Interfaces.Pin B "Base" ;
  Modelica.Electrical.Analog.Interfaces.Pin E "Emitter" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin S(final i = iS, final v = vS) if useSubstrate "Substrate" ;
initial equation
  if UIC then
    vcs = IC;
  end if;
equation
  assert(T_heatPort > 0, "Temperature must be positive");
  vbc = B.v - C.v;
  vbe = B.v - E.v;
  vcs = C.v - vS;
  qbk = 1 - vbc * Vak;
  hexp = (T_heatPort / Tnom - 1) * EG / vt_t;
  htempexp = smooth(1, Modelica.Electrical.Analog.Semiconductors.exlin2(hexp, EMin, EMax));
  is_t = if useTemperatureDependency then Is * Modelica.Electrical.Analog.Semiconductors.pow(T_heatPort / Tnom, XTI) * htempexp else Is;
  br_t = if useTemperatureDependency then Br * Modelica.Electrical.Analog.Semiconductors.pow(T_heatPort / Tnom, XTB) else Br;
  bf_t = if useTemperatureDependency then Bf * Modelica.Electrical.Analog.Semiconductors.pow(T_heatPort / Tnom, XTB) else Bf;
  vt_t = if useTemperatureDependency then k / q * T_heatPort else Vt;
  ibc = smooth(1, is_t * (Modelica.Electrical.Analog.Semiconductors.exlin2(vbc / (NR * vt_t), EMin, EMax) - 1) + vbc * Gbc);
  ibe = smooth(1, is_t * (Modelica.Electrical.Analog.Semiconductors.exlin2(vbe / (NF * vt_t), EMin, EMax) - 1) + vbe * Gbe);
  Capcjc = smooth(1, Cjc * Modelica.Electrical.Analog.Semiconductors.powlin(vbc / Phic, Mc));
  Capcje = smooth(1, Cje * Modelica.Electrical.Analog.Semiconductors.powlin(vbe / Phie, Me));
  cbc = smooth(1, Taur * is_t / (NR * vt_t) * Modelica.Electrical.Analog.Semiconductors.exlin2(vbc / (NR * vt_t), EMin, EMax) + Capcjc);
  cbe = smooth(1, Tauf * is_t / (NF * vt_t) * Modelica.Electrical.Analog.Semiconductors.exlin2(vbe / (NF * vt_t), EMin, EMax) + Capcje);
  C.i = (ibe - ibc) * qbk - ibc / br_t - cbc * der(vbc) - iS;
  B.i = ibe / bf_t + ibc / br_t + cbc * der(vbc) + cbe * der(vbe);
  E.i = -B.i - C.i - iS;
  iS = -Ccs * der(vcs);
  if not useSubstrate then
    vS = 0;
  end if;
  LossPower = vbc * ibc / br_t + vbe * ibe / bf_t + (ibe - ibc) * qbk * (C.v - E.v);

end NPN;

