  output Real z;
algorithm
  z := if x > 0 then 1 + y * x else Modelica.Electrical.Analog.Semiconductors.pow(1 - x, -y);
end powlin;

modelica://Modelica.Electrical/exlin:
Modelica.Electrical: exlin (function)

Code:
function exlin "Exponential function linearly continued for x > Maxexp"
  extends Modelica.Icons.Function;
  input Real x;
  input Real Maxexp;
  output Real z;
algorithm
  z := if x > Maxexp then exp(Maxexp) * (1 + x - Maxexp) else exp(x);
end exlin;

modelica://Modelica.Electrical/exlin2:
Modelica.Electrical: exlin2 (function)

Code:
function exlin2 "Exponential function linearly continued for x < MinExp and x > Maxexp"
  extends Modelica.Icons.Function;
  input Real x;
  input Real Minexp;
  input Real Maxexp;
  output Real z;
algorithm
  z := if x < Minexp then exp(Minexp) * (1 + x - Minexp) else Modelica.Electrical.Analog.Semiconductors.exlin(x, Maxexp);
end exlin2;

modelica://Modelica.Electrical/Thyristor:
Modelica.Electrical: Thyristor (model)

This is a simple thyristor model with three pins: Anode, Cathode and Gate. There are three operating modes:conducting, blocking and reverse breakthrough. 
As long as the thyristor is in blocking mode it behaves like a linear resistance Roff=VDRM^2/(VTM*IH). But if the voltage between anode and cathode exceeds VDRM or a positive gate current flows for a sufficient time the mode changes to conducting mode. The model stays in conducting mode until the anode current falls below the holding current IH. There is no way to switch off the thyristor via the gate. If the voltage between anode and cathode is negative, the model represents a diode (parameters Vt, Nbv) with reverse breakthrough voltage VRRM.  

The dV/dt switch on is not taken into account in this model. The gate circuit is not influenced by the main circuit.

Code:
model Thyristor "Simple Thyristor Model"
  parameter Modelica.Units.SI.Voltage VDRM(final min = 0) = 100 "Forward breakthrough voltage";
  parameter Modelica.Units.SI.Voltage VRRM(final min = 0) = 100 "Reverse breakthrough voltage";
  parameter Modelica.Units.SI.Current IDRM = 0.1 "Saturation current";
  parameter Modelica.Units.SI.Voltage VTM = 1.7 "Conducting voltage";
  parameter Modelica.Units.SI.Current IH = 6e-3 "Holding current";
  parameter Modelica.Units.SI.Current ITM = 25 "Conducting current";
  parameter Modelica.Units.SI.Voltage VGT = 0.7 "Gate trigger voltage";
  parameter Modelica.Units.SI.Current IGT = 5e-3 "Gate trigger current";
  parameter Modelica.Units.SI.Time TON = 1e-6 "Switch on time";
  parameter Modelica.Units.SI.Time TOFF = 15e-6 "Switch off time";
  parameter Modelica.Units.SI.Voltage Vt = 0.04 "Voltage equivalent of temperature (kT/qn)";
  parameter Real Nbv = 0.74 "Reverse Breakthrough emission coefficient";
  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort;
  Modelica.Units.SI.Current iGK "Gate current";
  Modelica.Units.SI.Voltage vGK "Voltage between gate and cathode";
  Modelica.Units.SI.Voltage vAK "Voltage between anode and cathode";
  Modelica.Units.SI.Voltage vControl(start = 0);
  Modelica.Units.SI.Voltage vContot;
  Modelica.Units.SI.Voltage vConmain;
  parameter Modelica.Units.SI.Voltage vRef = 0.65;
public
  Modelica.Electrical.Analog.Interfaces.PositivePin Anode ;
  Modelica.Electrical.Analog.Interfaces.NegativePin Cathode ;
  Modelica.Electrical.Analog.Interfaces.PositivePin Gate ;
protected
  parameter Modelica.Units.SI.Voltage Von = 5;
  parameter Modelica.Units.SI.Voltage Voff = 1.5;
  parameter Modelica.Units.SI.Resistance Ron = (VTM - 0.7) / ITM "Forward conducting mode resistance";
  parameter Modelica.Units.SI.Resistance Roff = VDRM ^ 2 / VTM / IH "Blocking mode resistance";
equation
  //Kirchhoff's equations
  Anode.i + Gate.i + Cathode.i = 0;
  vGK = Gate.v - Cathode.v;
  vAK = Anode.v - Cathode.v;
  // Gate and Control voltage
  iGK = Gate.i;
  vGK = smooth(0, (if vGK < vRef then VGT / IGT * iGK else vRef ^ 2 / VGT + iGK * (VGT - vRef) / IGT));
  vContot = vConmain + smooth(0, if iGK < 0.95 * IGT then 0 else if iGK < 0.95 * IGT + 1e-3 then 10000 * (iGK - 0.95 * IGT) * vAK else 10 * vAK);
  der(vControl) = (vContot - vControl) / (if vContot - vControl > 0 then 1.87 * TON else 0.638 * TOFF);
  // Anode-Cathode characteristics
  Anode.i = smooth(1, if vAK < -VRRM then -VRRM / Roff * exp(-(vAK + VRRM) / (Nbv * Vt)) else if vControl < Voff then vAK / Roff else if vControl < Von then vAK / (sqrt(Ron * Roff) * (Ron / Roff) ^ ((3 * ((2 * vControl - Von - Voff) / (2 * (Von - Voff))) - 4 * ((2 * vControl - Von - Voff) / (2 * (Von - Voff))) ^ 3) / 2)) else vAK / Ron);
  // holding effect and forward breakthrough
  vConmain = if Anode.i > IH or vAK > VDRM then Von else 0;
  LossPower = Anode.i * Anode.v + Cathode.i * Cathode.v + Gate.i * Gate.v;

end Thyristor;

modelica://Modelica.Electrical/SimpleTri:
Modelica.Electrical: SimpleTriac (model)

This is a simple TRIAC model based on the extended thyristor model Modelica.Electrical.Analog.Semiconductors.Thyristor. 
Two thyristors are contrarily connected in parallel, whereas each transistor is connected with a diode. 
Further information regarding the electrical component TRIAC can be detected in documentation of the ideal TRIAC model. 
As an additional information: this model is based on the Modelica.Electrical.Analog.Semiconductors.Thyristor.  
Attention: The model seems to be very sensitive with respect to the choice of some parameters (e.g., VDRM, VRRM). This is caused by the thyristor model. Further investigations are necessary.

Code:
model SimpleTriac "Simple triac, based on Semiconductors.Thyristor model"
  parameter Modelica.Units.SI.Voltage VDRM(final min = 0) = 100 "Forward breakthrough voltage";
  parameter Modelica.Units.SI.Voltage VRRM(final min = 0) = 100 "Reverse breakthrough voltage";
  parameter Modelica.Units.SI.Current IDRM = 0.1 "Saturation current";
  parameter Modelica.Units.SI.Voltage VTM = 1.7 "Conducting voltage";
  parameter Modelica.Units.SI.Current IH = 6e-3 "Holding current";
  parameter Modelica.Units.SI.Current ITM = 25 "Conducting current";
  parameter Modelica.Units.SI.Voltage VGT = 0.7 "Gate trigger voltage";
  parameter Modelica.Units.SI.Current IGT = 5e-3 "Gate trigger current";
  parameter Modelica.Units.SI.Time TON = 1e-6 "Switch on time";
  parameter Modelica.Units.SI.Time TOFF = 15e-6 "Switch off time";
  parameter Modelica.Units.SI.Voltage Vt = 0.04 "Voltage equivalent of temperature (kT/qn)";
  parameter Real Nbv = 0.74 "Reverse Breakthrough emission coefficient";
  Modelica.Electrical.Analog.Interfaces.NegativePin n "Cathode" ;
  Modelica.Electrical.Analog.Interfaces.PositivePin p "Anode" ;
  Modelica.Electrical.Analog.Interfaces.PositivePin g "Gate" ;
  Modelica.Electrical.Analog.Semiconductors.Thyristor thyristor(VDRM = VDRM, VRRM = VRRM, IDRM = IDRM, VTM = VTM, IH = IH, ITM = ITM, VGT = VGT, IGT = IGT, TON = TON, TOFF = TOFF, Vt = Vt, Nbv = Nbv, useHeatPort = useHeatPort, T = T) ;
  Modelica.Electrical.Analog.Semiconductors.Thyristor thyristor1(VDRM = VDRM, VRRM = VRRM, IDRM = IDRM, VTM = VTM, IH = IH, ITM = ITM, VGT = VGT, IGT = IGT, TON = TON, TOFF = TOFF, Vt = Vt, Nbv = Nbv, useHeatPort = useHeatPort, T = T) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode idealDiode(Vknee = 0) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode idealDiode1(Vknee = 0) ;
  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort;
equation
  if useHeatPort then
    connect(heatPort, thyristor.heatPort);
    connect(heatPort, thyristor1.heatPort);
  end if;
  connect(thyristor.Anode, n) ;
  connect(thyristor1.Anode, p) ;
  connect(thyristor1.Anode, thyristor.Cathode) ;
  connect(thyristor1.Cathode, thyristor.Anode) ;
  connect(thyristor.Gate, idealDiode.n) ;
  connect(idealDiode.p, g) ;
  connect(idealDiode1.n, thyristor1.Gate) ;
  connect(idealDiode1.p, g) ;
  LossPower = p.i * p.v + n.i * n.v + g.i * g.v;

end SimpleTriac;

modelica://Modelica.Electrical/Potential:
Modelica.Electrical: PotentialSensor (model)

The potential sensor converts the voltage of a node (with respect to the ground node) into a real valued signal. It does not influence the current sum at the node which voltage is measured, therefore, the electrical behavior is not influenced by the sensor.

Code:
model PotentialSensor "Sensor to measure the potential"
  extends Modelica.Icons.RoundSensor;
  Modelica.Electrical.Analog.Interfaces.PositivePin p "Pin to be measured" ;
  Modelica.Blocks.Interfaces.RealOutput phi(unit = "V") "Absolute voltage potential as output signal" ;
equation
  p.i = 0;
  phi = p.v;

end PotentialSensor;

modelica://Modelica.Electrical/VoltageSe:
Modelica.Electrical: VoltageSensor (model)

The voltage sensor converts the voltage between the two connectors into a real valued signal. It does not influence the current sum at the nodes in between the voltage is measured, therefore, the electrical behavior is not influenced by the sensor.

Code:
model VoltageSensor "Sensor to measure the voltage between two pins"
  extends Modelica.Icons.RoundSensor;
  Modelica.Electrical.Analog.Interfaces.PositivePin p "Positive pin" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin n "Negative pin" ;
  Modelica.Blocks.Interfaces.RealOutput v(unit = "V") "Voltage between pin p and n (= p.v - n.v) as output signal" ;
equation
  p.i = 0;
  n.i = 0;
  v = p.v - n.v;

end VoltageSensor;

modelica://Modelica.Electrical/CurrentSe:
Modelica.Electrical: CurrentSensor (model)

The current sensor converts the current flowing between the two connectors into a real valued signal. The two connectors are in the sensor connected like a short cut. The sensor has to be placed within an electrical connection in series. It does not influence the current sum at the connected nodes. Therefore, the electrical behavior is not influenced by the sensor.

Code:
model CurrentSensor "Sensor to measure the current in a branch"
  extends Modelica.Icons.RoundSensor;
  Modelica.Electrical.Analog.Interfaces.PositivePin p "Positive pin" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin n "Negative pin" ;
  Modelica.Blocks.Interfaces.RealOutput i(unit = "A") "Current in the branch from p to n as output signal" ;
equation
  p.v = n.v;
  p.i = i;
  n.i = -i;

end CurrentSensor;

modelica://Modelica.Electrical/PowerSens:
Modelica.Electrical: PowerSensor (model)

This power sensor measures instantaneous electrical power of a single-phase system and has a separated voltage and current path. The pins of the voltage path are pv and nv, the pins of the current path are pc and nc. The internal resistance of the current path is zero, the internal resistance of the voltage path is infinite.

Code:
model PowerSensor "Sensor to measure the power"
  extends Modelica.Icons.RoundSensor;
  Modelica.Electrical.Analog.Interfaces.PositivePin pc "Positive pin, current path" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin nc "Negative pin, current path" ;
  Modelica.Electrical.Analog.Interfaces.PositivePin pv "Positive pin, voltage path" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin nv "Negative pin, voltage path" ;
  Modelica.Blocks.Interfaces.RealOutput power(unit = "W") "Instantaneous power as output signal" ;
  Modelica.Electrical.Analog.Sensors.VoltageSensor voltageSensor ;
  Modelica.Electrical.Analog.Sensors.CurrentSensor currentSensor ;
  Modelica.Blocks.Math.Product product ;
equation
  connect(pv, voltageSensor.p) ;
  connect(voltageSensor.n, nv) ;
  connect(pc, currentSensor.p) ;
  connect(currentSensor.n, nc) ;
  connect(currentSensor.i, product.u2) ;
  connect(voltageSensor.v, product.u1) ;
  connect(product.y, power) ;

end PowerSensor;

modelica://Modelica.Electrical/MultiSens:
Modelica.Electrical: MultiSensor (model)

This multi sensor measures current, voltage and instantaneous electrical power of a single-phase system and has a separated voltage and current path. The pins of the voltage path are pv and nv, the pins of the current path are pc and nc. The internal resistance of the current path is zero, the internal resistance of the voltage path is infinite.

Code:
model MultiSensor "Sensor to measure current, voltage and power"
  extends Modelica.Icons.RoundSensor;
  Modelica.Electrical.Analog.Interfaces.PositivePin pc "Positive pin, current path" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin nc "Negative pin, current path" ;
  Modelica.Electrical.Analog.Interfaces.PositivePin pv "Positive pin, voltage path" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin nv "Negative pin, voltage path" ;
  Modelica.Blocks.Interfaces.RealOutput i(final quantity = "ElectricCurrent", final unit = "A") "Current as output signal" ;
  Modelica.Blocks.Interfaces.RealOutput v(final quantity = "ElectricPotential", final unit = "V") "Voltage as output signal" ;
  Modelica.Blocks.Interfaces.RealOutput power(final quantity = "Power", final unit = "W") "Instantaneous power as output signal" ;
equation
  pc.i + nc.i = 0;
  pc.v - nc.v = 0;
  pv.i = 0;
  nv.i = 0;
  i = pc.i;
  v = pv.v - nv.v;
  power = v * i;

end MultiSensor;

modelica://Modelica.Electrical/SignalVol:
