modelica://Modelica.Electrical/SineCurre:
Modelica.Electrical: SineCurrentVariableFrequencyAndAmplitude (model)

This current source provides a sinusoidal current with variable frequency f and variable amplitude I , i.e. the phase angle of the sine wave is integrated from 2*π*f.   
 Note that the initial value of the phase angle phi defines the initial phase shift, and that the parameter startTime is omitted since the current can be kept equal to offset with setting the input I to zero.

Code:
model SineCurrentVariableFrequencyAndAmplitude "Sine current source with variable frequency and amplitude"
  extends Modelica.Electrical.Analog.Interfaces.OnePort;
  extends Modelica.Electrical.Analog.Icons.CurrentSource;
  import Modelica.Constants.pi;
  parameter Boolean useConstantAmplitude = false "Enable constant amplitude";
  parameter Modelica.Units.SI.Current constantAmplitude = 1 "Constant amplitude" ;
  parameter Boolean useConstantFrequency = false "Enable constant frequency";
  parameter Modelica.Units.SI.Frequency constantFrequency = 1 "Constant frequency" ;
  parameter Modelica.Units.SI.Current offset = 0 "Offset of the sine wave";
  Modelica.Units.SI.Angle phi(start = 0) "Phase of the sine wave";
  Modelica.Blocks.Interfaces.RealInput I(unit = "A") if not useConstantAmplitude "Amplitude" ;
  Modelica.Blocks.Interfaces.RealInput f(unit = "Hz") if not useConstantFrequency "Frequency" ;
protected
  Modelica.Blocks.Sources.Constant I_constant(final k = constantAmplitude) if useConstantAmplitude ;
  Modelica.Blocks.Sources.Constant f_constant(final k = constantFrequency) if useConstantFrequency ;
  Modelica.Blocks.Interfaces.RealInput I_internal(unit = "A") "Amplitude" ;
  Modelica.Blocks.Interfaces.RealInput f_internal(unit = "Hz") "Frequency" ;
equation
  der(phi) = 2 * pi * f_internal;
  i = offset + I_internal * sin(phi);
  connect(f, f_internal) ;
  connect(I, I_internal) ;
  connect(f_constant.y, f_internal) ;
  connect(I_constant.y, I_internal) ;

end SineCurrentVariableFrequencyAndAmplitude;

