The multiplexer converts a parallel 4 bit signal in a sequential 1 bit stream. The multiplexer component is composed by basic gates. It can be found in the Utilities subpackage. The example is designed to test and demonstrate the basic gate components.

Code:
model Multiplexer "4 to 1 Bit Multiplexer Example"
  import D = Modelica.Electrical.Digital;
  import L = Modelica.Electrical.Digital.Interfaces.Logic;
  extends Modelica.Icons.Example;
  D.Sources.DigitalClock CLK(period = 20, startTime = 0, width = 50) ;
  D.Sources.Table D0(y0 = D.Interfaces.Logic.'0', x = {D.Interfaces.Logic.'1', D.Interfaces.Logic.'0', D.Interfaces.Logic.'1', D.Interfaces.Logic.'0'}, t = {50, 100, 145, 200}) ;
  D.Sources.Table D1(y0 = D.Interfaces.Logic.'0', x = {D.Interfaces.Logic.'1', D.Interfaces.Logic.'0', D.Interfaces.Logic.'1', D.Interfaces.Logic.'0'}, t = {22, 140, 150, 180}) ;
  D.Examples.Utilities.MUX4 MUX ;
  D.Sources.Table D2(y0 = D.Interfaces.Logic.'0', x = {D.Interfaces.Logic.'1', D.Interfaces.Logic.'0', D.Interfaces.Logic.'1', D.Interfaces.Logic.'0'}, t = {22, 140, 150, 180}) ;
  D.Sources.Table D3(y0 = D.Interfaces.Logic.'0', x = {D.Interfaces.Logic.'1', D.Interfaces.Logic.'0', D.Interfaces.Logic.'1', D.Interfaces.Logic.'0'}, t = {22, 140, 150, 180}) ;
  D.Examples.Utilities.JKFF FF ;
  D.Sources.Set Enable(x = D.Interfaces.Logic.'1') ;
equation
  connect(CLK.y, FF.clk) ;
  connect(Enable.y, FF.k) ;
  connect(Enable.y, FF.j) ;
  connect(CLK.y, MUX.a0) ;
  connect(D0.y, MUX.d0) ;
  connect(D1.y, MUX.d1) ;
  connect(D2.y, MUX.d2) ;
  connect(D3.y, MUX.d3) ;
  connect(FF.q, MUX.a1) ;

end Multiplexer;

