modelica://Modelica.Electrical/MemoryBas:
Modelica.Electrical: MemoryBase (model)

Code:
partial model MemoryBase "Base model for memory elements"
  import D = Modelica.Electrical.Digital;
  import L = Modelica.Electrical.Digital.Interfaces.Logic;
  import S = Modelica.Electrical.Digital.Interfaces.Strength;
  import T = Modelica.Electrical.Digital.Tables;
  parameter Modelica.Units.SI.Time tHL = 0 "High->Low delay";
  parameter Modelica.Units.SI.Time tLH = 0 "Low->High delay";
  parameter D.Interfaces.Strength strength = D.Interfaces.Strength.'S_X01' "Output strength";
  parameter Integer n_addr(min = 1) = 2 "Addr width";
  parameter Integer n_data(min = 1) = 2 "Data width";
  parameter String fileName = Modelica.Utilities.Files.loadResource("modelica://Modelica/Resources/Data/Electrical/Digital/Memory_Matrix.txt") "File where matrix for memory is stored" ;
  D.Interfaces.DigitalInput RE "Read enable" ;
  D.Interfaces.DigitalInput addr[n_addr] "Address" ;
  D.Interfaces.DigitalOutput dataOut[n_data] "Data output" ;

  function getMemory "Get Memory"
  extends Modelica.Icons.Function;
  input String filename;
  input Integer n_addr "Addr width";
  input Integer n_data "Data width";
  output D.Interfaces.Logic m[integer(2 ^ n_addr), n_data] "Memory with data, lowest bit on left side";
  output String data;
  output Integer bit;
  algorithm
  for i in 1:2 ^ n_addr loop
  data := Modelica.Utilities.Streams.readLine(filename, integer(i));
  for j in 1:n_data loop
    bit := Modelica.Utilities.Strings.scanInteger(data, 2 * j - 1);
    if bit == 1 then
      m[integer(i), j] := D.Interfaces.Logic.'1';
    elseif bit == 0 then
      m[integer(i), j] := D.Interfaces.Logic.'0';
    else
      m[integer(i), j] := D.Interfaces.Logic.'X';
    end if;
  end for;
  end for;
  end getMemory;
protected
  D.Interfaces.Logic nextstate[n_data](start = fill(D.Interfaces.Logic.'U', n_data));
  D.Interfaces.Logic mem_word[n_data](start = fill(D.Interfaces.Logic.'U', n_data));
  Integer int_addr;
  D.Interfaces.DigitalOutput yy[n_data](start = fill(D.Interfaces.Logic.'U', n_data));
  D.Delay.InertialDelaySensitive inertialDelaySensitive[n_data](each tLH = tLH, each tHL = tHL);

  function address "Compute memory address"
  extends Modelica.Icons.Function;
  input Integer n_addr;
  input D.Interfaces.Logic addr[n_addr];
  output Integer int_addr;
  protected
    D.Interfaces.Logic addr_bit;
  algorithm
  int_addr := 1;
  for i in 1:n_addr loop
  addr_bit := T.X01Table[addr[i]];
  if addr_bit == D.Interfaces.Logic.'1' then
    int_addr := int_addr + integer(2 ^ (i - 1));
  elseif addr_bit == D.Interfaces.Logic.'X' then
    int_addr := 0;
    break;
  end if;
  end for;
  end address;
equation
  for i in 1:n_data loop
    connect(yy[i], inertialDelaySensitive[i].x);
    connect(inertialDelaySensitive[i].y, dataOut[i]);
  end for;

end MemoryBase;

