Code:
model DLATR "Level sensitive register bank with reset"
  import D = Modelica.Electrical.Digital;
  import L = Modelica.Electrical.Digital.Interfaces.Logic;
  import S = Modelica.Electrical.Digital.Interfaces.Strength;
  import T = Modelica.Electrical.Digital.Tables;
  parameter Integer ResetMap[L] = {1, 4, 3, 2, 4, 4, 3, 2, 4} "Function selection, defaults for high active reset";
  parameter D.Interfaces.Strength strength = D.Interfaces.Strength.'S_X01' "Output strength";
  parameter Integer n(min = 1) = 1 "Data width";
  D.Interfaces.DigitalInput reset ;
  D.Interfaces.DigitalInput enable ;
  D.Interfaces.DigitalInput dataIn[n] ;
  D.Interfaces.DigitalOutput dataOut[n] ;
protected
  Integer enable_flag(start = 0);
  // 0: low level
  // 1: high level
  // 2: unknown
  // 3: uninitialized
  Integer reset_flag(start = 1);
  // 1: output := U
  // 2: output := 0
  // 3: output := -UdataIn
  // 4: output := U-0X
  D.Interfaces.Logic nextstate[n](start = fill(D.Interfaces.Logic.'U', n));
  D.Interfaces.Logic next_assign_val[n](start = fill(D.Interfaces.Logic.'U', n));
algorithm
  if enable == D.Interfaces.Logic.'1' or enable == D.Interfaces.Logic.'H' then
    enable_flag := 1;
  elseif enable == D.Interfaces.Logic.'0' or enable == D.Interfaces.Logic.'L' then
    enable_flag := 0;
  elseif enable == D.Interfaces.Logic.'U' then
    enable_flag := 3;
  else
    enable_flag := 2;
  end if;
  reset_flag := ResetMap[reset];
  for i in 1:n loop
    if reset_flag == 1 then
      nextstate[i] := D.Interfaces.Logic.'U';
    elseif reset_flag == 2 then
      nextstate[i] := T.StrengthMap[D.Interfaces.Logic.'0', strength];
    elseif reset_flag == 3 then
      if enable_flag == 0 then
        break;
      elseif enable_flag == 3 then
        nextstate[i] := D.Interfaces.Logic.'U';
      elseif enable_flag == 1 then
        nextstate[i] := T.StrengthMap[dataIn[i], strength];
      else
        if next_assign_val[i] == T.StrengthMap[dataIn[i], strength] or next_assign_val[i] == D.Interfaces.Logic.'U' then
          break;
        elseif dataIn[i] == D.Interfaces.Logic.'U' then
          nextstate[i] := D.Interfaces.Logic.'U';
        else
          nextstate[i] := T.StrengthMap[D.Interfaces.Logic.'X', strength];
        end if;
      end if;
    elseif reset_flag == 4 then
      if enable_flag == 3 or next_assign_val[i] == D.Interfaces.Logic.'U' and enable_flag <> 1 or dataIn[i] == D.Interfaces.Logic.'U' and enable_flag <> 0 then
        nextstate[i] := D.Interfaces.Logic.'U';
      elseif next_assign_val[i] == T.StrengthMap[D.Interfaces.Logic.'0', strength] and (dataIn[i] == D.Interfaces.Logic.'0' or dataIn[i] == D.Interfaces.Logic.'L' or enable_flag == 0) then
        break;
      elseif (dataIn[i] == D.Interfaces.Logic.'0' or dataIn[i] == D.Interfaces.Logic.'L') and enable_flag == 1 then
        nextstate[i] := T.StrengthMap[D.Interfaces.Logic.'0', strength];
      else
        nextstate[i] := T.StrengthMap[D.Interfaces.Logic.'X', strength];
      end if;
    end if;
  end for;
  next_assign_val := nextstate;
  dataOut := nextstate;

end DLATR;

