  Modelica.Electrical.Polyphase.Basic.Star star(final m = m) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Blocks.Sources.BooleanStep booleanStep[m](each startTime = tStart1) ;
  Modelica.Electrical.Polyphase.Ideal.IdealClosingSwitch idealCloser(final m = m, Ron = fill(1e-5, m), Goff = fill(1e-5, m)) ;
  Modelica.Mechanics.Rotational.Components.Inertia loadInertia(J = JLoad) ;
