  Modelica.Electrical.Machines.Sensors.ElectricalPowerSensor electricalPowerSensor ;
  Modelica.Electrical.Machines.Sensors.CurrentQuasiRMSSensor currentQuasiRMSSensor ;
  Modelica.Electrical.Polyphase.Sources.SineVoltage sineVoltage(final m = m, f = fill(fNominal, m), V = fill(sqrt(2 / 3) * VNominal, m)) ;
  Modelica.Electrical.Polyphase.Basic.Star star(final m = m) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Mechanics.Rotational.Sensors.PowerSensor powerSensor ;
  Modelica.Mechanics.Rotational.Components.Inertia loadInertia(J = aimcData.Jr) ;
  Modelica.Mechanics.Rotational.Sources.Torque torque ;
  Modelica.Blocks.Math.Gain gain(k = -1) ;
  Modelica.Blocks.Continuous.PI PI(k = 0.01, T = 0.01, initType = Modelica.Blocks.Types.Init.InitialState) ;
  Modelica.Blocks.Math.Feedback feedback ;
  Modelica.Blocks.Sources.Ramp ramp(height = 1.2 * PNominal, offset = 0, startTime = 4.5, duration = 5.5) ;
