modelica://Modelica.Electrical/IMC_DCBra:
Modelica.Electrical: IMC_DCBraking (model)

The stator windings of an induction machine are fed by a DC current, causing a stationary current space phasor. Since the rotor is turning, voltage is induced in the rotor cage which in turn drives rotor currents. This creates a braking torque.   
 Choose a layout and plot tauElectrical and tauShaft versus wMechanical.   
Default machine parameters are used.   References  
[Fischer2017] R. Fischer, Elektrische Maschinen, 17 th ed., chapter 5.3.3.,  Hanser , ISBN 978-3-446-45218-3, 2017.

Code:
model IMC_DCBraking "Induction machine with DC current braking"
  extends Modelica.Icons.Example;
  import Modelica.Constants.pi;
  constant Integer m = 3 "Number of phases";
  parameter Modelica.Units.SI.AngularVelocity w0(displayUnit = "rev/min") = 2 * pi * imcData.fsNominal / imcData.p "Initial mechanical speed";
  parameter Modelica.Units.SI.Inertia JLoad = 4 * imcData.Jr "Load's moment of inertia";
  Modelica.Units.SI.Torque tauElectrical = imc.tauElectrical "Electrical torque";
  Modelica.Units.SI.Torque tauShaft = imc.tauShaft "Shaft torque";
  Modelica.Units.SI.AngularVelocity wMechanical(displayUnit = "rev/min") = imc.wMechanical "Shaft speed";
  parameter Modelica.Electrical.Machines.Utilities.DcBrakeSettings settings(INominal = 100, layout = "D3") ;
  parameter Modelica.Electrical.Machines.Utilities.ParameterRecords.IM_SquirrelCageData imcData ;
  Modelica.Electrical.Machines.BasicMachines.InductionMachines.IM_SquirrelCage imc(p = imcData.p, fsNominal = imcData.fsNominal, Rs = imcData.Rs, TsRef = imcData.TsRef, alpha20s(displayUnit = "1/K") = imcData.alpha20s, Lssigma = imcData.Lssigma, Jr = imcData.Jr, Js = imcData.Js, Lszero = imcData.Lszero, frictionParameters = imcData.frictionParameters, phiMechanical(fixed = true, start = 0), wMechanical(fixed = true, start = w0), statorCoreParameters = imcData.statorCoreParameters, strayLoadParameters = imcData.strayLoadParameters, Lm = imcData.Lm, Lrsigma = imcData.Lrsigma, Rr = imcData.Rr, TrRef = imcData.TrRef, TsOperational = 293.15, alpha20r = imcData.alpha20r, TrOperational = 293.15) ;
  Modelica.Mechanics.Rotational.Components.Inertia loadInertia(J = JLoad) ;
  Modelica.Electrical.Machines.Utilities.TerminalBox terminalBox(m = m, terminalConnection = settings.terminalConnection) ;
  Modelica.Electrical.Polyphase.Basic.PlugToPin_p plugToPin1(m = m, k = 1) ;
  Modelica.Electrical.Polyphase.Basic.PlugToPin_p plugToPin2(m = m, k = 2) ;
  Modelica.Electrical.Polyphase.Basic.PlugToPin_p plugToPin3(m = m, k = 3) if settings.connect3 ;
  Modelica.Electrical.Analog.Sources.ConstantCurrent constantCurrent(I = settings.Idc) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
initial equation
  if settings.layout == "Y3" then
    //imc.is[2]=settings.is[2];
    der(imc.is[2]) = 0;
    der(imc.idq_rs[1]) = 0;
    der(imc.idq_rs[2]) = 0;
  end if;
  if settings.layout == "Y2" then
    der(imc.idq_rs[1]) = 0;
    der(imc.idq_rs[2]) = 0;
  end if;
  if settings.layout == "D2" then
    //imc.is[2]=settings.is[2];
    der(imc.is[2]) = 0;
    der(imc.idq_rs[1]) = 0;
    der(imc.idq_rs[2]) = 0;
  end if;
  if settings.layout == "D3" then
    //der(imc.idq_ss[1])=0;
    //der(imc.idq_ss[2])=0;
    der(imc.is[1]) = 0;
    der(imc.is[2]) = 0;
    der(imc.idq_rs[1]) = 0;
    der(imc.idq_rs[2]) = 0;
  end if;
equation
  connect(imc.flange, loadInertia.flange_a) ;
  connect(plugToPin1.pin_p, constantCurrent.n) ;
  connect(plugToPin2.pin_p, constantCurrent.p) ;
  connect(constantCurrent.p, plugToPin3.pin_p) ;
  connect(plugToPin2.plug_p, plugToPin1.plug_p) ;
  connect(plugToPin2.plug_p, plugToPin3.plug_p) ;
  connect(terminalBox.plug_sn, imc.plug_sn) ;
  connect(terminalBox.plug_sp, imc.plug_sp) ;
  connect(plugToPin2.plug_p, terminalBox.plugSupply) ;
  connect(plugToPin2.pin_p, ground.p) ;

end IMC_DCBraking;

