  Modelica.Electrical.Machines.SpacePhasors.Blocks.ToPolar toPolar ;
  Modelica.Blocks.Math.Gain toDeg(k = 180 / pi) ;
  Modelica.Electrical.Machines.Sensors.HallSensor hallSensor(p = smpmData.p) ;
