  Modelica.Thermal.FluidHeatFlow.Sources.VolumeFlow volumeFlow(T0 = TAmbient, constantVolumeFlow = CoolantFlow, m = 0) ;
  Modelica.Thermal.FluidHeatFlow.Components.Pipe cooling(tapT = 0.5, T0 = TAmbient, m = 0, h_g = 0, V_flowLaminar = 0.1, dpLaminar(displayUnit = "Pa") = 0.1, V_flowNominal = 1, dpNominal(displayUnit = "Pa") = 1, T0fixed = false, useHeatPort = true) ;
  Modelica.Thermal.FluidHeatFlow.Sources.Ambient outlet(constantAmbientTemperature = TAmbient, constantAmbientPressure = 0) ;
  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature fixedTemperature(T = TAmbient) ;
protected
  Modelica.Electrical.Machines.Interfaces.DCMachines.ThermalPortDCPM thermalPort ;
public
  parameter Modelica.Electrical.Machines.Utilities.ParameterRecords.DcPermanentMagnetData dcpmData(alpha20a(displayUnit = "1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Copper, TaNominal = 353.15, TaRef = 353.15) ;
equation
  connect(loadInertia.flange_b, loadTorque.flange) ;
  connect(dcpm.flange, loadInertia.flange_a) ;
  connect(armatureVoltage.n, groundArmature.p) ;
  connect(armatureVoltage.p, dcpm.pin_ap) ;
  connect(armatureVoltage.n, dcpm.pin_an) ;
  connect(armature.port, armatureCore.port_a) ;
  connect(armatureCore.port_b, core.port) ;
  connect(core.port, coreCooling.port_a) ;
  connect(pulse.y, loadTorque.tau) ;
  connect(coreCooling.port_b, cooling.heatPort) ;
  connect(cooling.flowPort_b, outlet.flowPort) ;
  connect(inlet.flowPort, volumeFlow.flowPort_a) ;
  connect(volumeFlow.flowPort_b, cooling.flowPort_a) ;
