model SwitchingDcDc "Switching DC-DC inverter"
  parameter Modelica.Units.SI.Frequency fS "Switching frequency";
  parameter Modelica.Units.SI.Voltage VMax "Maximum Voltage";
  parameter Modelica.Units.SI.Resistance RonT = 1e-05 "Transistor closed resistance";
