  parameter Modelica.Units.SI.Conductance GoffD = 1e-05 "Diode opened conductance";
  parameter Modelica.Units.SI.Voltage VkneeD = 0 "Diode threshold voltage";
  Modelica.Electrical.PowerConverters.DCDC.Control.Voltage2DutyCycle adaptor(useConstantVoltageLimit = false, VLim = VMax) ;
  Modelica.Electrical.PowerConverters.DCDC.Control.SignalPWM pwm(useConstantDutyCycle = false, f = fS) ;
