  output Modelica.Units.SI.Current ir[2] = squirrelCageR.i "Rotor cage currents";
  Modelica.Electrical.Machines.BasicMachines.Components.AirGapS airGap(final p = p, final Lm = Lm, final m = m) ;
  parameter Modelica.Units.SI.Inductance Lm(start = 3 * sqrt(1 - 0.0667) / (2 * pi * fsNominal)) "Stator main field inductance per phase" ;
  parameter Modelica.Units.SI.Inductance Lrsigma(start = 3 * (1 - sqrt(1 - 0.0667)) / (2 * pi * fsNominal)) "Rotor stray inductance per phase (equivalent three-phase winding)" ;
