model IM_SlipRing "Induction machine with slipring rotor"
  extends Modelica.Electrical.Machines.Interfaces.PartialBasicInductionMachine(final idq_ss = airGap.i_ss, final idq_sr = airGap.i_sr, final idq_rs = airGap.i_rs, final idq_rr = airGap.i_rr, redeclare final Modelica.Electrical.Machines.Thermal.InductionMachines.ThermalAmbientIMS thermalAmbient(final Tr = TrOperational, final mr = m), redeclare final Modelica.Electrical.Machines.Interfaces.InductionMachines.ThermalPortIMS thermalPort(final mr = m), redeclare final Modelica.Electrical.Machines.Interfaces.InductionMachines.ThermalPortIMS internalThermalPort(final mr = m), redeclare final Modelica.Electrical.Machines.Interfaces.InductionMachines.PowerBalanceIMS powerBalance(final lossPowerRotorWinding = sum(rr.resistor.LossPower), final lossPowerRotorCore = rotorCore.lossPower, final lossPowerBrush = 0, final powerRotor = Modelica.Electrical.Machines.SpacePhasors.Functions.activePower(vr, ir)), statorCore(final w = statorCoreParameters.wRef));
  Modelica.Electrical.Machines.BasicMachines.Components.AirGapS airGap(final p = p, final Lm = Lm, final m = m) ;
  parameter Modelica.Units.SI.Inductance Lm(start = 3 * sqrt(1 - 0.0667) / (2 * pi * fsNominal)) "Stator main field inductance per phase" ;
  parameter Modelica.Units.SI.Inductance Lrsigma(start = 3 * (1 - sqrt(1 - 0.0667)) / (2 * pi * fsNominal)) "Rotor stray inductance per phase w.r.t. rotor side" ;
  parameter Modelica.Units.SI.Inductance Lrzero = Lrsigma "Rotor zero sequence inductance w.r.t. rotor side" ;
  parameter Modelica.Units.SI.Resistance Rr(start = 0.04) "Rotor resistance per phase at TRef w.r.t. rotor side" ;
  parameter Modelica.Units.SI.Temperature TrRef(start = 293.15) "Reference temperature of rotor resistance" ;
  parameter Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20 alpha20r(start = 0) "Temperature coefficient of rotor resistance at 20 degC" ;
  parameter Boolean useTurnsRatio(start = true) "Use turnsRatio or calculate from locked-rotor voltage?";
  parameter Real turnsRatio(final min = Modelica.Constants.small, start = 1) "Effective number of stator turns / effective number of rotor turns" ;
  parameter Modelica.Units.SI.Voltage VsNominal(start = 100) "Nominal stator voltage per phase" ;
  parameter Modelica.Units.SI.Voltage VrLockedRotor(start = 100 * (2 * pi * fsNominal * Lm) / sqrt(Rs ^ 2 + (2 * pi * fsNominal * (Lm + Lssigma)) ^ 2)) "Locked-rotor voltage per phase" ;
  parameter Modelica.Units.SI.Temperature TrOperational(start = 293.15) "Operational temperature of rotor resistance" ;
  parameter Modelica.Electrical.Machines.Losses.CoreParameters rotorCoreParameters(final m = 3, PRef = 0, VRef(start = 1) = 1, wRef(start = 1) = 1) "Rotor core loss parameter record; all parameters refer to rotor side" ;
