  output Modelica.Units.SI.Voltage vr[m] = plug_rp.pin.v - plug_rn.pin.v "Rotor instantaneous voltages";
  output Modelica.Units.SI.Current ir[m] = plug_rp.pin.i "Rotor instantaneous currents";
protected
  final parameter Real internalTurnsRatio = if useTurnsRatio then turnsRatio else VsNominal / VrLockedRotor * (2 * pi * fsNominal * Lm) / sqrt(Rs ^ 2 + (2 * pi * fsNominal * (Lm + Lssigma)) ^ 2);
public
