  Modelica.Electrical.Polyphase.Basic.Resistor rr(final m = m, final R = fill(Rr, m), final T_ref = fill(TrRef, m), final alpha = fill(Modelica.Electrical.Machines.Thermal.convertAlpha(alpha20r, TrRef), m), final useHeatPort = true, final T = fill(TrRef, m)) ;
