  Modelica.Mechanics.Rotational.Sensors.RelSpeedSensor relSpeedSensor ;
  Modelica.Mechanics.Rotational.Components.Fixed fixed if not useSupport ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a support if useSupport "Support at which the reaction torque is acting" ;
equation
  connect(flange_a, torqueSensor.flange_a) ;
  connect(torqueSensor.flange_b, flange_b) ;
  connect(flange_a, relSpeedSensor.flange_b) ;
  connect(relSpeedSensor.flange_a, fixed.flange) ;
  connect(relSpeedSensor.flange_a, support) ;
  connect(relSpeedSensor.w_rel, product.u1) ;
  connect(torqueSensor.tau, product.u2) ;
  connect(product.y, P) ;

end MechanicalPowerSensor;

modelica://Modelica.Electrical/RotorDisp:
Modelica.Electrical: RotorDisplacementAngle (model)

Calculates rotor lagging angle by measuring the stator phase voltages, transforming them to the corresponding space phasor in stator-fixed coordinate system,
 rotating the space phasor to the rotor-fixed coordinate system and calculating the angle of this space phasor. 
 The sensor's housing can be implicitly fixed (useSupport=false).
 If the machine's stator also implicitly fixed (useSupport=false), the angle at the flange is equal to the angle of the machine's rotor against the stator.
 Otherwise, the sensor's support has to be connected to the machine's support.

Code:
model RotorDisplacementAngle "Rotor lagging angle"
  parameter Integer m = 3 "Number of phases" ;
  parameter Integer p(min = 1) "Number of pole pairs";
  parameter Boolean positiveRange = false "Use only positive output range, if true";
  parameter Real threshold(final min = 0) = 0 "Below threshold the voltage is considered as zero";
  parameter Boolean useSupport = false "Use support or fixed housing" ;
  Modelica.Blocks.Interfaces.RealOutput rotorDisplacementAngle(final quantity = "Angle", final unit = "rad") ;
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_p(final m = m) ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_n(final m = m) ;
  Modelica.Electrical.Polyphase.Sensors.VoltageSensor VoltageSensor1(final m = m) ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.ToSpacePhasor ToSpacePhasorVS(final m = m) ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a flange ;
  Modelica.Mechanics.Rotational.Sensors.RelAngleSensor relativeAngleSensor ;
  Modelica.Blocks.Sources.Constant constant_(final k = Modelica.Constants.pi / 2) ;
  Modelica.Blocks.Math.Add add(final k2 = 1, final k1 = p) ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.Rotator rotatorVS2R ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.ToPolar ToPolarVSR ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a support if useSupport "Support at which the reaction torque is acting" ;
  Modelica.Mechanics.Rotational.Components.Fixed fixed if not useSupport ;
  Modelica.Blocks.Math.WrapAngle wrapAngle(final positiveRange = positiveRange) ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.LessThreshold lessThreshold(final threshold = threshold) ;
equation
  connect(plug_p, VoltageSensor1.plug_p) ;
  connect(plug_n, VoltageSensor1.plug_n) ;
  connect(relativeAngleSensor.flange_b, flange) ;
  connect(relativeAngleSensor.flange_a, support) ;
  connect(relativeAngleSensor.flange_a, fixed.flange) ;
  connect(relativeAngleSensor.phi_rel, add.u1) ;
  connect(constant_.y, add.u2) ;
  connect(VoltageSensor1.v, ToSpacePhasorVS.u) ;
  connect(ToSpacePhasorVS.y, rotatorVS2R.u) ;
  connect(rotatorVS2R.y, ToPolarVSR.u) ;
  connect(add.y, rotatorVS2R.angle) ;
  connect(wrapAngle.y, rotorDisplacementAngle) ;
  connect(ToPolarVSR.y, lessThreshold.u) ;
  connect(lessThreshold.y, wrapAngle.u) ;

end RotorDisplacementAngle;

modelica://Modelica.Electrical/HallSenso:
Modelica.Electrical: HallSensor (model)

Simple model of a hall sensor, i.e. measuring the angle of the flange (w.r.t. the optional support), multiplying by the number of phases p to obtain the electrical angle, and adding a correction term i.e. the initial angle of the flange phi0.   
 Note that phi0 has to be set that way, that in shaft position phi0 the flux linkage of phase 1 is a maximum.

Code:
model HallSensor "Hall sensor"
  import Modelica.Constants.pi;
  extends Modelica.Mechanics.Rotational.Interfaces.PartialElementaryOneFlangeAndSupport2;
  parameter Integer p(final min = 1, start = 2) "Number of pole pairs";
  parameter Modelica.Units.SI.Angle phi0 = -pi / p "Initial mechanical angle";
  Modelica.Blocks.Interfaces.RealOutput y(quantity = "Angle", final unit = "rad", displayUnit = "deg") "\"Electrical angle\"" ;
equation
  flange.tau = 0;
  y = rem((flange.phi - phi_support - phi0) * p, 2 * pi);

end HallSensor;

modelica://Modelica.Electrical/SinCosRes:
Modelica.Electrical: SinCosResolver (model)

Simple model of a sin-cos-resolver, i.e. sensing the angle of the flange phi (w.r.t. the optional support) and multiplied by p , providing 4 signals:   
y[1] = offset + amplitude*cos(p*(phi - phi0)) y[2] = offset - amplitude*cos(p*(phi - phi0)) y[3] = offset + amplitude*sin(p*(phi - phi0)) y[4] = offset - amplitude*sin(p*(phi - phi0))  
 Thus the sine and cosine signals have p periods per mechanical revolution. Adding an offset > amplitude , the loss of one track can be determined. Subtracting the negated signal from the signal, the offset is removed and a cosine and a sine with doubled amplitude are accessible. From this signal, the angle within one pole pair of a machine can be determined for field oriented control. Block SinCosEvaluation can be used.   
 This model can be used to export FMUs of drives to develop control strategies in other environments. When switching to a real drive, the same inputs as from the FMU can be used.   
 Note that phi0 has to be set that way, that in shaft position phi0 the flux linkage of phase 1 is a maximum. In order to sense the mechanical angle of the shaft p = 1 has to be set.

Code:
model SinCosResolver "Sin-Cos-Resolver"
  import Modelica.Constants.pi;
  extends Modelica.Mechanics.Rotational.Interfaces.PartialElementaryOneFlangeAndSupport2;
  parameter Integer p(final min = 1, start = 2) "Number of pole pairs";
  parameter Real amplitude = 1 "Amplitude of signals";
  parameter Real offset = 1.5 "Offset of signals";
  parameter Modelica.Units.SI.Angle phi0 = -pi / p "Initial mechanical angle";
  Modelica.Blocks.Interfaces.RealOutput y[4] "Track signals" ;
equation
  flange.tau = 0;
  y[1] = offset + amplitude * cos(p * (flange.phi - phi_support - phi0));
  y[2] = offset - amplitude * cos(p * (flange.phi - phi_support - phi0));
  y[3] = offset + amplitude * sin(p * (flange.phi - phi_support - phi0));
  y[4] = offset - amplitude * sin(p * (flange.phi - phi_support - phi0));

end SinCosResolver;

modelica://Modelica.Electrical/SpacePhas:
Modelica.Electrical: SpacePhasor (model)

Physical transformation of voltages and currents: three-phases <-> space phasors:
 x[k] = X0 + {cos(-(k - 1)/m*2*pi),-sin(-(k - 1)/m*2*pi)}*X[Re,Im]
 and vice versa:
 X0 = sum(x[k])/m
 X[Re,Im] = sum(2/m*{cos((k - 1)/m*2*pi),sin((k - 1)/m*2*pi)}*x[k])
 were x designates three-phase values, X[Re,Im] designates the space phasor and X0 designates the zero sequence system.
  Physical transformation means that both voltages and currents are transformed in both directions.
 Zero-sequence voltage and current are present at pin zero. An additional zero-sequence impedance could be connected between pin zero and pin ground.

Code:
model SpacePhasor "Physical transformation: three-phase <-> space phasors"
  import Modelica.Constants.pi;
  constant Integer m = 3 "Number of phases";
  parameter Real turnsRatio = 1 "Turns ratio";
  Modelica.Units.SI.Voltage v[m] "Instantaneous phase voltages";
  Modelica.Units.SI.Current i[m] "Instantaneous phase currents";
protected
  parameter Real TransformationMatrix[2, m] = 2 / m * {array(cos(+(k - 1) / m * 2 * pi) for k in 1:m), array(+sin(+(k - 1) / m * 2 * pi) for k in 1:m)};
  parameter Real InverseTransformation[m, 2] = array({cos(-(k - 1) / m * 2 * pi), -sin(-(k - 1) / m * 2 * pi)} for k in 1:m);
public
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_p(final m = m) ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_n(final m = m) ;
  Modelica.Electrical.Analog.Interfaces.PositivePin zero ;
  Modelica.Electrical.Analog.Interfaces.NegativePin ground ;
  Modelica.Electrical.Machines.Interfaces.SpacePhasor spacePhasor ;
equation
  v / turnsRatio = plug_p.pin.v - plug_n.pin.v;
  i * turnsRatio = +plug_p.pin.i;
  i * turnsRatio = -plug_n.pin.i;
  m * zero.v = sum(v);
  spacePhasor.v_ = TransformationMatrix * v;
  //v  = fill(zero.v,m) + InverseTransformation*spacePhasor.v_;
  -m * zero.i = sum(i);
  -spacePhasor.i_ = TransformationMatrix * i;
  //-i  = fill(zero.i,m) + InverseTransformation*spacePhasor.i_;
  ground.v = 0;

end SpacePhasor;

