  parameter Modelica.Units.SI.Power PRef(min = 0) = 0 "Reference friction losses at wRef";
  parameter Modelica.Units.SI.AngularVelocity wRef(displayUnit = "rev/min", min = Modelica.Constants.small) "Reference angular velocity that the PRef refer to";
  parameter Real power_w(min = Modelica.Constants.small) = 2 "Exponent of friction torque w.r.t. angular velocity";
  final parameter Modelica.Units.SI.Torque tauRef = if PRef <= 0 then 0 else PRef / wRef "Reference friction torque at reference angular velocity";
  final parameter Real linear = 0.001 "Linear angular velocity range with respect to reference angular velocity";
  final parameter Modelica.Units.SI.AngularVelocity wLinear = linear * wRef "Linear angular velocity range";
  final parameter Modelica.Units.SI.Torque tauLinear = if PRef <= 0 then 0 else tauRef * (wLinear / wRef) ^ power_w "Torque corresponding with linear angular velocity range";

end FrictionParameters;

