model ThermalAmbientIMC "Thermal ambient for induction machine with squirrel cage"
  extends Modelica.Electrical.Machines.Interfaces.InductionMachines.PartialThermalAmbientInductionMachines(redeclare final Modelica.Electrical.Machines.Interfaces.InductionMachines.ThermalPortIMC thermalPort);
