modelica://Modelica.Electrical/PartialBa:
Modelica.Electrical: PartialBasicMachine (model)

Base partial model DC machines: 
main parts of the icon mechanical shaft mechanical support  Besides the mechanical connector flange (i.e., the shaft) the machines have a second mechanical connector support .
 If useSupport = false, it is assumed that the stator is fixed.
 Otherwise reaction torque (i.e., air gap torque, minus acceleration torque for stator's moment of inertia) can be measured at support .
 One may also fix the shaft and let rotate the stator; parameter Js is only of importance when the stator is rotating.

Code:
partial model PartialBasicMachine "Partial model for all machines"
  import Modelica.Constants.pi;
  extends Modelica.Electrical.Machines.Icons.TransientMachine;
  parameter Modelica.Units.SI.Inertia Jr "Rotor's moment of inertia";
  parameter Boolean useSupport = false "Enable / disable (=fixed stator) support" ;
  parameter Modelica.Units.SI.Inertia Js = Jr "Stator's moment of inertia" ;
  parameter Boolean useThermalPort = false "Enable / disable (=fixed temperatures) thermal port" ;
  parameter Modelica.Electrical.Machines.Losses.FrictionParameters frictionParameters "Friction loss parameter record" ;
  output Modelica.Units.SI.Angle phiMechanical(start = 0) = flange.phi - internalSupport.phi "Mechanical angle of rotor against stator";
  output Modelica.Units.SI.AngularVelocity wMechanical(displayUnit = "rev/min", start = 0) = der(phiMechanical) "Mechanical angular velocity of rotor against stator";
  output Modelica.Units.SI.Torque tauElectrical = inertiaRotor.flange_a.tau "Electromagnetic torque";
  output Modelica.Units.SI.Torque tauShaft = -flange.tau "Shaft torque";
  Modelica.Mechanics.Rotational.Interfaces.Flange_a flange "Shaft" ;
  Modelica.Mechanics.Rotational.Components.Inertia inertiaRotor(final J = Jr) ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a support if useSupport "Support at which the reaction torque is acting" ;
  Modelica.Mechanics.Rotational.Components.Inertia inertiaStator(final J = Js) ;
  Modelica.Mechanics.Rotational.Components.Fixed fixed if not useSupport ;
  Modelica.Electrical.Machines.Losses.Friction friction(final frictionParameters = frictionParameters) ;
protected
  Modelica.Mechanics.Rotational.Interfaces.Support internalSupport ;
equation
  connect(inertiaRotor.flange_b, flange) ;
  connect(inertiaStator.flange_b, support) ;
  connect(internalSupport, fixed.flange) ;
  connect(internalSupport, inertiaStator.flange_a) ;
  connect(inertiaRotor.flange_b, friction.flange) ;
  connect(friction.support, internalSupport) ;

end PartialBasicMachine;

Modelica.Electrical: PartialBasicInductionMachine (model)

Partial model for induction machine models

Code:
partial model PartialBasicInductionMachine "Partial model for induction machine"
  final parameter Integer m = 3 "Number of phases" ;
  parameter Integer p(min = 1, start = 2) "Number of pole pairs (Integer)";
  parameter Modelica.Units.SI.Frequency fsNominal(start = 50) "Nominal frequency";
  parameter Modelica.Units.SI.Temperature TsOperational(start = 293.15) "Operational temperature of stator resistance" ;
  parameter Modelica.Units.SI.Resistance Rs(start = 0.03) "Stator resistance per phase at TRef" ;
  parameter Modelica.Units.SI.Temperature TsRef(start = 293.15) "Reference temperature of stator resistance" ;
  parameter Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20 alpha20s(start = 0) "Temperature coefficient of stator resistance at 20 degC" ;
  parameter Modelica.Units.SI.Inductance Lszero = Lssigma "Stator zero sequence inductance" ;
  parameter Modelica.Units.SI.Inductance Lssigma(start = 3 * (1 - sqrt(1 - 0.0667)) / (2 * pi * fsNominal)) "Stator stray inductance per phase" ;
  extends Modelica.Electrical.Machines.Interfaces.PartialBasicMachine(Jr(start = 0.29), frictionParameters(wRef = 2 * pi * fsNominal / p), friction(final useHeatPort = true));
  parameter Modelica.Electrical.Machines.Losses.CoreParameters statorCoreParameters(final m = 3, VRef(start = 100), wRef = 2 * pi * fsNominal) "Stator core loss parameter record; all parameters refer to stator side" ;
  parameter Modelica.Electrical.Machines.Losses.StrayLoadParameters strayLoadParameters(IRef(start = 100), wRef = 2 * pi * fsNominal / p) "Stray load loss parameter record" ;
  replaceable output Modelica.Electrical.Machines.Interfaces.InductionMachines.PartialPowerBalanceInductionMachines powerBalance(final powerStator = Modelica.Electrical.Machines.SpacePhasors.Functions.activePower(vs, is), final powerMechanical = wMechanical * tauShaft, final powerInertiaStator = inertiaStator.J * inertiaStator.a * inertiaStator.w, final powerInertiaRotor = inertiaRotor.J * inertiaRotor.a * inertiaRotor.w, final lossPowerStatorWinding = sum(rs.resistor.LossPower), final lossPowerStatorCore = statorCore.lossPower, final lossPowerStrayLoad = strayLoad.lossPower, final lossPowerFriction = friction.lossPower) "Power balance";
  output Modelica.Units.SI.Voltage vs[m] = plug_sp.pin.v - plug_sn.pin.v "Stator instantaneous voltages";
  output Modelica.Units.SI.Current is[m] = plug_sp.pin.i "Stator instantaneous currents";
  output Modelica.Units.SI.Current i_0_s(stateSelect = StateSelect.prefer) = spacePhasorS.zero.i "Stator zero-sequence current";
  // to be defined in model that extends from this partial (since airgap isn't included here)
  input Modelica.Units.SI.Current idq_ss[2] "Stator space phasor current / stator fixed frame";
  input Modelica.Units.SI.Current idq_sr[2](each stateSelect = StateSelect.prefer) "Stator space phasor current / rotor fixed frame";
  input Modelica.Units.SI.Current idq_rs[2] "Rotor space phasor current / stator fixed frame";
  input Modelica.Units.SI.Current idq_rr[2](each stateSelect = StateSelect.prefer) "Rotor space phasor current / rotor fixed frame";
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_sp(final m = m) "Positive stator plug" ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_sn(final m = m) "Negative stator plug" ;
  Modelica.Electrical.Polyphase.Basic.Resistor rs(final m = m, final R = fill(Rs, m), final T_ref = fill(TsRef, m), final alpha = fill(Modelica.Electrical.Machines.Thermal.convertAlpha(alpha20s, TsRef), m), final useHeatPort = true, final T = fill(TsRef, m)) ;
  Modelica.Electrical.Machines.BasicMachines.Components.Inductor lssigma(final L = fill(Lssigma, 2)) ;
  Modelica.Electrical.Analog.Basic.Inductor lszero(final L = Lszero) ;
  Modelica.Electrical.Machines.Losses.InductionMachines.Core statorCore(final coreParameters = statorCoreParameters, final useHeatPort = true, final turnsRatio = 1) ;
  Modelica.Electrical.Machines.SpacePhasors.Components.SpacePhasor spacePhasorS(final turnsRatio = 1) ;
  Modelica.Electrical.Machines.Losses.InductionMachines.StrayLoad strayLoad(final strayLoadParameters = strayLoadParameters, final useHeatPort = true, final m = m) ;
  replaceable Modelica.Electrical.Machines.Interfaces.InductionMachines.PartialThermalPortInductionMachines thermalPort(final m = m) if useThermalPort ;
  replaceable Modelica.Electrical.Machines.Interfaces.InductionMachines.PartialThermalAmbientInductionMachines thermalAmbient(final useTemperatureInputs = false, final Ts = TsOperational, final m = m) if not useThermalPort ;
protected
  constant Real pi = Modelica.Constants.pi;
  replaceable Modelica.Electrical.Machines.Interfaces.InductionMachines.PartialThermalPortInductionMachines internalThermalPort(final m = m) ;
equation
  connect(spacePhasorS.plug_n, plug_sn) ;
  connect(strayLoad.plug_n, rs.plug_p) ;
  connect(strayLoad.plug_p, plug_sp) ;
  connect(strayLoad.support, internalSupport) ;
  connect(spacePhasorS.plug_p, rs.plug_n) ;
  connect(spacePhasorS.zero, lszero.p) ;
  connect(lszero.n, spacePhasorS.ground) ;
  connect(spacePhasorS.spacePhasor, lssigma.spacePhasor_a) ;
  connect(statorCore.spacePhasor, lssigma.spacePhasor_a) ;
  connect(statorCore.heatPort, internalThermalPort.heatPortStatorCore) ;
  connect(strayLoad.heatPort, internalThermalPort.heatPortStrayLoad) ;
  connect(rs.heatPort, internalThermalPort.heatPortStatorWinding) ;
  connect(friction.heatPort, internalThermalPort.heatPortFriction) ;
  connect(strayLoad.flange, inertiaRotor.flange_b) ;
  connect(internalThermalPort, thermalPort) ;
  connect(thermalAmbient.thermalPort, internalThermalPort) ;

end PartialBasicInductionMachine;

