  Modelica.Electrical.Machines.Losses.DCMachines.Brush brush(final brushParameters = brushParameters, final useHeatPort = true) ;
  Modelica.Electrical.Machines.Losses.DCMachines.Core core(final coreParameters = coreParameters, final useHeatPort = true) ;
  Modelica.Electrical.Machines.Losses.DCMachines.StrayLoad strayLoad(final strayLoadParameters = strayLoadParameters, final useHeatPort = true) ;
  replaceable Modelica.Electrical.Machines.Interfaces.DCMachines.PartialThermalPortDCMachines thermalPort if useThermalPort ;
  replaceable Modelica.Electrical.Machines.Interfaces.DCMachines.PartialThermalAmbientDCMachines thermalAmbient(final useTemperatureInputs = false, final Ta = TaOperational) if not useThermalPort ;
protected
  constant Real pi = Modelica.Constants.pi;
  constant Boolean quasiStatic = false "No electrical transients if true" ;
  parameter Modelica.Units.SI.Voltage ViNominal "Nominal induced Voltage";
  parameter Modelica.Units.SI.MagneticFlux psi_eNominal "Nominal magnetic flux";
  parameter Real turnsRatio = ViNominal / (wNominal * psi_eNominal) "Ratio of armature turns over number of turns of the excitation winding";
  replaceable Modelica.Electrical.Machines.Interfaces.DCMachines.PartialThermalPortDCMachines internalThermalPort ;
equation
  assert(ViNominal > Modelica.Constants.eps, "VaNominal has to be > (Ra[+Rse])*IaNominal");
  connect(la.p, ra.n) ;
  connect(brush.n, pin_an) ;
  connect(pin_ap, strayLoad.p) ;
  connect(strayLoad.n, ra.p) ;
  connect(strayLoad.support, internalSupport) ;
  connect(la.p, core.p) ;
  connect(core.n, brush.p) ;
  connect(core.heatPort, internalThermalPort.heatPortCore) ;
  connect(brush.heatPort, internalThermalPort.heatPortBrush) ;
  connect(strayLoad.heatPort, internalThermalPort.heatPortStrayLoad) ;
  connect(friction.heatPort, internalThermalPort.heatPortFriction) ;
  connect(ra.heatPort, internalThermalPort.heatPortArmature) ;
  connect(inertiaRotor.flange_b, strayLoad.flange) ;
  connect(thermalAmbient.thermalPort, internalThermalPort) ;
  connect(internalThermalPort, thermalPort) ;

end PartialBasicDCMachine;

Modelica.Electrical: PartialBasicTransformer (model)

Partial model of a three-phase transformer, containing primary and secondary resistances and stray inductances, as well as the iron core. Circuit layout (vector group) of primary and secondary windings have to be defined. 
Default values for transformer's parameters (a realistic example) are:

turns ratio n 1
nominal frequency fNominal 50 Hz
nominal voltage per phase 100 V RMS
nominal current per phase 100 A RMS
nominal apparent power 30 kVA
primary resistance R1 0.005 Ohm per phase at reference temperature
reference temperature T1Ref 20 °C
temperature coefficient alpha20_1 0 1/K
primary stray inductance L1sigma 78E-6 H per phase
secondary resistance R2 0.005 Ohm per phase at reference temperature
reference temperature T2Ref 20 °C
temperature coefficient alpha20_2 0 1/K
secondary stray inductance L2sigma 78E-6 H per phase
operational temperature T1Operational 20 °C
operational temperature T2Operational 20 °C
These values give the operational parameters:
nominal voltage drop 0.05 p.u.
nominal copper losses 300 W

Code:
partial model PartialBasicTransformer "Partial model of three-phase transformer"
  extends Modelica.Electrical.Machines.Icons.TransientTransformer;
  final parameter Integer m(min = 1) = 3 "Number of phases" ;
  constant String VectorGroup = "Yy00";
  parameter Real n(start = 1) "Ratio primary voltage (line-to-line) / secondary voltage (line-to-line)";
  parameter Modelica.Units.SI.Resistance R1(start = 5E-3 / (if C1 == "D" then 1 else 3)) "Primary resistance per phase at TRef" ;
  parameter Modelica.Units.SI.Temperature T1Ref(start = 293.15) "Reference temperature of primary resistance" ;
  parameter Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20 alpha20_1(start = 0) "Temperature coefficient of primary resistance at 20 degC" ;
  parameter Modelica.Units.SI.Inductance L1sigma(start = 78E-6 / (if C1 == "D" then 1 else 3)) "Primary stray inductance per phase" ;
  parameter Modelica.Units.SI.Resistance R2(start = 5E-3 / (if C2 == "d" then 1 else 3)) "Secondary resistance per phase at TRef" ;
  parameter Modelica.Units.SI.Temperature T2Ref(start = 293.15) "Reference temperature of secondary resistance" ;
  parameter Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20 alpha20_2(start = 0) "Temperature coefficient of secondary resistance at 20 degC" ;
  parameter Modelica.Units.SI.Inductance L2sigma(start = 78E-6 / (if C2 == "d" then 1 else 3)) "Secondary stray inductance per phase" ;
  parameter Boolean useThermalPort = false "Enable / disable (=fixed temperatures) thermal port" ;
  parameter Modelica.Units.SI.Temperature T1Operational(start = 293.15) "Operational temperature of primary resistance" ;
  parameter Modelica.Units.SI.Temperature T2Operational(start = 293.15) "Operational temperature of secondary resistance" ;
  output Modelica.Electrical.Machines.Interfaces.PowerBalanceTransformer powerBalance(final power1 = Modelica.Electrical.Machines.SpacePhasors.Functions.activePower(v1, i1), final power2 = Modelica.Electrical.Machines.SpacePhasors.Functions.activePower(v2, i2), final lossPower1 = sum(r1.resistor.LossPower), final lossPower2 = sum(r2.resistor.LossPower), final lossPowerCore = 0) "Power balance";
  output Modelica.Units.SI.Voltage v1[m] = plug1.pin.v "Primary voltage";
  output Modelica.Units.SI.Current i1[m] = plug1.pin.i "Primary current";
  output Modelica.Units.SI.Voltage v2[m] = plug2.pin.v "Secondary voltage";
  output Modelica.Units.SI.Current i2[m] = plug2.pin.i "Secondary current";
protected
  constant String C1 = Modelica.Utilities.Strings.substring(VectorGroup, 1, 1);
  constant String C2 = Modelica.Utilities.Strings.substring(VectorGroup, 2, 2);
  parameter Real ni = n * (if C2 == "z" then sqrt(3) else 2) * (if C2 == "d" then 1 else sqrt(3)) / (if C1 == "D" then 1 else sqrt(3));
public
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug1(final m = m) "Primary plug" ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug2(final m = m) "Secondary plug" ;
  Modelica.Electrical.Polyphase.Basic.Resistor r1(final m = m, final R = fill(R1, m), final T_ref = fill(T1Ref, m), final alpha = fill(Modelica.Electrical.Machines.Thermal.convertAlpha(alpha20_1, T1Ref), m), final useHeatPort = true, final T = fill(T1Ref, m)) ;
  Modelica.Electrical.Polyphase.Basic.Inductor l1sigma(final m = m, final L = fill(L1sigma, m)) ;
  Modelica.Electrical.Polyphase.Basic.Resistor r2(final m = m, final R = fill(R2, m), final T_ref = fill(T2Ref, m), final alpha = fill(Modelica.Electrical.Machines.Thermal.convertAlpha(alpha20_2, T2Ref), m), final useHeatPort = true, final T = fill(T2Ref, m)) ;
  Modelica.Electrical.Polyphase.Basic.Inductor l2sigma(final m = m, final L = fill(L2sigma, m)) ;
  Modelica.Electrical.Machines.BasicMachines.Components.IdealCore core(final m = m, final n12 = ni, final n13 = ni) ;
  Modelica.Electrical.Machines.Interfaces.ThermalPortTransformer thermalPort(final m = m) if useThermalPort ;
  Modelica.Electrical.Machines.Thermal.ThermalAmbientTransformer thermalAmbient(final useTemperatureInputs = false, final T1 = T1Operational, final T2 = T2Operational, final m = m) if not useThermalPort ;
protected
  Modelica.Electrical.Machines.Interfaces.ThermalPortTransformer internalThermalPort(final m = m) ;
equation
  connect(r1.plug_n, l1sigma.plug_p) ;
  connect(plug1, r1.plug_p) ;
  connect(thermalPort, internalThermalPort) ;
  connect(thermalAmbient.thermalPort, internalThermalPort) ;
  connect(r1.heatPort, internalThermalPort.heatPort1) ;
  connect(r2.heatPort, internalThermalPort.heatPort2) ;
  connect(r2.plug_p, plug2) ;
  connect(l2sigma.plug_p, r2.plug_n) ;

end PartialBasicTransformer;

