Modelica.Electrical: PartialThermalAmbientInductionMachines (model)

Partial thermal ambience for induction machines

Code:
model PartialThermalAmbientInductionMachines "Partial thermal ambience for induction machines"
  parameter Integer m = 3 "Number of stator phases" ;
  parameter Boolean useTemperatureInputs = false "If true, temperature inputs are used; else, temperatures are constant" ;
  constant Modelica.Units.SI.Temperature TDefault = 293.15 "Default temperature";
  parameter Modelica.Units.SI.Temperature Ts(start = TDefault) "Temperature of stator windings" ;
  output Modelica.Units.SI.HeatFlowRate Q_flowStatorWinding = temperatureStatorWinding.port.Q_flow "Heat flow rate of stator windings";
  output Modelica.Units.SI.HeatFlowRate Q_flowStatorCore = temperatureStatorCore.port.Q_flow "Heat flow rate of stator core losses";
  output Modelica.Units.SI.HeatFlowRate Q_flowRotorCore = temperatureRotorCore.port.Q_flow "Heat flow rate of stator core losses";
  output Modelica.Units.SI.HeatFlowRate Q_flowStrayLoad = temperatureStrayLoad.port.Q_flow "Heat flow rate of stray load losses";
  output Modelica.Units.SI.HeatFlowRate Q_flowFriction = temperatureFriction.port.Q_flow "Heat flow rate of friction losses";
  replaceable Modelica.Electrical.Machines.Interfaces.InductionMachines.PartialThermalPortInductionMachines thermalPort(final m = m) ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedTemperature temperatureStatorWinding ;
  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature temperatureStatorCore(final T = TDefault) ;
  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature temperatureRotorCore(final T = TDefault) ;
  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature temperatureStrayLoad(final T = TDefault) ;
  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature temperatureFriction(final T = TDefault) ;
  Modelica.Blocks.Interfaces.RealInput TStatorWinding(unit = "K") if useTemperatureInputs "Temperature of stator windings" ;
  Modelica.Blocks.Sources.Constant constTs(final k = Ts) if not useTemperatureInputs ;
  Modelica.Thermal.HeatTransfer.Components.ThermalCollector thermalCollectorStator(final m = m) ;
equation
  connect(constTs.y, temperatureStatorWinding.T) ;
  connect(TStatorWinding, temperatureStatorWinding.T) ;
  connect(temperatureStrayLoad.port, thermalPort.heatPortStrayLoad) ;
  connect(temperatureFriction.port, thermalPort.heatPortFriction) ;
  connect(thermalCollectorStator.port_b, temperatureStatorWinding.port) ;
  connect(thermalCollectorStator.port_a, thermalPort.heatPortStatorWinding) ;
  connect(temperatureStatorCore.port, thermalPort.heatPortStatorCore) ;
  connect(temperatureRotorCore.port, thermalPort.heatPortRotorCore) ;

end PartialThermalAmbientInductionMachines;

