  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plugSupply(final m = m) "To be connected with grid" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin starpoint if terminalConnection <> "D" "Star point" ;
equation
  connect(plug_sn, star.plug_p) ;
  connect(plug_sn, delta.plug_n) ;
  connect(delta.plug_p, plug_sp) ;
  connect(plug_sp, plugSupply) ;
  connect(star.pin_n, starpoint) ;

end TerminalBox;

