  Modelica.Electrical.Polyphase.Basic.Resistor rheostat(final m = m, final R = fill(RStart, m)) ;
  Modelica.Electrical.Polyphase.Basic.Star starRheostat(final m = m) ;
  Modelica.Blocks.Sources.BooleanStep booleanStep[m](final startTime = fill(tStart, m), final startValue = fill(false, m)) ;
equation
  connect(plug_p, idealCommutingSwitch.plug_p) ;
  connect(idealCommutingSwitch.plug_n2, plug_n) ;
  connect(rheostat.plug_p, idealCommutingSwitch.plug_n1) ;
  connect(idealCommutingSwitch.plug_n2, star.plug_p) ;
  connect(rheostat.plug_n, starRheostat.plug_p) ;
  connect(starRheostat.pin_n, star.pin_n) ;
  connect(star.pin_n, ground.p) ;
  connect(booleanStep.y, idealCommutingSwitch.control) ;

end SwitchedRheostat;

modelica://Modelica.Electrical/RampedRhe:
Modelica.Electrical: RampedRheostat (model)

Ramped rheostat, used for starting induction motors with slipring rotor:  
The external rotor resistance RStart is reduced to zero, starting at time tStart with a linear ramp tRamp .

Code:
model RampedRheostat "Rheostat with linearly decreasing resistance"
  parameter Integer m = 3 "Number of phases" ;
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_p(final m = m) "To positive rotor plug" ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_n(final m = m) "To negative rotor plug" ;
  parameter Modelica.Units.SI.Resistance RStart "Starting resistance";
  parameter Modelica.Units.SI.Time tStart "Time instance of reducing the rheostat";
  parameter Modelica.Units.SI.Time tRamp "Duration of ramp";
  Modelica.Electrical.Polyphase.Basic.Star star(final m = m) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Electrical.Polyphase.Basic.VariableResistor rheostat(final m = m) ;
  Modelica.Blocks.Sources.Ramp ramp[m](final height = fill(-RStart, m), final duration = fill(tRamp, m), final offset = fill(RStart, m), final startTime = fill(tStart, m)) ;
equation
  connect(plug_p, rheostat.plug_p) ;
  connect(rheostat.plug_n, plug_n) ;
  connect(rheostat.R, ramp.y) ;
  connect(rheostat.plug_n, star.plug_p) ;
  connect(star.pin_n, ground.p) ;

end RampedRheostat;

modelica://Modelica.Electrical/DcBrakeSe:
Modelica.Electrical: DcBrakeSettings (record)

Lets the user choose the layout, and determines the necessary DC current for DC current braking of an induction machine.   
 The icon shows the four layout variants. Phases with half the current are depicted with half the line thickness, phases with zero current are depicted with dashed line.

Code:
record DcBrakeSettings "Setting for DC current braking"
  parameter Modelica.Units.SI.Current INominal = 100 "Nominal RMS current per phase";
  parameter String layout = "Y3" "Braking connection layout" ;
  parameter String terminalConnection = if layout == "Y3" or layout == "Y2" then "Y" else "D" "Terminal connection" ;
  parameter Boolean connect3 = layout == "Y3" or layout == "D3" "Connect 3rd terminal" ;
  parameter Modelica.Units.SI.Current Idc = if layout == "Y3" then INominal * sqrt(2) elseif layout == "Y2" then INominal * sqrt(3 / 2)
   elseif layout == "D2" then INominal * 3 / sqrt(2) else INominal * sqrt(6) "DC braking current" ;
  parameter Modelica.Units.SI.Current is[3] = if layout == "Y3" then Idc * {1, -1 / 2, -1 / 2} elseif layout == "Y2" then Idc * {1, -1, 0}
   elseif layout == "D2" then Idc * {2 / 3, -1 / 3, -1 / 3} else Idc * {1 / 2, -1 / 2, 0} "Phase currents" ;

end DcBrakeSettings;

modelica://Modelica.Electrical/Synchrono:
Modelica.Electrical: SynchronousMachineData (record)

The parameters of the   synchronous machine model with electrical excitation (and damper) are calculated from parameters normally given in a technical description, according to the standard EN 60034-4:2008 Appendix C.

Code:
record SynchronousMachineData "Computes machine parameter from usual datasheet"
  extends Modelica.Icons.Record;
  import Modelica.Constants.pi;
  parameter Modelica.Units.SI.ApparentPower SNominal(start = 30E3) "Nominal apparent power";
  parameter Modelica.Units.SI.Voltage VsNominal(start = 100) "Nominal stator voltage per phase";
  final parameter Modelica.Units.SI.Current IsNominal = SNominal / (3 * VsNominal) "Nominal stator current per phase";
  final parameter Modelica.Units.SI.Impedance ZReference = VsNominal / IsNominal "Reference impedance";
  parameter Modelica.Units.SI.Frequency fsNominal(start = 50) "Nominal stator frequency";
  final parameter Modelica.Units.SI.AngularVelocity omega = 2 * pi * fsNominal "Nominal angular frequency";
  parameter Modelica.Units.SI.Current IeOpenCircuit(start = 10) "Open circuit excitation current @ nominal voltage and frequency";
  parameter Real effectiveStatorTurns = 1 "Effective number of stator turns";
  final parameter Real turnsRatio = sqrt(2) * VsNominal / (omega * Lmd * IeOpenCircuit) "Stator current / excitation current";
  parameter Real x0(start = 0.1) "Stator stray inductance per phase (approximately zero impedance) [pu]";
  parameter Real xd(start = 1.6) "Synchronous reactance per phase, d-axis [pu]";
  parameter Real xq(start = 1.6) "Synchronous reactance per phase, q-axis [pu]";
  parameter Real xdTransient(start = 0.1375) "Transient reactance per phase, d-axis [pu]";
  parameter Real xdSubtransient(start = 0.121428571) "Subtransient reactance per phase, d-axis [pu]";
  parameter Real xqSubtransient(start = 0.148387097) "Subtransient reactance per phase, q-axis [pu]";
  parameter Modelica.Units.SI.Time Ta(start = 0.014171268) "Armature time constant";
  parameter Modelica.Units.SI.Time Td0Transient(start = 0.261177343) "Open circuit field time constant Td0'";
  parameter Modelica.Units.SI.Time Td0Subtransient(start = 0.006963029) "Open circuit subtransient time constant Td0'', d-axis";
  parameter Modelica.Units.SI.Time Tq0Subtransient(start = 0.123345081) "Open circuit subtransient time constant Tq0'', q-axis";
  parameter Modelica.Units.SI.Temperature TsSpecification(start = 293.15) "Specification temperature of stator resistance" ;
  parameter Modelica.Units.SI.Temperature TsRef(start = 293.15) "Reference temperature of stator resistance" ;
  parameter Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20 alpha20s(start = 0) "Temperature coefficient of stator resistance at 20 degC" ;
  parameter Modelica.Units.SI.Temperature TrSpecification(start = 293.15) "Specification temperature of (optional) damper cage" ;
  parameter Modelica.Units.SI.Temperature TrRef(start = 293.15) "Reference temperature of damper resistances in d- and q-axis" ;
  parameter Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20 alpha20r(start = 0) "Temperature coefficient of damper resistances in d- and q-axis" ;
  parameter Modelica.Units.SI.Temperature TeSpecification(start = 293.15) "Specification excitation temperature" ;
  parameter Modelica.Units.SI.Temperature TeRef(start = 293.15) "Reference temperature of excitation resistance" ;
  parameter Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20 alpha20e(start = 0) "Temperature coefficient of excitation resistance" ;
  final parameter Real xmd = xd - x0 "Main field reactance per phase, d-axis [pu]";
  final parameter Real xmq = xq - x0 "Main field reactance per phase, q-axis [pu]";
  final parameter Real xe = xmd ^ 2 / (xd - xdTransient) "Excitation reactance [pu]";
  final parameter Real xrd = xmd ^ 2 / (xdTransient - xdSubtransient) * (1 - xmd / xe) ^ 2 + xmd ^ 2 / xe "Damper reactance per phase, d-axis [pu]";
  final parameter Real xrq = xmq ^ 2 / (xq - xqSubtransient) "Damper reactance per phase, d-axis [pu]";
  final parameter Real rs = 2 / (1 / xdSubtransient + 1 / xqSubtransient) / (omega * Ta) "Stator resistance per phase at specification temperature [pu]";
  final parameter Real rrd = (xrd - xmd ^ 2 / xe) / (omega * Td0Subtransient) "Damper resistance per phase at specification temperature, d-axis [pu]";
  final parameter Real rrq = xrq / (omega * Tq0Subtransient) "Damper resistance per phase at specification temperature, q-axis [pu]";
  final parameter Real re = xe / (omega * Td0Transient) "Excitation resistance per phase at specification temperature [pu]";
  parameter Modelica.Units.SI.Resistance Rs = Modelica.Electrical.Machines.Thermal.convertResistance(rs * ZReference, TsSpecification, alpha20s, TsRef) "Stator resistance per phase at TRef" ;
  parameter Modelica.Units.SI.Inductance Lssigma = x0 * ZReference / omega "Stator stray inductance per phase" ;
  parameter Modelica.Units.SI.Inductance Lmd = xmd * ZReference / omega "Main field inductance per phase in d-axis" ;
  parameter Modelica.Units.SI.Inductance Lmq = xmq * ZReference / omega "Main field inductance per phase in q-axis" ;
  parameter Modelica.Units.SI.Inductance Lrsigmad = (xrd - xmd) * ZReference / omega "Damper stray inductance in d-axis" ;
  parameter Modelica.Units.SI.Inductance Lrsigmaq = (xrq - xmq) * ZReference / omega "Damper stray inductance in q-axis" ;
  parameter Modelica.Units.SI.Resistance Rrd = Modelica.Electrical.Machines.Thermal.convertResistance(rrd * ZReference, TrSpecification, alpha20r, TrRef) "Damper resistance in d-axis at TRef" ;
  parameter Modelica.Units.SI.Resistance Rrq = Modelica.Electrical.Machines.Thermal.convertResistance(rrq * ZReference, TrSpecification, alpha20r, TrRef) "Damper resistance in q-axis at TRef" ;
  parameter Modelica.Units.SI.Resistance Re = 3 / 2 * turnsRatio ^ 2 * Modelica.Electrical.Machines.Thermal.convertResistance(re * ZReference, TeSpecification, alpha20e, TeRef) "Excitation resistance at TRef" ;
  parameter Real sigmae = 1 - xmd / xe "Stray fraction of total excitation inductance" ;

end SynchronousMachineData;

modelica://Modelica.Electrical/Transform:
Modelica.Electrical: TransformerData (record)

The parameters of the transformer models are calculated from parameters normally given in a technical description.

Code:
record TransformerData "Calculates Impedances from nominal values"
  extends Modelica.Icons.Record;
  parameter Modelica.Units.SI.Frequency f(start = 50) "Nominal frequency";
  parameter Modelica.Units.SI.Voltage V1(start = 100) "Primary nominal line-to-line voltage (RMS)";
  parameter String C1(start = "Y") "Choose primary connection" ;
  parameter Modelica.Units.SI.Voltage V2(start = 100) "Secondary open circuit line-to-line voltage (RMS) @ primary nominal voltage";
  parameter String C2(start = "y") "Choose secondary connection" ;
  parameter Modelica.Units.SI.ApparentPower SNominal(start = 30E3) "Nominal apparent power";
  parameter Real v_sc(final min = 0, final max = 1, start = 0.05) "Impedance voltage drop pu";
  parameter Modelica.Units.SI.Power P_sc(start = 300) "Short-circuit (copper) losses";
  parameter Real n = V1 / V2 "Ratio primary voltage (line-to-line) / secondary voltage (line-to-line)" ;
  final parameter Modelica.Units.SI.Voltage V1ph = V1 / (if C1 == "D" then 1 else sqrt(3)) "Primary phase voltage (RMS)";
  final parameter Modelica.Units.SI.Current I1ph = SNominal / (3 * V1ph) "Primary phase current (RMS)";
  final parameter Modelica.Units.SI.Voltage V2ph = V2 / (if C2 == "d" then 1 else sqrt(3)) "Secondary phase voltage (RMS)";
  final parameter Modelica.Units.SI.Current I2ph = SNominal / (3 * V2ph) "Secondary phase current (RMS)";
  final parameter Modelica.Units.SI.Impedance Z1ph = 0.5 * v_sc * V1ph / I1ph "Primary impedance per phase";
  parameter Modelica.Units.SI.Resistance R1 = 0.5 * P_sc / (3 * I1ph ^ 2) "Warm primary resistance per phase" ;
  parameter Modelica.Units.SI.Inductance L1sigma = sqrt(Z1ph ^ 2 - R1 ^ 2) / (2 * Modelica.Constants.pi * f) "Primary stray inductance per phase" ;
  final parameter Modelica.Units.SI.Impedance Z2ph = 0.5 * v_sc * V2ph / I2ph "Secondary impedance per phase";
  parameter Modelica.Units.SI.Resistance R2 = 0.5 * P_sc / (3 * I2ph ^ 2) "Warm secondary resistance per phase" ;
  parameter Modelica.Units.SI.Inductance L2sigma = sqrt(Z2ph ^ 2 - R2 ^ 2) / (2 * Modelica.Constants.pi * f) "Secondary stray inductance per phase" ;

end TransformerData;

