record IM_SlipRingData "Common parameters for induction machines with slip ring"
  extends Modelica.Electrical.Machines.Utilities.ParameterRecords.InductionMachineData;
  import Modelica.Constants.pi;
  parameter Modelica.Units.SI.Inductance Lm = 3 * sqrt(1 - 0.0667) / (2 * pi * fsNominal) "Stator main field inductance per phase" ;
  parameter Modelica.Units.SI.Inductance Lrsigma = 3 * (1 - sqrt(1 - 0.0667)) / (2 * pi * fsNominal) / turnsRatio ^ 2 "Rotor stray inductance per phase w.r.t. rotor side" ;
