  parameter Modelica.Units.SI.Voltage VsNominal = 100 "Nominal stator voltage per phase" ;
  parameter Modelica.Units.SI.Voltage VrLockedRotor = 100 * (2 * pi * fsNominal * Lm) / sqrt(Rs ^ 2 + (2 * pi * fsNominal * (Lm + Lssigma)) ^ 2) "Locked-rotor voltage per phase" ;
  parameter Modelica.Electrical.Machines.Losses.CoreParameters rotorCoreParameters(final m = 3, PRef = 0, VRef = 1, wRef = 1) "Rotor core loss parameter record; all parameters refer to rotor side" ;

