modelica://Modelica.Electrical/Analysato:
Modelica.Electrical: AnalysatorAC (model)

Provides mean of total power over one period as well as the following values for each phase:   
RMS of first harmonic of line-to-line voltage RMS of first harmonic of line-to-neutral voltage RMS of first harmonic of feed current

Code:
model AnalysatorAC "Analyze AC voltage, current and power"
  extends Modelica.Icons.RoundSensor;
  extends Modelica.Electrical.Polyphase.Interfaces.TwoPlug;
  import Modelica.Electrical.Polyphase.Functions.numberOfSymmetricBaseSystems;
  parameter Modelica.Units.SI.Frequency f = 50 "Mains frequency";
  final parameter Integer mSystems = numberOfSymmetricBaseSystems(m) "Number of base systems";
  final parameter Integer mBasic = integer(m / mSystems) "Phase number of base systems";
  final parameter Integer kPolygon = if m == 2 then 1 else integer((mBasic - 1) / 2) "Alternative of largest polygon voltage";
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_nv(final m = m) "Negative polyphase electrical plug with m pins" ;
  Modelica.Blocks.Interfaces.RealOutput pTotal(unit = "W") "Total power, mean" ;
  Modelica.Blocks.Interfaces.RealOutput iFeed[m](each unit = "A") "RMS feed currents, first harmonic" ;
  Modelica.Blocks.Interfaces.RealOutput vLL1[m](each unit = "V") "RMS voltages line-to-line, first harmonic" ;
  Modelica.Blocks.Interfaces.RealOutput vLN[m](each unit = "V") "RMS voltages line-to-neutral, first harmonic" ;
  Modelica.Electrical.Polyphase.Sensors.MultiSensor multiSensorAC(m = m) ;
  Modelica.Electrical.Polyphase.Basic.MultiDelta multiDelta(m = m, kPolygon = kPolygon) ;
  Modelica.Electrical.Polyphase.Sensors.VoltageSensor voltageSensor(m = m) ;
  Modelica.Blocks.Math.Harmonic iH1[m](each f = f, each k = 1) ;
  Modelica.Blocks.Math.Harmonic vH1[m](each f = f, each k = 1) ;
  Modelica.Blocks.Math.Mean powerTotal(f = f) ;
  Modelica.Blocks.Math.Harmonic voltageLine2Line[m](each f = f, each k = 1) "Line-to-line voltage" ;
equation
  connect(plug_p, multiSensorAC.pc) ;
  connect(multiSensorAC.pc, multiSensorAC.pv) ;
  connect(multiSensorAC.nc, plug_n) ;
  connect(multiSensorAC.nv, plug_nv) ;
  connect(multiDelta.plug_p, voltageSensor.plug_p) ;
  connect(multiDelta.plug_n, voltageSensor.plug_n) ;
  connect(plug_p, multiDelta.plug_p) ;
  connect(voltageLine2Line.y_rms, vLL1) ;
