Modelica.Electrical: ThyristorBridge2mPulse_DC_Drive (model)

In this example a PM excited DC machine is started with nominal torque at nominal speed. After 5 seconds, load torque is reduced to zero over a period of additional 10 seconds. At 15 seconds, the machine is operating at no load.   
Plot current currentSensor.i , average current meanCurrent.y , voltage voltageSensor.v and average voltage meanVoltage.v .

Code:
model ThyristorBridge2mPulse_DC_Drive "2*m pulse thyristor bridge feeding a DC drive"
  extends Modelica.Icons.Example;
  import Modelica.Constants.pi;
  parameter Integer m(final min = 3) = 3 "Number of phases" ;
  parameter Modelica.Units.SI.Voltage Vrms = dcpmData.VaNominal / Modelica.Electrical.Polyphase.Functions.factorY2DC(m) "RMS supply voltage";
  parameter Modelica.Units.SI.Frequency f = 50 "Frequency";
  parameter Modelica.Units.SI.ApparentPower SMains = 250E3 "Mains short circuit apparent power";
  parameter Real lamdaMains = 0.1 "Mains short circuit power factor";
  final parameter Modelica.Units.SI.Impedance ZMains = Vrms ^ 2 / SMains * m "Mains short circuit impedance";
  final parameter Modelica.Units.SI.Resistance RMains = ZMains * lamdaMains "Mains resistance" ;
  final parameter Modelica.Units.SI.Inductance LMains = ZMains * sqrt(1 - lamdaMains ^ 2) / (2 * pi * f) "Mains inductance" ;
  parameter Modelica.Units.SI.Inductance Ld = 3 * dcpmData.La "Smoothing inductance" ;
  final parameter Modelica.Units.SI.Torque tauNominal = dcpmData.ViNominal * dcpmData.IaNominal / dcpmData.wNominal "Nominal torque";
  output Modelica.Units.SI.AngularVelocity w(displayUnit = "rpm") = dcpm.wMechanical;
  output Modelica.Units.SI.Torque tau = dcpm.tauShaft;
  Modelica.Electrical.Polyphase.Sources.SineVoltage sinevoltage(m = m, final V = fill(sqrt(2) * Vrms, m), f = fill(f, m)) ;
  Modelica.Electrical.PowerConverters.ACDC.ThyristorBridge2mPulse rectifier(useHeatPort = false, m = m) ;
  Modelica.Electrical.Analog.Sensors.VoltageSensor voltagesensor ;
  Modelica.Blocks.Math.Mean meanVoltage(f = 2 * m * f) ;
  Modelica.Blocks.Math.RootMeanSquare rootMeanSquareVoltage(f = 2 * m * f) ;
  Modelica.Electrical.Analog.Sensors.CurrentSensor currentSensor ;
  Modelica.Blocks.Math.Mean meanCurrent(f = 2 * m * f) ;
  Modelica.Electrical.PowerConverters.ACDC.Control.VoltageBridge2mPulse pulse2(useConstantFiringAngle = false, useFilter = true, m = m) ;
  Modelica.Electrical.Analog.Basic.Inductor inductor(L = Ld) ;
  Modelica.Electrical.Machines.BasicMachines.DCMachines.DC_PermanentMagnet dcpm(VaNominal = dcpmData.VaNominal, IaNominal = dcpmData.IaNominal, wNominal = dcpmData.wNominal, TaNominal = dcpmData.TaNominal, Ra = dcpmData.Ra, TaRef = dcpmData.TaRef, La = dcpmData.La, Jr = dcpmData.Jr, useSupport = false, Js = dcpmData.Js, frictionParameters = dcpmData.frictionParameters, coreParameters = dcpmData.coreParameters, strayLoadParameters = dcpmData.strayLoadParameters, brushParameters = dcpmData.brushParameters, phiMechanical(fixed = true), wMechanical(fixed = true, start = dcpmData.wNominal), TaOperational = 293.15, alpha20a = dcpmData.alpha20a, ia(start = 0, fixed = true)) ;
  parameter Modelica.Electrical.Machines.Utilities.ParameterRecords.DcPermanentMagnetData dcpmData "Data record of PM excited DC machine" ;
  Modelica.Mechanics.Rotational.Sources.Torque torque ;
  Modelica.Blocks.Sources.Ramp ramp(duration = 10, startTime = 5, height = tauNominal, offset = -tauNominal) ;
  Modelica.Blocks.Sources.Constant const(k = 0) ;
  Modelica.Electrical.Polyphase.Basic.Resistor rMains(m = m, R = fill(RMains, m)) ;
  Modelica.Electrical.Polyphase.Basic.Inductor lMains(m = m, L = fill(LMains, m)) ;
  Modelica.Electrical.Polyphase.Basic.MultiStarResistance earthing(m = m) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
initial equation
  lMains.i[1:m - 1] = zeros(m - 1);
equation
  connect(meanCurrent.u, currentSensor.i) ;
  connect(voltagesensor.v, meanVoltage.u) ;
  connect(voltagesensor.v, rootMeanSquareVoltage.u) ;
  connect(rectifier.dc_n, currentSensor.n) ;
  connect(rectifier.dc_p, voltagesensor.p) ;
  connect(voltagesensor.n, currentSensor.p) ;
  connect(pulse2.fire_p, rectifier.fire_p) ;
  connect(pulse2.fire_n, rectifier.fire_n) ;
  connect(inductor.n, dcpm.pin_ap) ;
  connect(torque.flange, dcpm.flange) ;
  connect(ramp.y, torque.tau) ;
  connect(rectifier.dc_p, inductor.p) ;
  connect(currentSensor.p, dcpm.pin_an) ;
  connect(const.y, pulse2.firingAngle) ;
  connect(rMains.plug_p, sinevoltage.plug_p) ;
  connect(lMains.plug_p, rMains.plug_n) ;
  connect(lMains.plug_n, rectifier.ac) ;
  connect(rectifier.ac, pulse2.ac) ;
  connect(sinevoltage.plug_n, earthing.plug) ;
  connect(rectifier.dc_n, ground.p) ;

end ThyristorBridge2mPulse_DC_Drive;

