Code:
partial model Dimmer "Dimmer including control"
  extends Modelica.Electrical.PowerConverters.Icons.ExampleTemplate;
  import Modelica.Constants.pi;
  parameter Modelica.Units.SI.Frequency f = 50 "Source frequency";
  parameter Modelica.Units.SI.Voltage Vrms = 110 "RMS source voltage";
  parameter Modelica.Units.SI.ApparentPower S = 1000 "Load apparent power";
  parameter Real powerFactor(final min = 0, final max = 1) = 0.87 "Load power factor";
  parameter Modelica.Units.SI.Impedance ZLoad = Vrms ^ 2 / S "Load impedance";
  parameter Modelica.Units.SI.Resistance RLoad = ZLoad * powerFactor "Load resistance";
  parameter Modelica.Units.SI.Inductance LLoad = ZLoad * sqrt(1 - powerFactor ^ 2) / (2 * pi * f) "Load inductance";
  Modelica.Electrical.Analog.Sources.SineVoltage sineVoltage(final V = sqrt(2) * Vrms, f = f) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Electrical.PowerConverters.ACAC.SinglePhaseTriac triac(Ron = 1e-9, Goff = 1e-9) ;
  Modelica.Electrical.Analog.Sensors.VoltageSensor voltageSensor ;
  Modelica.Electrical.PowerConverters.ACDC.Control.Signal2mPulse adaptor(m = 1, useConstantFiringAngle = false, f = f) ;
  Modelica.Electrical.Analog.Sensors.MultiSensor multiSensor ;
  Modelica.Electrical.PowerConverters.ACAC.Control.VoltageToAngle voltageToAngle(VNominal = 1, voltage2Angle = Modelica.Electrical.PowerConverters.Types.Voltage2AngleType.RMS) ;
  Modelica.Blocks.Sources.Trapezoid trapezoid(amplitude = 1, rising = 2, width = 2, falling = 2, period = 8, nperiod = 1, offset = 0, startTime = 1) ;
  Modelica.Blocks.Math.Mean meanPower(f = f) ;
  Modelica.Blocks.Math.RootMeanSquare vRMS(f = f) ;
  Modelica.Blocks.Math.Harmonic vH01(f = f, k = 1) ;
  Modelica.Blocks.Math.RootMeanSquare iRMS(f = f) ;
  Modelica.Blocks.Math.Harmonic iH01(f = f, k = 1) ;
equation
  connect(sineVoltage.n, ground.p) ;
  connect(ground.p, voltageSensor.n) ;
  connect(voltageSensor.v, adaptor.v[1]) ;
  connect(sineVoltage.p, triac.p) ;
  connect(triac.p, voltageSensor.p) ;
  connect(adaptor.fire_p[1], triac.fire1) ;
  connect(adaptor.fire_n[1], triac.fire2) ;
  connect(triac.n, multiSensor.pc) ;
  connect(multiSensor.pc, multiSensor.pv) ;
  connect(voltageToAngle.firingAngle, adaptor.firingAngle) ;
  connect(trapezoid.y, voltageToAngle.vRef) ;
  connect(multiSensor.power, meanPower.u) ;
  connect(ground.p, multiSensor.nv) ;
  connect(multiSensor.i, iRMS.u) ;
  connect(multiSensor.i, iH01.u) ;
  connect(multiSensor.v, vRMS.u) ;
  connect(multiSensor.v, vH01.u) ;

end Dimmer;

