model DiodeBridge2Pulse "Two pulse Graetz diode rectifier bridge"
  extends Modelica.Electrical.PowerConverters.Icons.Converter;
  import Modelica.Constants.pi;
  parameter Modelica.Units.SI.Resistance RonDiode(final min = 0) = 1e-05 "Closed diode resistance";
  parameter Modelica.Units.SI.Conductance GoffDiode(final min = 0) = 1e-05 "Opened diode conductance";
  parameter Modelica.Units.SI.Voltage VkneeDiode(final min = 0) = 0 "Diode forward threshold voltage";
  extends Modelica.Electrical.PowerConverters.Interfaces.ACDC.ACtwoPin;
  extends Modelica.Electrical.PowerConverters.Interfaces.ACDC.DCtwoPin;
  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort(final T = 293.15);
  Modelica.Electrical.Analog.Ideal.IdealDiode diode_p1(final Goff = GoffDiode, final Vknee = VkneeDiode, final useHeatPort = useHeatPort, final Ron = RonDiode) "Diode connecting the positive AC input pin with positive DC output" ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode_p2(final Ron = RonDiode, final Goff = GoffDiode, final Vknee = VkneeDiode, final useHeatPort = useHeatPort) "Diode connecting the negative AC input pin with positive DC output" ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode_n1(final Ron = RonDiode, final Goff = GoffDiode, final Vknee = VkneeDiode, final useHeatPort = useHeatPort) "Diode connecting the positive AC input pin with negative DC output" ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode_n2(final Ron = RonDiode, final Goff = GoffDiode, final Vknee = VkneeDiode, final useHeatPort = useHeatPort) "Diode connecting the negative AC input pin with negative DC output" ;
equation
  if not useHeatPort then
    LossPower = diode_p1.LossPower + diode_p2.LossPower + diode_n1.LossPower + diode_n2.LossPower;
  end if;
  connect(diode_p2.n, diode_p1.n) ;
  connect(diode_n1.p, diode_n2.p) ;
  connect(diode_n2.n, diode_p2.p) ;
  connect(diode_p1.p, diode_n1.n) ;
  connect(diode_p1.n, dc_p) ;
  connect(diode_n1.p, dc_n) ;
  connect(diode_n1.heatPort, heatPort) ;
  connect(diode_n2.heatPort, heatPort) ;
  connect(diode_p1.heatPort, heatPort) ;
  connect(diode_p2.heatPort, heatPort) ;
  connect(ac_p, diode_p1.p) ;
  connect(ac_n, diode_p2.p) ;

end DiodeBridge2Pulse;

