  parameter Modelica.Units.SI.Conductance GoffTransistor = 1e-05 "Transistor opened conductance";
  parameter Modelica.Units.SI.Voltage VkneeTransistor = 0 "Transistor threshold voltage";
  parameter Modelica.Units.SI.Resistance RonDiode = 1e-05 "Diode closed resistance";
  parameter Modelica.Units.SI.Conductance GoffDiode = 1e-05 "Diode opened conductance";
  parameter Modelica.Units.SI.Voltage VkneeDiode = 0 "Diode threshold voltage";
  // parameter Boolean useEnable "Enables enable signal connector";
  extends Modelica.Electrical.PowerConverters.Interfaces.DCAC.DCtwoPin;
  extends Modelica.Electrical.PowerConverters.Interfaces.DCAC.ACpin;
  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort(final T = 293.15);
  extends Modelica.Electrical.PowerConverters.Interfaces.Enable.Enable2;
  Modelica.Electrical.Analog.Ideal.IdealGTOThyristor transistor_p(final Ron = RonTransistor, final Goff = GoffTransistor, final Vknee = VkneeTransistor, final useHeatPort = useHeatPort) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode_p(final Ron = RonDiode, final Goff = GoffDiode, final Vknee = VkneeDiode, final useHeatPort = useHeatPort) ;
  Modelica.Electrical.Analog.Ideal.IdealGTOThyristor transistor_n(final Ron = RonTransistor, final Goff = GoffTransistor, final Vknee = VkneeTransistor, final useHeatPort = useHeatPort) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode_n(final Ron = RonDiode, final Goff = GoffDiode, final Vknee = VkneeDiode, final useHeatPort = useHeatPort) ;
equation
  if not useHeatPort then
    LossPower = transistor_p.LossPower + diode_n.LossPower + transistor_n.LossPower + diode_n.LossPower;
  end if;
  connect(transistor_p.p, dc_p) ;
  connect(transistor_n.n, dc_n) ;
  connect(transistor_p.p, diode_p.n) ;
  connect(transistor_p.n, diode_p.p) ;
  connect(transistor_n.p, diode_n.n) ;
  connect(transistor_n.n, diode_n.p) ;
  connect(transistor_p.n, transistor_n.p) ;
  connect(ac, transistor_p.n) ;
  connect(transistor_p.heatPort, heatPort) ;
  connect(transistor_n.heatPort, heatPort) ;
  connect(diode_p.heatPort, heatPort) ;
  connect(diode_n.heatPort, heatPort) ;
  connect(andCondition_p.y, transistor_p.fire) ;
  connect(andCondition_n.y, transistor_n.fire) ;

end SinglePhase2Level;

