  Modelica.Blocks.Math.Gain gain_v(final k = 1 / VNominal) ;
  Modelica.Blocks.Nonlinear.Limiter limiter(final uMax = 1, final uMin = 0) ;
  Modelica.Blocks.Tables.CombiTable1Ds combiTable1Ds(final table = if voltage2Angle == Modelica.Electrical.PowerConverters.Types.Voltage2AngleType.Lin then Lin elseif voltage2Angle == Modelica.Electrical.PowerConverters.Types.Voltage2AngleType.H01 then H01 else RMS, final extrapolation = Modelica.Blocks.Types.Extrapolation.HoldLastPoint) ;
