  constant Real RMS[:, 2] = [0, 1; 0.000906877, 0.995; 0.002564847, 0.99; 0.004711343, 0.985; 0.007252334, 0.98; 0.010133194, 0.975; 0.028608003, 0.95; 0.052394349, 0.925; 0.080318563, 0.9; 0.111626433, 0.875; 0.14574274, 0.85; 0.182186463, 0.825; 0.22053266, 0.8; 0.260393008, 0.775; 0.301405137, 0.75; 0.343226628, 0.725; 0.385531651, 0.7; 0.428009237, 0.675; 0.470362569, 0.65; 0.51230895, 0.625; 0.553580231, 0.6; 0.593923537, 0.575; 0.633102218, 0.55; 0.670896923, 0.525; 0.707106781, 0.5; 0.741550618, 0.475; 0.774068203, 0.45; 0.804521493, 0.425; 0.83279585, 0.4; 0.858801222, 0.375; 0.882473259, 0.35; 0.903774359, 0.325; 0.922694611, 0.3; 0.939252619, 0.275; 0.953496168, 0.25; 0.965502709, 0.225; 0.975379591, 0.2; 0.983263999, 0.175; 0.989322523, 0.15; 0.99375024, 0.125; 0.996769245, 0.1; 0.998626473, 0.075; 0.999590707, 0.05; 0.999948658, 0.025; 0.999973701, 0.02; 0.999988902, 0.015; 0.999996711, 0.01; 0.999999589, 0.005; 1, 0];
