  Modelica.ComplexBlocks.ComplexMath.PolarToComplex polarToComplex ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToPolar complexToPolar ;
equation
  connect(currentSource.pin_n, resistor.pin_p) ;
  connect(currentSource.pin_n, inductor.pin_p) ;
  connect(currentSource.pin_n, capacitor.pin_p) ;
  connect(currentSource.pin_n, voltageSensor.pin_p) ;
  connect(currentSource.pin_p, ground.pin) ;
  connect(resistor.pin_n, ground.pin) ;
  connect(inductor.pin_n, ground.pin) ;
  connect(capacitor.pin_n, ground.pin) ;
  connect(voltageSensor.pin_n, ground.pin) ;
  connect(f.y, currentSource.f) ;
  connect(polarToComplex.y, currentSource.I) ;
  connect(phi.y, polarToComplex.phi) ;
  connect(I.y, polarToComplex.len) ;
  connect(voltageSensor.v, complexToPolar.u) ;

end ParallelResonance;

modelica://Modelica.Electrical/Rectifier:
Modelica.Electrical: Rectifier (model)

This example demonstrates coupling a quasi-static circuit with a DC circuit. The QS voltage is rectified (using an   ideal AC DC converter ), loaded by a variable load conductor. The conversionFactor = DC voltage / AC rms voltage in this case is the root mean square of a rectified sine, i.e., 1. You may compare the quasi-static results with that of a fully transient model (using a   Graetz rectifier ), plotting:   
QS: AC rms current = iQS.len AC: AC instantaneous current = iAC.u AC: AC rms current = iAC.y_rms QS: DC current = iDC1.i AC: DC instantaneous current = iDC2.u AC: DC rms current = iDC2.y  
 It can be seen that at the DC side the current is represented by its averaged value, at the AC side by its rms value.    Note  
 The quasi-static model needs a grounding at the QS side as well as the DC side, whereas the transient model may have only one ground since AC side and DC side are connected via the diodes.

Code:
model Rectifier "Rectifier example"
  extends Modelica.Icons.Example;
  import Modelica.Constants.pi;
  parameter Modelica.Units.SI.Voltage VAC = 100 "AC rms voltage";
  parameter Real conversionFactor = 1 "Ratio of DC voltage / AC rms voltage";
  output Modelica.Units.SI.Current Itr = iAC.y_rms "Transient current";
  output Modelica.Units.SI.Current Iqs = iQS.len "QS current";
  Modelica.Electrical.QuasiStatic.SinglePhase.Sources.VoltageSource voltageQS(f = 50, V = VAC, phi = 0, i(re(start = 0), im(start = 0)), gamma(fixed = true, start = 0)) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Resistor resistorQS(R_ref = 50E-3) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.CurrentSensor currentSensorQS ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToPolar iQS ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground groundQS ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Utilities.IdealACDCConverter rectifierQS(conversionFactor = conversionFactor) ;
  Modelica.Electrical.Analog.Basic.Ground groundDC1 ;
  Modelica.Electrical.Analog.Sensors.CurrentSensor iDC1 ;
  Modelica.Electrical.Analog.Basic.VariableConductor load1 ;
  Modelica.Electrical.Analog.Sources.SineVoltage voltageAC(V = sqrt(2) * VAC, f = 50, phase = pi / 2) ;
  Modelica.Electrical.Analog.Basic.Resistor resistorAC(R = 50E-3) ;
  Modelica.Electrical.Analog.Sensors.CurrentSensor currentSensorAC ;
  Modelica.Blocks.Math.Harmonic iAC(f = 50, k = 1) ;
  Modelica.Electrical.Analog.Basic.Ground groundAC ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Utilities.GraetzRectifier rectifierAC ;
  Modelica.Electrical.Analog.Sensors.CurrentSensor currentSensorDC2 ;
  Modelica.Blocks.Math.RootMeanSquare iDC2(f = 50) ;
  Modelica.Electrical.Analog.Basic.VariableConductor load2 ;
  Modelica.Blocks.Sources.Ramp ramp(height = 1, duration = 0.8, startTime = 0.1) ;
equation
  connect(voltageQS.pin_p, resistorQS.pin_p) ;
  connect(voltageQS.pin_n, rectifierQS.pin_nQS) ;
  connect(rectifierQS.pin_nQS, groundQS.pin) ;
  connect(rectifierQS.pin_nDC, groundDC1.p) ;
  connect(load1.n, rectifierQS.pin_nDC) ;
  connect(voltageAC.p, resistorAC.p) ;
  connect(voltageAC.n, rectifierAC.pin_nAC) ;
  connect(rectifierAC.pin_nAC, groundAC.p) ;
  connect(rectifierAC.pin_nDC, load2.n) ;
  connect(ramp.y, load1.G) ;
  connect(ramp.y, load2.G) ;
  connect(resistorQS.pin_n, currentSensorQS.pin_p) ;
  connect(currentSensorQS.pin_n, rectifierQS.pin_pQS) ;
  connect(currentSensorQS.i, iQS.u) ;
  connect(rectifierQS.pin_pDC, iDC1.p) ;
  connect(iDC1.n, load1.p) ;
  connect(resistorAC.n, currentSensorAC.p) ;
  connect(currentSensorAC.n, rectifierAC.pin_pAC) ;
  connect(currentSensorAC.i, iAC.u) ;
  connect(currentSensorDC2.i, iDC2.u) ;
  connect(currentSensorDC2.p, rectifierAC.pin_pDC) ;
  connect(currentSensorDC2.n, load2.p) ;

end Rectifier;

modelica://Modelica.Electrical/Transform:
Modelica.Electrical: Transformer (model)

This examples shows the operational behavior of transformer with short circuit impedance. The transformer is loaded with constant current magnitude of 250A but variable phase angle. The angle varies from 0 to 360 degrees within one second of simulation time.   
Transformer data  
Nominal primary voltage V1N = 1000 V Nominal secondary voltage V2N = 200 V Nominal apparent power SN = 50 kVA Short circuit impedance Z k = 0.72 Ohm + j*0.96 Ohm Magnetizing current and core loss are not taken into account  
Plot the real part of the secondary voltage idealTransformer.v2.re on the x axis and idealTransformer.v2.im on the y axis. The locus of this complex voltage v 2 is a circle. The center of the circle is the primary supply voltage divided by the transformation ratio of n=5 . Since in this experiment the load current magnitude is constant, the voltage drop across the short circuit impedance of the transformer is constant, as well. The radius of the circle is equal to the constant magnitude of the voltage drop across the short circuit impedance.

Code:
model Transformer "Example of transformer with short circuit impedance, transmission resistances and load"
  extends Modelica.Icons.Example;
  Modelica.Electrical.QuasiStatic.SinglePhase.Sources.VoltageSource voltageSource(f = 50, V = 1000, phi = 0, gamma(fixed = true, start = 0)) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Ideal.IdealTransformer idealTransformer(n = 5) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.PowerSensor sensor0 ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Impedance zk(Z_ref(re = 0.72, im = 0.96)) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Sources.VariableCurrentSource load(gamma(fixed = true, start = 0)) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.PowerSensor sensorL ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground1 ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground ground2 ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.VoltageSensor v2 ;
  Modelica.ComplexBlocks.ComplexMath.PolarToComplex polarToComplex ;
  Modelica.Blocks.Sources.Constant const(k = 250) ;
  Modelica.Blocks.Sources.Ramp ramp(duration = 1, offset = 0, startTime = 0, height = 2 * Modelica.Constants.pi) ;
  Modelica.Blocks.Sources.Constant constFrequency(k = 50) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.CurrentSensor i2 ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.CurrentSensor i1 ;
equation
  connect(voltageSource.pin_p, sensor0.currentP) ;
  connect(zk.pin_n, idealTransformer.pin_p1) ;
  connect(sensorL.voltageP, sensorL.currentP) ;
  connect(voltageSource.pin_n, ground1.pin) ;
  connect(ground1.pin, idealTransformer.pin_n1) ;
  connect(sensor0.currentP, sensor0.voltageP) ;
  connect(sensor0.voltageN, ground1.pin) ;
  connect(v2.pin_n, ground2.pin) ;
  connect(const.y, polarToComplex.len) ;
  connect(ramp.y, polarToComplex.phi) ;
  connect(load.pin_p, sensorL.currentN) ;
  connect(sensorL.voltageN, ground2.pin) ;
  connect(load.pin_n, ground2.pin) ;
  connect(ground2.pin, idealTransformer.pin_n2) ;
  connect(load.I, polarToComplex.y) ;
  connect(load.f, constFrequency.y) ;
  connect(sensorL.currentP, v2.pin_p) ;
  connect(i2.pin_n, sensorL.currentP) ;
  connect(sensor0.currentN, i1.pin_p) ;
  connect(i1.pin_n, zk.pin_p) ;
  connect(idealTransformer.pin_p2, i2.pin_p) ;

end Transformer;

