  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort(T = T_ref);
  Modelica.ComplexBlocks.Interfaces.ComplexInput Z_ref "Variable complex impedance" ;
  parameter Boolean frequencyDependent = false "Consider frequency dependency, if true" ;
  parameter Modelica.Units.SI.Frequency f_ref = 1 "Reference frequency, if frequency dependency is considered" ;
  Modelica.Units.SI.Resistance R_actual "Resistance = R_ref*(1 + alpha_ref*(heatPort.T - T_ref))";
  Modelica.Units.SI.Reactance X_actual "Reactance considering possible frequency dependency";
  Modelica.Units.SI.Resistance R_ref = real(Z_ref) "Resistive component of impedance, resistance";
  Modelica.Units.SI.Reactance X_ref = imag(Z_ref) "Reactive component of impedance, reactance";
equation
  assert(1 + alpha_ref * (T_heatPort - T_ref) >= Modelica.Constants.eps, "Temperature outside scope of model!");
  R_actual = R_ref * (1 + alpha_ref * (T_heatPort - T_ref));
  X_actual = X_ref * (if not frequencyDependent then 1 else if X_ref >= 0 then omega / (2 * Modelica.Constants.pi * f_ref) else 2 * Modelica.Constants.pi * f_ref / omega);
  v = Complex(R_actual, X_actual) * i;
  LossPower = real(v * conj(i));

end VariableImpedance;

modelica://Modelica.Electrical/VariableA:
Modelica.Electrical: VariableAdmittance (model)

The admittance model represents a parallel connection of a conductor and either a capacitor or inductor.

 The linear admittance connects the complex voltage v with the complex current i by v * Y = i . The admittance Y_ref = G_ref + j*B_ref is given as complex input signal, representing the resistive and reactive component of the input admittance. The resistive component is modeled temperature dependent, so the real part G_actual = real( Y ) is determined from the actual operating temperature and the reference input conductance real(Y_ref) . The reactive component B_actual = imag( Y )  is equal to imag(Y_ref) if frequencyDependent = false . Frequency dependency is considered by frequencyDependent = true , distinguishing two cases:    (a) imag(Y_ref) > 0 : capacitive case The actual susceptance B_actual is proportional to f/f_ref (b) imag(Y_ref) < 0 : inductive case The actual susceptance B_actual is proportional to f_ref/f   Note  
 A zero crossing of the real or imaginary part of the admittance signal Y_ref could cause singularities due to the actual structure of the connected network.    See also  
  Resistor ,  Conductor ,  Capacitor ,  Inductor ,  Impedance ,  Admittance ,  Variable resistor ,  Variable conductor ,  Variable capacitor ,  Variable inductor ,  Variable impedance

Code:
model VariableAdmittance "Single-phase variable admittance"
  extends Modelica.Electrical.QuasiStatic.SinglePhase.Interfaces.OnePort;
  import Modelica.ComplexMath.real;
  import Modelica.ComplexMath.imag;
  import Modelica.ComplexMath.conj;
  parameter Modelica.Units.SI.Temperature T_ref = 293.15 "Reference temperature";
  parameter Modelica.Units.SI.LinearTemperatureCoefficient alpha_ref = 0 "Temperature coefficient of resistance (R_actual = R_ref*(1 + alpha_ref*(heatPort.T - T_ref))";
  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort(T = T_ref);
  Modelica.ComplexBlocks.Interfaces.ComplexInput Y_ref "Variable complex admittance" ;
  parameter Boolean frequencyDependent = false "Consider frequency dependency, if true" ;
  parameter Modelica.Units.SI.Frequency f_ref = 1 "Reference frequency, if frequency dependency is considered" ;
  Modelica.Units.SI.Conductance G_actual "Resistance = R_ref*(1 + alpha_ref*(heatPort.T - T_ref))";
  Modelica.Units.SI.Susceptance B_actual "Susceptance considering possible frequency dependency";
  Modelica.Units.SI.Conductance G_ref = real(Y_ref) "Resistive component of conductance";
  Modelica.Units.SI.Susceptance B_ref = imag(Y_ref) "Reactive component of susceptance";
equation
  assert(1 + alpha_ref * (T_heatPort - T_ref) >= Modelica.Constants.eps, "Temperature outside scope of model!");
  G_actual = G_ref / (1 + alpha_ref * (T_heatPort - T_ref));
  B_actual = B_ref * (if not frequencyDependent then 1 else if B_ref >= 0 then omega / (2 * Modelica.Constants.pi * f_ref) else 2 * Modelica.Constants.pi * f_ref / omega);
  i = Complex(G_actual, B_actual) * v;
  LossPower = real(v * conj(i));

end VariableAdmittance;

