model PowerSensor "Power sensor"
  import Modelica.ComplexMath.conj;
  extends Modelica.Icons.RoundSensor;
  Modelica.Electrical.QuasiStatic.SinglePhase.Interfaces.PositivePin currentP ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Interfaces.NegativePin currentN ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Interfaces.PositivePin voltageP ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Interfaces.NegativePin voltageN ;
  output Modelica.Units.SI.ComplexCurrent i;
  output Modelica.Units.SI.ComplexVoltage v;
  Modelica.ComplexBlocks.Interfaces.ComplexOutput apparentPower(re(unit = "W"), im(unit = "var")) "Complex apparent power = active power + j * reactive power" ;
  Modelica.Units.SI.ApparentPower abs_apparentPower = Modelica.ComplexMath.abs(apparentPower) "Magnitude of complex apparent power";
  Modelica.Units.SI.Angle arg_apparentPower = Modelica.ComplexMath.arg(apparentPower) "Argument of complex apparent power";
equation
  Connections.branch(currentP.reference, currentN.reference);
  currentP.reference.gamma = currentN.reference.gamma;
  Connections.branch(voltageP.reference, voltageN.reference);
  voltageP.reference.gamma = voltageN.reference.gamma;
  Connections.branch(currentP.reference, voltageP.reference);
  currentP.reference.gamma = voltageP.reference.gamma;
  currentP.i + currentN.i = Complex(0);
  currentP.v - currentN.v = Complex(0);
  i = currentP.i;
  voltageP.i + voltageN.i = Complex(0);
  voltageP.i = Complex(0);
  v = voltageP.v - voltageN.v;
  //P + j*Q = v * conj(i);
  apparentPower = v * conj(i);

end PowerSensor;

modelica://Modelica.Electrical/MultiSens:
Modelica.Electrical: MultiSensor (model)

This multi sensor measures current, voltage and instantaneous electrical power of a single-phase system and has a separated voltage and current path. The pins of the voltage path are pv and nv, the pins of the current path are pc and nc. The internal resistance of the current path is zero, the internal resistance of the voltage path is infinite.   See also  
