model MultiSensor "Sensor to measure current, voltage and power"
  extends Modelica.Icons.RoundSensor;
  import Modelica.ComplexMath.conj;
  import Modelica.ComplexMath.abs;
  import Modelica.ComplexMath.arg;
  Modelica.Electrical.QuasiStatic.SinglePhase.Interfaces.PositivePin pc "Positive pin, current path" ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Interfaces.NegativePin nc "Negative pin, current path" ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Interfaces.PositivePin pv "Positive pin, voltage path" ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Interfaces.NegativePin nv "Negative pin, voltage path" ;
  Modelica.ComplexBlocks.Interfaces.ComplexOutput i(redeclare final Modelica.Units.SI.Current re, redeclare final Modelica.Units.SI.Current im) "Current as complex output signal" ;
  Modelica.ComplexBlocks.Interfaces.ComplexOutput v(redeclare final Modelica.Units.SI.Voltage re, redeclare final Modelica.Units.SI.Voltage im) "Voltage as complex output signal" ;
  Modelica.ComplexBlocks.Interfaces.ComplexOutput apparentPower(redeclare final Modelica.Units.SI.ActivePower re, redeclare final Modelica.Units.SI.ReactivePower im) "Instantaneous apparent power as complex output signal" ;
  output Modelica.Units.SI.Current abs_i = abs(i) "Absolute of complex current";
  output Modelica.Units.SI.Angle arg_i = arg(i) "Argument of complex current";
  output Modelica.Units.SI.Voltage abs_v = abs(v) "Absolute of complex voltage";
  output Modelica.Units.SI.Angle arg_v = arg(v) "Argument of complex voltage";
  output Modelica.Units.SI.ApparentPower abs_apparentPower = abs(apparentPower) "Absolute of complex apparent power";
  output Modelica.Units.SI.Angle arg_apparentPower = arg(apparentPower) "Argument of complex apparent power";
equation
  Connections.branch(pc.reference, nc.reference);
  pc.reference.gamma = nc.reference.gamma;
  Connections.branch(pv.reference, nv.reference);
  pv.reference.gamma = nv.reference.gamma;
  Connections.branch(pc.reference, pv.reference);
  pc.reference.gamma = pv.reference.gamma;
  pc.i + nc.i = Complex(0);
  pc.v - nc.v = Complex(0);
  pv.i = Complex(0);
  nv.i = Complex(0);
  i = pc.i;
  v = pv.v - nv.v;
  apparentPower = v * conj(i);

end MultiSensor;

