modelica://Modelica.Electrical/Transform:
Modelica.Electrical: TransformerTestbench (model)

Transformer test bench:
 You may choose different connections as well as vary the load (even not symmetrical).
  Please pay attention to proper grounding of the primary and secondary part of the whole circuit.
 The primary and secondary starpoint are available as connectors, if the connection is not delta (D or d).
 In some cases it may be necessary to ground the transformer's starpoint even though the source's or load's starpoint are grounded; you may use a reasonable high earthing resistance.

Code:
model TransformerTestbench "Transformer test bench"
  extends Modelica.Icons.Example;
  parameter Integer m = 3 "Number of phases" ;
  parameter Modelica.Units.SI.Resistance RL[m] = fill(1 / 3, m) "Load resistance";
  output Modelica.Units.SI.Voltage VS = polarVS.len "Grid voltage";
  output Modelica.Units.SI.Angle phiS = polarVS.phi "Grid phase";
  output Modelica.Units.SI.Voltage VL = polarVL.len "Load voltage";
  output Modelica.Units.SI.Angle phiL = polarVL.phi "Load phase";
  Modelica.Electrical.QuasiStatic.Polyphase.Sources.VoltageSource source(f = 50, V = fill(100 / sqrt(3), 3), m = m, gamma(fixed = true, start = 0)) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star starS(m = m) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground groundS ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PowerSensor electricalPowerSensorS(m = m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.CurrentSensor currentSensorS(m = m) ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToPolar polarIS ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.VoltageSensor voltageSensorS(m = m) ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToPolar polarVS ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Delta deltaS(m = m) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Resistor earth(R_ref = 1e6) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground groundT ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.VoltageSensor voltageSensorL(m = m) ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToPolar polarVL ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Delta deltaL(m = m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.CurrentSensor currentSensorL(m = m) ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToPolar polarIL ;
  Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PowerSensor electricalPowerSensorL(m = m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Resistor load(R_ref = RL, m = m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Star starL(m = m) ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground groundL ;
  Modelica.Electrical.Machines.Utilities.TransformerData transformerData(C1 = Modelica.Utilities.Strings.substring(transformer.VectorGroup, 1, 1), C2 = Modelica.Utilities.Strings.substring(transformer.VectorGroup, 2, 2), f = 50, V1 = 100, V2 = 100, SNominal = 30E3, v_sc = 0.05, P_sc = 300) ;
  Modelica.Electrical.QuasiStatic.Machines.BasicMachines.Transformers.Yd.Yd01 transformer(n = transformerData.n, R1 = transformerData.R1, L1sigma = transformerData.L1sigma, R2 = transformerData.R2, L2sigma = transformerData.L2sigma, T1Ref = 293.15, alpha20_1(displayUnit = "1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero, T2Ref = 293.15, alpha20_2(displayUnit = "1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero, T1Operational = 293.15, T2Operational = 293.15) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Blocks.SymmetricalComponents symmetricalComponentsIS(final m = m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Blocks.SymmetricalComponents symmetricalComponentsIL(final m = m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Blocks.SymmetricalComponents symmetricalComponentsVS(final m = m) ;
  Modelica.Electrical.QuasiStatic.Polyphase.Blocks.SymmetricalComponents symmetricalComponentsVL(final m = m) ;
equation
  connect(starS.pin_n, groundS.pin) ;
  connect(source.plug_n, starS.plug_p) ;
  connect(starL.pin_n, groundL.pin) ;
  connect(load.plug_n, starL.plug_p) ;
  connect(electricalPowerSensorS.currentP, electricalPowerSensorS.voltageP) ;
  connect(electricalPowerSensorS.currentN, currentSensorS.plug_p) ;
  connect(currentSensorS.plug_n, transformer.plug1) ;
  connect(transformer.plug2, currentSensorL.plug_p) ;
  connect(currentSensorL.plug_n, electricalPowerSensorL.currentP) ;
  connect(electricalPowerSensorL.currentP, electricalPowerSensorL.voltageP) ;
  connect(electricalPowerSensorL.currentN, load.plug_p) ;
  connect(electricalPowerSensorL.voltageN, starL.plug_p) ;
  connect(electricalPowerSensorS.voltageN, starS.plug_p) ;
  connect(earth.pin_n, groundT.pin) ;
  connect(deltaS.plug_p, voltageSensorS.plug_n) ;
  connect(deltaS.plug_n, voltageSensorS.plug_p) ;
  connect(currentSensorS.plug_n, deltaS.plug_n) ;
  connect(deltaL.plug_p, voltageSensorL.plug_n) ;
  connect(deltaL.plug_n, voltageSensorL.plug_p) ;
  connect(currentSensorL.plug_p, deltaL.plug_n) ;
  connect(symmetricalComponentsIS.u, currentSensorS.i) ;
  connect(symmetricalComponentsIL.u, currentSensorL.i) ;
  connect(symmetricalComponentsIS.y[1], polarIS.u) ;
  connect(symmetricalComponentsIL.y[1], polarIL.u) ;
  connect(voltageSensorS.v, symmetricalComponentsVS.u) ;
  connect(symmetricalComponentsVS.y[1], polarVS.u) ;
  connect(voltageSensorL.v, symmetricalComponentsVL.u) ;
  connect(symmetricalComponentsVL.y[1], polarVL.u) ;
  connect(electricalPowerSensorS.currentP, source.plug_p) ;

