  output Modelica.Units.SI.Angle arg_y[m](displayUnit = "deg") = arg(y) "Argument of output";
protected
  final parameter Complex sbTM[m, m] = Modelica.Electrical.Polyphase.Functions.symmetricBackTransformationMatrix(m);
equation
  // Symmetrical components (preferred): y = sbTM*u;
  for j in 1:m loop
    y[j] = Complex(sum(array(sbTM[j, k].re * u[k].re - sbTM[j, k].im * u[k].im for k in 1:m)), sum(array(sbTM[j, k].re * u[k].im + sbTM[j, k].im * u[k].re for k in 1:m)));
  end for;

end FromSymmetricalComponents;

