model VoltageSource "Constant polyphase AC voltage"
  extends Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.Source;
  import Modelica.ComplexMath.j;
  import Modelica.ComplexMath.exp;
  parameter Modelica.Units.SI.Frequency f(start = 1) "Frequency of the source";
  parameter Modelica.Units.SI.Voltage V[m](start = fill(1, m)) "RMS voltage of the source";
  parameter Modelica.Units.SI.Angle phi[m] = -Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m) "Phase shift of the source";
equation
