model TankController "Controller for tank system"
  extends Modelica.StateGraph.Interfaces.PartialStateGraphIcon;
  parameter Modelica.Units.SI.Height maxLevel "Fill level of tank 1";
  parameter Modelica.Units.SI.Height minLevel "Lowest level of tank 1 and 2";
