  Modelica.Blocks.Interfaces.BooleanOutput valve2 ;
  Modelica.Blocks.Interfaces.BooleanOutput valve3 ;
  Modelica.Blocks.Sources.BooleanExpression setValve1(y = normal.fillTank1.active) ;
  Modelica.Blocks.Sources.BooleanExpression setValve2(y = normal.fillTank2.active or emptyTanks.active and level1 > minLevel) ;
  Modelica.Blocks.Sources.BooleanExpression setValve3(y = normal.emptyTank2.active or emptyTanks.active and level2 > minLevel) ;
  inner Modelica.StateGraph.StateGraphRoot stateGraphRoot ;
equation
