modelica://Modelica.Fluid/TankWith3Inlet:
Modelica.Fluid: TankWith3InletOutletArraysWithEvaporatorCondensor (model)

This tank has the same geometric variables as TankWith3InletOutletArrays plus the feature of a HeatPort and the possibility of evaporation. (Assumption: The gas is condensed immediately afterwards so that a liquid boiling fluid is created.)  
The tank can be initialized with the following options:  
GuessValues: no explicit initial conditions InitialValues: initial values of temperature (or specific enthalpy), composition and level are specified SteadyStateHydraulic: initial values of temperature (or specific enthalpy) and composition are specified; the initial level is determined so that levels and pressure are at steady state.  
 Full steady state initialization is not supported, because the corresponding initial equations for temperature/enthalpy are undetermined (the flow rate through the port at steady state is zero).

Code:
model TankWith3InletOutletArraysWithEvaporatorCondensor "Tank with Heating and Evaporation"
  import Modelica.Fluid.Examples.AST_BatchPlant.BaseClasses.Init;
  replaceable package Medium = Modelica.Media.Water.WaterIF97_ph constrainedby Modelica.Media.Interfaces.PartialTwoPhaseMedium "Medium in the component" ;
  // parameter for Tank
  parameter Modelica.Units.SI.Area crossArea "Tank area";
  parameter Modelica.Units.SI.Area top_pipeArea[n_TopPorts] "Area of outlet pipe";
  parameter Modelica.Units.SI.Area side_pipeArea[n_SidePorts] "Area of outlet pipe";
  parameter Modelica.Units.SI.Area bottom_pipeArea[n_BottomPorts] "Area of outlet pipe";
  parameter Modelica.Units.SI.Height height = 10 "Height of Tank";
  parameter Modelica.Units.SI.Volume V0 = 0 "Volume of the liquid when the level is zero";
  constant Modelica.Units.SI.Acceleration g = Modelica.Constants.g_n;
  parameter Modelica.Units.SI.Height side_heights[n_SidePorts] = zeros(n_SidePorts) "Side heights";
  parameter Modelica.Units.SI.Height bottom_heights[n_BottomPorts] = zeros(n_BottomPorts) "Bottom heights";
  parameter Modelica.Units.SI.Height top_heights[n_TopPorts] = fill(height, n_TopPorts) "Top heights";
  parameter Modelica.Units.SI.Height level_start "Initial tank level" ;
  parameter Init initType = Init.GuessValues "Initialization option" ;
  parameter Boolean use_T_start = true "= true, if T_start is used, otherwise h_start" ;
  parameter Medium.Temperature T_start = if use_T_start then 293.15 else Medium.temperature_phX(p_ambient, h_start, X_start) "Start value of temperature" ;
  parameter Medium.SpecificEnthalpy h_start = if use_T_start then Medium.specificEnthalpy_pTX(p_ambient, T_start, X_start[1:Medium.nXi]) else 1e4 "Start value of specific enthalpy" ;
  parameter Medium.MassFraction X_start[Medium.nX] = Medium.reference_X "Start value of mass fractions m_i/m" ;
  parameter Medium.AbsolutePressure p_ambient = 101325 "Tank surface pressure";
  parameter Medium.Temperature T_ambient = 293.15 "Tank surface Temperature";
  parameter Integer n_TopPorts = 1 "Number of Top connectors";
  parameter Integer n_SidePorts = 1 "Number of side connectors";
  parameter Integer n_BottomPorts = 1 "Number of bottom connectors";
  Medium.BaseProperties medium(preferredMediumStates = true, p(start = p_ambient), T(start = T_start), Xi(start = X_start[1:Medium.nXi]));
  Modelica.Units.SI.Height level(stateSelect = StateSelect.prefer, min = 0, max = height) "Level height of tank";
  Modelica.Units.SI.Volume V(stateSelect = StateSelect.never) "Actual tank volume";
  Modelica.Units.SI.Energy U "Internal energy of tank volume";
  Real m(unit = "kg") "Mass of tank volume";
  Real mXi[Medium.nXi](each unit = "kg") "Component masses of the independent substances";
  // additional variables
  Real H_flow_BottomPorts[n_BottomPorts];
  Real H_flow_SidePorts[n_SidePorts];
  Real H_flow_TopPorts[n_TopPorts];
  Real m_flow_BottomPorts[n_BottomPorts];
  Real m_flow_SidePorts[n_SidePorts];
  Real m_flow_TopPorts[n_TopPorts];
  Real m_flow_BottomPorts_pos[n_BottomPorts];
  Real m_flow_SidePorts_pos[n_SidePorts];
  Real m_flow_TopPorts_pos[n_TopPorts];
  Real m_flow_pos;
  Medium.MassFlowRate mXi_flow_topPorts[n_TopPorts, Medium.nXi];
  Medium.MassFlowRate mXi_flowBottomPorts[n_BottomPorts, Medium.nXi];
  Medium.MassFlowRate mXi_flow_sidePorts[n_SidePorts, Medium.nXi];
  // Connectors and InnerTanks
  Modelica.Fluid.Interfaces.FluidPort_b BottomFluidPort[n_BottomPorts](redeclare package Medium = Medium, m_flow(each start = 0)) ;
  Modelica.Fluid.Interfaces.FluidPort_a TopFluidPort[n_TopPorts](redeclare package Medium = Medium, m_flow(each start = 0)) ;
  Modelica.Fluid.Interfaces.FluidPort_b SideFluidPort[n_SidePorts](redeclare package Medium = Medium, m_flow(each start = 0)) ;
  Modelica.Fluid.Examples.AST_BatchPlant.BaseClasses.InnerTank InnerTankTop[n_TopPorts](each h = medium.h, each p_ambient = p_ambient, each d = medium.d, each Xi = medium.Xi, aboveLevel = array(level - top_heights[i] for i in 1:n_TopPorts), pipeArea = array(top_pipeArea[i] for i in 1:n_TopPorts), redeclare package Medium = Medium) ;
  Modelica.Fluid.Examples.AST_BatchPlant.BaseClasses.InnerTank InnerTankSide[n_SidePorts](each h = medium.h, each p_ambient = p_ambient, each d = medium.d, each Xi = medium.Xi, aboveLevel = array(level - side_heights[i] for i in 1:n_SidePorts), pipeArea = array(side_pipeArea[i] for i in 1:n_SidePorts), redeclare package Medium = Medium) ;
  Modelica.Fluid.Examples.AST_BatchPlant.BaseClasses.InnerTank InnerTankBottom[n_BottomPorts](each h = medium.h, each p_ambient = p_ambient, each d = medium.d, each Xi = medium.Xi, aboveLevel = array(level - bottom_heights[i] for i in 1:n_BottomPorts), pipeArea = array(bottom_pipeArea[i] for i in 1:n_BottomPorts), redeclare package Medium = Medium) ;
  Modelica.Fluid.Interfaces.FluidPort_b Condensed(redeclare package Medium = Medium) ;
  // Heat transfer through boundary
  replaceable model HeatTransfer = Modelica.Fluid.Vessels.BaseClasses.HeatTransfer.IdealHeatTransfer constrainedby Modelica.Fluid.Vessels.BaseClasses.HeatTransfer.PartialVesselHeatTransfer "Wall heat transfer" ;
  HeatTransfer heatTransfer(redeclare package Medium = Medium, final n = 1, final states = {medium.state}, surfaceAreas = {crossArea + 2 * sqrt(crossArea * Modelica.Constants.pi) * level}, final use_k = true) ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPort ;
  // parameter for Evaporator
  parameter Modelica.Units.SI.Height min_level_for_heating "Minimum level for heating";
  Medium.SaturationProperties sat "State vector to compute saturation properties";
  Medium.SpecificEnthalpy h_v = Medium.dewEnthalpy(sat) "Specific enthalpy of vapour";
  Medium.SpecificEnthalpy h_l = Medium.bubbleEnthalpy(sat) "Specific enthalpy of liquid";
  Medium.SpecificEnthalpy h "Actual specific enthalpy of liquid";
  Medium.Density rho_v = Medium.dewDensity(sat) "Density in vapour phase";
  Medium.Density rho_l = Medium.bubbleDensity(sat) "Density in liquid phase";
  Medium.Density rho "Actual density in liquid phase";
equation
  H_flow_TopPorts = InnerTankTop.H_flow;
  m_flow_TopPorts = InnerTankTop.m_flow;
  mXi_flow_topPorts = InnerTankTop.mXi_flow;
  H_flow_SidePorts = InnerTankSide.H_flow;
  m_flow_SidePorts = InnerTankSide.m_flow;
  mXi_flow_sidePorts = InnerTankSide.mXi_flow;
  H_flow_BottomPorts = InnerTankBottom.H_flow;
  m_flow_BottomPorts = InnerTankBottom.m_flow;
  mXi_flowBottomPorts = InnerTankBottom.mXi_flow;
  for i in 1:n_BottomPorts loop
    m_flow_BottomPorts_pos[i] = if m_flow_BottomPorts[i] > 0 then m_flow_BottomPorts[i] else 0;
  end for;
  for i in 1:n_SidePorts loop
    m_flow_SidePorts_pos[i] = if m_flow_SidePorts[i] > 0 then m_flow_SidePorts[i] else 0;
  end for;
  for i in 1:n_TopPorts loop
    m_flow_TopPorts_pos[i] = if m_flow_TopPorts[i] > 0 then m_flow_TopPorts[i] else 0;
  end for;
  for i in 1:n_BottomPorts loop
    connect(InnerTankBottom[i].port, BottomFluidPort[i]) ;
  end for;
  for i in 1:n_TopPorts loop
    connect(InnerTankTop[i].port, TopFluidPort[i]) ;
  end for;
  for i in 1:n_SidePorts loop
    connect(InnerTankSide[i].port, SideFluidPort[i]) ;
  end for;
  medium.p = p_ambient;
  // Mass balance
  der(m) = sum(m_flow_BottomPorts) + sum(m_flow_SidePorts) + sum(m_flow_TopPorts) + Condensed.m_flow;
  // Energy balance
  U = m * medium.h - p_ambient * V "Internal energy of fluid";
  m = V * medium.d "Mass of fluid";
  V = crossArea * level + V0 "Volume of fluid";
  mXi = m * medium.Xi "Mass of fluid components";
  sat.psat = medium.p;
  sat.Tsat = Medium.saturationTemperature(medium.p);
  if noEvent(medium.T < sat.Tsat) then
    if Medium.singleState then
      der(U) = sum(H_flow_BottomPorts) + sum(H_flow_SidePorts) + sum(H_flow_TopPorts) + Condensed.m_flow * actualStream(Condensed.h_outflow) + heatTransfer.Q_flows[1] "Mechanical work is neglected";
    else
      der(U) = sum(H_flow_BottomPorts) + sum(H_flow_SidePorts) + sum(H_flow_TopPorts) + Condensed.m_flow * actualStream(Condensed.h_outflow) - p_ambient * der(V) + heatTransfer.Q_flows[1];
    end if;
    Condensed.h_outflow = h;
    Condensed.m_flow = 0;
    rho = medium.d;
    h = medium.h;
  else
    if Medium.singleState then
      der(U) = sum(H_flow_BottomPorts) + sum(H_flow_SidePorts) + sum(H_flow_TopPorts) + Condensed.m_flow * actualStream(Condensed.h_outflow) "Mechanical work is neglected";
    else
      der(U) = sum(H_flow_BottomPorts) + sum(H_flow_SidePorts) + sum(H_flow_TopPorts) + Condensed.m_flow * actualStream(Condensed.h_outflow) - p_ambient * der(V);
    end if;
    Condensed.h_outflow = h;
    Condensed.m_flow = -heatTransfer.Q_flows[1] / (h_v - h_l);
    rho = rho_l;
    //Density = liquid Density
    h = h_l;
    //Enthalpy = liquid Enthalpy
    if noEvent(heatPort.Q_flow > 0.0) then
      assert(noEvent(abs(m_flow_pos) <= 0.01), "Attempt to fill tank while evaporating.");
    end if;
  end if;
  m_flow_pos = sum(m_flow_TopPorts_pos) + sum(m_flow_SidePorts_pos) + sum(m_flow_BottomPorts_pos);
  for i in 1:Medium.nXi loop
    der(mXi[i]) = sum(mXi_flowBottomPorts[:, i]) + sum(mXi_flow_sidePorts[:, i]) + sum(mXi_flow_topPorts[:, i]);
  end for;
  assert(level < height, "Tank is overflowing.");
  assert(not (heatPort.Q_flow > 0.0 and level <= min_level_for_heating), "Attempting to heat an empty tank.");
initial equation
  if initType == Init.GuessValues then
  elseif initType == Init.InitialValues then
    // no initial equations
    level = level_start;
    if use_T_start then
      medium.T = T_start;
    else
      medium.h = h_start;
    end if;
    medium.Xi = X_start[1:Medium.nXi];
  elseif initType == Init.SteadyStateHydraulic then
    der(level) = 0;
    if use_T_start then
      medium.T = T_start;
    else
      medium.h = h_start;
    end if;
    medium.Xi = X_start[1:Medium.nXi];
  else
    assert(false, "Unsupported initialization option");
  end if;
equation
  connect(heatPort, heatTransfer.heatPorts[1]) ;

end TankWith3InletOutletArraysWithEvaporatorCondensor;

modelica://Modelica.Fluid/InnerTank:
Modelica.Fluid: InnerTank (model)

Code:
model InnerTank
  replaceable package Medium = Modelica.Media.Interfaces.PartialMedium "Medium in the component" ;
  Modelica.Fluid.Interfaces.FluidPort_a port(redeclare package Medium = Medium) ;
  Boolean m_flow_negative(start = true, fixed = true) "= true, if mass flow out of tank";
  constant Modelica.Units.SI.Acceleration g = Modelica.Constants.g_n;
  input Real aboveLevel;
  input Real d;
  input Real p_ambient;
  input Real h;
  input Medium.MassFraction Xi[Medium.nXi] "Actual mass fractions of fluid in tank" ;
  input Real pipeArea;
  output Real H_flow;
  output Real m_flow;
  output Medium.MassFlowRate mXi_flow[Medium.nXi] "= port.mXi_flow (used to transform vector of connectors in vector of Real numbers)";
equation
  m_flow_negative = pre(m_flow_negative) and not port.p > p_ambient or port.m_flow < -1e-6;
  if noEvent(aboveLevel > 0) then
    port.p = aboveLevel * g * d + p_ambient - smooth(2, noEvent(if noEvent(m_flow < 0) then m_flow ^ 2 / (2 * d * pipeArea ^ 2) else 0));
  else
    if pre(m_flow_negative) then
      port.m_flow = 0;
    else
      port.p = p_ambient;
    end if;
  end if;
  H_flow = port.m_flow * actualStream(port.h_outflow);
  m_flow = port.m_flow;
  mXi_flow = port.m_flow * actualStream(port.Xi_outflow);
  port.h_outflow = h;
  port.Xi_outflow = Xi;
end InnerTank;

