  parameter Modelica.Fluid.Types.ModelStructure modelStructure_1 = Modelica.Fluid.Types.ModelStructure.av_vb "Determines whether flow or volume models are present at the ports" ;
  parameter Modelica.Fluid.Types.ModelStructure modelStructure_2 = Modelica.Fluid.Types.ModelStructure.av_vb "Determines whether flow or volume models are present at the ports" ;
  replaceable package Medium_1 = Modelica.Media.Water.StandardWater constrainedby Modelica.Media.Interfaces.PartialMedium "Fluid 1" ;
  replaceable package Medium_2 = Modelica.Media.Water.StandardWater constrainedby Modelica.Media.Interfaces.PartialMedium "Fluid 2" ;
  parameter Modelica.Units.SI.Area crossArea_1 "Cross sectional area" ;
  parameter Modelica.Units.SI.Area crossArea_2 "Cross sectional area" ;
  parameter Modelica.Units.SI.Length perimeter_1 "Flow channel perimeter" ;
  parameter Modelica.Units.SI.Length perimeter_2 "Flow channel perimeter" ;
  final parameter Boolean use_HeatTransfer = true "= true to use the HeatTransfer_1/_2 model";
  // Heat transfer
