  replaceable model HeatTransfer_2 = Modelica.Fluid.Pipes.BaseClasses.HeatTransfer.IdealFlowHeatTransfer constrainedby Modelica.Fluid.Pipes.BaseClasses.HeatTransfer.PartialFlowHeatTransfer "Heat transfer model" ;
  parameter Modelica.Units.SI.Area area_h_1 "Heat transfer area" ;
  parameter Modelica.Units.SI.Area area_h_2 "Heat transfer area" ;
  //Wall
  parameter Modelica.Units.SI.Length s_wall(min = 0) "Wall thickness" ;
  parameter Modelica.Units.SI.ThermalConductivity k_wall "Thermal conductivity of wall material" ;
