  parameter Modelica.Units.SI.TemperatureDifference dT "Start value for pipe_1.T - pipe_2.T" ;
  parameter Boolean use_T_start = true "Use T_start if true, otherwise h_start" ;
  parameter Medium_1.AbsolutePressure p_a_start1 = Medium_1.p_default "Start value of pressure" ;
  parameter Medium_1.AbsolutePressure p_b_start1 = Medium_1.p_default "Start value of pressure" ;
  parameter Medium_1.Temperature T_start_1 = if use_T_start then Medium_1.T_default else Medium_1.temperature_phX((p_a_start1 + p_b_start1) / 2, h_start_1, X_start_1) "Start value of temperature" ;
