modelica://Modelica.Fluid/pressureLoss_m:
Modelica.Fluid: pressureLoss_m_flow (function)

Code:
partial function pressureLoss_m_flow "Return pressure loss dp as function of mass flow rate m_flow, i.e., dp = f(m_flow), due to wall friction"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate from port_a to port_b";
