function extends pressureLoss_m_flow_staticHead "Return pressure loss dp as function of mass flow rate m_flow, i.e., dp = f(m_flow), due to wall friction and static head"
    // WARNING: The following equation is only correct for circular tubes!

  protected
    Real k0 = 128 * length / (Modelica.Constants.pi * diameter ^ 4) "Constant factor";
  Modelica.Units.SI.Pressure dp_grav_a = g_times_height_ab * rho_a "Static head if mass flows in design direction (a to b)";
  Modelica.Units.SI.Pressure dp_grav_b = g_times_height_ab * rho_b "Static head if mass flows against design direction (b to a)";
    Real ddp_dm_flow_a = k0 * mu_a / rho_a "Slope of dp over mass flow rate if flow in design direction (a to b)";
    Real ddp_dm_flow_b = k0 * mu_b / rho_b "Slope of dp over mass flow rate if flow against design direction (b to a)";
  Modelica.Units.    SI.MassFlowRate m_flow_a = if dp_grav_a >= dp_grav_b then m_flow_small else m_flow_small + (dp_grav_b - dp_grav_a) / ddp_dm_flow_a "Upper end of regularization domain of the dp(m_flow) relation";
  Modelica.Units.SI.MassFlowRate m_flow_b = if dp_grav_a >= dp_grav_b then -m_flow_small else -m_flow_small - (dp_grav_b - dp_grav_a) / ddp_dm_flow_b "Lower end of regularization domain of the dp(m_flow) relation";
  Modelica.Units.    SI.Pressure dp_a "Value at upper end of regularization domain";
  Modelica.Units.SI.Pressure dp_b "Value at lower end of regularization domain";
    // Properly define zero mass flow conditions
  Modelica.Units.    SI.MassFlowRate m_flow_zero = 0;
  Modelica.Units.SI.Pressure dp_zero = (dp_grav_a + dp_grav_b) / 2;
    Real ddp_dm_flow_zero;

  algorithm
    /*
  dp = 0.5*zeta/(A^2*d) * m_flow * |m_flow|
     = 0.5 * c0/(|m_flow|*(4/pi)/(D_Re*mu)) / ((pi*(D_Re/2)^2)^2*d) * m_flow*|m_flow|
     = 0.5 * c0*(pi/4)*(D_Re*mu) * 16/(pi^2*D_Re^4*d) * m_flow*|m_flow|
     = 2*c0/(pi*D_Re^3) * mu/d * m_flow
     = k0 * mu/d * m_flow
  k0 = 2*c0/(pi*D_Re^3)
*/
    if m_flow >= m_flow_a then
      // Positive flow outside regularization
      dp := ddp_dm_flow_a * m_flow + dp_grav_a;
    elseif m_flow <= m_flow_b then
      // Negative flow outside regularization
      dp := ddp_dm_flow_b * m_flow + dp_grav_b;
    else
      // Regularization parameters
      dp_a := ddp_dm_flow_a * m_flow_a + dp_grav_a;
      dp_b := ddp_dm_flow_b * m_flow_b + dp_grav_b;
      // Include a properly defined zero mass flow point
      // Obtain a suitable slope from the linear section slope c (value of dp is overwritten later)
      (dp, ddp_dm_flow_zero) := Modelica.Fluid.Utilities.regFun3(m_flow_zero, m_flow_b, m_flow_a, dp_b, dp_a, ddp_dm_flow_b, ddp_dm_flow_a);
      // Do regularization
      if m_flow > m_flow_zero then
        dp := Modelica.Fluid.Utilities.regFun3(m_flow, m_flow_zero, m_flow_a, dp_zero, dp_a, ddp_dm_flow_zero, ddp_dm_flow_a);
      else
        dp := Modelica.Fluid.Utilities.regFun3(m_flow, m_flow_b, m_flow_zero, dp_b, dp_zero, ddp_dm_flow_b, ddp_dm_flow_zero);
      end if;
    end if;

end pressureLoss_m_flow_staticHead;

