Code:
function extends massFlowRate_dp "Return mass flow rate m_flow as function of pressure loss dp, i.e., m_flow = f(dp), due to wall friction"
    import Modelica.Math;

  protected
    Real zeta;
    Real k_inv;

  algorithm
    /*
   dp = 0.5*zeta*d*v*|v|
      = 0.5*zeta*d*1/(d*A)^2 * m_flow * |m_flow|
      = 0.5*zeta/A^2 *1/d * m_flow * |m_flow|
      = k/d * m_flow * |m_flow|
   k  = 0.5*zeta/A^2
      = 0.5*zeta/(pi*(D/2)^2)^2
      = 8*zeta/(pi*D^2)^2
  */
    assert(roughness > 1e-10, "roughness > 0 required for quadratic turbulent wall friction characteristic");
    zeta := length / diameter / (2 * Math.log10(3.7 / (roughness / diameter))) ^ 2;
    // WARNING: The following equation is only correct for circular tubes!
    k_inv := (pi * diameter * diameter) ^ 2 / (8 * zeta);
    m_flow := Modelica.Fluid.Utilities.regRoot2(dp, dp_small, rho_a * k_inv, rho_b * k_inv);

end massFlowRate_dp;

