  Modelica.Units.    SI.MassFlowRate m_flow_b = if dp_grav_a >= dp_grav_b then -m_flow_small else -m_flow_small - sqrt((dp_grav_b - dp_grav_a) / k2) "Lower end of regularization domain of the dp(m_flow) relation";
  Modelica.Units.SI.Pressure dp_a "Value at upper end of regularization domain";
  Modelica.Units.SI.Pressure dp_b "Value at lower end of regularization domain";
    Real ddp_dm_flow_a "Derivative of pressure drop with mass flow rate at m_flow_a";
    Real ddp_dm_flow_b "Derivative of pressure drop with mass flow rate at m_flow_b";
