function extends pressureLoss_m_flow_staticHead "Return pressure loss dp as function of mass flow rate m_flow, i.e., dp = f(m_flow), due to wall friction and static head"
    import Modelica.Math;

  protected
    Real Delta(min = 0) = roughness / diameter "Relative roughness";
  Modelica.Units.SI.ReynoldsNumber Re1 = min(745 * Math.exp(if Delta <= 0.0065 then 1 else 0.0065 / Delta), Re_turbulent) "Boundary between laminar regime and transition";
  Modelica.Units.SI.ReynoldsNumber Re2 = Re_turbulent "Boundary between transition and turbulent regime";
  Modelica.Units.    SI.MassFlowRate m_flow_a "Upper end of regularization domain of the dp(m_flow) relation";
  Modelica.Units.SI.MassFlowRate m_flow_b "Lower end of regularization domain of the dp(m_flow) relation";
  Modelica.Units.SI.Pressure dp_a "Value at upper end of regularization domain";
  Modelica.Units.SI.Pressure dp_b "Value at lower end of regularization domain";
  Modelica.Units.SI.Pressure dp_grav_a = g_times_height_ab * rho_a "Static head if mass flows in design direction (a to b)";
  Modelica.Units.SI.Pressure dp_grav_b = g_times_height_ab * rho_b "Static head if mass flows against design direction (b to a)";
    Real ddp_dm_flow_a "Derivative of pressure drop with mass flow rate at m_flow_a";
    Real ddp_dm_flow_b "Derivative of pressure drop with mass flow rate at m_flow_b";
    // Properly define zero mass flow conditions
  Modelica.Units.SI.MassFlowRate m_flow_zero = 0;
  Modelica.Units.SI.Pressure dp_zero = (dp_grav_a + dp_grav_b) / 2;
    Real ddp_dm_flow_zero;

  algorithm
    assert(roughness > 1e-10, "roughness > 0 required for quadratic turbulent wall friction characteristic");
    m_flow_a := if dp_grav_a < dp_grav_b then Modelica.Fluid.Pipes.BaseClasses.WallFriction.LaminarAndQuadraticTurbulent.Internal.m_flow_of_dp_fric(dp_grav_b - dp_grav_a, rho_a, rho_b, mu_a, mu_b, length, diameter, crossArea, Re1, Re2, Delta) + m_flow_small else m_flow_small;
    m_flow_b := if dp_grav_a < dp_grav_b then Modelica.Fluid.Pipes.BaseClasses.WallFriction.LaminarAndQuadraticTurbulent.Internal.m_flow_of_dp_fric(dp_grav_a - dp_grav_b, rho_a, rho_b, mu_a, mu_b, length, diameter, crossArea, Re1, Re2, Delta) - m_flow_small else -m_flow_small;
    if m_flow >= m_flow_a then
      // Positive flow outside regularization
      dp := Modelica.Fluid.Pipes.BaseClasses.WallFriction.LaminarAndQuadraticTurbulent.Internal.dp_fric_of_m_flow(m_flow, rho_a, rho_b, mu_a, mu_b, length, diameter, crossArea, Re1, Re2, Delta) + dp_grav_a;
    elseif m_flow <= m_flow_b then
      // Negative flow outside regularization
      dp := Modelica.Fluid.Pipes.BaseClasses.WallFriction.LaminarAndQuadraticTurbulent.Internal.dp_fric_of_m_flow(m_flow, rho_a, rho_b, mu_a, mu_b, length, diameter, crossArea, Re1, Re2, Delta) + dp_grav_b;
    else
      // Regularization parameters
      (dp_a, ddp_dm_flow_a) := Modelica.Fluid.Pipes.BaseClasses.WallFriction.LaminarAndQuadraticTurbulent.Internal.dp_fric_of_m_flow(m_flow_a, rho_a, rho_b, mu_a, mu_b, length, diameter, crossArea, Re1, Re2, Delta);
      dp_a := dp_a + dp_grav_a "Adding dp_grav to dp_fric to get dp";
      (dp_b, ddp_dm_flow_b) := Modelica.Fluid.Pipes.BaseClasses.WallFriction.LaminarAndQuadraticTurbulent.Internal.dp_fric_of_m_flow(m_flow_b, rho_a, rho_b, mu_a, mu_b, length, diameter, crossArea, Re1, Re2, Delta);
      dp_b := dp_b + dp_grav_b "Adding dp_grav to dp_fric to get dp";
      // Include a properly defined zero mass flow point
      // Obtain a suitable slope from the linear section slope c (value of dp is overwritten later)
      (dp, ddp_dm_flow_zero) := Modelica.Fluid.Utilities.regFun3(m_flow_zero, m_flow_b, m_flow_a, dp_b, dp_a, ddp_dm_flow_b, ddp_dm_flow_a);
      // Do regularization
      if m_flow > m_flow_zero then
        dp := Modelica.Fluid.Utilities.regFun3(m_flow, m_flow_zero, m_flow_a, dp_zero, dp_a, ddp_dm_flow_zero, ddp_dm_flow_a);
      else
        dp := Modelica.Fluid.Utilities.regFun3(m_flow, m_flow_b, m_flow_zero, dp_b, dp_zero, ddp_dm_flow_b, ddp_dm_flow_zero);
      end if;
    end if;

end pressureLoss_m_flow_staticHead;

