function dp_fric_of_m_flow "Calculate pressure drop due to friction as function of mass flow rate"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate from port_a to port_b";
  input Modelica.Units.SI.Density rho_a "Density at port_a";
  input Modelica.Units.SI.Density rho_b "Density at port_b";
  input Modelica.Units.SI.DynamicViscosity mu_a "Dynamic viscosity at port_a (dummy if use_mu = false)";
  input Modelica.Units.SI.DynamicViscosity mu_b "Dynamic viscosity at port_b (dummy if use_mu = false)";
  input Modelica.Units.SI.Length length "Length of pipe";
  input Modelica.Units.SI.Diameter diameter "Inner (hydraulic) diameter of pipe";
  input Modelica.Units.SI.Area crossArea "Inner cross section area";
  input Modelica.Units.SI.ReynoldsNumber Re1 "Boundary between laminar regime and transition";
  input Modelica.Units.SI.ReynoldsNumber Re2 "Boundary between transition and turbulent regime";
  input Real Delta(min = 0) "Relative roughness";
  output Modelica.Units.SI.Pressure dp_fric "Pressure loss due to friction (dp_fric = port_a.p - port_b.p - dp_grav)";
  output Real ddp_fric_dm_flow "Derivative of pressure drop with mass flow rate";
protected
  Modelica.Units.SI.DynamicViscosity mu "Upstream viscosity";
  Modelica.Units.SI.Density rho "Upstream density";
  Real zeta;
  Real k0;
  Real k;
  Real ddp_fric_dm_flow_laminar "Derivative of dp_fric = f(m_flow) at zero";
  Modelica.Units.SI.MassFlowRate m_flow_turbulent "The turbulent region is: |m_flow| >= m_flow_turbulent";
  Modelica.Units.SI.MassFlowRate m_flow_laminar "The laminar region is: |m_flow| <= m_flow_laminar";
algorithm
  /*
Turbulent region:
   Re = m_flow*(4/pi)/(D_Re*mu)
   dp = 0.5*zeta*rho*v*|v|
      = 0.5*zeta*rho*1/(rho*A)^2 * m_flow * |m_flow|
      = 0.5*zeta/A^2 *1/rho * m_flow * |m_flow|
      = k/rho * m_flow * |m_flow|
   k  = 0.5*zeta/A^2
      = 0.5*zeta/(pi*(D/2)^2)^2
      = 8*zeta/(pi*D^2)^2
   m_flow_turbulent = (pi/4)*D_Re*mu*Re_turbulent

Laminar region:
   dp = 0.5*zeta/(A^2*d) * m_flow * |m_flow|
      = 0.5 * c0/(|m_flow|*(4/pi)/(D_Re*mu)) / ((pi*(D_Re/2)^2)^2*d) * m_flow*|m_flow|
      = 0.5 * c0*(pi/4)*(D_Re*mu) * 16/(pi^2*D_Re^4*d) * m_flow*|m_flow|
      = 2*c0/(pi*D_Re^3) * mu/rho * m_flow
      = k0 * mu/rho * m_flow
   k0 = 2*c0/(pi*D_Re^3)
*/
  // Determine upstream density and upstream viscosity
  if m_flow >= 0 then
    rho := rho_a;
    mu := mu_a;
  else
    rho := rho_b;
    mu := mu_b;
  end if;
  // Turbulent
  // WARNING: The following equations are only correct for circular tubes!
  zeta := length / diameter / (2 * Modelica.Math.log10(3.7 / Delta)) ^ 2;
  k := 8 * zeta / (pi * diameter * diameter) ^ 2;
  m_flow_turbulent := sign(m_flow) * (pi / 4) * diameter * mu * Re2;
  // Laminar
  k0 := 128 * length / (pi * diameter ^ 4);
  ddp_fric_dm_flow_laminar := k0 * mu / rho;
  m_flow_laminar := sign(m_flow) * (pi / 4) * diameter * mu * Re1;
  if abs(m_flow) > abs(m_flow_turbulent) then
    dp_fric := k / rho * m_flow * abs(m_flow);
    ddp_fric_dm_flow := 2 * k / rho * abs(m_flow);
  elseif abs(m_flow) < abs(m_flow_laminar) then
    dp_fric := ddp_fric_dm_flow_laminar * m_flow;
    ddp_fric_dm_flow := ddp_fric_dm_flow_laminar;
  else
    // Preliminary testing seems to indicate that the log-log transform is not required here
    (dp_fric, ddp_fric_dm_flow) := Modelica.Fluid.Utilities.cubicHermite_withDerivative(m_flow, m_flow_laminar, m_flow_turbulent, ddp_fric_dm_flow_laminar * m_flow_laminar, k / rho * m_flow_turbulent * abs(m_flow_turbulent), ddp_fric_dm_flow_laminar, 2 * k / rho * abs(m_flow_turbulent));
  end if;

end dp_fric_of_m_flow;

