    import Modelica.Math;

  protected
    Real Delta(min = 0) = roughness / diameter "Relative roughness";
  Modelica.Units.    SI.ReynoldsNumber Re1 = min((745 * Math.exp(if Delta <= 0.0065 then 1 else 0.0065 / Delta)) ^ 0.97, Re_turbulent) "Re leaving laminar curve";
  Modelica.Units.SI.ReynoldsNumber Re2 = Re_turbulent "Re entering turbulent curve";
  Modelica.Units.    SI.DynamicViscosity mu "Upstream viscosity";
  Modelica.Units.SI.Density rho "Upstream density";
  Modelica.Units.SI.ReynoldsNumber Re "Reynolds number";
    Real lambda2 "Modified friction coefficient (= lambda*Re^2)";
    function interpolateInRegion2 = Modelica.Fluid.Dissipation.Utilities.Functions.General.CubicInterpolation_Re "Cubic Hermite spline interpolation in transition region";

  algorithm
    // Determine upstream density, upstream viscosity, and lambda2
    rho := if dp >= 0 then rho_a else rho_b;
    mu := if dp >= 0 then mu_a else mu_b;
    lambda2 := abs(dp) * 2 * diameter ^ 3 * rho / (length * mu * mu);
    // Determine Re under the assumption of laminar flow
    Re := lambda2 / 64;
    // Modify Re, if turbulent flow
    if Re > Re1 then
      Re := -2 * sqrt(lambda2) * Math.log10(2.51 / sqrt(lambda2) + 0.27 * Delta);
      if Re < Re2 then
        Re := interpolateInRegion2(Re, Re1, Re2, Delta, lambda2);
      end if;
    end if;
    // Determine mass flow rate
    m_flow := crossArea / diameter * mu * (if dp >= 0 then Re else -Re);

end massFlowRate_dp;

