function extends pressureLoss_m_flow "Return pressure loss dp as function of mass flow rate m_flow, i.e., dp = f(m_flow), due to wall friction"
    import Modelica.Math;
    import Modelica.Constants.pi;

  protected
    Real Delta(min = 0) = roughness / diameter "Relative roughness";
  Modelica.Units.SI.ReynoldsNumber Re1 = min(745 * Math.exp(if Delta <= 0.0065 then 1 else 0.0065 / Delta), Re_turbulent) "Re leaving laminar curve";
  Modelica.Units.SI.ReynoldsNumber Re2 = Re_turbulent "Re entering turbulent curve";
  Modelica.Units.SI.DynamicViscosity mu "Upstream viscosity";
  Modelica.Units.    SI.Density rho "Upstream density";
  Modelica.Units.    SI.ReynoldsNumber Re "Reynolds number";
    Real lambda2 "Modified friction coefficient (= lambda*Re^2)";
    function interpolateInRegion2 = Modelica.Fluid.Dissipation.Utilities.Functions.General.CubicInterpolation_lambda "Cubic Hermite spline interpolation in transition region";

  algorithm
    // Determine upstream density and upstream viscosity
    rho := if m_flow >= 0 then rho_a else rho_b;
    mu := if m_flow >= 0 then mu_a else mu_b;
    // Determine Re, lambda2 and pressure drop
    Re := diameter * abs(m_flow) / (crossArea * mu);
    lambda2 := if Re <= Re1 then 64 * Re else if Re >= Re2 then 0.25 * (Re / Math.log10(Delta / 3.7 + 5.74 / Re ^ 0.9)) ^ 2 else interpolateInRegion2(Re, Re1, Re2, Delta);
    dp := length * mu * mu / (2 * rho * diameter * diameter * diameter) * (if m_flow >= 0 then lambda2 else -lambda2);

end pressureLoss_m_flow;

