function extends massFlowRate_dp_staticHead "Return mass flow rate m_flow as function of pressure loss dp, i.e., m_flow = f(dp), due to wall friction and static head"
  protected
    Real Delta(min = 0) = roughness / diameter "Relative roughness";
  Modelica.Units.SI.ReynoldsNumber Re "Reynolds number";
  Modelica.Units.SI.ReynoldsNumber Re1 = min((745 * Modelica.Math.exp(if Delta <= 0.0065 then 1 else 0.0065 / Delta)) ^ 0.97, Re_turbulent) "Boundary between laminar regime and transition";
  Modelica.Units.SI.ReynoldsNumber Re2 = Re_turbulent "Boundary between transition and turbulent regime";
  Modelica.Units.SI.Pressure dp_a "Upper end of regularization domain of the m_flow(dp) relation";
  Modelica.Units.SI.Pressure dp_b "Lower end of regularization domain of the m_flow(dp) relation";
  Modelica.Units.SI.MassFlowRate m_flow_a "Value at upper end of regularization domain";
  Modelica.Units.    SI.MassFlowRate m_flow_b "Value at lower end of regularization domain";
  Modelica.Units.SI.MassFlowRate dm_flow_ddp_fric_a "Derivative at upper end of regularization domain";
  Modelica.Units.SI.MassFlowRate dm_flow_ddp_fric_b "Derivative at lower end of regularization domain";
  Modelica.Units.SI.Pressure dp_grav_a = g_times_height_ab * rho_a "Static head if mass flows in design direction (a to b)";
  Modelica.Units.SI.Pressure dp_grav_b = g_times_height_ab * rho_b "Static head if mass flows against design direction (b to a)";
    // Properly define zero mass flow conditions
  Modelica.Units.SI.MassFlowRate m_flow_zero = 0;
  Modelica.Units.    SI.Pressure dp_zero = (dp_grav_a + dp_grav_b) / 2;
    Real dm_flow_ddp_fric_zero;

  algorithm
    dp_a := max(dp_grav_a, dp_grav_b) + dp_small;
    dp_b := min(dp_grav_a, dp_grav_b) - dp_small;
    if dp >= dp_a then
      // Positive flow outside regularization
      m_flow := Modelica.Fluid.Pipes.BaseClasses.WallFriction.Detailed.Internal.m_flow_of_dp_fric(dp - dp_grav_a, rho_a, rho_b, mu_a, mu_b, length, diameter, crossArea, Re1, Re2, Delta);
    elseif dp <= dp_b then
      // Negative flow outside regularization
      m_flow := Modelica.Fluid.Pipes.BaseClasses.WallFriction.Detailed.Internal.m_flow_of_dp_fric(dp - dp_grav_b, rho_a, rho_b, mu_a, mu_b, length, diameter, crossArea, Re1, Re2, Delta);
    else
      // Regularization parameters
      (m_flow_a, dm_flow_ddp_fric_a) := Modelica.Fluid.Pipes.BaseClasses.WallFriction.Detailed.Internal.m_flow_of_dp_fric(dp_a - dp_grav_a, rho_a, rho_b, mu_a, mu_b, length, diameter, crossArea, Re1, Re2, Delta);
      (m_flow_b, dm_flow_ddp_fric_b) := Modelica.Fluid.Pipes.BaseClasses.WallFriction.Detailed.Internal.m_flow_of_dp_fric(dp_b - dp_grav_b, rho_a, rho_b, mu_a, mu_b, length, diameter, crossArea, Re1, Re2, Delta);
      // Include a properly defined zero mass flow point
      // Obtain a suitable slope from the linear section slope c (value of m_flow is overwritten later)
      (m_flow, dm_flow_ddp_fric_zero) := Modelica.Fluid.Utilities.regFun3(dp_zero, dp_b, dp_a, m_flow_b, m_flow_a, dm_flow_ddp_fric_b, dm_flow_ddp_fric_a);
      // Do regularization
      if dp > dp_zero then
        m_flow := Modelica.Fluid.Utilities.regFun3(dp, dp_zero, dp_a, m_flow_zero, m_flow_a, dm_flow_ddp_fric_zero, dm_flow_ddp_fric_a);
      else
        m_flow := Modelica.Fluid.Utilities.regFun3(dp, dp_b, dp_zero, m_flow_b, m_flow_zero, dm_flow_ddp_fric_b, dm_flow_ddp_fric_zero);
      end if;
    end if;

end massFlowRate_dp_staticHead;

