  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPort if use_HeatTransfer ;
  // Variables
  final parameter Modelica.Units.SI.Acceleration g = system.g "Constant gravity acceleration";
  Medium.Density rho = medium.d;
  Modelica.Units.SI.Pressure dp_pump = port_b.p - port_a.p "Pressure change";
  Modelica.Units.SI.Position head = dp_pump / (rho * g) "Pump head";
  Modelica.Units.SI.MassFlowRate m_flow = port_a.m_flow "Mass flow rate (total)";
  Modelica.Units.SI.MassFlowRate m_flow_single = m_flow / nParallel "Mass flow rate (single pump)";
  Modelica.Units.SI.VolumeFlowRate V_flow "Volume flow rate (total)";
  Modelica.Units.SI.VolumeFlowRate V_flow_single(start = m_flow_start / rho_nominal / nParallel) "Volume flow rate (single pump)";
  NonSI.AngularVelocity_rpm N(start = N_nominal) "Shaft rotational speed";
  Modelica.Units.SI.Power W_single "Power Consumption (single pump)";
  Modelica.Units.SI.Power W_total = W_single * nParallel "Power Consumption (total)";
  Real eta "Global Efficiency";
  final constant Medium.MassFlowRate unit_m_flow = 1 ;
  Real s(start = m_flow_start / unit_m_flow) "Curvilinear abscissa for the flow curve in parametric form (either mass flow rate or head)";
  // Diagnostics
  replaceable model Monitoring = Modelica.Fluid.Machines.BaseClasses.PumpMonitoring.PumpMonitoringBase constrainedby Modelica.Fluid.Machines.BaseClasses.PumpMonitoring.PumpMonitoringBase "Optional pump monitoring" ;
  Monitoring monitoring(redeclare package Medium = Medium, final state_in = Medium.setState_phX(port_a.p, inStream(port_a.h_outflow), inStream(port_a.Xi_outflow)), final state = medium.state) "Monitoring model" ;
protected
  constant Modelica.Units.SI.Position unitHead = 1;
  constant Modelica.Units.SI.MassFlowRate unitMassFlowRate = 1;
equation
  // Flow equations
  V_flow = homotopy(m_flow / rho, m_flow / rho_nominal);
  V_flow_single = V_flow / nParallel;
  if not checkValve then
    // Regular flow characteristics without check valve
    // The simplified model uses an approximation of the tangent to the head curve in the initialization point
    head = homotopy((N / N_nominal) ^ 2 * flowCharacteristic(V_flow_single * N_nominal / N), N / N_nominal * (flowCharacteristic(V_flow_single_init) + (V_flow_single - V_flow_single_init) * noEvent(if abs(V_flow_single_init) > 0 then delta_head_init / (0.1 * V_flow_single_init) else 0)));
    s = 0;
  else
    // Flow characteristics when check valve is open
    // The simplified model uses an approximation of the tangent to the head curve in the initialization point
    // or the zero-flow vertical axis in case the system is initialized with the check valve closed
    if checkValveHomotopy == Modelica.Fluid.Types.CheckValveHomotopyType.NoHomotopy then
      head = if s > 0 then (N / N_nominal) ^ 2 * flowCharacteristic(V_flow_single * N_nominal / N) else (N / N_nominal) ^ 2 * flowCharacteristic(0) - s * unitHead;
      V_flow_single = if s > 0 then s * unitMassFlowRate / rho else 0;
    else
      head = homotopy(if s > 0 then (N / N_nominal) ^ 2 * flowCharacteristic(V_flow_single * N_nominal / N) else (N / N_nominal) ^ 2 * flowCharacteristic(0) - s * unitHead, if checkValveHomotopy == Modelica.Fluid.Types.CheckValveHomotopyType.Open then N / N_nominal * (flowCharacteristic(V_flow_single_init) + (V_flow_single - V_flow_single_init) * noEvent(if abs(V_flow_single_init) > 0 then delta_head_init / (0.1 * V_flow_single_init) else 0)) else N / N_nominal * flowCharacteristic(0) - s * unitHead);
      V_flow_single = homotopy(if s > 0 then s * unitMassFlowRate / rho else 0, if checkValveHomotopy == Modelica.Fluid.Types.CheckValveHomotopyType.Open then s * unitMassFlowRate / rho_nominal else 0);
    end if;
  end if;
  // Power consumption
  if use_powerCharacteristic then
    W_single = homotopy((N / N_nominal) ^ 3 * (rho / rho_nominal) * powerCharacteristic(V_flow_single * N_nominal / N), N / N_nominal * V_flow_single / V_flow_single_init * powerCharacteristic(V_flow_single_init));
    eta = dp_pump * V_flow_single / W_single;
  else
    eta = homotopy(efficiencyCharacteristic(V_flow_single * (N_nominal / N)), efficiencyCharacteristic(V_flow_single_init));
    W_single = homotopy(dp_pump * V_flow_single / eta, dp_pump * V_flow_single_init / eta);
  end if;
  // Energy balance
  Wb_flow = W_total;
  Qb_flow = heatTransfer.Q_flows[1];
  Hb_flow = port_a.m_flow * actualStream(port_a.h_outflow) + port_b.m_flow * actualStream(port_b.h_outflow);
  // Ports
  port_a.h_outflow = medium.h;
  port_b.h_outflow = medium.h;
  port_b.p = medium.p "Outlet pressure is equal to medium pressure, which includes Wb_flow";
  // Mass balance
  mb_flow = port_a.m_flow + port_b.m_flow;
  mbXi_flow = port_a.m_flow * actualStream(port_a.Xi_outflow) + port_b.m_flow * actualStream(port_b.Xi_outflow);
  port_a.Xi_outflow = medium.Xi;
  port_b.Xi_outflow = medium.Xi;
  mbC_flow = port_a.m_flow * actualStream(port_a.C_outflow) + port_b.m_flow * actualStream(port_b.C_outflow);
  port_a.C_outflow = C;
  port_b.C_outflow = C;
  connect(heatTransfer.heatPorts[1], heatPort) ;

this is recommended to avoid singularities in the computation of the outlet enthalpy in case of zero flow rate.
If zero flow rate conditions are always avoided, this dynamic effect can be neglected by leaving the default value <code>V = 0</code>, thus avoiding fast state variables in the model.
</p>

<p><strong>Dynamics options</strong></p>
