Code:
function linearFlow "Linear flow characteristic"
  extends Modelica.Fluid.Machines.BaseClasses.PumpCharacteristics.baseFlow;
  input Modelica.Units.SI.VolumeFlowRate V_flow_nominal[2] "Volume flow rate for two operating points (single pump)" ;
  input Modelica.Units.SI.Position head_nominal[2] "Pump head for two operating points" ;
  /* Linear system to determine the coefficients:
  head_nominal[1] = c[1] + V_flow_nominal[1]*c[2];
  head_nominal[2] = c[1] + V_flow_nominal[2]*c[2];
  */
protected
  Real c[2] = Modelica.Math.Matrices.solve([ones(2), V_flow_nominal], head_nominal) "Coefficients of linear head curve";
algorithm
  assert(c[2] <= -Modelica.Constants.small, "Wrong pump curve -- head_nominal must be monotonically decreasing with increasing V_flow_nominal", level = AssertionLevel.warning);
  // Flow equation: head = q*c[1] + c[2];
  head := c[1] + V_flow * c[2];
end linearFlow;

