function quadraticFlow "Quadratic flow characteristic, including linear extrapolation"
  extends Modelica.Fluid.Machines.BaseClasses.PumpCharacteristics.baseFlow;
  input Modelica.Units.SI.VolumeFlowRate V_flow_nominal[3] "Volume flow rate for three operating points (single pump)" ;
  input Modelica.Units.SI.Position head_nominal[3] "Pump head for three operating points" ;
protected
  Real V_flow_nominal2[3] = {V_flow_nominal[1] ^ 2, V_flow_nominal[2] ^ 2, V_flow_nominal[3] ^ 2} "Squared nominal flow rates";
  /* Linear system to determine the coefficients:
  head_nominal[1] = c[1] + V_flow_nominal[1]*c[2] + V_flow_nominal[1]^2*c[3];
  head_nominal[2] = c[1] + V_flow_nominal[2]*c[2] + V_flow_nominal[2]^2*c[3];
  head_nominal[3] = c[1] + V_flow_nominal[3]*c[2] + V_flow_nominal[3]^2*c[3];
  */
  Real c[3] = Modelica.Math.Matrices.solve([ones(3), V_flow_nominal, V_flow_nominal2], head_nominal) "Coefficients of quadratic head curve";
  Modelica.Units.SI.VolumeFlowRate V_flow_min = min(V_flow_nominal);
  Modelica.Units.SI.VolumeFlowRate V_flow_max = max(V_flow_nominal);
algorithm
  assert(max(c[2] .+ 2 * c[3] * V_flow_nominal) <= -Modelica.Constants.small, "Wrong pump curve -- head_nominal must be monotonically decreasing with increasing V_flow_nominal", level = AssertionLevel.warning);
  if V_flow < V_flow_min then
    head := max(head_nominal) + (V_flow - V_flow_min) * (c[2] + 2 * c[3] * V_flow_min);
  elseif V_flow > V_flow_max then
    head := min(head_nominal) + (V_flow - V_flow_max) * (c[2] + 2 * c[3] * V_flow_max);
  else
    // Flow equation: head  = c[1] + V_flow*c[2] + V_flow^2*c[3];
    head := c[1] + V_flow * (c[2] + V_flow * c[3]);
  end if;

end quadraticFlow;

modelica://Modelica.Fluid/polynomialFlow:
Modelica.Fluid: polynomialFlow (function)

Code:
function polynomialFlow "Polynomial flow characteristic, including linear extrapolation"
  extends Modelica.Fluid.Machines.BaseClasses.PumpCharacteristics.baseFlow;
  input Modelica.Units.SI.VolumeFlowRate V_flow_nominal[:] "Volume flow rate for N operating points (single pump)" ;
  input Modelica.Units.SI.Position head_nominal[:] "Pump head for N operating points" ;
protected
  Integer N = size(V_flow_nominal, 1) "Number of nominal operating points";
  Real V_flow_nominal_pow[N, N] = array(array(if j > 1 then V_flow_nominal[i] ^ (j - 1) else 1 for j in 1:N) for i in 1:N) "Rows: different operating points; columns: increasing powers";
  /* Linear system to determine the coefficients (example N=3):
  head_nominal[1] = c[1] + V_flow_nominal[1]*c[2] + V_flow_nominal[1]^2*c[3];
  head_nominal[2] = c[1] + V_flow_nominal[2]*c[2] + V_flow_nominal[2]^2*c[3];
  head_nominal[3] = c[1] + V_flow_nominal[3]*c[2] + V_flow_nominal[3]^2*c[3];
  */
  Real c[size(V_flow_nominal, 1)] = Modelica.Math.Matrices.solve(V_flow_nominal_pow, head_nominal) "Coefficients of polynomial head curve";
  Modelica.Units.SI.VolumeFlowRate V_flow_min = min(V_flow_nominal);
  Modelica.Units.SI.VolumeFlowRate V_flow_max = max(V_flow_nominal);
  Real max_dhdV = c[2] + max(sum((i - 1) * V_flow_nominal .^ (i - 2) * c[i] for i in 3:N));
  Real poly;
algorithm
  assert(max_dhdV <= -Modelica.Constants.small, "Wrong pump curve -- head_nominal must be monotonically decreasing with increasing V_flow_nominal", level = AssertionLevel.warning);
  if V_flow < V_flow_min then
    //head := max(head_nominal) + (V_flow-V_flow_min)*(c[2]+sum((i-1)*V_flow_min^(i-2)*c[i] for i in 3:N));
    poly := c[N] * (N - 1);
    for i in 1:N - 2 loop
      poly := V_flow_min * poly + c[N - i] * (N - i - 1);
    end for;
    head := max(head_nominal) + (V_flow - V_flow_min) * poly;
  elseif V_flow > V_flow_max then
    //head := min(head_nominal) + (V_flow-V_flow_max)*(c[2]+sum((i-1)*V_flow_max^(i-2)*c[i] for i in 3:N));
    poly := c[N] * (N - 1);
    for i in 1:N - 2 loop
      poly := V_flow_max * poly + c[N - i] * (N - i - 1);
    end for;
    head := min(head_nominal) + (V_flow - V_flow_max) * poly;
  else
    // Flow equation (example N=3): head  = c[1] + V_flow*c[2] + V_flow^2*c[3];
    // Note: the implementation is numerically efficient only for low values of Na
    //head := sum(V_flow^(i-1)*c[i] for i in 1:N);
    poly := c[N];
    for i in 1:N - 1 loop
      poly := V_flow * poly + c[N - i];
    end for;
    head := poly;
  end if;

end polynomialFlow;

