function linearPower "Linear power consumption characteristic"
  extends Modelica.Fluid.Machines.BaseClasses.PumpCharacteristics.basePower;
  input Modelica.Units.SI.VolumeFlowRate V_flow_nominal[2] "Volume flow rate for two operating points (single pump)" ;
  input Modelica.Units.SI.Power W_nominal[2] "Power consumption for two operating points" ;
  /* Linear system to determine the coefficients:
  W_nominal[1] = c[1] + V_flow_nominal[1]*c[2];
  W_nominal[2] = c[1] + V_flow_nominal[2]*c[2];
  */
protected
  Real c[2] = Modelica.Math.Matrices.solve([ones(3), V_flow_nominal], W_nominal) "Coefficients of linear power consumption curve";
algorithm
  consumption := c[1] + V_flow * c[2];
end linearPower;

