  input Modelica.Units.SI.Power W_nominal[3] "Power consumption for three operating points" ;
protected
  Real V_flow_nominal2[3] = {V_flow_nominal[1] ^ 2, V_flow_nominal[2] ^ 2, V_flow_nominal[3] ^ 2} "Squared nominal flow rates";
  /* Linear system to determine the coefficients:
  W_nominal[1] = c[1] + V_flow_nominal[1]*c[2] + V_flow_nominal[1]^2*c[3];
  W_nominal[2] = c[1] + V_flow_nominal[2]*c[2] + V_flow_nominal[2]^2*c[3];
  W_nominal[3] = c[1] + V_flow_nominal[3]*c[2] + V_flow_nominal[3]^2*c[3];
  */
  Real c[3] = Modelica.Math.Matrices.solve([ones(3), V_flow_nominal, V_flow_nominal2], W_nominal) "Coefficients of quadratic power consumption curve";
algorithm
  consumption := c[1] + V_flow * c[2] + V_flow ^ 2 * c[3];
end quadraticPower;

