equation
  if allowFlowReversal then
    m_flow = Modelica.Fluid.Fittings.BaseClasses.Bends.CurvedBend.massFlowRate(dp, geometry, d_a, d_b, eta_a, eta_b, dp_small, m_flow_small);
  else
    m_flow = Modelica.Fluid.Dissipation.PressureLoss.Bend.dp_curvedOverall_MFLOW(geometry, Modelica.Fluid.Dissipation.PressureLoss.Bend.dp_curvedOverall_IN_var(rho = d_a, eta = eta_a), dp);
  end if;

end CurvedBend;

