  Real k2 = Modelica.Fluid.Fittings.BaseClasses.lossConstant_D_zeta(if data.zeta2_at_a then data.diameter_a else data.diameter_b, data.zeta2);
algorithm
  /*
   dp = 0.5*zeta*rho*v*|v|
      = 0.5*zeta*rho*1/(rho*A)^2 * m_flow * |m_flow|
      = 0.5*zeta/A^2 *1/rho * m_flow * |m_flow|
      = k/rho * m_flow * |m_flow|
   k  = 0.5*zeta/A^2
      = 0.5*zeta/(pi*(D/2)^2)^2
      = 8*zeta/(pi*D^2)^2
