  output Modelica.Units.SI.Pressure dp "Pressure drop (dp = port_a.p - port_b.p)";
protected
  Real k1 = Modelica.Fluid.Fittings.BaseClasses.lossConstant_D_zeta(if data.zeta1_at_a then data.diameter_a else data.diameter_b, data.zeta1);
  Real k2 = Modelica.Fluid.Fittings.BaseClasses.lossConstant_D_zeta(if data.zeta2_at_a then data.diameter_a else data.diameter_b, data.zeta2);
