partial model BaseModel "Generic pressure drop component with constant turbulent loss factor data and without an icon"
  extends Modelica.Fluid.Interfaces.PartialTwoPortTransport(dp_start = dp_nominal, m_flow_small = if system.use_eps_Re then system.eps_m_flow * m_flow_nominal else system.m_flow_small, m_flow(stateSelect = if momentumDynamics == Modelica.Fluid.Types.Dynamics.SteadyState then StateSelect.default else StateSelect.prefer));
  extends Modelica.Fluid.Interfaces.PartialLumpedFlow(final pathLength = 0, final momentumDynamics = Modelica.Fluid.Types.Dynamics.SteadyState);
  parameter Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.LossFactorData data "Loss factor data";
  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal = if system.use_eps_Re then system.m_flow_nominal else 1e2 * system.m_flow_small "Nominal mass flow rate" ;
  // Advanced
  parameter Boolean use_Re = system.use_eps_Re "= true, if turbulent region is defined by Re, otherwise by m_flow_small" ;
  parameter Boolean from_dp = true "= true, use m_flow = f(dp) else dp = f(m_flow)" ;
protected
  parameter Medium.ThermodynamicState state_nominal = Medium.setState_pTX(Medium.reference_p, Medium.reference_T, Medium.reference_X) "Medium state to compute nominal pressure drop";
  parameter Modelica.Units.SI.Pressure dp_nominal = Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.pressureLoss_m_flow(m_flow_nominal, Medium.density(state_nominal), Medium.density(state_nominal), data, m_flow_small) "Nominal pressure loss";
  parameter Medium.AbsolutePressure dp_small(min = 0) = if system.use_eps_Re then dp_nominal / m_flow_nominal * m_flow_small else system.dp_small "Regularization of zero flow if |dp| < dp_small" ;
  //parameter Medium.MassFlowRate m_flow_small = system.m_flow_small
  //  "Turbulent flow if |m_flow| >= m_flow_small"
  //  ;
  // Diagnostics
public
  parameter Boolean show_Re = false "= true, if Reynolds number is included for plotting" ;
  Modelica.Units.SI.ReynoldsNumber Re = Modelica.Fluid.Pipes.BaseClasses.CharacteristicNumbers.ReynoldsNumber_m_flow(m_flow, noEvent(if m_flow > 0 then Medium.dynamicViscosity(state_a) else Medium.dynamicViscosity(state_b)), data.D_Re) if show_Re "Reynolds number at diameter data.D_Re";
  // Variables
  Modelica.Units.SI.Pressure dp_fg "Pressure loss due to friction and gravity";
  Modelica.Units.SI.Area A_mean = Modelica.Constants.pi / 4 * (data.diameter_a ^ 2 + data.diameter_b ^ 2) / 2 "Mean cross flow area";
equation
  Ib_flow = 0;
  F_p = A_mean * (Medium.pressure(state_b) - Medium.pressure(state_a));
  F_fg = A_mean * dp_fg;
  if from_dp then
    m_flow = homotopy(if use_Re then Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.massFlowRate_dp_and_Re(dp_fg, Medium.density(state_a), Medium.density(state_b), Medium.dynamicViscosity(state_a), Medium.dynamicViscosity(state_b), data) else Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.massFlowRate_dp(dp_fg, Medium.density(state_a), Medium.density(state_b), data, dp_small), m_flow_nominal * dp_fg / dp_nominal);
  else
    dp_fg = homotopy(if use_Re then Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.pressureLoss_m_flow_and_Re(m_flow, Medium.density(state_a), Medium.density(state_b), Medium.dynamicViscosity(state_a), Medium.dynamicViscosity(state_b), data) else Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.pressureLoss_m_flow(m_flow, Medium.density(state_a), Medium.density(state_b), data, m_flow_small), dp_nominal * m_flow / m_flow_nominal);
  end if;
  // Isenthalpic state transformation (no storage and no loss of energy)
  port_a.h_outflow = inStream(port_b.h_outflow);
  port_b.h_outflow = inStream(port_a.h_outflow);

end BaseModel;

