  extends Modelica.Fluid.Interfaces.PartialLumpedFlow(final pathLength = 0, final momentumDynamics = Modelica.Fluid.Types.Dynamics.SteadyState);
  parameter Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.LossFactorData data "Loss factor data";
  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal = if system.use_eps_Re then system.m_flow_nominal else 1e2 * system.m_flow_small "Nominal mass flow rate" ;
  // Advanced
  /// Other settings than the final values are not yet implemented ///
  final parameter Boolean use_Re = false "= true, if turbulent region is defined by Re, otherwise by m_flow_small" ;
  final parameter Boolean from_dp = false "= true, use m_flow = f(dp) else dp = f(m_flow)" ;
  // End not yet implemented /////////////////////////////////////////
protected
  parameter Medium.ThermodynamicState state_nominal = Medium.setState_pTX(Medium.reference_p, Medium.reference_T, Medium.reference_X) "Medium state to compute nominal pressure drop" ;
  parameter Modelica.Units.SI.Pressure dp_nominal = Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.pressureLoss_m_flow(m_flow_nominal, Medium.density(state_nominal), Medium.density(state_nominal), data, m_flow_small) "Nominal pressure loss";
  parameter Medium.AbsolutePressure dp_small(min = 0) = if system.use_eps_Re then dp_nominal / m_flow_nominal * m_flow_small else system.dp_small "Regularization of zero flow if |dp| < dp_small" ;
  //parameter Medium.MassFlowRate m_flow_small = system.m_flow_small
  //  "Turbulent flow if |m_flow| >= m_flow_small"
  //  ;
  // Diagnostics
public
  parameter Boolean show_Re = false "= true, if Reynolds number is included for plotting" ;
  Modelica.Units.SI.ReynoldsNumber Re = Modelica.Fluid.Pipes.BaseClasses.CharacteristicNumbers.ReynoldsNumber_m_flow(m_flow, noEvent(if m_flow > 0 then Medium.dynamicViscosity(state_a) else Medium.dynamicViscosity(state_b)), data.D_Re) if show_Re "Reynolds number at diameter data.D_Re";
  parameter Boolean show_totalPressures = false "= true, if total pressures are included for plotting" ;
  Modelica.Units.SI.AbsolutePressure p_total_a = port_a.p + 0.5 * m_flow ^ 2 / ((Modelica.Constants.pi / 4 * data.diameter_a ^ 2) ^ 2 * noEvent(if port_a.m_flow > 0 then Medium.density(state_a) else Medium.density(state_b))) if show_totalPressures "Total pressure at port_a";
  Modelica.Units.SI.AbsolutePressure p_total_b = port_b.p + 0.5 * m_flow ^ 2 / ((Modelica.Constants.pi / 4 * data.diameter_b ^ 2) ^ 2 * noEvent(if port_b.m_flow > 0 then Medium.density(state_b) else Medium.density(state_a))) if show_totalPressures "Total pressure at port_a";
  parameter Boolean show_portVelocities = false "= true, if port velocities are included for plotting" ;
  Modelica.Units.SI.Velocity v_a = port_a.m_flow / (Modelica.Constants.pi / 4 * data.diameter_a ^ 2 * noEvent(if port_a.m_flow > 0 then Medium.density(state_a) else Medium.density(state_b))) if show_portVelocities "Fluid velocity into port_a";
  Modelica.Units.SI.Velocity v_b = port_b.m_flow / (Modelica.Constants.pi / 4 * data.diameter_b ^ 2 * noEvent(if port_b.m_flow > 0 then Medium.density(state_b) else Medium.density(state_a))) if show_portVelocities "Fluid velocity into port_b";
  // Variables
  Modelica.Units.SI.Pressure dp_fg "Pressure loss due to friction and gravity";
  Modelica.Units.SI.Area A_mean = Modelica.Constants.pi / 4 * (data.diameter_a ^ 2 + data.diameter_b ^ 2) / 2 "Mean cross flow area";
  Medium.ThermodynamicState state_b_des "Thermodynamic state at port b for flow a -> b";
  Medium.ThermodynamicState state_a_nondes "Thermodynamic state at port a for flow a <- b";
equation
  Ib_flow = 0;
  F_p = A_mean * (Medium.pressure(state_b) - Medium.pressure(state_a));
  F_fg = A_mean * dp_fg;
  if from_dp then
    m_flow = if use_Re then Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.massFlowRate_dp_and_Re(dp_fg, Medium.density(state_a), Medium.density(state_b), Medium.dynamicViscosity(state_a), Medium.dynamicViscosity(state_b), data) else Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.massFlowRate_dp(dp_fg, Medium.density(state_a), Medium.density(state_b), data, dp_small);
  else
    dp_fg = if use_Re then Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.pressureLoss_m_flow_and_Re(m_flow, Medium.density(state_a), Medium.density(state_b), Medium.dynamicViscosity(state_a), Medium.dynamicViscosity(state_b), data) else Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.pressureLoss_m_flow_totalPressure(m_flow, Medium.density(state_a), Medium.density(state_b_des), Medium.density(state_b), Medium.density(state_a_nondes), data, m_flow_small);
  end if;
  // Isenthalpic state transformation (no storage and no loss of energy)
  port_a.h_outflow = inStream(port_b.h_outflow);
  port_b.h_outflow = inStream(port_a.h_outflow);
  // medium states for downstream properties, may want to change this neglecting the only difference from state_a, state_b, which is in pressure
  // This will remove the extra interaction variables
  state_b_des = Medium.setState_phX(port_b.p, inStream(port_a.h_outflow), inStream(port_a.Xi_outflow));
  state_a_nondes = Medium.setState_phX(port_a.p, inStream(port_b.h_outflow), inStream(port_b.Xi_outflow));

end BaseModelNonconstantCrossSectionArea;

modelica://Modelica.Fluid/pressureLoss_m:
Modelica.Fluid: pressureLoss_m_flow_totalPressure (function)

Compute pressure drop from constant loss factor and mass flow rate (dp = f(m_flow)). For small mass flow rates(|m_flow| < m_flow_small), the characteristic is approximated by a polynomial in order to have a finite derivative at zero mass flow rate.

Code:
function pressureLoss_m_flow_totalPressure "Return pressure drop from constant loss factor and mass flow rate (dp = f(m_flow))"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate from port_a to port_b";
  input Modelica.Units.SI.Density rho_a_des "Density at port_a, mass flow in design direction a -> b";
  input Modelica.Units.SI.Density rho_b_des "Density at port_b, mass flow in design direction a -> b";
  input Modelica.Units.SI.Density rho_b_nondes "Density at port_b, mass flow against design direction a <- b";
  input Modelica.Units.SI.Density rho_a_nondes "Density at port_a, mass flow against design direction a <- b";
  input Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.LossFactorData data "Constant loss factors for both flow directions" ;
  input Modelica.Units.SI.MassFlowRate m_flow_small = 0.01 "Turbulent flow if |m_flow| >= m_flow_small";
  output Modelica.Units.SI.Pressure dp "Pressure drop (dp = port_a.p - port_b.p)";
protected
  Modelica.Units.SI.Area A_a = Modelica.Constants.pi * data.diameter_a ^ 2 / 4 "Cross section area at port_a";
  Modelica.Units.SI.Area A_b = Modelica.Constants.pi * data.diameter_b ^ 2 / 4 "Cross section area at port_b";
algorithm
  dp := 1 / 2 * m_flow ^ 2 * (if m_flow > 0 then data.zeta1 / (if data.zeta1_at_a then rho_a_des * A_a ^ 2 else rho_b_des * A_b ^ 2) - 1 / (rho_a_des * A_a ^ 2) + 1 / (rho_b_des * A_b ^ 2) else -data.zeta2 / (if data.zeta2_at_a then rho_a_nondes * A_a ^ 2 else rho_b_nondes * A_b ^ 2) - 1 / (rho_a_nondes * A_a ^ 2) + 1 / (rho_b_nondes * A_b ^ 2));

end pressureLoss_m_flow_totalPressure;

modelica://Modelica.Fluid/wallFriction:
Modelica.Fluid: wallFriction (function)

Friction in straight pipe with walls of nonuniform roughness (commercial pipes) in the region that does not depend on the Reynolds-number   
 The loss factors are given for mass flow rates from port_a to port_b as:     turbulent flow (Idelchik 1994, diagram 2-5, p. 117) zeta = (L/D)/(2*lg(3.7 / Δ))^2, for Re >= 560/Δ for Re ≥ 560/Δ the loss factor does not depend on the Reynolds number. For Re ≥ 4000, the flow is turbulent, but depends both on Δ and slightly on Re. laminar flow (Idelchik 1994, diagram 2-1, p. 110): zeta = 64*(L/D)/Re   
 where   
D is the inner pipe diameter L is the length of the pipe Δ = δ/D is the relative roughness where δ is the absolute "roughness", i.e., the averaged height of asperities in the pipe. (δ may change over time due to growth of surface asperities during service, see [Idelchik 1994, p. 85, Tables 2-1, 2-2]).  
 Since the LossFactorData record can only describe loss factors that depend on geometry (but, e.g., not on the Reynolds number), only the region with Re ≥ 560/Δ is described by this data. Still, the turbulent region with the above zeta is defined to start at Re=4000, since otherwise the approximation for Re < 560/Δ is too bad.   
 The absolute roughness δ has usually to be estimated. In [Idelchik 1994, pp. 105-109, Table 2-5; Miller 1990, p. 190, Table 8-1] many examples are given. As a short summary:   
Smooth pipes Drawn brass, copper, aluminium, glass, etc. δ = 0.0025 mm
Steel pipes New smooth pipes δ = 0.025 mm
Mortar lined, average finish δ = 0.1 mm
Heavy rust δ = 1 mm
Concrete pipes Steel forms, first class workmanship δ = 0.025 mm
Steel forms, average workmanship δ = 0.1 mm
Block linings δ = 1 mm

Code:
encapsulated function wallFriction "Return pressure loss data due to friction in a straight pipe with walls of nonuniform roughness (not useful for smooth pipes, since zeta is no function of Re)"
  import Modelica.Units.SI;
  import Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.LossFactorData;
  import Modelica.Fluid.Types.Roughness;
  import lg = Modelica.Math.log10;
  input SI.Length length "Length of pipe" ;
  input SI.Diameter diameter "Inner diameter of pipe" ;
  input Roughness roughness(min = 1e-10) "Absolute roughness of pipe (> 0 required, details see info layer)" ;
  output LossFactorData data "Pressure loss factors for both flow directions";
protected
  Real Delta(min = 0) = roughness / diameter "Relative roughness";
algorithm
  data.diameter_a := diameter;
  data.diameter_b := diameter;
  data.zeta1 := length / diameter / (2 * Modelica.Math.log10(3.7 / Delta)) ^ 2;
  data.zeta2 := data.zeta1;
  data.Re_turbulent := 4000 ">= 560/Delta flow does not depend on Re, but interpolation is bad";
  data.D_Re := diameter;
  data.zeta1_at_a := true;
  data.zeta2_at_a := false;
  data.zetaLaminarKnown := true;
  data.c0 := 64 * (length / diameter);

end wallFriction;

modelica://Modelica.Fluid/suddenExpansio:
Modelica.Fluid: suddenExpansion (function)

The loss factors are given for mass flow rates from port_a to port_b as:     A_a < A_b (Idelchik 1994, diagram 4-1, p. 208): zeta = dp/(rho_a*v_a^2/2) = (1 - A_a/A_b)^2 for Re_a ≥ 3.3e3 (turbulent flow) zeta = 30/Re for Re_a < 10 (laminar flow) A_a > A_b (Idelchik 1994, diagram 4-9, p. 216 and diagram 4-10, p. 217) zeta = dp/(rho_b*v_b^2/2) = 0.5*(1 - A_b/A_a)^0.75 for Re_b ≥ 1e4 (turbulent flow) zeta = 30/Re for Re_a < 10 (laminar flow)

Code:
encapsulated function suddenExpansion "Return pressure loss data for sudden expansion or contraction in a pipe (for both flow directions)"
  import Modelica.Units.SI;
  import Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.LossFactorData;
  input SI.Diameter diameter_a "Inner diameter of pipe at port_a" ;
  input SI.Diameter diameter_b "Inner diameter of pipe at port_b" ;
  output LossFactorData data "Pressure loss factors for both flow directions";
protected
  Real A_rel;
algorithm
  data.diameter_a := diameter_a;
  data.diameter_b := diameter_b;
  data.Re_turbulent := 100;
  data.zetaLaminarKnown := true;
  data.c0 := 30;
  if diameter_a <= diameter_b then
    A_rel := (diameter_a / diameter_b) ^ 2;
    data.zeta1 := (1 - A_rel) ^ 2;
    data.zeta2 := 0.5 * (1 - A_rel) ^ 0.75;
    data.zeta1_at_a := true;
    data.zeta2_at_a := true;
    data.D_Re := diameter_a;
  else
    A_rel := (diameter_b / diameter_a) ^ 2;
    data.zeta1 := 0.5 * (1 - A_rel) ^ 0.75;
    data.zeta2 := (1 - A_rel) ^ 2;
    data.zeta1_at_a := false;
    data.zeta2_at_a := false;
    data.D_Re := diameter_b;
  end if;

end suddenExpansion;

modelica://Modelica.Fluid/sharpEdgedOrif:
Modelica.Fluid: sharpEdgedOrifice (function)

Loss factor for mass flow rate from port_a to port_b (Idelchik 1994, diagram 4-14, p. 221):     zeta = [(1-A0/A1) + 0.707*(1-A0/A1)^0.375]^2*(A1/A0)^2 for Re(A0) ≥ 1e5, independent of alpha   
 Loss factor for mass flow rate from port_b to port_a (Idelchik 1994, diagram 4-13, p. 220, with A2=A1):     zeta = k*(1 - A0/A1)^0.75 + (1 - A0/A1)^2 + 2*sqrt(k*(1-A0/A1)^0.375) + (1- A0/A1) k = 0.13 + 0.34*10^(-(3.4*LD+88.4*LD^2.3)) (there is a typing error in the formula in diagram 4-13, the above equation corresponds to table (a) in diagram 4-12) LD = L/D0 for Re(A0) ≥ 1e4, 40 deg ≤ alpha ≤ 60 deg for other values of alpha, k is given as table in diagram 3-7 (this is not yet included in the function)

Code:
encapsulated function sharpEdgedOrifice "Return pressure loss data for sharp edged orifice (for both flow directions)"
  import Modelica.Units.SI;
  import Modelica.Units.NonSI;
  import Modelica.Fluid.Fittings.BaseClasses.QuadraticTurbulent.LossFactorData;
  input SI.Diameter diameter "Inner diameter of pipe (= same at port_a and port_b)" ;
  input SI.Diameter leastDiameter "Smallest diameter of orifice" ;
  input SI.Diameter length "Length of orifice" ;
  input NonSI.Angle_deg alpha "Angle of orifice" ;
  output LossFactorData data "Pressure loss factors for both flow directions";
protected
  Real D_rel = leastDiameter / diameter;
  Real LD = length / leastDiameter;
  Real k = 0.13 + 0.34 * 10 ^ (-(3.4 * LD + 88.4 * LD ^ 2.3));
algorithm
  data.diameter_a := diameter;
  data.diameter_b := diameter;
  data.zeta1 := (1 - D_rel + 0.707 * (1 - D_rel) ^ 0.375) ^ 2 * (1 / D_rel) ^ 2;
  data.zeta2 := k * (1 - D_rel) ^ 0.75 + (1 - D_rel) ^ 2 + 2 * sqrt(k * (1 - D_rel) ^ 0.375) + (1 - D_rel);
  data.Re_turbulent := 1e4;
  data.D_Re := leastDiameter;
  data.zeta1_at_a := true;
  data.zeta2_at_a := false;
  data.zetaLaminarKnown := false;
  data.c0 := 0;

end sharpEdgedOrifice;

modelica://Modelica.Fluid/massFlowRate:
Modelica.Fluid: massFlowRate (function)

This function returns the mass flow rate m_flow as function of pressure loss dp for a curved bend. The details of the function are described  here .   
 The bend characteristic is valid for constant density and constant dynamic viscosity. It can be approximately also used for compressible media. This is performed by providing the upstream density and upstream dynamic viscosity. In order to be able to regularize density and dynamic viscosity around zero mass flow rate, the two quantities have to be given if fluid flows from port_a to port_b (d_a, eta_a) and if fluid flows from port_b to port_a (d_b, eta_b).

Code:
function massFlowRate "Return mass flow rate m_flow as function of pressure loss dp for a curved bend"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure dp "Pressure loss";
  input Modelica.Fluid.Fittings.BaseClasses.Bends.CurvedBend.Geometry geometry "Geometry of bend";
  input Modelica.Units.SI.Density d_a "Density at port_a when fluid is flowing from port_a to port_b";
  input Modelica.Units.SI.Density d_b "Density at port_b when fluid is flowing from port_b to port_a";
  input Modelica.Units.SI.DynamicViscosity eta_a "Dynamic viscosity at port_a when fluid is flowing from port_a to port_b";
  input Modelica.Units.SI.DynamicViscosity eta_b "Dynamic viscosity at port_b when fluid is flowing from port_b to port_a";
  input Modelica.Units.SI.AbsolutePressure dp_small "Small pressure drop used for regularization if m_flow=f(...,dp_small,..,dp)";
  input Modelica.Units.SI.MassFlowRate m_flow_small "Small mass flow rate used for regularization if dp=f_inv(...,m_flow_small,m_flow)";
  output Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate (= port_a.m_flow)";
algorithm
  m_flow := Modelica.Fluid.Dissipation.PressureLoss.Bend.dp_curvedOverall_MFLOW(geometry, Modelica.Fluid.Dissipation.PressureLoss.Bend.dp_curvedOverall_IN_var(rho = Modelica.Fluid.Utilities.regStep(dp, d_a, d_b, dp_small), eta = Modelica.Fluid.Utilities.regStep(dp, eta_a, eta_b, dp_small)), dp);

end massFlowRate;

