modelica://Modelica.Fluid/circular:
Modelica.Fluid: circular (function)

Function that returns the ThickEdgedOrifice.Geometry for a circular cross section of the orifice.

Code:
function circular "Circular cross section"
  import Modelica.Constants.pi;
  input Modelica.Units.SI.Diameter diameter "Inner diameter of circular orifice" ;
  input Modelica.Units.SI.Diameter venaDiameter "Diameter of vena contraction" ;
  input Modelica.Units.SI.Length venaLength "Length of vena contraction" ;
  output Modelica.Fluid.Fittings.BaseClasses.Orifices.ThickEdgedOrifice.Geometry geometry "Geometry of circular thick edged orifice";
algorithm
  geometry.crossArea := diameter ^ 2 * pi / 4;
  geometry.perimeter := pi * diameter;
  geometry.venaCrossArea := venaDiameter ^ 2 * pi / 4;
  geometry.venaPerimeter := pi * venaDiameter;
  geometry.venaLength := venaLength;

end circular;

modelica://Modelica.Fluid/rectangular:
Modelica.Fluid: rectangular (function)

Function that returns the ThickEdgedOrifice.Geometry for a rectangular cross section of the orifice.

Code:
function rectangular "Rectangular cross section"
  import Modelica.Constants.pi;
  input Modelica.Units.SI.Length width "Inner width of rectangular orifice" ;
  input Modelica.Units.SI.Length height "Inner height of rectangular orifice" ;
  input Modelica.Units.SI.Length venaWidth "Width of vena contraction" ;
  input Modelica.Units.SI.Length venaHeight "Height of vena contraction" ;
  input Modelica.Units.SI.Length venaLength "Length of vena contraction" ;
  output Modelica.Fluid.Fittings.BaseClasses.Orifices.ThickEdgedOrifice.Geometry geometry "Geometry of circular thick edged orifice";
algorithm
  geometry.crossArea := width * height;
  geometry.perimeter := 2 * width + 2 * height;
  geometry.venaCrossArea := venaWidth * venaHeight;
  geometry.venaPerimeter := 2 * venaWidth + 2 * venaHeight;
  geometry.venaLength := venaLength;

end rectangular;

