  if not use_X_in then
    X_in_internal = X;
  end if;
  if not use_C_in then
    C_in_internal = C;
  end if;
  if Medium.ThermoStates == IndependentVariables.ph or Medium.ThermoStates == IndependentVariables.phX then
    medium.h = Medium.specificEnthalpy(Medium.setState_pTX(medium.p, T_in_internal, X_in_internal));
  else
    medium.T = T_in_internal;
  end if;
  sum(ports.m_flow) = -m_flow_in_internal;
  medium.Xi = X_in_internal[1:Medium.nXi];
  ports.C_outflow = fill(C_in_internal, nPorts);

end MassFlowSource_T;

Modelica.Fluid: MassFlowSource_h (model)

Models an ideal flow source, with prescribed values of flow rate, temperature and composition:   
Prescribed mass flow rate. Prescribed specific enthalpy. Boundary composition (only for multi-substance or trace-substance flow).  
If use_m_flow_in is false (default option), the m_flow parameter is used as boundary pressure, and the m_flow_in input connector is disabled; if use_m_flow_in is true, then the m_flow parameter is ignored, and the value provided by the input connector is used instead.  
The same thing goes for the temperature and composition  
 Note, that boundary temperature, mass fractions and trace substances have only an effect if the mass flow is from the boundary into the port. If mass is flowing from the port into the boundary, the boundary definitions, with exception of boundary flow rate, do not have an effect.

Code:
model MassFlowSource_h "Ideal flow source that produces a prescribed mass flow with prescribed specific enthalpy, mass fraction and trace substances"
  import Modelica.Media.Interfaces.Choices.IndependentVariables;
  extends Modelica.Fluid.Sources.BaseClasses.PartialFlowSource;
  parameter Boolean use_m_flow_in = false "Get the mass flow rate from the input connector" ;
  parameter Boolean use_h_in = false "Get the specific enthalpy from the input connector" ;
  parameter Boolean use_X_in = false "Get the composition from the input connector" ;
  parameter Boolean use_C_in = false "Get the trace substances from the input connector" ;
  parameter Medium.MassFlowRate m_flow = 0 "Fixed mass flow rate going out of the fluid port" ;
  parameter Medium.SpecificEnthalpy h = Medium.h_default "Fixed value of specific enthalpy" ;
  parameter Medium.MassFraction X[Medium.nX] = Medium.X_default "Fixed value of composition" ;
  parameter Medium.ExtraProperty C[Medium.nC](quantity = Medium.extraPropertiesNames) = Medium.C_default "Fixed values of trace substances" ;
  Modelica.Blocks.Interfaces.RealInput m_flow_in(unit = "kg/s") if use_m_flow_in "Prescribed mass flow rate" ;
  Modelica.Blocks.Interfaces.RealInput h_in(unit = "J/kg") if use_h_in "Prescribed fluid specific enthalpy" ;
  Modelica.Blocks.Interfaces.RealInput X_in[Medium.nX](each unit = "1") if use_X_in "Prescribed fluid composition" ;
  Modelica.Blocks.Interfaces.RealInput C_in[Medium.nC] if use_C_in "Prescribed boundary trace substances" ;
protected
  Modelica.Blocks.Interfaces.RealInput m_flow_in_internal(unit = "kg/s") "Needed to connect to conditional connector";
  Modelica.Blocks.Interfaces.RealInput h_in_internal(unit = "J/kg") "Needed to connect to conditional connector";
  Modelica.Blocks.Interfaces.RealInput X_in_internal[Medium.nX](each unit = "1") "Needed to connect to conditional connector";
  Modelica.Blocks.Interfaces.RealInput C_in_internal[Medium.nC] "Needed to connect to conditional connector";
equation
  Modelica.Fluid.Utilities.checkBoundary(Medium.mediumName, Medium.substanceNames, Medium.singleState, true, X_in_internal, "MassFlowSource_h");
  connect(m_flow_in, m_flow_in_internal);
  connect(h_in, h_in_internal);
  connect(X_in, X_in_internal);
  connect(C_in, C_in_internal);
  if not use_m_flow_in then
    m_flow_in_internal = m_flow;
  end if;
  if not use_h_in then
    h_in_internal = h;
  end if;
  if not use_X_in then
    X_in_internal = X;
  end if;
  if not use_C_in then
    C_in_internal = C;
  end if;
  if Medium.ThermoStates == IndependentVariables.ph or Medium.ThermoStates == IndependentVariables.phX then
    medium.h = h_in_internal;
  else
    medium.T = Medium.temperature(Medium.setState_phX(medium.p, h_in_internal, X_in_internal));
  end if;
  sum(ports.m_flow) = -m_flow_in_internal;
  medium.Xi = X_in_internal[1:Medium.nXi];
  ports.C_outflow = fill(C_in_internal, nPorts);

end MassFlowSource_h;

modelica://Modelica.Fluid/PartialSource:
Modelica.Fluid: PartialSource (model)

Partial component to model the volume interface of a source  component, such as a mass flow source. The essential features are:   
The pressure in the connection port (= ports.p) is identical to the pressure in the volume. The outflow enthalpy rate (= port.h_outflow) and the composition of the substances (= port.Xi_outflow) are identical to the respective values in the volume.

Code:
partial model PartialSource "Partial component source with one fluid connector"
  import Modelica.Constants;
  parameter Integer nPorts = 0 "Number of ports" ;
  replaceable package Medium = Modelica.Media.Interfaces.PartialMedium "Medium model within the source" ;
  Medium.BaseProperties medium "Medium in the source";
  Modelica.Fluid.Interfaces.FluidPorts_b ports[nPorts](redeclare each package Medium = Medium, m_flow(each max = if flowDirection == Modelica.Fluid.Types.PortFlowDirection.Leaving then 0 else +Constants.inf, each min = if flowDirection == Modelica.Fluid.Types.PortFlowDirection.Entering then 0 else -Constants.inf)) ;
protected
  parameter Modelica.Fluid.Types.PortFlowDirection flowDirection = Modelica.Fluid.Types.PortFlowDirection.Bidirectional "Allowed flow direction" ;
equation
  // Only one connection allowed to a port to avoid unwanted ideal mixing
  for i in 1:nPorts loop
    assert(cardinality(ports[i]) <= 1, "
each ports[i] of boundary shall at most be connected to one component.
If two or more connections are present, ideal mixing takes
place with these connections, which is usually not the intention
of the modeller. Increase nPorts to add an additional port.
");
    ports[i].p = medium.p;
    ports[i].h_outflow = medium.h;
    ports[i].Xi_outflow = medium.Xi;
  end for;

end PartialSource;

