  extends Modelica.Icons.RectangularSensor;
  replaceable package Medium = Modelica.Media.Interfaces.PartialMedium "Medium in the sensor" ;
  Modelica.Fluid.Interfaces.FluidPort_a port_a(m_flow(min = 0), redeclare package Medium = Medium) ;
  Modelica.Fluid.Interfaces.FluidPort_b port_b(m_flow(min = 0), redeclare package Medium = Medium) ;
equation
  // Zero flow equations for connectors
  port_a.m_flow = 0;
  port_b.m_flow = 0;
  // No contribution of specific quantities
  port_a.h_outflow = Medium.h_default;
  port_b.h_outflow = Medium.h_default;
  port_a.Xi_outflow = Medium.X_default[1:Medium.nXi];
  port_b.Xi_outflow = Medium.X_default[1:Medium.nXi];
  port_a.C_outflow = zeros(Medium.nC);
  port_b.C_outflow = zeros(Medium.nC);

end PartialRelativeSensor;

modelica://Modelica.Fluid/PartialFlowSen:
Modelica.Fluid: PartialFlowSensor (model)

Partial component to model a sensor that measures any intensive properties of a flow, e.g., to get temperature or density in the flow between fluid connectors.
 The model includes zero-volume balance equations. Sensor models inheriting from this partial class should add a medium instance to calculate the measured property.

Code:
partial model PartialFlowSensor "Partial component to model sensors that measure flow properties"
  extends Modelica.Fluid.Interfaces.PartialTwoPort;
  parameter Medium.MassFlowRate m_flow_nominal = system.m_flow_nominal "Nominal value of m_flow = port_a.m_flow" ;
  parameter Medium.MassFlowRate m_flow_small(min = 0) = if system.use_eps_Re then system.eps_m_flow * m_flow_nominal else system.m_flow_small "Regularization for bi-directional flow in the region |m_flow| < m_flow_small (m_flow_small > 0 required)" ;
equation
  // mass balance
  0 = port_a.m_flow + port_b.m_flow;
  // momentum equation (no pressure loss)
  port_a.p = port_b.p;
  // isenthalpic state transformation (no storage and no loss of energy)
  port_a.h_outflow = inStream(port_b.h_outflow);
  port_b.h_outflow = inStream(port_a.h_outflow);
  port_a.Xi_outflow = inStream(port_b.Xi_outflow);
  port_b.Xi_outflow = inStream(port_a.Xi_outflow);
  port_a.C_outflow = inStream(port_b.C_outflow);
  port_b.C_outflow = inStream(port_a.C_outflow);

end PartialFlowSensor;

