Code:
function kc_evenGapTurbulent_KC "Mean heat transfer coefficient of even gap | turbulent flow regime | developed fluid flow | heat transfer at BOTH sides | identical and constant wall temperatures"
  extends Modelica.Icons.Function;
  //SOURCE: VDI-Waermeatlas, 9th edition, Springer-Verlag, 2002, Section Gb 7
  //input records
  input Modelica.Fluid.Dissipation.HeatTransfer.Channel.kc_evenGapTurbulent_IN_con IN_con "Input record for function kc_evenGapTurbulent_KC" ;
  input Modelica.Fluid.Dissipation.HeatTransfer.Channel.kc_evenGapTurbulent_IN_var IN_var "Input record for function kc_evenGapTurbulent_KC" ;
  //output variables
  output Modelica.Units.SI.CoefficientOfHeatTransfer kc "Output for function kc_evenGapTurbulent_KC";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Area A_cross = max(MIN, IN_con.s * IN_con.h) "Cross sectional area of gap";
  Modelica.Units.SI.Diameter d_hyd = 2 * IN_con.s "Hydraulic diameter";
  Modelica.Units.SI.Velocity velocity = abs(IN_var.m_flow) / max(MIN, IN_var.rho * A_cross) "Mean velocity in gap";
  Modelica.Units.SI.ReynoldsNumber Re = max(MIN, IN_var.rho * velocity * d_hyd / max(MIN, IN_var.eta));
  Modelica.Units.SI.PrandtlNumber Pr = abs(IN_var.eta * IN_var.cp / max(MIN, IN_var.lambda));
  //SOURCE: p.Ga 5, eq. 27
  Real zeta = 1 / max(MIN, 1.8 * Modelica.Math.log10(abs(Re)) - 1.5) ^ 2 "Pressure loss coefficient";
  //SOURCE: p.Gb 5, eq. 26
  //assumption according to Gb 7, sec. 2.4
  Modelica.Units.SI.NusseltNumber Nu = abs(zeta / 8 * Re * Pr / (1 + 12.7 * (zeta / 8) ^ 0.5 * (Pr ^ (2 / 3) - 1)) * (1 + (d_hyd / max(MIN, IN_con.L)) ^ (2 / 3)));
  //Documentation
algorithm
  kc := Nu * (IN_var.lambda / max(MIN, d_hyd));

end kc_evenGapTurbulent_KC;

