Modelica.Fluid: kc_flatTube (function)

Calculation of the mean convective heat transfer coefficient kc for the air-side heat transfer of heat exchangers with flat tubes and several fin geometries. Note that additionally a failure status is observed in this function to check if the intended boundary conditions are fulfilled.  See more information .

Code:
function kc_flatTube
  extends Modelica.Icons.Function;
  //SOURCE: A.M. Jacobi, Y. Park, D. Tafti, X. Zhang. AN ASSESSMENT OF THE STATE OF THE ART, AND POTENTIAL DESIGN IMPROVEMENTS, FOR FLAT-TUBE HEAT EXCHANGERS IN AIR CONDITIONING AND REFRIGERATION APPLICATIONS - PHASE I
  //icon
  //input records
  input Modelica.Fluid.Dissipation.HeatTransfer.HeatExchanger.kc_flatTube_IN_con IN_con "Input record for function kc_flatTube" ;
  input Modelica.Fluid.Dissipation.HeatTransfer.HeatExchanger.kc_flatTube_IN_var IN_var "Input record for function kc_flatTube" ;
  //output variables
  output Modelica.Units.SI.CoefficientOfHeatTransfer kc "Convective heat transfer coefficient" ;
  output Modelica.Units.SI.PrandtlNumber Pr "Prandtl number" ;
  output Modelica.Units.SI.ReynoldsNumber Re "Reynolds number" ;
  output Modelica.Units.SI.NusseltNumber Nu "Nusselt number" ;
  output Real failureStatus "0== boundary conditions fulfilled | 1== failure >> check if still meaningful results" ;
protected
  type TYP = Modelica.Fluid.Dissipation.Utilities.Types.HTXGeometry_flatTubes;
  Modelica.Units.SI.Area A_c = if IN_con.geometry == TYP.LouverFin then IN_con.A_fr * ((IN_con.F_l - IN_con.delta_f) * (IN_con.F_p - IN_con.delta_f) / ((IN_con.F_l + IN_con.D_m) * IN_con.F_p)) else if IN_con.geometry == TYP.RectangularFin then IN_con.A_fr * (h * s / ((h + t + IN_con.D_m) * (s + t))) else 0 "Minimum flow cross-sectional area";
  Modelica.Units.SI.Length h = if IN_con.geometry == TYP.RectangularFin then IN_con.D_h * (1 + IN_con.alpha) / (2 * IN_con.alpha) else 0 "Free flow height";
  Modelica.Units.SI.Length l = if IN_con.geometry == TYP.RectangularFin then t / IN_con.delta else 0 "Fin length";
  Modelica.Units.SI.Length s = if IN_con.geometry == TYP.RectangularFin then h * IN_con.alpha else 0 "Lateral fin spacing (free flow width)";
  Modelica.Units.SI.Length t = if IN_con.geometry == TYP.RectangularFin then s * IN_con.gamma else 0 "Fin thickness";
algorithm
  kc := Modelica.Fluid.Dissipation.HeatTransfer.HeatExchanger.kc_flatTube_KC(IN_con, IN_var);
  Pr := abs(IN_var.eta * IN_var.cp / IN_var.lambda);
  if IN_con.geometry == TYP.LouverFin then
    Re := abs(IN_var.m_flow) * IN_con.L_p / (IN_var.eta * A_c);
    Nu := max(1e-3, kc * IN_con.L_p / IN_var.lambda);
  elseif IN_con.geometry == TYP.RectangularFin then
    Re := abs(IN_var.m_flow) * IN_con.D_h / (IN_var.eta * A_c);
    Nu := max(1e-3, kc * IN_con.D_h / IN_var.lambda);
  end if;
  failureStatus := if IN_con.geometry == TYP.LouverFin then if Re < 100 or Re > 3000 then 1 else 0 else if IN_con.geometry == TYP.RectangularFin then if Re < 300 or Re > 5000 then 1 else 0 else 0;

end kc_flatTube;

modelica://Modelica.Fluid/kc_flatTube_KC:
Modelica.Fluid: kc_flatTube_KC (function)

Calculation of the mean convective heat transfer coefficient kc for the air-side heat transfer of heat exchangers with flat tubes and several fin geometries.  See more information .

Code:
function kc_flatTube_KC
  extends Modelica.Icons.Function;
  //SOURCE: A.M. Jacobi, Y. Park, D. Tafti, X. Zhang. AN ASSESSMENT OF THE STATE OF THE ART, AND POTENTIAL DESIGN IMPROVEMENTS, FOR FLAT-TUBE HEAT EXCHANGERS IN AIR CONDITIONING AND REFRIGERATION APPLICATIONS - PHASE I
  //input records
  input Modelica.Fluid.Dissipation.HeatTransfer.HeatExchanger.kc_flatTube_IN_con IN_con "Input record for function kc_flatTube_KC" ;
  input Modelica.Fluid.Dissipation.HeatTransfer.HeatExchanger.kc_flatTube_IN_var IN_var "Input record for function kc_flatTube_KC" ;
  //output variables
  output Modelica.Units.SI.CoefficientOfHeatTransfer kc "Output for function kc_flatTubePlateFin_KC";
protected
  type TYP = Modelica.Fluid.Dissipation.Utilities.Types.HTXGeometry_flatTubes;
  Real MIN = Modelica.Constants.eps;
  Real Phi = IN_con.Phi * 180 / PI "Louver angle";
  Modelica.Units.SI.ReynoldsNumber Re_Dh = max(MIN, abs(IN_var.m_flow) * IN_con.D_h / (IN_var.eta * A_c)) "Reynolds number based on hydraulic diameter";
  Modelica.Units.SI.ReynoldsNumber Re_Lp = max(MIN, abs(IN_var.m_flow) * IN_con.L_p / (IN_var.eta * A_c)) "Reynolds number based on louver pitch";
  Modelica.Units.SI.PrandtlNumber Pr = IN_var.eta * IN_var.cp / IN_var.lambda "Prandtl number";
  Real j "Colburn j factor";
  Modelica.Units.SI.Area A_c = if IN_con.geometry == TYP.LouverFin then IN_con.A_fr * ((IN_con.F_l - IN_con.delta_f) * (IN_con.F_p - IN_con.delta_f) / ((IN_con.F_l + IN_con.D_m) * IN_con.F_p)) else if IN_con.geometry == TYP.RectangularFin then IN_con.A_fr * (h * s / ((h + t + IN_con.D_m) * (s + t))) else 0 "Minimum flow cross-sectional area";
  Modelica.Units.SI.Length h = if IN_con.geometry == TYP.RectangularFin then IN_con.D_h * (1 + IN_con.alpha) / (2 * IN_con.alpha) else 0 "Free flow height";
  Modelica.Units.SI.Length l = if IN_con.geometry == TYP.RectangularFin then t / IN_con.delta else 0 "Fin length";
  Modelica.Units.SI.Length s = if IN_con.geometry == TYP.RectangularFin then h * IN_con.alpha else 0 "Lateral fin spacing (free flow width)";
  Modelica.Units.SI.Length t = if IN_con.geometry == TYP.RectangularFin then s * IN_con.gamma else 0 "Fin thickness";
algorithm
  if IN_con.geometry == TYP.LouverFin then
    j := Re_Lp ^ (-0.49) * (Phi / 90) ^ 0.27 * (IN_con.F_p / IN_con.L_p) ^ (-0.14) * (IN_con.F_l / IN_con.L_p) ^ (-0.29) * (IN_con.T_d / IN_con.L_p) ^ (-0.23) * (IN_con.L_l / IN_con.L_p) ^ 0.68 * (IN_con.T_p / IN_con.L_p) ^ (-0.28) * (IN_con.delta_f / IN_con.L_p) ^ (-0.05);
    kc := j * (Re_Lp * Pr ^ (1 / 3) * IN_var.lambda / IN_con.L_p);
  elseif IN_con.geometry == TYP.RectangularFin then
    j := 0.6522 * Re_Dh ^ (-0.5403) * (s / h) ^ (-0.1541) * (t / l) ^ 0.1499 * (t / s) ^ (-0.0678) * (1 + 5.269e-5 * Re_Dh ^ 1.340 * (s / h) ^ 0.504 * (t / l) ^ 0.456 * (t / s) ^ (-1.055)) ^ 0.1;
    kc := j * (Re_Dh * Pr ^ (1 / 3) * IN_var.lambda / IN_con.D_h);
  end if;

end kc_flatTube_KC;

