  input Modelica.Fluid.Dissipation.HeatTransfer.HeatExchanger.kc_roundTube_IN_var IN_var "Input record for function kc_roundTube_KC" ;
  //output variables
  output Modelica.Units.SI.CoefficientOfHeatTransfer kc "Output for function kc_roundTube_KC";
protected
  type TYP = Modelica.Fluid.Dissipation.Utilities.Types.HTXGeometry_roundTubes;
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.ReynoldsNumber Re_Dc = max(MIN, abs(IN_var.m_flow) * IN_con.D_c / (IN_var.eta * A_c)) "Reynolds number based on fin collar diameter";
  Modelica.Units.SI.ReynoldsNumber Re_i "Reynolds number at transition to linearized calculation for wavy fins";
  Modelica.Units.SI.PrandtlNumber Pr = IN_var.eta * IN_var.cp / IN_var.lambda "Prandtl number";
  Real j "Colburn j factor";
  Modelica.Units.SI.Area A_c = IN_con.A_fr * ((IN_con.F_p * IN_con.P_t - IN_con.F_p * IN_con.D_c - (IN_con.P_t - IN_con.D_c) * IN_con.delta_f) / (IN_con.F_p * IN_con.P_t)) "Minimum flow cross-sectional area";
  Modelica.Units.SI.Area A_tot = if IN_con.geometry == TYP.LouverFin then IN_con.A_fr * ((IN_con.N * PI * IN_con.D_c * (IN_con.F_p - IN_con.delta_f) + 2 * (IN_con.P_t * IN_con.L - IN_con.N * PI * IN_con.D_c ^ 2 / 4)) / (IN_con.P_t * IN_con.F_p)) else 0 "Total heat transfer area";
  Modelica.Units.SI.Length D_h = if IN_con.geometry == TYP.LouverFin then 4 * A_c * IN_con.L / A_tot else 0 "Hydraulic diameter";
  /*SI.Length D_h=
    if IN_con.geometry==2 then
      4*A_c/(IN_con.A_fr*(2*(IN_con.P_t-IN_con.D_c+IN_con.F_p-IN_con.delta_f)/(IN_con.F_p*IN_con.P_t))) else
      0 "Hydraulic diameter";*/
  Real J1 = 0 "Exponent for computation of Colburn j factor";
  Real J2 = 0 "Exponent for computation of Colburn j factor";
  Real J3 = 0 "Exponent for computation of Colburn j factor";
  Real J4 = 0 "Exponent for computation of Colburn j factor";
  Real J5 = 0 "Exponent for computation of Colburn j factor";
  Real J6 = 0 "Exponent for computation of Colburn j factor";
  Real J7 = 0 "Exponent for computation of Colburn j factor";
  Real J8 = 0 "Exponent for computation of Colburn j factor";
algorithm
  if IN_con.geometry == TYP.PlainFin then
    j := 0.991 * (2.24 * Re_Dc ^ (-0.092) * (IN_con.N / 4) ^ (-0.031)) ^ (0.607 * (4 - IN_con.N)) * (0.14 * Re_Dc ^ (-0.328) * (IN_con.P_t / IN_con.P_l) ^ (-0.502) * (IN_con.F_p / IN_con.D_c) ^ 0.0312) * (2.55 * (IN_con.P_l / IN_con.D_c) ^ (-1.28));
