      j := (Re_Dc - Re_i) * (-1.201 * 2.921 * (A_c / IN_con.A_fr) / (Modelica.Math.log(Re_i ^ (A_c / IN_con.A_fr)) ^ 3.921 * Re_i)) + 1.201 / Modelica.Math.log(Re_i ^ (A_c / IN_con.A_fr)) ^ 2.921;
    end if;
    kc := j * (Re_Dc * Pr ^ (1 / 3) * IN_var.lambda / IN_con.D_c);
  end if;

end kc_roundTube_KC;

