  //Notation of equations according to SOURCE
  //input records
  input Modelica.Fluid.Dissipation.HeatTransfer.Plate.kc_laminar_IN_con IN_con "Input record for function kc_laminar" ;
  input Modelica.Fluid.Dissipation.HeatTransfer.Plate.kc_laminar_IN_var IN_var "Input record for function kc_laminar" ;
