  input Modelica.Fluid.Dissipation.HeatTransfer.Plate.kc_laminar_IN_var IN_var "Input record for function kc_laminar_KC" ;
  //output variables
  output Modelica.Units.SI.CoefficientOfHeatTransfer kc "Output for function kc_laminar_KC";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Length L = max(MIN, IN_con.L);
  Modelica.Units.SI.SpecificHeatCapacityAtConstantPressure cp = IN_var.cp;
  Modelica.Units.SI.DynamicViscosity eta = max(MIN, IN_var.eta);
  Modelica.Units.SI.ThermalConductivity lambda = max(MIN, IN_var.lambda);
