Calculation of mean convective heat transfer coefficient kc of a straight pipe at an uniform wall temperature or uniform heat flux and for a hydrodynamically developed or undeveloped laminar fluid flow. See more information .

Code:
function kc_laminar_KC "Mean heat transfer coefficient of straight pipe | uniform wall temperature or uniform heat flux | hydrodynamically developed or undeveloped laminar flow regime"
  extends Modelica.Icons.Function;
  //input records
  input Modelica.Fluid.Dissipation.HeatTransfer.StraightPipe.kc_laminar_IN_con IN_con "Input record for function kc_laminar_KC" ;
  input Modelica.Fluid.Dissipation.HeatTransfer.StraightPipe.kc_laminar_IN_var IN_var "Input record for function kc_laminar_KC" ;
  //output variables
  output Modelica.Units.SI.CoefficientOfHeatTransfer kc "Output for function kc_laminar_KC";
protected
  type TYP = Modelica.Fluid.Dissipation.Utilities.Types.HeatTransferBoundary;
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Area A_cross = PI * IN_con.d_hyd ^ 2 / 4 "Circular cross sectional area";
  Real Nu0 = if IN_con.target == TYP.UWTuDFF or IN_con.target == TYP.UWTuUFF then 0.7 else if IN_con.target == TYP.UHFuDFF or IN_con.target == TYP.UHFuUFF then 0.6 else 0 "Help variable for mean Nusselt number";
  Real Nu1 = if IN_con.target == TYP.UWTuDFF or IN_con.target == TYP.UWTuUFF then 3.66 else if IN_con.target == TYP.UHFuDFF or IN_con.target == TYP.UHFuUFF then 4.364 else 0 "Help variable for mean Nusselt number";
  Modelica.Units.SI.Velocity velocity = abs(IN_var.m_flow) / max(MIN, IN_var.rho * A_cross) "Mean velocity";
  Modelica.Units.SI.ReynoldsNumber Re = IN_var.rho * velocity * IN_con.d_hyd / max(MIN, IN_var.eta);
  Modelica.Units.SI.PrandtlNumber Pr = abs(IN_var.eta * IN_var.cp / max(MIN, IN_var.lambda));
  Modelica.Units.SI.NusseltNumber Nu2 = if IN_con.target == TYP.UWTuDFF or IN_con.target == TYP.UWTuUFF then 1.615 * (Re * Pr * IN_con.d_hyd / IN_con.L) ^ (1 / 3) else if IN_con.target == TYP.UHFuDFF or IN_con.target == TYP.UHFuUFF then 1.953 * (Re * Pr * IN_con.d_hyd / IN_con.L) ^ (1 / 3) else 0 "Help variable for mean Nusselt number";
  Modelica.Units.SI.NusseltNumber Nu3 = if IN_con.target == TYP.UWTuUFF then (2 / (1 + 22 * Pr)) ^ (1 / 6) * (Re * Pr * IN_con.d_hyd / IN_con.L) ^ 0.5 else if IN_con.target == TYP.UHFuUFF then 0.924 * Pr ^ (1 / 3) * (Re * IN_con.d_hyd / IN_con.L) ^ (1 / 2) else 0 "Help variable for mean Nusselt number";
  Modelica.Units.SI.NusseltNumber Nu = (Nu1 ^ 3 + Nu0 ^ 3 + (Nu2 - Nu0) ^ 3 + Nu3 ^ 3) ^ (1 / 3) "Mean Nusselt number";
  //Documentation
algorithm
  kc := Nu * IN_var.lambda / max(MIN, IN_con.d_hyd);

end kc_laminar_KC;

