function kc_overall "Mean heat transfer coefficient of straight pipe | uniform wall temperature or uniform heat flux | hydrodynamically developed or undeveloped overall flow regime| pressure loss dependence"
  extends Modelica.Icons.Function;
  //input records
  input Modelica.Fluid.Dissipation.HeatTransfer.StraightPipe.kc_overall_IN_con IN_con "Input record for function kc_overall" ;
  input Modelica.Fluid.Dissipation.HeatTransfer.StraightPipe.kc_overall_IN_var IN_var "Input record for function kc_overall" ;
  //output variables
  output Modelica.Units.SI.CoefficientOfHeatTransfer kc "Convective heat transfer coefficient" ;
  output Modelica.Units.SI.PrandtlNumber Pr "Prandtl number" ;
  output Modelica.Units.SI.ReynoldsNumber Re "Reynolds number" ;
  output Modelica.Units.SI.NusseltNumber Nu "Nusselt number" ;
  output Real failureStatus "0== boundary conditions fulfilled | 1== failure >> check if still meaningful results" ;
protected
  type TYP = Modelica.Fluid.Dissipation.Utilities.Types.Roughness;
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Area A_cross = PI * IN_con.d_hyd ^ 2 / 4 "Cross sectional area";
  Modelica.Units.SI.Velocity velocity = abs(IN_var.m_flow) / max(MIN, IN_var.rho * A_cross) "Mean velocity";
  //failure status
  Real fstatus[3] "Check of expected boundary conditions";
algorithm
  Pr := abs(IN_var.eta * IN_var.cp / max(MIN, IN_var.lambda));
  Re := IN_var.rho * velocity * IN_con.d_hyd / max(MIN, IN_var.eta);
  kc := Modelica.Fluid.Dissipation.HeatTransfer.StraightPipe.kc_overall_KC(IN_con, IN_var);
  Nu := kc * IN_con.d_hyd / max(MIN, IN_var.lambda);
  //failure status
  if IN_con.roughness == TYP.Neglected then
    if Re < 2e4 or Re > 1e6 then
      fstatus[1] := 1;
    else
      fstatus[1] := 0;
    end if;
  elseif IN_con.roughness == TYP.Considered then
    if Re < 1e4 or Re > 1e6 then
      fstatus[1] := 1;
    else
      fstatus[1] := 0;
    end if;
  else
    assert(false, "No choice of roughness is selected");
  end if;
  fstatus[2] := if Pr < 0.6 or Pr > 1e3 then 1 else 0;
  fstatus[3] := if IN_con.d_hyd / max(MIN, IN_con.L) > 1 then 1 else 0;
  failureStatus := 0;
  for i in 1:size(fstatus, 1) loop
    if fstatus[i] == 1 then
      failureStatus := 1;
    end if;
  end for;

end kc_overall;

