  Modelica.Units.SI.ReynoldsNumber Re_min = 1 "Minimum Reynolds number";
  Modelica.Units.SI.ReynoldsNumber Re_lam_max = 6.5e3 "Maximum Reynolds number for laminar regime (6.5e3)";
  Modelica.Units.SI.ReynoldsNumber Re_turb_min = 4e4 "Minimum Reynolds number for turbulent regime (4e4)";
  Modelica.Units.SI.ReynoldsNumber Re_turb_max = 3e5 "Maximum Reynolds number for turbulent regime (3e5)";
  Modelica.Units.SI.ReynoldsNumber Re_turb_const = 1e6 "Reynolds number for independence on pressure loss coefficient (1e6)";
  Modelica.Units.SI.ReynoldsNumber Re_lam_leave = min(Re_lam_max, max(1e2, 754 * Modelica.Math.exp(if k <= 0.007 then 0.0065 / 0.007 else 0.0065 / k))) "Start of transition regime for increasing Reynolds number (leaving laminar regime)";
  //SOURCE_1: p.357, diag. 6-1: coefficients for local resistance coefficient [zeta_LOC]:
  //IN_con.R_0/IN_con.d_hyd <= 3
  Real A1 = if delta <= 70 then 0.9 * sin(delta / 180 * PI) else if delta >= 100 then 0.7 + 0.35 * delta / 90 else 1.0 "Coefficient considering effect for angle of turning on zeta_LOC";
  Real A2 = if frac_RD > 2.0 then 6e2 else if frac_RD <= 2.0 and frac_RD > 0.55 then if frac_RD > 1.0 then 1e3 else if frac_RD <= 1.0 and frac_RD > 0.7 then 3e3 else 6e3 else 4e3 "Coefficient considering laminar regime on zeta_LOC";
  Real B1 = if frac_RD >= 1.0 then 0.21 * frac_RD ^ (-0.5) else 0.21 * frac_RD ^ (-2.5) "Coefficient considering relative curvature radius (R_0/d_hyd) on zeta_LOC";
  Real C1 = 1.0 "Considering relative elongation of cross sectional area on zeta_LOC (here: circular cross sectional area)";
  Modelica.Fluid.Dissipation.Utilities.Types.LocalResistanceCoefficient zeta_LOC_sharp_turb = max(MIN, A1 * B1 * C1) "Local resistance coefficient for turbulent regime (Re > Re_turb_max)";
  //SOURCE_1: p.357, diag. 6-1: pressure loss boundaries for w.r.t. flow regimes
  //IN_con.R_0/d_hyd <=3
  Modelica.Units.SI.AbsolutePressure dp_lam_max = (zeta_LOC_sharp_turb + A2 / Re_lam_leave) * IN_var.rho / 2 * (Re_lam_leave * IN_var.eta / (IN_var.rho * d_hyd)) ^ 2 "Maximum pressure loss for laminar regime";
  Modelica.Units.SI.AbsolutePressure dp_turb_min = zeta_LOC_sharp_turb * (if frac_RD > 0.7 then 11.5 / Re_turb_min ^ 0.19 else if frac_RD <= 0.7 and frac_RD >= 0.55 then 5.45 / Re_turb_min ^ 0.131 else 1 + 4400 / Re_turb_min) * IN_var.rho / 2 * (Re_turb_min * IN_var.eta / (IN_var.rho * d_hyd)) ^ 2 "Minimum pressure loss for turbulent regime";
  Modelica.Units.SI.AbsolutePressure dp_turb_max = zeta_LOC_sharp_turb * (if frac_RD > 0.7 then 11.5 / Re_turb_max ^ 0.19 else if frac_RD <= 0.7 and frac_RD >= 0.55 then 5.45 / Re_turb_max ^ 0.131 else 1 + 4400 / Re_turb_max) * IN_var.rho / 2 * (Re_turb_max * IN_var.eta / (IN_var.rho * d_hyd)) ^ 2 "Maximum pressure loss for turbulent regime";
  Modelica.Units.SI.AbsolutePressure dp_turb_const = zeta_LOC_sharp_turb * IN_var.rho / 2 * (Re_turb_const * IN_var.eta / (IN_var.rho * d_hyd)) ^ 2 "Pressure loss for independence of Reynolds number on pressure loss coefficient";
  //SOURCE_1: p.357, diag. 6-1: mean velocities for assumed flow regime
  //IN_con.R_0/d_hyd <=3
  Modelica.Units.SI.Velocity v_lam = if 1e7 * sqrt(abs(zeta_LOC_sharp_turb * abs(dp) * IN_var.rho * d_hyd ^ 2)) < abs(A2 * IN_var.eta) then 2 * abs(dp) * d_hyd / A2 / IN_var.eta else (-A2 / 2 * IN_var.eta + 0.5 * sqrt(max(MIN, (A2 * IN_var.eta) ^ 2 + 8 * zeta_LOC_sharp_turb * abs(dp) * IN_var.rho * d_hyd ^ 2))) / zeta_LOC_sharp_turb / IN_var.rho / d_hyd "Mean velocity in laminar regime (Re < Re_lam_leave)";
  Modelica.Units.SI.Velocity v_tra = if 1e7 * sqrt(abs(zeta_LOC_sharp_turb * abs(dp_lam_max) * IN_var.rho * d_hyd ^ 2)) < abs(A2 * IN_var.eta) then 2 * abs(dp_lam_max) * d_hyd / A2 / IN_var.eta else (-A2 / 2 * IN_var.eta + 0.5 * sqrt(max(MIN, (A2 * IN_var.eta) ^ 2 + 8 * zeta_LOC_sharp_turb * abs(dp_lam_max) * IN_var.rho * d_hyd ^ 2))) / zeta_LOC_sharp_turb / IN_var.rho / d_hyd "Mean velocity in transition regime (Re_lam_leave < Re_turb_min)";
  Modelica.Units.SI.Velocity v_turb = if frac_RD > 0.7 then (max(MIN, abs(dp)) / (IN_var.rho / 2 * 11.5 * zeta_LOC_sharp_turb) * (IN_var.rho * IN_con.d_hyd / max(MIN, IN_var.eta)) ^ 0.19) ^ (1 / (2 - 0.19)) else if frac_RD > 0.55 and frac_RD < 0.7 then (max(MIN, abs(dp)) / (IN_var.rho / 2 * 5.45 * zeta_LOC_sharp_turb) * (IN_var.rho * IN_con.d_hyd / max(MIN, IN_var.eta)) ^ 0.131) ^ (1 / (2 - 0.131)) else -2200 / (IN_var.rho * IN_con.d_hyd / IN_var.eta) + ((-2200 / (IN_var.rho * IN_con.d_hyd / max(MIN, IN_var.eta))) ^ 2 + 2 * abs(max(MIN, dp)) / max(MIN, IN_var.rho)) ^ 0.5 "Mean velocity in turbulent regime with dependence on pressure loss coefficient (Re_turb_min < Re < Re_turb_max)";
  Modelica.Units.SI.Velocity v_turb_const = sqrt(max(MIN, 2 * abs(dp) / (IN_var.rho * zeta_LOC_sharp_turb))) "Mean velocity in turbulent regime with independence on pressure loss coefficient (Re > Re_turb_max)";
  //mean velocity under smooth conditions w.r.t. flow regime
  Modelica.Units.SI.Velocity v_smooth = if dp < dp_lam_max then v_lam else if dp < dp_turb_min then Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(dp_lam_max, dp_turb_min, dp) * v_lam + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(dp_turb_min, dp_lam_max, dp) * v_turb else if dp < dp_turb_max then v_turb else Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(dp_turb_max, dp_turb_const, dp) * v_turb + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(dp_turb_const, dp_turb_max, dp) * v_turb_const "Mean velocity under smooth conditions for R_0/d_hyd < 3";
  Modelica.Units.SI.ReynoldsNumber Re_smooth = max(Re_min, IN_var.rho * v_smooth * d_hyd / IN_var.eta) "Reynolds number under smooth conditions";
  //SOURCE_2: p.191, eq. 8.4: considering surface roughness
  //restriction of lambda_FRI at maximum Reynolds number Re=1e6 (SOURCE_2: p.207, sec. 9.2.4)
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_FRI_rough = 0.25 / Modelica.Math.log10(k / (3.7 * IN_con.d_hyd) + 5.74 / min(1e6, max(Re_lam_leave, Re_smooth)) ^ 0.9) ^ 2 "Darcy friction factor considering surface roughness";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_FRI_smooth = 0.25 / Modelica.Math.log10(5.74 / max(Re_lam_leave, Re_smooth) ^ 0.9) ^ 2 "Darcy friction factor neglecting surface roughness";
  //SOURCE_2: p.207, sec. 9.2.4: correction factors CF w.r.t.surface roughness
  Real CF_3 = 1 + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(6e3, 1e3, Re_smooth) * min(1.4, lambda_FRI_rough * L / d_hyd / zeta_LOC_sharp_turb) + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(1e3, 6e3, Re_smooth) "Correction factor for surface roughness";
  Modelica.Units.SI.Velocity velocity = v_smooth / max(1, CF_3) ^ 0.5 "Corrected velocity considering surface roughness";
  //Documentation
algorithm
  M_FLOW := sign(dp) * IN_var.rho * A_cross * abs(velocity);

end dp_curvedOverall_MFLOW;

