Modelica.Fluid: dp_edgedOverall_DP (function)

Calculation of pressure loss in edged bends with sharp corners at overall flow regime for incompressible and single-phase fluid flow through circular cross sectional area considering surface roughness.   
 There are larger pressure losses in an edged bend compared to a curved bend under the same conditions. The effect of a sharp corner in an edged bend on the pressure loss is much larger than the influence of surface roughness.   
 Generally this function is numerically best used for the incompressible case , where the mass flow rate (m_flow) is known (as state variable) in the used model and the corresponding pressure loss (DP) has to be calculated. On the other hand the function dp_edgedOverall_MFLOW is numerically best used for the compressible case if the pressure loss (dp) is known (out of pressures as state variable) and the mass flow rate (M_FLOW) has to be calculated.  See more information .

Code:
function dp_edgedOverall_DP "Pressure loss of edged bend | calculate pressure loss | overall flow regime | surface roughness"
  extends Modelica.Icons.Function;
  //SOURCE_1: Idelchik, I.E.: HANDBOOK OF HYDRAULIC RESISTANCE, 3rd edition, 2006.
  //SOURCE_2: Miller, D.S.: INTERNAL FLOW SYSTEMS, 2nd edition, 1984.
  //SOURCE_3: VDI-Waermeatlas, 9th edition, Springer-Verlag, 2002, Section Lac 6 (Verification)
  //Notation of equations according to SOURCES
  import FD = Modelica.Fluid.Dissipation.PressureLoss.Bend;
  import SMOOTH = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother;
  //input records
  input FD.dp_edgedOverall_IN_con IN_con "Input record for function dp_edgedOverall_DP" ;
  input FD.dp_edgedOverall_IN_var IN_var "Input record for function dp_edgedOverall_DP" ;
  input Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate" ;
  //output variables
  output Modelica.Units.SI.Pressure DP "Output for function dp_edgedOverall_DP";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Diameter d_hyd = max(MIN, IN_con.d_hyd) "Hydraulic diameter";
  Modelica.Units.SI.Area A_cross = PI * d_hyd ^ 2 / 4 "Circular cross sectional area";
  Real k = max(MIN, abs(IN_con.K) / IN_con.d_hyd) "Relative roughness";
  Real delta = IN_con.delta * 180 / PI "Angle of turning";
  //definition of flow regime boundaries
  //SOURCE_2: p.207, sec. 9.2.4
  //SOURCE_3: p.Lac 6, fig. 16
  Modelica.Units.SI.ReynoldsNumber Re_min = 1 "Minimum Reynolds number";
  Modelica.Units.SI.ReynoldsNumber Re_lam_min = 5e2 "Start of transition regime for roughness contribution";
  Modelica.Units.SI.ReynoldsNumber Re_lam_max = 1e4 "End of transition regime for roughness contribution";
  Modelica.Units.SI.ReynoldsNumber Re_turb_min = 1e5 "Minimum Reynolds number for Reynolds-dependent transition regime";
  Modelica.Units.SI.ReynoldsNumber Re_turb_max = 2e5 "Maximum Reynolds number for Reynolds-dependent transition regime (k_Re=1)";
  Modelica.Units.SI.ReynoldsNumber Re_turb_const = 1e6 "Reynolds number for independence on pressure loss coefficient (1e6)";
  //SOURCE_1: p. 81, sec. 2-2-21: start of transition regime
  Modelica.Units.SI.ReynoldsNumber Re_lam_leave = min(Re_lam_max, max(Re_lam_min, 754 * Modelica.Math.exp(if k <= 0.007 then 0.0065 / 0.007 else 0.0065 / k))) "Start of transition regime for increasing Reynolds number (leaving laminar regime)";
  //SOURCE_1: p.366, diag. 6-7
  Real A = 0.95 + 33.5 / max(MIN, delta) "Coefficient considering effect of angle of turning on zeta_LOC";
  Real C1 = 1 "Considering relative elongation of cross sectional area on zeta_LOC (here: circular cross sectional area)";
  //SOURCE_1: p.366, diag. 6-7
  Modelica.Fluid.Dissipation.Utilities.Types.LocalResistanceCoefficient zeta_LOC = max(MIN, 0.95 * sin(PI / 180 * delta / 2) ^ 2 + 2.05 * sin(PI / 180 * delta / 2) ^ 4) "Local resistance coefficient";
  //SOURCE_1: p.365: Correction w.r.t. effect of Reynolds number in laminar regime
  Real B = 24.8 "Coefficient considering effect of Reynolds number on zeta_TOT";
  Real exp = 0.263 "Exponent for Reynolds number correction in laminar regime";
  Real v_min = Re_min * IN_var.eta / (IN_var.rho * d_hyd) "Minimum mean velocity for linear interpolation";
  Modelica.Units.SI.Velocity velocity = m_flow / (IN_var.rho * A_cross) "Mean velocity";
  Modelica.Units.SI.ReynoldsNumber Re = max(Re_min, IN_var.rho * abs(velocity) * d_hyd / IN_var.eta) "Reynolds number";
  //SOURCE_2: p.191, eq. 8.4: considering surface roughness
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_FRI_rough = 0.25 / Modelica.Math.log10(k / (3.7 * IN_con.d_hyd) + 5.74 / max(Re_lam_min, Re) ^ 0.9) ^ 2 "Darcy friction factor considering surface roughness";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_FRI_smooth = 0.25 / Modelica.Math.log10(5.74 / max(Re_lam_min, Re) ^ 0.9) ^ 2 "Darcy friction factor neglecting surface roughness";
  //SOURCE_3: Lac 6, Figure 18
  Real CF_fri = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(Re_lam_leave, Re_lam_min, Re) * max(1, min(1.4, lambda_FRI_rough / lambda_FRI_smooth)) + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(Re_lam_min, Re_lam_leave, Re) "Correction factor for surface roughness";
  //SOURCE_2: p.208, diag. 9.3: Correction w.r.t. effect of Reynolds number
  Real CF_Re = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(Re_turb_min, Re_turb_max, Re) * B / Re ^ exp + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(Re_turb_max, Re_turb_min, Re) "Correction factor for Reynolds number";
  Modelica.Fluid.Dissipation.Utilities.Types.PressureLossCoefficient zeta_TOT = A * C1 * zeta_LOC * CF_Re * CF_fri "Pressure loss coefficient";
algorithm
  DP := zeta_TOT * (IN_var.rho / 2) * Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower(velocity, v_min, 2);

end dp_edgedOverall_DP;

Modelica.Fluid: dp_edgedOverall_MFLOW (function)

Calculation of pressure loss in edged bends with sharp corners at overall flow regime for incompressible and single-phase fluid flow through circular cross sectional area considering surface roughness.   
 There are larger pressure losses in an edged bend compared to a curved bend under the same conditions. The effect of a sharp corner in an edged bend on the pressure loss is much larger than the influence of surface roughness.   
 Generally this function is numerically best used for the compressible case if the pressure loss (dp) is known (out of pressures as state variable) and the mass flow rate (M_FLOW) has to be calculated. On the other hand the function dp_edgedOverall_DP is numerically best used for the incompressible case , where the mass flow rate (m_flow) is known (as state variable) in the used model and the corresponding pressure loss (DP) has to be calculated.  See more information .

Code:
function dp_edgedOverall_MFLOW "Pressure loss of edged bend | calculate mass flow rate | overall flow regime | surface roughness"
  extends Modelica.Icons.Function;
  //SOURCE_1: Idelchik, I.E.: HANDBOOK OF HYDRAULIC RESISTANCE, 3rd edition, 2006.
  //SOURCE_2: Miller, D.S.: INTERNAL FLOW SYSTEMS, 2nd edition, 1984.
  //SOURCE_3: VDI-Waermeatlas, 9th edition, Springer-Verlag, 2002, Section Lac 6 (Verification)
  //Notation of equations according to SOURCES
  import FD = Modelica.Fluid.Dissipation.PressureLoss.Bend;
  import SMOOTH = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother;
  //input records
  input FD.dp_edgedOverall_IN_con IN_con "Input record for function dp_edgedOverall_MFLOW" ;
  input FD.dp_edgedOverall_IN_var IN_var "Input record for function dp_edgedOverall_MFLOW" ;
  input Modelica.Units.SI.Pressure dp "Pressure loss" ;
  //output variables
  output Modelica.Units.SI.MassFlowRate M_FLOW "Output for function dp_edgedOverall_MFLOW";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Diameter d_hyd = IN_con.d_hyd "Hydraulic diameter";
  Modelica.Units.SI.Area A_cross = PI * d_hyd ^ 2 / 4 "Circular cross sectional area";
  Real k = max(MIN, abs(IN_con.K) / IN_con.d_hyd) "Relative roughness";
  Real delta = IN_con.delta * 180 / PI "Angle of turning";
  //definition of flow regime boundaries
  //SOURCE_2: p.207, sec. 9.2.4
  //SOURCE_3: p.Lac 6, fig. 16
  Modelica.Units.SI.ReynoldsNumber Re_min = 1 "Minimum Reynolds number";
  Modelica.Units.SI.ReynoldsNumber Re_lam_min = 500 "Start of transition regime for roughness contribution";
  Modelica.Units.SI.ReynoldsNumber Re_lam_max = 1e4 "End of transition regime for roughness contribution";
  Modelica.Units.SI.ReynoldsNumber Re_turb_min = 1e5 "Minimum Reynolds number for Reynolds-dependent transition regime";
  Modelica.Units.SI.ReynoldsNumber Re_turb_max = 2e5 "Maximum Reynolds number for Reynolds-dependent transition regime (k_Re=1)";
  Modelica.Units.SI.ReynoldsNumber Re_turb_const = 1e6 "Reynolds number for independence on pressure loss coefficient (1e6)";
  //SOURCE_1: p. 81, sec. 2-2-21: start of transition regime
  Modelica.Units.SI.ReynoldsNumber Re_lam_leave = min(Re_lam_max, max(Re_lam_min, 754 * Modelica.Math.exp(if k <= 0.007 then 0.0065 / 0.007 else 0.0065 / k))) "Start of transition regime for increasing Reynolds number (leaving laminar regime)";
  //SOURCE_1: p.366, diag. 6-7
  Real A = 0.95 + 33.5 / max(MIN, delta) "Coefficient considering effect of angle of turning on zeta_LOC";
  Real C1 = 1 "Considering relative elongation of cross sectional area on zeta_LOC (here: circular cross sectional area)";
  //SOURCE_1: p.366, diag. 6-7
  Modelica.Fluid.Dissipation.Utilities.Types.LocalResistanceCoefficient zeta_LOC = max(MIN, 0.95 * sin(PI / 180 * delta / 2) ^ 2 + 2.05 * sin(PI / 180 * delta / 2) ^ 4) "Local resistance coefficient";
  //SOURCE_1: p.365: Correction w.r.t. effect of Reynolds number
  Real B = 24.8 "Coefficient considering effect of Reynolds number on zeta_TOT";
  Real exp = 0.263 "Exponent for Reynolds number correction";
  Real pow = 2 - exp "Pressure loss = f(mass flow rate^pow)";
  //   Real k_Re = B/(max(MIN, velocity)*IN_con.d_hyd*IN_var.rho)^exp*IN_var.eta^exp;
  Modelica.Units.SI.Velocity v_min = Re_min * IN_var.eta / (IN_var.rho * d_hyd) "Minimum mean velocity for regularization";
  Modelica.Units.SI.Pressure dp_min = A * C1 * zeta_LOC * (B / 2) * (d_hyd / IN_var.eta) ^ (-exp) * IN_var.rho ^ (1 - exp) * v_min ^ pow "Linear smoothing of mass flow rate for decreasing pressure loss";
  Modelica.Units.SI.Velocity v_lam_min = Re_lam_min * IN_var.eta / (IN_var.rho * d_hyd) "Mean velocity for starting of transition to roughness regime";
  Modelica.Units.SI.Velocity v_lam_leave = Re_lam_leave * IN_var.eta / (IN_var.rho * d_hyd) "Mean velocity for end of transition to roughness regime";
  Modelica.Units.SI.Pressure dp_lam_min = A * C1 * zeta_LOC * (B / 2) * (d_hyd / IN_var.eta) ^ (-exp) * IN_var.rho ^ (1 - exp) * v_lam_min ^ pow "Pressure loss for starting of transition to roughness regime";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_lam_leave_rough = 0.25 / Modelica.Math.log10(k / (3.7 * IN_con.d_hyd) + 5.74 / Re_lam_leave ^ 0.9) ^ 2 "Darcy friction factor considering surface roughness at Re_lem_leave";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_lam_leave_smooth = 0.25 / Modelica.Math.log10(5.74 / Re_lam_leave ^ 0.9) ^ 2 "Darcy friction factor neglecting surface roughness at Re_lam_leave";
  Modelica.Units.SI.Pressure dp_lam_leave = A * C1 * zeta_LOC * (B / 2) * max(1, min(1.4, lambda_lam_leave_rough / lambda_lam_leave_smooth)) * (d_hyd / IN_var.eta) ^ (-exp) * IN_var.rho ^ (1 - exp) * v_lam_leave ^ pow "Pressure loss at end of transition to surface roughness regime";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_turb_min_rough = 0.25 / Modelica.Math.log10(k / (3.7 * IN_con.d_hyd) + 5.74 / Re_turb_min ^ 0.9) ^ 2 "Darcy friction factor considering surface roughness at starting transition to constant turbulent regime";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_turb_min_smooth = 0.25 / Modelica.Math.log10(5.74 / Re_turb_min ^ 0.9) ^ 2 "Darcy friction factor neglecting surface roughness at starting transition to constant turbulent regime";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_turb_max_rough = 0.25 / Modelica.Math.log10(k / (3.7 * IN_con.d_hyd) + 5.74 / Re_turb_max ^ 0.9) ^ 2 "Darcy friction factor considering surface roughness at starting transition to constant turbulent regime";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_turb_max_smooth = 0.25 / Modelica.Math.log10(5.74 / Re_turb_max ^ 0.9) ^ 2 "Darcy friction factor neglecting surface roughness at starting transition to constant turbulent regime";
  Modelica.Units.SI.Velocity v_turb_min = Re_turb_min * IN_var.eta / (IN_var.rho * d_hyd) "Mean velocity for starting of transition to constant turbulent regime";
  Modelica.Units.SI.Velocity v_turb_max = Re_turb_max * IN_var.eta / (IN_var.rho * d_hyd) "Mean velocity for end of transition to constant turbulent regime";
  Modelica.Units.SI.Pressure dp_turb_min = A * C1 * zeta_LOC * (B / 2) * max(1, min(1.4, lambda_turb_min_rough / lambda_turb_min_smooth)) * (d_hyd / IN_var.eta) ^ (-exp) * IN_var.rho ^ (1 - exp) * v_turb_min ^ pow "Pressure loss at starting of transition to constant turbulent regime";
  Modelica.Units.SI.Pressure dp_turb_max = A * C1 * zeta_LOC * max(1, min(1.4, lambda_turb_max_rough / lambda_turb_max_smooth)) * IN_var.rho / 2 * v_turb_max ^ 2 "Pressure loss at end of transition to constant turbulent regime";
  Modelica.Units.SI.Velocity v_turb = (A * C1 * zeta_LOC * IN_var.rho / 2) ^ (-0.5) * Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower(abs(dp), dp_min, 0.5) "Mean velocity under turbulent conditions";
  Modelica.Units.SI.Velocity v_lam = (2 * (d_hyd / IN_var.eta) ^ exp / (A * C1 * zeta_LOC * B * IN_var.rho ^ (1 - exp))) ^ (1 / pow) * Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower(abs(dp), dp_min, 1 / pow) "Mean velocity under laminar conditions";
  //mean velocity under smooth conditions w.r.t. flow regime
  Modelica.Units.SI.Velocity v_smooth = if abs(dp) > dp_turb_max then v_turb else if abs(dp) < dp_turb_min then v_lam else Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(dp_turb_max, dp_turb_min, abs(dp)) * v_turb + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(dp_turb_min, dp_turb_max, abs(dp)) * v_lam "Mean velocity under smooth conditions";
  Modelica.Units.SI.ReynoldsNumber Re_smooth = max(Re_min, IN_var.rho * v_smooth * d_hyd / IN_var.eta) "Reynolds number under smooth conditions";
  //SOURCE_2: p.191, eq. 8.4: considering surface roughness
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_FRI_rough = 0.25 / Modelica.Math.log10(k / (3.7 * IN_con.d_hyd) + 5.74 / max(Re_lam_min, Re_smooth) ^ 0.9) ^ 2 "Darcy friction factor considering surface roughness";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_FRI_smooth = 0.25 / Modelica.Math.log10(5.74 / max(Re_lam_min, Re_smooth) ^ 0.9) ^ 2 "Darcy friction factor neglecting surface roughness";
  //SOURCE_3: Lac 6, Figure 18
  Real CF_fri = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(dp_lam_leave, dp_lam_min, abs(dp)) * max(1, min(1.4, lambda_FRI_rough / lambda_FRI_smooth)) + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(dp_lam_min, dp_lam_leave, abs(dp)) "Correction factor for surface roughness";
  Modelica.Units.SI.Velocity velocity = v_smooth / max(1, CF_fri) ^ 0.5 "Corrected velocity considering surface roughness";
algorithm
  M_FLOW := sign(dp) * IN_var.rho * A_cross * velocity;

end dp_edgedOverall_MFLOW;

