Code:
function dp_suddenChange_MFLOW "Pressure loss of orifice with sudden change in cross sectional area | calculate mass flow rate | turbulent flow regime | smooth surface | arbitrary cross sectional area | without baffles | sharp edge"
  extends Modelica.Icons.Function;
  //SOURCE_1: Idelchik, I.E.: HANDBOOK OF HYDRAULIC RESISTANCE, 3rd edition, 2006.
  //Notation of equations according to SOURCES
  import FD = Modelica.Fluid.Dissipation.PressureLoss.Orifice;
  import SMOOTH = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother;
  //input records
  input FD.dp_suddenChange_IN_con IN_con "Input record for function dp_suddenChange_MFLOW" ;
  input FD.dp_suddenChange_IN_var IN_var "Input record for function dp_suddenChange_MFLOW" ;
  input Modelica.Units.SI.Pressure dp "Pressure loss" ;
  //output variables
  output Modelica.Units.SI.MassFlowRate M_FLOW "Output for function dp_suddenChange_MFLOW";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Pressure dp_min = 1 "Pressure loss for linear smoothing";
  //restriction of local resistance coefficient zeta_LOC >> numerical improvement
  Modelica.Fluid.Dissipation.Utilities.Types.LocalResistanceCoefficient zeta_LOC_min = 1e-3 "Minimal local resistance coefficient";
  Modelica.Units.SI.Area A_1 = max(MIN, min(IN_con.A_1, IN_con.A_2)) "Small cross sectional area of orifice";
  Modelica.Units.SI.Area A_2 = max(MIN, max(IN_con.A_1, IN_con.A_2)) "Large cross sectional area of orifice";
  //sudden expansion  :  SOURCE_1, section 4, diagram 4-1, page 208
  //assumption of Re >= 3.3e3 for sudden expansion
  Modelica.Fluid.Dissipation.Utilities.Types.LocalResistanceCoefficient zeta_LOC_exp = max(zeta_LOC_min, (1 - A_1 / A_2) ^ 2);
  //sudden contraction:  SOURCE_1, section 4, diagram 4-9, page 216 / 217
  //assumption of Re >= 1.0e4 for sudden contraction
  Modelica.Fluid.Dissipation.Utilities.Types.LocalResistanceCoefficient zeta_LOC_con = max(zeta_LOC_min, 0.5 * (1 - A_1 / A_2) ^ 0.75);
  //actual local resistance coefficient
  Modelica.Fluid.Dissipation.Utilities.Types.LocalResistanceCoefficient zeta_LOC = max(zeta_LOC_min, zeta_LOC_exp * Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(dp_min, 0, dp) + zeta_LOC_con * Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(-dp_min, 0, dp)) + zeta_LOC_min * Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(0, dp_min, abs(dp));
  //Documentation
algorithm
  M_FLOW := IN_var.rho * A_1 * Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower(dp, dp_min, 0.5) * max(MIN, 2 / (IN_var.rho * zeta_LOC)) ^ 0.5;

end dp_suddenChange_MFLOW;

