Modelica.Fluid: dp_twoPhaseChisholm_DP (function)

Code:
function dp_twoPhaseChisholm_DP "Frictional pressure loss of straight pipe for two phase flow according to Chisholm correlation | calculate pressure loss | overall flow regime"
  extends Modelica.Icons.Function;
  //SOURCE_1: Chisholm,D.:PRESSURE GRADIENTS DUE TO FRICTION DURING THE FLOW OF EVAPORATING TWO-PHASE MIXTURES IN SMOOTH TUBES AND CHANNELS, Int. J. Heat Mass Transfer, Vol. 16, pp. 347-358, Pergamon Press 1973
  //records
  input Modelica.Fluid.Dissipation.Utilities.Records.General.TwoPhaseFlow_con IN_con ;
  input Modelica.Fluid.Dissipation.Utilities.Records.General.TwoPhaseFlow_var IN_var ;
  input Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate" ;
  output Modelica.Units.SI.Pressure DP "Output for function dp_twoPhaseChisholm_DP";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Fluid.Dissipation.PressureLoss.StraightPipe.dp_overall_IN_con IN_con_1ph(final roughness = Modelica.Fluid.Dissipation.Utilities.Types.Roughness.Neglected, final d_hyd = 4 * abs(IN_con.A_cross) / max(MIN, abs(IN_con.perimeter)), final K = 0, final L = abs(IN_con.length));
  Modelica.Fluid.Dissipation.PressureLoss.StraightPipe.dp_overall_IN_var IN_var_1ph(final eta = IN_var.eta_l, final rho = IN_var.rho_l);
algorithm
  DP := Modelica.Fluid.Dissipation.PressureLoss.StraightPipe.dp_overall_DP(IN_con_1ph, IN_var_1ph, m_flow) * Modelica.Fluid.Dissipation.Utilities.Functions.PressureLoss.TwoPhase.TwoPhaseMultiplierChisholm(IN_con, IN_var, m_flow);

end dp_twoPhaseChisholm_DP;

modelica://Modelica.Fluid/dp_twoPhaseFri:
Modelica.Fluid: dp_twoPhaseFriedel_DP (function)

Code:
function dp_twoPhaseFriedel_DP "Frictional pressure loss of straight pipe for two phase flow according to Friedel correlation | calculate pressure loss| overall flow regime"
  extends Modelica.Icons.Function;
  //SOURCE_1: Friedel,L.:IMPROVED FRICTION PRESSURE DROP CORRELATIONS FOR HORIZONTAL AND VERTICAL TWO PHASE PIPE FLOW, 3R International, Vol. 18, Issue 7, pp. 485-491, 1979
  //SOURCE_2: VDI-Waermeatlas, 10th edition, Springer-Verlag, 2006.
  import SMOOTH = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother;
  import SMOOTH2 = Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower;
  //records
  input Modelica.Fluid.Dissipation.Utilities.Records.General.TwoPhaseFlow_con IN_con ;
  input Modelica.Fluid.Dissipation.Utilities.Records.General.TwoPhaseFlow_var IN_var ;
  input Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate" ;
  output Modelica.Units.SI.Pressure DP "Output for function dp_twoPhaseFriedel_DP";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Area A_cross = max(MIN, IN_con.A_cross) "Cross sectional area";
  Modelica.Units.SI.Diameter d_hyd = max(MIN, 4 * A_cross / max(MIN, IN_con.perimeter)) "Hydraulic diameter";
  Real mdot_A = abs(m_flow) / A_cross "Mass flux";
  Modelica.Units.SI.ReynoldsNumber Re_liq = max(1, mdot_A * d_hyd / max(MIN, IN_var.eta_l)) "Reynolds number assuming (total) mass flux flowing as liquid";
  Modelica.Units.SI.ReynoldsNumber Re_lam_leave = 1055 "Maximum Reynolds number for laminar regime (1055)";
  Modelica.Units.SI.ReynoldsNumber Re_turb = 1100 "Minimum Reynolds number for turbulent regime (1100)";
  Modelica.Units.SI.ReynoldsNumber Re_smooth = m_flow / A_cross * d_hyd / max(MIN, abs(IN_var.eta_l)) "Reynolds number for smoothing";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_FRI_lam = 64 / Re_liq "Darcy friction factor for laminar regime";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_FRI_turb = (0.86859 * Modelica.Math.log(max(1, Re_liq / max(MIN, 1.964 * Modelica.Math.log(Re_liq) - 3.8215)))) ^ (-2) "Darcy friction factor for turbulent regime";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_FRI = lambda_FRI_lam * Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(Re_lam_leave, Re_turb, Re_liq) + lambda_FRI_turb * Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(Re_turb, Re_lam_leave, Re_liq);
  Modelica.Fluid.Dissipation.Utilities.Types.PressureLossCoefficient zeta_FRI = lambda_FRI * IN_con.length / d_hyd "Pressure loss coefficient";
  Modelica.Units.SI.Pressure DP_liq = zeta_FRI * mdot_A ^ 2 / (2 * max(MIN, IN_var.rho_l)) "Frictional pressure loss assuming (total) mass flux flowing as liquid";
algorithm
  DP := Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower(Re_smooth, 1, 0) * DP_liq * Modelica.Fluid.Dissipation.Utilities.Functions.PressureLoss.TwoPhase.TwoPhaseMultiplierFriedel(IN_con, IN_var, m_flow);

end dp_twoPhaseFriedel_DP;

modelica://Modelica.Fluid/dp_twoPhaseGeo:
Modelica.Fluid: dp_twoPhaseGeodetic_DP (function)

Code:
function dp_twoPhaseGeodetic_DP "Geodetic pressure loss of straight pipe for two phase flow | calculate pressure loss"
  extends Modelica.Icons.Function;
  //SOURCE_1: VDI-Waermeatlas, 10th edition, Springer-Verlag, 2006.
  import PI = Modelica.Constants.pi;
  input Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach voidFractionApproach = Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Homogeneous "Choice of void fraction approach";
  input Boolean crossSectionalAveraged = true "= true, if cross sectional averaged void fraction, otherwise volumetric" ;
  //geometry
  input Modelica.Units.SI.Length length = 1 "Length in fluid flow direction" ;
  input Modelica.Units.SI.Angle phi = 0 "Tilt angle to horizontal" ;
  //fluid properties
  input Modelica.Units.SI.Density rho_g(min = Modelica.Constants.eps) "Density of gaseous phase" ;
  input Modelica.Units.SI.Density rho_l(min = Modelica.Constants.eps) "Density of liquid phase" ;
  input Real x_flow(min = 0, max = 1) = 0 "Mass flow rate quality" ;
  output Modelica.Units.SI.Pressure DP_geo "Geodetic pressure loss";
protected
  Real xflow = min(1, max(0, abs(x_flow))) "Mass flow rate quality";
  Real eps = Modelica.Fluid.Dissipation.Utilities.Functions.PressureLoss.TwoPhase.VoidFraction(voidFractionApproach, crossSectionalAveraged, rho_g, rho_l, xflow) "Void fraction";
algorithm
  //SOURCE_1: p.Lbb 1, eq. 4: Considering geodetic pressure loss assuming constant void fraction for flow length
  DP_geo := (eps * rho_g + (1 - eps) * rho_l) * 9.81 * length * sin(phi);

end dp_twoPhaseGeodetic_DP;

modelica://Modelica.Fluid/dp_twoPhaseMom:
Modelica.Fluid: dp_twoPhaseMomentum_DP (function)

Code:
function dp_twoPhaseMomentum_DP "Momentum pressure loss of straight pipe for two phase flow | calculate pressure loss"
  extends Modelica.Icons.Function;
  //SOURCE_1: VDI-Waermeatlas, 10th edition, Springer-Verlag, 2006.
  //SOURCE_2: Thome, J.R., Engineering Data Book 3, Swiss Federal Institute of Technology Lausanne (EPFL), 2009.
  //SOURCE 3: J.M. Jensen and H. Tummescheit. Moving boundary models for dynamic simulations of two-phase flows. In Proceedings of the 2nd International Modelica Conference, pp. 235-244, Oberpfaffenhofen, Germany, 2002. The Modelica Association.
  import PI = Modelica.Constants.pi;
  import MIN = Modelica.Constants.eps;
  import SMOOTH = Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower;
  //choices
  input Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach voidFractionApproach = Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Homogeneous "Choice of void fraction approach" ;
  //SOURCE_3: p.52, eq. 4.6: heterogeneous effects on momentum pressure loss considered through corrected mass flow rate
  input Boolean massFlowRateCorrection = false "Consider heterogeneous mass flow rate correction" ;
  //geometry
  input Modelica.Units.SI.Area A_cross(min = Modelica.Constants.eps) = PI * 0.1 ^ 2 / 4 "Cross sectional area" ;
  input Modelica.Units.SI.Length perimeter(min = Modelica.Constants.eps) = PI * 0.1 "Perimeter" ;
  //fluid properties
  input Modelica.Units.SI.Density rho_g(min = Modelica.Constants.eps) "Density of gas" ;
  input Modelica.Units.SI.Density rho_l(min = Modelica.Constants.eps) "Density of liquid" ;
  input Real x_flow_end(min = 0, max = 1) = 0 "Mass flow rate quality at end of length" ;
  input Real x_flow_sta(min = 0, max = 1) = 0 "Mass flow rate quality at start of length" ;
  input Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate" ;
  output Modelica.Units.SI.Pressure DP_mom "Momentum pressure loss";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Area Across = max(MIN, A_cross) "Cross sectional area";
  Modelica.Units.SI.Diameter d_hyd = max(MIN, 4 * A_cross / max(MIN, perimeter)) "Hydraulic diameter";
  Real mdot_A = abs(m_flow) / Across "Mass flux";
  Real xflowEnd = min(1, max(0, abs(x_flow_end))) "Mass flow rate quality at end of length";
  Real xflowSta = min(1, max(0, abs(x_flow_sta))) "Mass flow rate quality at start of length";
  Real xflowMean = (xflowEnd + xflowSta) / 2 "Mean mass flow rate quality over length";
  Real delta_xflow = xflowEnd - xflowSta "Difference of mass flow rate quality between end and start of length (pos >> evaporation, neg >> condensation";
  //SOURCE_2: Considering void fraction approaches
  Real eps_end = Modelica.Fluid.Dissipation.Utilities.Functions.PressureLoss.TwoPhase.VoidFraction(voidFractionApproach, true, rho_g, rho_l, xflowEnd) "Void fraction at end of length";
  Real eps_sta = Modelica.Fluid.Dissipation.Utilities.Functions.PressureLoss.TwoPhase.VoidFraction(voidFractionApproach, true, rho_g, rho_l, xflowSta) "Void fraction at start of length";
  //SOURCE_2: p.17-6, eq. 17.3.3: Considering mean two phase density at end and start of length
  Modelica.Units.SI.Density rho_end = Modelica.Fluid.Dissipation.Utilities.Functions.PressureLoss.TwoPhase.TwoPhaseDensity(voidFractionApproach, massFlowRateCorrection, rho_g, rho_l, eps_end, xflowEnd) "Mean two phase density at end of length";
  Modelica.Units.SI.Density rho_sta = Modelica.Fluid.Dissipation.Utilities.Functions.PressureLoss.TwoPhase.TwoPhaseDensity(voidFractionApproach, massFlowRateCorrection, rho_g, rho_l, eps_sta, xflowSta) "Mean two phase density at start of length";
  Modelica.Units.SI.Velocity meanVelEnd = abs(m_flow) / max(MIN, rho_end * A_cross) "Mean velocity of two phase flow at end of length";
  Modelica.Units.SI.Velocity meanVelSta = abs(m_flow) / max(MIN, rho_sta * A_cross) "Mean velocity of two phase flow at start of length";
  //SOURCE 3: p.15, eq. 2.26: Considering velocity difference for heterogeneous approach using slip ratio
  Real SR = Modelica.Fluid.Dissipation.Utilities.Functions.PressureLoss.TwoPhase.SlipRatio(voidFractionApproach, rho_g, rho_l, xflowMean) "Slip ratio for velocity void fraction approach";
  Modelica.Units.SI.Velocity deltaVelEnd = meanVelEnd * (SR - 1) / (xflowEnd * (SR - 1) + 1) "Velocity difference of two phases at end of length";
  Modelica.Units.SI.Velocity deltaVelSta = meanVelSta * (SR - 1) / (xflowSta * (SR - 1) + 1) "Velocity difference of two phases at start of length";
  //SOURCE 3: p.52, eq. 4.6: Considering of corrected mass flow rate for heterogeneous approach
  Modelica.Units.SI.MassFlowRate mdotCorEnd = xflowEnd * (1 - xflowEnd) * rho_end * deltaVelEnd * Across "Correction mass flow rate at end of length";
  Modelica.Units.SI.MassFlowRate mdotCorSta = xflowSta * (1 - xflowSta) * rho_sta * deltaVelSta * Across "Correction mass flow rate at start of length";
  //SOURCE 3: p.53, eq. 4.13: Calculation of heterogeneous approach with correction of mass flow rate for considering velocity difference between fluid phases
  Modelica.Units.SI.Pressure dp_mom_cor = Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower(delta_xflow, 0.05, 0) * abs(mdot_A * meanVelEnd + mdotCorEnd * deltaVelEnd / Across) - abs(mdot_A * meanVelSta + mdotCorEnd * deltaVelSta / Across) "Momentum pressure loss using mass flow rate correction";
algorithm
  //SOURCE_1: p.Lba 4, eq. 22: Considering momentum pressure loss assuming heterogeneous approach for two phase flow
  //Momentum pressure loss occurs for a changing mass flow rate quality due to condensation or evaporation
  //At evaporation the liquid phase with a slow velocity has to be accelerated to the higher velocity of the gas
  //The difference in static pressure at the outlet and the inlet causes a positive momentum pressure loss at evaporation (assumed vice versa for condensation)
  DP_mom := if massFlowRateCorrection then dp_mom_cor else mdot_A ^ 2 * Modelica.Fluid.Dissipation.Utilities.Functions.General.SmoothPower(delta_xflow, 0.05, 0) * abs(1 / max(MIN, rho_end) - 1 / max(MIN, rho_sta));

end dp_twoPhaseMomentum_DP;

modelica://Modelica.Fluid/TwoPhaseMultip:
Modelica.Fluid: TwoPhaseMultiplierFriedel (function)

Code:
function TwoPhaseMultiplierFriedel "Calculation of two phase multiplier according to Friedel | constant mass flow rate quality | horizontal flow | vertical upflow and downflow"
  extends Modelica.Icons.Function;
  //SOURCE_1: Friedel,L.:IMPROVED FRICTION PRESSURE DROP CORRELATIONS FOR HORIZONTAL AND VERTICAL TWO PHASE PIPE FLOW, 3R International, Vol. 18, Issue 7, pp. 485-491, 1979
  //SOURCE_2: VDI-Waermeatlas, 10th edition, Springer-Verlag, 2006.
  import Modelica.Math.log;
  import SMOOTH = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother;
  input Modelica.Fluid.Dissipation.Utilities.Records.General.TwoPhaseFlow_con IN_con ;
  input Modelica.Fluid.Dissipation.Utilities.Records.General.TwoPhaseFlow_var IN_var(final sigma = 0) ;
  input Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate" ;
  output Real phi "Two phase multiplier w.r.t. Friedel";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Area A_cross = max(MIN, IN_con.A_cross) "Cross sectional area";
  Modelica.Units.SI.Diameter d_hyd = max(MIN, 4 * A_cross / max(MIN, IN_con.perimeter)) "Hydraulic diameter";
  //SOURCE_2: p.Lba 4, sec. 3.3: Correlation based on constant mass flow rate quality (x_flow) for increment (dx)
  //Pressure loss for total length (e.g., L=n*dx) can be achieved by discretization
  Real mdot_A = abs(m_flow) / A_cross "Mass flux";
  Real x_flow = max(0, min(1, abs(IN_var.x_flow))) "Mass flow rate quality";
  //SOURCE_1: p.490 (Appendix): Characteristic numbers based on total mass flow rate flowing as liquid
  Modelica.Units.SI.FroudeNumber Fr_l = max(MIN, mdot_A ^ 2 / max(MIN, 9.81 * IN_var.rho_l ^ 2 * d_hyd)) "Froude number based on liquid flow";
  Modelica.Units.SI.ReynoldsNumber Re_g = max(1, mdot_A * d_hyd / max(MIN, IN_var.eta_g)) "Reynolds number based on gas flow";
  Modelica.Units.SI.ReynoldsNumber Re_l = max(1, mdot_A * d_hyd / max(MIN, IN_var.eta_l)) "Reynolds number based on liquid flow";
  Modelica.Units.SI.WeberNumber We_l = max(MIN, mdot_A ^ 2 * d_hyd / max(MIN, IN_var.sigma * IN_var.rho_l)) "Weber number based on liquid flow";
  //SOURCE_1: p.490 (Appendix): Smoothing for sudden change from assumed laminar to assumed turbulent regime (numerical improvement at Re=1055)
  Modelica.Units.SI.ReynoldsNumber Re_lam_max = 1025 "Maximum Reynolds number assuming laminar regime";
  Modelica.Units.SI.ReynoldsNumber Re_turb_min = 1075 "Minimum Reynolds number assuming turbulent regime";
  //SOURCE_2: p.Lbb 2, eq. 9-10: Considering influence of Reynolds number on Darcy friction factor for smooth straight pipes
  //Correlation based on neglect of surface roughness
  //Correlation based on assumption that total mass flow rate is flowing as gas
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_lam_g = 64 / Re_g "Darcy friction factor of gas for assumed laminar regime";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_turb_g = 1 / max(MIN, 0.86859 * log(max(1, Re_g / max(MIN, 1.964 * log(Re_g) - 3.8215)))) ^ 2 "Darcy friction factor of gas for assumed turbulent regime";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_g = lambda_lam_g * Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(Re_lam_max, Re_turb_min, Re_g) + lambda_turb_g * Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(Re_turb_min, Re_lam_max, Re_g) "Darcy friction factor of gas for overall regime";
  //Correlation based on assumption that total mass flow rate is flowing as liquid
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_lam_l = 64 / Re_l "Darcy friction factor of liquid for assumed laminar regime";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_turb_l = 1 / max(MIN, 0.86859 * log(max(1, Re_l / max(MIN, 1.964 * log(Re_l) - 3.8215)))) ^ 2 "Darcy friction factor of liquid for assumed turbulent regime";
  Modelica.Fluid.Dissipation.Utilities.Types.DarcyFrictionFactor lambda_l = lambda_lam_l * Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(Re_lam_max, Re_turb_min, Re_l) + lambda_turb_l * Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(Re_turb_min, Re_lam_max, Re_l) "Darcy friction factor of liquid for overall regime";
  Real A = (1 - x_flow) ^ 2 + x_flow ^ 2 * (IN_var.rho_l / max(MIN, IN_var.rho_g)) * (lambda_g / max(MIN, lambda_l)) "Summand for two phase multiplier";
  //SOURCE_1: p.490 (Appendix): Two phase multiplier for vertical downflow for future usage
  Real phi_vdo = A + 38.5 * x_flow ^ 0.76 * (1 - x_flow) ^ 0.314 * (IN_var.rho_l / max(MIN, IN_var.rho_g)) ^ 0.86 * (IN_var.eta_g / max(MIN, IN_var.eta_l)) ^ 0.73 * (1 - IN_var.eta_g / max(MIN, IN_var.eta_l)) ^ 6.84 * (1 / Fr_l ^ 0.0001) * (1 / We_l ^ 0.087);
  //SOURCE_1: p.490 (Appendix): Two phase multiplier for horizontal and vertical upflow (failure in SOURCE_2)
  Real phi_vup = A + 3.43 * x_flow ^ 0.685 * (1 - x_flow) ^ 0.24 * (IN_var.rho_l / max(MIN, IN_var.rho_g)) ^ 0.8 * (IN_var.eta_g / max(MIN, IN_var.eta_l)) ^ 0.22 * (1 - IN_var.eta_g / max(MIN, IN_var.eta_l)) ^ 0.89 * (1 / Fr_l ^ 0.048) * (1 / We_l ^ 0.0334);
algorithm
  phi := phi_vup;

end TwoPhaseMultiplierFriedel;

Modelica.Fluid: TwoPhaseMultiplierChisholm (function)

Code:
function TwoPhaseMultiplierChisholm "Calculation of two phase multiplier according to Chisholm | constant mass flow rate quality"
  extends Modelica.Icons.Function;
  //SOURCE_1: Chisholm,D.:PRESSURE GRADIENTS DUE TO FRICTION DURING THE FLOW OF EVAPORATING TWO-PHASE MIXTURES IN SMOOTH TUBES AND CHANNELS, Int. J. Heat Mass Transfer, Vol. 16, pp. 347-358, Pergamon Press 1973
  //SOURCE_2: VDI-Waermeatlas, 10th edition, Springer-Verlag, 2006.
  import SMOOTH = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother;
  input Modelica.Fluid.Dissipation.Utilities.Records.General.TwoPhaseFlow_con IN_con ;
  input Modelica.Fluid.Dissipation.Utilities.Records.General.TwoPhaseFlow_var IN_var ;
  input Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate" ;
  output Real phi "Two phase multiplier w.r.t. Chisholm";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Area A_cross = max(MIN, IN_con.A_cross) "Cross sectional area";
  Modelica.Units.SI.Diameter d_hyd = max(MIN, 4 * A_cross / max(MIN, IN_con.perimeter)) "Hydraulic diameter";
  Real mdot_A = abs(m_flow) / A_cross "Mass flux";
  Real x_flow = max(0, min(1, abs(IN_var.x_flow))) "Mass flow rate quality";
  //SOURCE_1: p.357, Appendix 1: Considering Darcy friction factor (lambda_FRI) of smooth pipes for overall flow regime
  Real n_exp = 0.2 "Exponent for Reynolds number (lambda_FRI= A/Re^n)";
  //SOURCE_1: p.349, eq. 21: Considering effect of physical properties (failure in SOURCE_2)
  Real gamma = max(1, abs(IN_var.rho_l / max(MIN, IN_var.rho_g)) ^ 0.5 * (IN_var.eta_g / max(MIN, IN_var.eta_l)) ^ (n_exp / 2));
  //SOURCE: p. 353, tab. 2: Considering effect of mass flux on two phase multiplier
  Real B_gamma_1 = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(450, 550, mdot_A) * 4.8 + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(550, 450, mdot_A) * 2400 / max(MIN, mdot_A) - Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(1950, 1850, mdot_A) * 2400 / max(MIN, mdot_A) + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(1950, 1850, mdot_A) * 55 / max(MIN, mdot_A ^ 0.5) "Coefficient B for gamma <= 9.5";
  Real B_gamma_2 = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(550, 650, mdot_A) * 520 / max(1, max(9.5, gamma) * mdot_A ^ 0.5) + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(650, 550, mdot_A) * 21 / max(9.5, gamma) "Coefficient B for 9.5 <= gamma <= 28";
  Real B_gamma = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(9.0, 10, gamma) * B_gamma_1 + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(10, 9.0, gamma) * B_gamma_2 - Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(28.5, 27.7, gamma) * B_gamma_2 + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(28.5, 27.5, gamma) * 15000 / max(MIN, gamma ^ 2 * mdot_A ^ 0.5) "Coefficient B for gamma";
  //SOURCE_1: p. 350, eq. 24/26: Considering two phase multiplier w.r.t. Chisholm
algorithm
  phi := 1 + (gamma ^ 2 - 1) * (B_gamma * x_flow ^ ((2 - n_exp) / 2) * (1 - x_flow) ^ ((2 - n_exp) / 2) + x_flow ^ (2 - n_exp));

end TwoPhaseMultiplierChisholm;

modelica://Modelica.Fluid/TwoPhaseDensit:
Modelica.Fluid: TwoPhaseDensity (function)

The gaseous and the liquid part of a fluid in a two phase flow are often discontinuously distributed. This complex behaviour is simplified for engineering calculations. The two phase flow of different fluid flow situations (e.g., bubble or stratified flow) is modelled as if the gaseous and the liquid phase are continuously distributed.   
 A mean density assuming a continuous distribution out of a discontinuous two phase fluid flow situation can be calculated with a homogeneous or a heterogeneous approach (see dp_twoPhaseOverall_DP ).  
 The following modelling approaches can be used to calculate the mean density of two phase flow:   
homogeneous density (homogeneous approach) momentum flux density (heterogeneous approach) kinetic energy flow density (heterogeneous approach)  
 The heterogeneous approaches are analytically derived by minimising the momentum flux or the kinetic energy flow assuming implicitly that the two-phase flow will tend towards the minimum of this quantity.    References   VDI: VDI - Wärmeatlas: Berechnungsblätter für den Wärmeübergang . Springer Verlag, 10th edition, 2006.

Code:
function TwoPhaseDensity "Calculation of mean density for two phase flow"
  extends Modelica.Icons.Function;
  //SOURCE_1: VDI-Waermeatlas, 10th edition, Springer-Verlag, 2006.
  input Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach voidFractionApproach = Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Homogeneous "Choice of void fraction approach" ;
  //SOURCE_3: p.52, eq. 4.6: heterogeneous effects on momentum pressure loss considered through corrected mass flow rate
  input Boolean massFlowRateCorrection = false "Consider heterogeneous mass flow rate correction" ;
  input Modelica.Units.SI.Density rho_g(min = Modelica.Constants.eps) "Density of gaseous phase" ;
  input Modelica.Units.SI.Density rho_l(min = Modelica.Constants.eps) "Density of liquid phase" ;
  input Real epsilon_A(min = 0, max = 1) "Void fraction (cross sectional averaged)" ;
  input Real x_flow(min = 0, max = 1) "Mass flow rate quality" ;
  output Modelica.Units.SI.Density rho_2ph "Mean density of two phase flow";
protected
  Real MIN = Modelica.Constants.eps;
  Real epsilonA = min(1, max(0, abs(epsilon_A))) "Void fraction (cross sectional averaged)";
  Real xflow = min(1, max(0, abs(x_flow))) "Mass flow rate quality";
  //SOURCE_1: p.Lba 3, eq. 17: Mean two phase density assuming homogeneous approach
  Modelica.Units.SI.Density rho_hom = 1 / max(MIN, x_flow / max(MIN, rho_g) + (1 - x_flow) / max(MIN, rho_l));
  //SOURCE_1: p.Lbb 7, tab. 2: Mean two phase density assuming momentum flux approach
  Modelica.Units.SI.Density rho_mom = 1 / max(MIN, x_flow ^ 2 / max(MIN, rho_g * epsilonA) + (1 - x_flow) ^ 2 / max(MIN, rho_l * (1 - epsilonA)));
  //SOURCE_1: p.Lbb 7, tab. 2: Mean two phase density assuming kinetic energy flow approach from Zivi (corrected formula!)
  Modelica.Units.SI.Density rho_kin = 1 / max(MIN, rho_hom * (x_flow ^ 3 / max(MIN, rho_g ^ 2 * epsilonA ^ 2) + (1 - x_flow) ^ 3 / max(MIN, rho_l ^ 2 * (1 - epsilonA) ^ 2)));
algorithm
  rho_2ph := if not massFlowRateCorrection then rho_hom else if voidFractionApproach == Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Homogeneous then rho_hom else if voidFractionApproach == Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Momentum then rho_mom else if voidFractionApproach == Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Energy then rho_kin else MIN;

end TwoPhaseDensity;

modelica://Modelica.Fluid/VoidFraction:
Modelica.Fluid: VoidFraction (function)

Code:
function VoidFraction "Calculation of (cross sectional) void fraction for two phase flow"
  extends Modelica.Icons.Function;
  //SOURCE_1: VDI-Waermeatlas, 10th edition, Springer-Verlag, 2006.
  //SOURCE_2: Thome, J.R., Engineering Data Book 3, Swiss Federal Institute of Technology Lausanne (EPFL), 2009.
  input Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach voidFractionApproach = Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Homogeneous "Choice of void fraction approach" ;
  input Boolean crossSectionalAveraged = true "= true, if cross sectional averaged void fraction, otherwise volumetric" ;
  input Modelica.Units.SI.Density rho_g(min = Modelica.Constants.eps) "Density of gaseous phase" ;
  input Modelica.Units.SI.Density rho_l(min = Modelica.Constants.eps) "Density of liquid phase" ;
  input Real x_flow(min = 0, max = 1) = 0 "Mass flow rate quality" ;
  output Real epsilon "Void fraction";
  output Real slipRatio "Slip ratio";
protected
  Real MIN = Modelica.Constants.eps;
  Real xflow = min(1, max(0, abs(x_flow))) "Mass flow rate quality";
  Real SR = Modelica.Fluid.Dissipation.Utilities.Functions.PressureLoss.TwoPhase.SlipRatio(voidFractionApproach, rho_g, rho_l, xflow) "Slip ratio for void fraction approach";
  //SOURCE_2: p.17-5, eq. 17.2.5: (Heterogeneous) cross sectional void fraction [epsilon_A=A_g/(A_g+A_l)]
  Real epsilon_A = rho_l * x_flow / max(MIN, rho_l * x_flow + rho_g * (1 - x_flow) * SR);
algorithm
  epsilon := if crossSectionalAveraged then epsilon_A else epsilon_A / (1 / max(MIN, SR) * (1 - epsilon_A) + epsilon_A);
  slipRatio := SR;

end VoidFraction;

modelica://Modelica.Fluid/SlipRatio:
Modelica.Fluid: SlipRatio (function)

Code:
function SlipRatio "Calculation of (analytical/empirical) slip ratio"
  extends Modelica.Icons.Function;
  //SOURCE_1: VDI-Waermeatlas, 10th edition, Springer-Verlag, 2006.
  //SOURCE_2: Thome, J.R., Engineering Data Book 3, Swiss Federal Institute of Technology Lausanne (EPFL), 2009.
  //SOURCE 3: J.M. Jensen and H. Tummescheit. Moving boundary models for dynamic simulations of two-phase flows. In Proceedings of the 2nd International Modelica Conference, pp. 235-244, Oberpfaffenhofen, Germany, 2002. The Modelica Association.
  input Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach voidFractionApproach = Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Homogeneous "Choice of void fraction approach" ;
  input Modelica.Units.SI.Density rho_g(min = Modelica.Constants.eps) "Density of gaseous phase" ;
  input Modelica.Units.SI.Density rho_l(min = Modelica.Constants.eps) "Density of liquid phase" ;
  input Real x_flow = 0 "Mass flow rate quality" ;
  output Real SR "Slip ratio";
protected
  Real MIN = Modelica.Constants.eps;
  //SOURCE_1: p.Lba 3, sec. 3.2
  Real SR_hom = 1 "Slip ratio w.r.t. homogeneous approach";
  //SOURCE_2: p.17-6, eq. 17.3.4
  Real SR_mom = abs(rho_l / max(MIN, rho_g)) ^ 0.5 "Slip ratio w.r.t. momentum flux approach (heterogeneous)";
  //SOURCE_2: p.17-7, eq. 17.3.13
  Real SR_kin = abs(rho_l / max(MIN, rho_g)) ^ (1 / 3) "Slip ratio w.r.t. kinetic energy flow approach from Zivi (heterogeneous)";
  //SOURCE_2: p.17-10, eq. 17.4.3
  Real SR_chi = (1 - x_flow * (1 - abs(rho_l) / max(MIN, abs(rho_g)))) ^ 0.5 "Empirical slip ratio w.r.t. momentum flux approach from Chisholm (heterogeneous)";
algorithm
  SR := if voidFractionApproach == Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Homogeneous then SR_hom else if voidFractionApproach == Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Momentum then SR_mom else if voidFractionApproach == Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Energy then SR_kin else if voidFractionApproach == Modelica.Fluid.Dissipation.Utilities.Types.VoidFractionApproach.Chisholm then SR_chi else 1;

end SlipRatio;

modelica://Modelica.Fluid/kc_twoPhase_co:
Modelica.Fluid: kc_twoPhase_condensationHorizontal_KC (function)

Code:
function kc_twoPhase_condensationHorizontal_KC "Local two phase heat transfer coefficient of straight pipe | horizontal condensation"
  extends Modelica.Icons.Function;
  //SOURCE_1: M.M. Shah. A general correlation for heat transfer during film condensation inside pipes.Int. J. Heat Mass Transfer, Vol.22, p.547-556, 1979.
  //records
  input Modelica.Fluid.Dissipation.Utilities.Records.HeatTransfer.TwoPhaseFlowHT_IN_con IN_con ;
  input Modelica.Fluid.Dissipation.Utilities.Records.HeatTransfer.TwoPhaseFlowHT_IN_var IN_var ;
  output Modelica.Units.SI.CoefficientOfHeatTransfer kc "Local two phase heat transfer coefficient";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Area A_cross = max(MIN, IN_con.A_cross) "Cross sectional area";
  Modelica.Units.SI.Diameter d_hyd = max(MIN, 4 * A_cross / max(MIN, IN_con.perimeter)) "Hydraulic diameter";
  Real x_flow = max(0, min(1, abs(IN_var.x_flow))) "Mass flow rate quality";
  Real p_red = max(MIN, abs(IN_var.pressure) / max(MIN, abs(IN_con.p_crit))) "Reduced pressure";
  Modelica.Units.SI.Velocity velocity = abs(IN_var.m_flow) / max(MIN, IN_var.rho_l * A_cross) "Mean velocity";
  Modelica.Units.SI.ReynoldsNumber Re_l = IN_var.rho_l * velocity * d_hyd / max(MIN, IN_var.eta_l) "Reynolds number assuming (total) mass flux flowing as liquid";
  Modelica.Units.SI.PrandtlNumber Pr_l = abs(IN_var.eta_l * IN_var.cp_l / max(MIN, IN_var.lambda_l)) "Prandtl number assuming (total) mass flux flowing as liquid";
  //SOURCE_1: p.548, eq. 8: Considering two phase multiplier for condensation w.r.t. Shah
  Modelica.Units.SI.CoefficientOfHeatTransfer kc_1ph = 0.023 * Re_l ^ 0.8 * Pr_l ^ 0.4 * IN_var.lambda_l / d_hyd;
algorithm
  kc := kc_1ph * ((1 - x_flow) ^ 0.8 + 3.8 * x_flow ^ 0.76 * (1 - x_flow) ^ 0.04 / p_red ^ 0.38);

end kc_twoPhase_condensationHorizontal_KC;

modelica://Modelica.Fluid/kc_twoPhase_bo:
Modelica.Fluid: kc_twoPhase_boilingVertical_KC (function)

Code:
function kc_twoPhase_boilingVertical_KC "Local two phase heat transfer coefficient of straight pipe | vertical boiling"
  extends Modelica.Icons.Function;
  //SOURCE_1: Bejan,A.: HEAT TRANSFER HANDBOOK, Wiley, 2003.
  //SOURCE_2: Gungor, K.E. and R.H.S. Winterton: A general correlation for flow boiling in tubes and annuli, Int.J. Heat Mass Transfer, Vol.29, p.351-358, 1986.
  //records
  input Modelica.Fluid.Dissipation.Utilities.Records.HeatTransfer.TwoPhaseFlowHT_IN_con IN_con ;
  input Modelica.Fluid.Dissipation.Utilities.Records.HeatTransfer.TwoPhaseFlowHT_IN_var IN_var ;
  output Modelica.Units.SI.CoefficientOfHeatTransfer kc "Local two phase heat transfer coefficient";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Area A_cross = max(MIN, IN_con.A_cross) "Cross sectional area";
  Modelica.Units.SI.Diameter d_hyd = max(MIN, 4 * A_cross / max(MIN, IN_con.perimeter)) "Hydraulic diameter";
  Real mdot_A = abs(IN_var.m_flow) / A_cross "Mass flux";
  Real x_flow = max(0, min(1, abs(IN_var.x_flow))) "Mass flow rate quality";
  Real p_red = max(MIN, abs(IN_var.pressure) / max(MIN, abs(IN_con.p_crit))) "Reduced pressure";
  //SOURCE_1: p.674, sec. 9.8.3: Considering nucleate and convective boiling w.r.t. equation of Gungor-Winterton
  Modelica.Units.SI.MassFlowRate mdot_l = abs(IN_var.m_flow) * (1 - x_flow) "Mass flow rate of liquid only";
  Modelica.Units.SI.Velocity velocity_l = mdot_l / max(MIN, IN_var.rho_l * A_cross) "Mean velocity assuming liquid mass flow rate flows alone";
  Modelica.Units.SI.ReynoldsNumber Re_l = IN_var.rho_l * velocity_l * d_hyd / max(MIN, IN_var.eta_l) "Reynolds number assuming liquid mass flow rate flows alone";
  Modelica.Units.SI.PrandtlNumber Pr_l = abs(IN_var.eta_l * IN_var.cp_l / max(MIN, IN_var.lambda_l)) "Prandtl number assuming liquid mass flow rate flows alone";
  //SOURCE_1: p.674, eq. 9.98: Considering effect of heat flux on nucleate boiling with Boiling number
  //Boiling number (Bo) is defined as ratio of actual heat flux to maximum heat flux necessary for complete evaporation of liquid
  Real Bo = abs(IN_var.qdot_A) / max(MIN, mdot_A * IN_var.dh_lg) "Boiling number";
  //SOURCE_1: p.673, eq. 9.94: Considering of Martinelli parameter w.r.t. equation of Chen
  Real X_tt = abs(((1 - x_flow) / max(MIN, x_flow)) ^ 0.9 * (IN_var.rho_g / max(MIN, IN_var.rho_l)) ^ 0.5 * (IN_var.eta_l / max(MIN, IN_var.eta_g)) ^ 0.1) "Martinelli parameter";
  //SOURCE_1: p.675, eq. 9.105: Considering of convection enhancement factor w.r.t. equation of Gungor-Winterton
  Real E_fc = 1 + 24000 * Bo ^ 1.16 + 1.37 * (1 / max(MIN, X_tt)) ^ 0.86 "Enhancement factor for forced convection";
  //SOURCE_1: p.675, eq. 9.105: Considering of boiling suppression factor w.r.t. equation of Gungor-Winterton
  Real S_nb = 1 / max(MIN, 1 + 1.15e-6 * E_fc ^ 2 * Re_l ^ 1.17) "Suppression factor for nucleate boiling";
  //SOURCE_1: p.672, eq. 9.91: Considering effect of forced convective boiling ew.r.t. equation of Dittus-Boelter
  Modelica.Units.SI.CoefficientOfHeatTransfer kc_fc = 0.023 * Re_l ^ 0.8 * Pr_l ^ 0.4 * (IN_var.lambda_l / d_hyd) "Convective heat transfer coefficient assuming liquid mass flow rate only";
  //SOURCE_1: p.675, eq. 9.107: Considering effect of nucleate boiling w.r.t. equation of Cooper
  Modelica.Units.SI.CoefficientOfHeatTransfer kc_nb = 55 * p_red ^ 0.12 * (1 / max(MIN, Modelica.Math.log10(1 / p_red)) ^ 0.55) * (1 / max(MIN, IN_con.MM) ^ 0.5) * IN_var.qdot_A ^ 0.67 "Nucleate boiling heat transfer coefficient";
  //SOURCE_2: p.354, sec. final equations: Calculation of two phase heat transfer coefficient for vertical pipes w.r.t. equation of Gungor-Winterton
algorithm
  kc := E_fc * kc_fc + S_nb * kc_nb;

end kc_twoPhase_boilingVertical_KC;

Modelica.Fluid: kc_twoPhase_boilingHorizontal_KC (function)

Code:
function kc_twoPhase_boilingHorizontal_KC "Local two phase heat transfer coefficient of straight pipe | horizontal boiling"
  extends Modelica.Icons.Function;
  //SOURCE_1: Bejan,A.: HEAT TRANSFER HANDBOOK, Wiley, 2003.
  //SOURCE_2: Gungor, K.E. and R.H.S. Winterton: A general correlation for flow boiling in tubes and annuli, Int.J. Heat Mass Transfer, Vol.29, p.351-358, 1986.
  import SMOOTH = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother;
  //records
  input Modelica.Fluid.Dissipation.Utilities.Records.HeatTransfer.TwoPhaseFlowHT_IN_con IN_con ;
  input Modelica.Fluid.Dissipation.Utilities.Records.HeatTransfer.TwoPhaseFlowHT_IN_var IN_var ;
  output Modelica.Units.SI.CoefficientOfHeatTransfer kc "Local two phase heat transfer coefficient";
protected
  Real MIN = Modelica.Constants.eps;
  Modelica.Units.SI.Area A_cross = max(MIN, IN_con.A_cross) "Cross sectional area";
  Modelica.Units.SI.Diameter d_hyd = max(MIN, 4 * A_cross / max(MIN, IN_con.perimeter)) "Hydraulic diameter";
  Real mdot_A = abs(IN_var.m_flow) / A_cross "Mass flux";
  Real x_flow = max(0, min(1, abs(IN_var.x_flow))) "Mass flow rate quality";
  Real p_red = max(MIN, abs(IN_var.pressure) / max(MIN, abs(IN_con.p_crit))) "Reduced pressure";
  //SOURCE_1: p.674, sec. 9.8.3: Considering nucleate and convective boiling w.r.t. equation of Gungor-Winterton
  Modelica.Units.SI.MassFlowRate mdot_l = abs(IN_var.m_flow) * (1 - x_flow) "Mass flow rate of liquid only";
  Modelica.Units.SI.Velocity velocity_l = mdot_l / max(MIN, IN_var.rho_l * A_cross) "Mean velocity assuming liquid mass flow rate flows alone";
  Modelica.Units.SI.ReynoldsNumber Re_l = IN_var.rho_l * velocity_l * d_hyd / max(MIN, IN_var.eta_l) "Reynolds number assuming liquid mass flow rate flows alone";
  Modelica.Units.SI.PrandtlNumber Pr_l = abs(IN_var.eta_l * IN_var.cp_l / max(MIN, IN_var.lambda_l)) "Prandtl number assuming liquid mass flow rate flows alone";
  //SOURCE_1: p.352, sec. Nomenclature: Considering effect of stratification w.r.t. Froude number
  Modelica.Units.SI.FroudeNumber Fr_l = abs(mdot_A ^ 2 / max(MIN, IN_var.rho_l ^ 2 * 9.81 * d_hyd)) "Froude number assuming (total) mass flux flowing as liquid";
  //SOURCE_1: p.674, eq. 9.98: Considering effect of heat flux on nucleate boiling with Boiling number
  //Boiling number (Bo) is defined as ratio of actual heat flux to maximum heat flux necessary for complete evaporation of liquid
  Real Bo = abs(IN_var.qdot_A) / max(MIN, mdot_A * IN_var.dh_lg) "Boiling number";
  //SOURCE_1: p.673, eq. 9.94: Considering of Martinelli parameter w.r.t. equation of Chen
  Real X_tt = abs(((1 - x_flow) / max(MIN, x_flow)) ^ 0.9 * (IN_var.rho_g / max(MIN, IN_var.rho_l)) ^ 0.5 * (IN_var.eta_l / max(MIN, IN_var.eta_g)) ^ 0.1) "Martinelli parameter";
  //SOURCE_1: p.675, eq. 9.105: Considering of convection enhancement factor w.r.t. equation of Gungor-Winterton
  Real E_fc = 1 + 24000 * Bo ^ 1.16 + 1.37 * (1 / max(MIN, X_tt)) ^ 0.86 "Enhancement factor for forced convection";
  //SOURCE_1: p.675, eq. 9.105: Considering of boiling suppression factor w.r.t. equation of Gungor-Winterton
  Real S_nb = 1 / max(MIN, 1 + 1.15e-6 * E_fc ^ 2 * Re_l ^ 1.17) "Suppression factor for nucleate boiling";
  //SOURCE_1: p.680, eq. 9.123: Considering correction of convection enhancement factor for horizontal pipes
  Real E_fc_hor = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(0.049, 0.051, Fr_l) * Fr_l ^ max(0, abs(0.1 - 2 * Fr_l)) + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(0.051, 0.049, Fr_l) "Correction of enhancement factor for forced convection in horizontal pipes";
  //SOURCE_1: p.680, eq. 9.124: Considering correction of boiling suppression factor for horizontal pipes
  Real S_nb_hor = Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(0.049, 0.051, Fr_l) * Fr_l ^ 0.5 + Modelica.Fluid.Dissipation.Utilities.Functions.General.Stepsmoother(0.051, 0.049, Fr_l) "Correction of suppression factor for nucleate boiling in horizontal pipes";
  //SOURCE_1: p.672, eq. 9.91: Considering effect of forced convective boiling ew.r.t. equation of Dittus-Boelter
  Modelica.Units.SI.CoefficientOfHeatTransfer kc_fc = 0.023 * Re_l ^ 0.8 * Pr_l ^ 0.4 * (IN_var.lambda_l / d_hyd) "Convective heat transfer coefficient assuming liquid mass flow rate only";
  //SOURCE_1: p.675, eq. 9.107: Considering effect of nucleate boiling w.r.t. equation of Cooper
  Modelica.Units.SI.CoefficientOfHeatTransfer kc_nb = 55 * p_red ^ 0.12 * (1 / max(MIN, Modelica.Math.log10(1 / p_red)) ^ 0.55) * (1 / max(MIN, IN_con.MM ^ 0.5)) * abs(IN_var.qdot_A) ^ 0.67 "Nucleate boiling heat transfer coefficient";
  //SOURCE_2: p.354, sec. final equations: Calculation of two phase heat transfer coefficient for horizontal pipes w.r.t. equation of Gungor-Winterton
algorithm
  kc := E_fc * E_fc_hor * kc_fc + S_nb * S_nb_hor * kc_nb;

end kc_twoPhase_boilingHorizontal_KC;

modelica://Modelica.Fluid/CubicInterpola:
Modelica.Fluid: CubicInterpolation_Re (function)

Syntax    Re = CubicInterpolation_Re (0, Re1, Re2, Delta, lambda2);    Description  
 Function CubicInterpolation_Re (..) approximates the Reynolds number  Re in the transition regime between laminar and turbulent flow of the Moody diagram by an inverse formulation of a cubic Hermite spline interpolation. See  Modelica.Fluid.UsersGuide.ComponentDefinition.WallFriction (especially Region 2 ) for a detailed explanation.

Code:
function CubicInterpolation_Re "Cubic Hermite spline interpolation of the Reynolds number in transition regime of the Moody diagram (inverse formulation)"
  extends Modelica.Icons.Function;
  import Modelica.Math;
  input Real Re_turbulent "Unused input";
  input Modelica.Units.SI.ReynoldsNumber Re1 "Boundary Reynolds number for laminar regime";
  input Modelica.Units.SI.ReynoldsNumber Re2 "Boundary Reynolds number for turbulent regime";
  input Real Delta "Relative roughness";
  input Real lambda2 "Modified friction coefficient (= independent variable)";
  output Modelica.Units.SI.ReynoldsNumber Re "Interpolated Reynolds number in transition region";
protected
  // Point x1=lg(lambda2(Re1)) with derivative yd1=1 at y1=lg(Re1)
  Real x1 = Math.log10(64 * Re1) "Lower abscissa value";
  Real y1 = Math.log10(Re1) "Lower ordinate value";
  Real yd1 = 1 "Left boundary slope";
  // Point x2=lg(lambda2(Re2)) with derivative yd2 at y2≈lg(Re2)
  Real aux1 = 0.5 / Math.log(10) * 5.74 * 0.9;
  Real aux2 = Delta / 3.7 + 5.74 / Re2 ^ 0.9;
  Real aux3 = Math.log10(aux2);
  Real L2 = 0.25 * (Re2 / aux3) ^ 2;
  Real aux4 = 2.51 / sqrt(L2) + 0.27 * Delta;
  Real aux5 = -2 * sqrt(L2) * Math.log10(aux4);
  Real x2 = Math.log10(L2) "Upper abscissa value";
  Real y2 = Math.log10(aux5) "Upper ordinate value";
  Real yd2 = 0.5 + 2.51 / Math.log(10) / (aux5 * aux4) "Right boundary slope";
  // Constants: Cubic polynomial between x1=lg(lambda2(Re1)) and x2=lg(lambda2(Re2))
  Real diff_x = x2 - x1 "Interval length";
  Real m = (y2 - y1) / diff_x;
  Real c2 = (3 * m - 2 * yd1 - yd2) / diff_x;
  Real c3 = (yd1 + yd2 - 2 * m) / (diff_x * diff_x);
  Real lambda2_1 = 64 * Re1;
  Real dx = Math.log10(lambda2 / lambda2_1);
algorithm
  // Prefer optimized interpolation formula for Re to avoid cubicHermite function call
  // Re := 10^Modelica.Fluid.Utilities.cubicHermite(Math.log10(lambda2), x1, x2, y1, y2, yd1, yd2);
  Re := Re1 * (lambda2 / lambda2_1) ^ (yd1 + dx * (c2 + dx * c3));

</pre></blockquote>
<h4>Description</h4>
<p>
Function <strong>CubicInterpolation_Re</strong>(..) approximates the Reynolds number
<code>Re</code> in the transition regime between laminar and turbulent flow
of the Moody diagram by an inverse formulation of a cubic Hermite spline interpolation. See <a href=\"modelica://Modelica.Fluid.UsersGuide.ComponentDefinition.WallFriction\">
Modelica.Fluid.UsersGuide.ComponentDefinition.WallFriction</a> (especially <strong>Region 2</strong>)
for a detailed explanation.
</p>
