  Modelica.Blocks.Sources.Ramp x_set(duration = 10, height = -(advancedSolenoid.x_max - advancedSolenoid.x_min), offset = advancedSolenoid.x_max) "Prescribed armature position, slow enforced motion from x_max to x_min" ;
  Modelica.Electrical.Analog.Basic.Ground advancedGround ;
  Modelica.Electrical.Analog.Sources.StepVoltage advancedSource(V = v_step) ;
  Modelica.Magnetic.FluxTubes.Examples.SolenoidActuator.Components.AdvancedSolenoid advancedSolenoid ;
  Modelica.Mechanics.Translational.Sources.Position advancedFeed_x(f_crit = 1000, exact = false) ;
  Modelica.Electrical.Analog.Basic.Ground simpleGround ;
  Modelica.Electrical.Analog.Sources.StepVoltage simpleSource(V = v_step) ;
  Modelica.Magnetic.FluxTubes.Examples.SolenoidActuator.Components.SimpleSolenoid simpleSolenoid ;
  Modelica.Mechanics.Translational.Sources.Position simpleFeed_x(f_crit = 1000, exact = false) ;
  Modelica.Blocks.Tables.CombiTable1Ds comparisonWithFEA(table = [0.00025, -85.8619, 0.00014821, 0.11954; 0.0005, -59.9662, 0.00013931, 0.11004; 0.00075, -41.0806, 0.0001277, 0.098942; 0.001, -28.88, 0.00011587, 0.088425; 0.00125, -21.4113, 0.00010643, 0.08015; 0.0015, -16.8003, 9.9406e-005, 0.073992; 0.00175, -13.6942, 9.3416e-005, 0.068792; 0.002, -11.1188, 8.8564e-005, 0.064492; 0.00225, -9.6603, 8.4505e-005, 0.060917; 0.0025, -8.4835, 8.1215e-005, 0.058017; 0.00275, -7.4658, 7.7881e-005, 0.055125; 0.003, -6.5591, 7.5197e-005, 0.052733; 0.00325, -5.9706, 7.2447e-005, 0.05035; 0.0035, -5.5013, 7.0342e-005, 0.048525; 0.00375, -5.0469, 6.8527e-005, 0.046867; 0.004, -4.6573, 6.6526e-005, 0.045158; 0.00425, -4.2977, 6.4425e-005, 0.043442; 0.0045, -4.0912, 6.2747e-005, 0.04205; 0.00475, -3.7456, 6.1231e-005, 0.040733; 0.005, -3.5869, 5.9691e-005, 0.039467]) "Valid for u_source=12V only; column 1: position, col.2: force, col.3: armature flux, col.4: inductance" ;
equation
  connect(advancedGround.p, advancedSource.n) ;
  connect(x_set.y, advancedFeed_x.s_ref) ;
  connect(simpleSolenoid.p, simpleSource.p) ;
  connect(simpleSolenoid.n, simpleSource.n) ;
  connect(simpleSolenoid.flange, simpleFeed_x.flange) ;
  connect(advancedSolenoid.n, advancedSource.n) ;
