  parameter Modelica.Units.SI.Resistivity rho1 = 1.678e-8 "Resistivity of primary winding (at 20degC)" ;
  parameter Modelica.Units.SI.LinearTemperatureCoefficient alpha1 = 0 "Temperature coefficient of primary turns" ;
  // Tab: Electrical //Group:Secondary Winding
  parameter Integer N2 = 10 "Secondary turns" ;
  parameter Modelica.Units.SI.Length L2(displayUnit = "mm") = L1 "Mean secondary turn length" ;
  parameter Modelica.Units.SI.Length d2(displayUnit = "mm") = d1 "Wire diameter of secondary turns" ;
  parameter Modelica.Units.SI.Resistivity rho2 = rho1 "Resistivity of secondary winding (at 20degC)" ;
  parameter Modelica.Units.SI.LinearTemperatureCoefficient alpha2 = alpha1 "Temperature coefficient of secondary turns" ;
  parameter Modelica.Units.SI.Length l1(displayUnit = "mm") = 40e-3 "Mean length l1 of core" ;
  parameter Modelica.Units.SI.Length l2(displayUnit = "mm") = 60e-3 "Mean length l2 of core" ;
  parameter Modelica.Units.SI.Length a(displayUnit = "mm") = 15e-3 "Height of core" ;
  parameter Modelica.Units.SI.Length b(displayUnit = "mm") = 10e-3 "Width of core" ;
  parameter Modelica.Magnetic.FluxTubes.Material.HysteresisEverettParameter.BaseData mat = Modelica.Magnetic.FluxTubes.Material.HysteresisEverettParameter.BaseData() "Core Material" ;
  output Modelica.Units.SI.Voltage v1[3] "Voltage drop of primary winding 1-3";
  output Modelica.Units.SI.Voltage v2[3] "Voltage drop of secondary winding 1-3";
  output Modelica.Units.SI.Resistance R1[3] "Resistance of primary winding 1-3";
  output Modelica.Units.SI.Resistance R2[3] "Resistance of secondary winding 1-3";
  output Modelica.Units.SI.Current i1[3] "Current in primary winding 1-3";
  output Modelica.Units.SI.Current i2[3] "Current in secondary winding 1-3";
  output Modelica.Units.SI.MagneticFluxDensity B[3] "Magnetic Flux Density in core portions 1-3";
  output Modelica.Units.SI.MagneticFlux Phi[3] "Magnetic Flux through core portions 1-3";
  output Modelica.Units.SI.MagneticFieldStrength Hstat[3] "Ferromagnetic portion of magnetic field strength";
  output Modelica.Units.SI.MagneticFieldStrength Heddy[3] "Eddy current portion of magnetic field strength";
  output Modelica.Units.SI.MagneticFieldStrength H[3] "Total magnetic field strength of core";
  //output SI.Resistance R1
  parameter Real MagRelStart[3] = {0, 0, 0} "Initial magnetization of Core (-1..1)" ;
  parameter Boolean MagRelFixed[3] = {false, false, false} "Fixed" ;
  parameter Modelica.Units.SI.MagneticFieldStrength HStart[3] = {0, 0, 0} "Initial magnetic field strength of Core" ;
  parameter Boolean HFixed[3] = {false, false, false} "Fixed" ;
  parameter Modelica.Units.SI.ElectricCurrent I1Start[3] = {0, 0, 0} "Initial current of primary Windings" ;
  parameter Boolean I1Fixed[3] = {false, false, false} "Fixed" ;
  parameter Modelica.Units.SI.ElectricCurrent I2Start[3] = {0, 0, 0} "Initial current of secondary Windings" ;
  parameter Boolean I2Fixed[3] = {false, false, false} "Fixed" ;
  output Modelica.Units.SI.Power LossPowerWinding "Winding losses";
  output Modelica.Units.SI.Power LossPowerStat "Ferromagnetic hysteresis losses";
  output Modelica.Units.SI.Power LossPowerEddy "Eddy current losses";
  extends Modelica.Magnetic.FluxTubes.Interfaces.ConditionalHeatPort;
  parameter Boolean EddyCurrents = false "Enable eddy currents" ;
  parameter Modelica.Units.SI.Conductivity sigma = mat.sigma "Conductivity of core material" ;
  parameter Modelica.Units.SI.Length t(displayUnit = "mm") = 0.5e-3 "Thickness of lamination" ;
  parameter Modelica.Units.SI.Length L_l1 = 10e-3 "Length of leakage of primary Winding" ;
  parameter Modelica.Units.SI.Area A_l1 = 10e-6 "Cross section of leakage of primary Winding" ;
  parameter Real mu_rel1 = 1 "Constant relative permeability of primary leakage (>0 required)" ;
  parameter Modelica.Units.SI.Length L_l2 = 10e-3 "Cross section of leakage of secondary Winding" ;
  parameter Modelica.Units.SI.Area A_l2 = 10e-6 "Length of leakage of secondary Winding" ;
  parameter Real mu_rel2 = 1 "Constant relative permeability of secondary leakage (>0 required)" ;
  Modelica.Magnetic.FluxTubes.Shapes.HysteresisAndMagnets.GenericHystTellinenEverett core1(mat = mat, A = a * b, sigma = sigma, d = t, useHeatPort = false, includeEddyCurrents = EddyCurrents, l = l1 + 2 * l2, H(start = HStart[1], fixed = HFixed[1]), MagRel(start = MagRelStart[1], fixed = MagRelFixed[1])) ;
  Modelica.Magnetic.FluxTubes.Shapes.HysteresisAndMagnets.GenericHystTellinenEverett core2(mat = mat, A = a * b, sigma = sigma, d = t, useHeatPort = false, includeEddyCurrents = EddyCurrents, l = l2, H(start = HStart[2], fixed = HFixed[2]), MagRel(start = MagRelStart[2], fixed = MagRelFixed[2])) ;
  Modelica.Magnetic.FluxTubes.Shapes.HysteresisAndMagnets.GenericHystTellinenEverett core3(mat = mat, A = a * b, includeEddyCurrents = EddyCurrents, sigma = sigma, d = t, l = l1 + 2 * l2, H(start = HStart[3], fixed = HFixed[3]), MagRel(start = MagRelStart[3], fixed = MagRelFixed[3])) ;
  Modelica.Magnetic.FluxTubes.Basic.Ground ground ;
  Modelica.Magnetic.FluxTubes.Basic.ElectroMagneticConverterWithLeakageInductance winding11(N = N1, L = L_l1, A = A_l1, mu_rel = mu_rel1, i(start = I1Start[1], fixed = I1Fixed[1])) ;
  Modelica.Magnetic.FluxTubes.Basic.ElectroMagneticConverterWithLeakageInductance winding12(L = L_l1, A = A_l1, mu_rel = mu_rel1, i(start = I1Start[2], fixed = I1Fixed[2]), final N = N1) ;
  Modelica.Magnetic.FluxTubes.Basic.ElectroMagneticConverterWithLeakageInductance winding13(N = N1, L = L_l1, A = A_l1, mu_rel = mu_rel1, i(start = I1Start[3], fixed = I1Fixed[3])) ;
  Modelica.Magnetic.FluxTubes.Basic.ElectroMagneticConverterWithLeakageInductance winding21(N = N2, L = L_l2, A = A_l2, mu_rel = mu_rel2, i(start = I2Start[1], fixed = I2Fixed[1])) ;
  Modelica.Magnetic.FluxTubes.Basic.ElectroMagneticConverterWithLeakageInductance winding22(N = N2, L = L_l2, A = A_l2, mu_rel = mu_rel2, i(start = I2Start[1], fixed = I2Fixed[1])) ;
  Modelica.Magnetic.FluxTubes.Basic.ElectroMagneticConverterWithLeakageInductance winding23(N = N2, L = L_l2, A = A_l2, mu_rel = mu_rel2, i(start = I2Start[1], fixed = I2Fixed[1])) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor11(R = rho1 * N1 * L1 / (pi / 4 * d1 ^ 2), useHeatPort = true, alpha = alpha1, T_ref = 293.15) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor21(R = rho2 * N2 * L2 / (pi / 4 * d2 ^ 2), useHeatPort = true, alpha = alpha2, T_ref = 293.15) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor12(R = rho1 * N1 * L1 / (pi / 4 * d1 ^ 2), useHeatPort = true, alpha = alpha1, T_ref = 293.15) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor22(R = rho2 * N2 * L2 / (pi / 4 * d2 ^ 2), useHeatPort = true, alpha = alpha2, T_ref = 293.15) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor23(R = rho2 * N2 * L2 / (pi / 4 * d2 ^ 2), useHeatPort = true, alpha = alpha2, T_ref = 293.15) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor13(R = rho1 * N1 * L1 / (pi / 4 * d1 ^ 2), useHeatPort = true, alpha = alpha1, T_ref = 293.15) ;
  Modelica.Magnetic.FluxTubes.Shapes.FixedShape.Cuboid leakage(nonLinearPermeability = false, mu_rConst = 1, l = l2, a = a, b = b / 1000) ;
  Modelica.Electrical.Analog.Interfaces.PositivePin p1 "Primary winding 1" ;
  Modelica.Electrical.Analog.Interfaces.PositivePin p2 "Primary winding 2" ;
  Modelica.Electrical.Analog.Interfaces.PositivePin p3 "Primary winding 3" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin n1 "Secondary winding 1" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin n2 "Secondary winding 2" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin n3 "Secondary winding 3" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin starPoint2 "Star point of secondary windings" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin starPoint1 "Star point of primary windings" ;
equation
  v1[1] = resistor11.p.v - winding11.n.v;
  v1[2] = resistor12.p.v - winding12.n.v;
  v1[3] = resistor13.p.v - winding13.n.v;
  i1[1] = resistor11.i;
  i1[2] = resistor12.i;
  i1[3] = resistor13.i;
  R1[1] = resistor11.R_actual;
  R1[2] = resistor12.R_actual;
  R1[3] = resistor13.R_actual;
  v2[1] = resistor21.n.v - winding21.n.v;
  v2[2] = resistor21.n.v - winding21.n.v;
  v2[3] = resistor21.n.v - winding21.n.v;
  i2[1] = resistor21.i;
  i2[2] = resistor22.i;
  i2[3] = resistor23.i;
  R2[1] = resistor21.R_actual;
  R2[2] = resistor22.R_actual;
  R2[3] = resistor23.R_actual;
  B[1] = core1.B;
  B[2] = core2.B;
  B[3] = core3.B;
  Phi[1] = core1.Phi;
  Phi[2] = core2.Phi;
  Phi[3] = core3.Phi;
  Hstat[1] = core1.Hstat;
  Hstat[2] = core2.Hstat;
  Hstat[3] = core3.Hstat;
  Heddy[1] = core1.Heddy;
  Heddy[2] = core2.Heddy;
  Heddy[3] = core3.Heddy;
  H[1] = core1.H;
  H[2] = core2.H;
  H[3] = core3.H;
  Temp.T = if useHeatPort then T_heatPort else T;
  LossPowerWinding = resistor11.LossPower + resistor12.LossPower + resistor13.LossPower + resistor21.LossPower + resistor22.LossPower + resistor23.LossPower;
  LossPowerStat = core1.LossPowerStat + core2.LossPowerStat + core3.LossPowerStat;
  LossPowerEddy = core1.LossPowerEddy + core2.LossPowerEddy + core3.LossPowerEddy;
  LossPower = LossPowerWinding + LossPowerEddy + LossPowerStat;
  connect(winding11.port_n, winding21.port_p) ;
  connect(winding11.p, resistor11.n) ;
  connect(resistor11.p, p1) ;
  connect(winding12.p, resistor12.n) ;
  connect(winding13.p, resistor13.n) ;
  connect(winding12.port_p, core2.port_n) ;
  connect(winding12.port_n, winding22.port_p) ;
  connect(winding21.port_n, ground.port) ;
  connect(ground.port, winding22.port_n) ;
  connect(winding23.port_n, ground.port) ;
  connect(winding23.port_p, winding13.port_n) ;
  connect(winding13.port_p, core3.port_n) ;
  connect(p2, resistor12.p) ;
  connect(p3, resistor13.p) ;
  connect(Temp.port, resistor11.heatPort) ;
  connect(resistor12.heatPort, Temp.port) ;
  connect(resistor13.heatPort, Temp.port) ;
  connect(resistor23.heatPort, Temp.port) ;
  connect(resistor22.heatPort, Temp.port) ;
  connect(resistor21.heatPort, Temp.port) ;
  connect(resistor21.p, winding21.p) ;
  connect(resistor22.p, winding22.p) ;
  connect(resistor23.p, winding23.p) ;
  connect(resistor21.n, n1) ;
