model SinglePhaseInductance "Single-phase inductance"
  extends Modelica.Icons.Example;
  parameter Modelica.Units.SI.Frequency f = 1 "Supply frequency";
  parameter Modelica.Units.SI.Voltage VRMS = 100 "RMS supply voltage";
  parameter Modelica.Units.SI.Resistance R = 0.1 "Leader cable resistance";
  parameter Modelica.Units.SI.Inductance L = 1 "Load inductance";
  parameter Real effectiveTurns = 5 "Effective number of turns";
  final parameter Modelica.Units.SI.Reluctance R_m = effectiveTurns ^ 2 / L "Equivalent magnetic reluctance";
  Modelica.Electrical.Analog.Basic.Ground ground_e ;
  Modelica.Electrical.Analog.Basic.Ground ground_m ;
  Modelica.Electrical.Analog.Sources.SineVoltage voltageSource_e(f = f, V = sqrt(2) * VRMS, phase = Modelica.Constants.pi / 2) ;
  Modelica.Electrical.Analog.Sources.SineVoltage voltageSource_m(f = f, V = sqrt(2) * VRMS, phase = Modelica.Constants.pi / 2) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor_e(R = R) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor_m(R = R) ;
  Modelica.Electrical.Analog.Basic.Inductor inductor_e(L = L) ;
  Modelica.Magnetic.FundamentalWave.Components.SinglePhaseElectroMagneticConverter converter_m(effectiveTurns = effectiveTurns, orientation = 0) ;
  Modelica.Magnetic.FundamentalWave.Components.Reluctance reluctance_m(R_m(d = R_m, q = R_m)) ;
  Modelica.Magnetic.FundamentalWave.Components.Ground groundM_m ;
initial equation
  resistor_e.i = 0;
  resistor_m.i = 0;
equation
  connect(converter_m.port_p, reluctance_m.port_p) ;
  connect(converter_m.port_n, reluctance_m.port_n) ;
  connect(converter_m.port_n, groundM_m.port_p) ;
