model IMC_withLosses "Induction machine with squirrel cage and losses"
  extends Modelica.Icons.Example;
  constant Integer m = 3 "Number of phases";
  import Modelica.Constants.pi;
  import Modelica.Units.Conversions.from_rpm;
  import Modelica.Units.Conversions.to_rpm;
  import Modelica.Units.Conversions.from_degC;
protected
  parameter Modelica.Units.SI.Power PNominal = 18500 "Nominal output";
  parameter Modelica.Units.SI.Voltage VNominal = 400 "Nominal RMS voltage";
  parameter Modelica.Units.SI.Current INominal = 32.85 "Nominal RMS current";
  parameter Real pfNominal = 0.898 "Nominal power factor";
  parameter Modelica.Units.SI.Power PsNominal = sqrt(3) * VNominal * INominal * pfNominal "Nominal stator power";
  parameter Modelica.Units.SI.Power lossNominal = PsNominal - PNominal "Nominal losses";
  parameter Real etaNominal = 0.9049 "Nominal efficiency";
  parameter Modelica.Units.SI.Frequency fNominal = aimcData.fsNominal "Nominal frequency";
  parameter Modelica.Units.SI.AngularVelocity wNominal = from_rpm(1462.5) "Nominal speed";
  parameter Modelica.Units.SI.Torque TNominal = PNominal / wNominal "Nominal torque";
  parameter Modelica.Units.SI.Temperature TempNominal = from_degC(90) "Nominal temperature";
  Modelica.Units.SI.Power Pel = electricalPowerSensor.P;
  Modelica.Units.SI.ReactivePower Qel = electricalPowerSensor.Q;
  Modelica.Units.SI.ApparentPower Sel = sqrt(Pel ^ 2 + Qel ^ 2);
  parameter Real Ptable[:] = {1E-6, 1845, 3549, 5325, 7521, 9372, 11010, 12930, 14950, 16360, 18500, 18560, 20180, 22170} "Table of measured power data";
  parameter Real Itable[:] = {11.0, 11.20, 12.27, 13.87, 16.41, 18.78, 21.07, 23.92, 27.05, 29.40, 32.85, 32.95, 35.92, 39.35} "Table of measured current data";
  parameter Real wtable[:] = from_rpm({1500, 1496, 1493, 1490, 1486, 1482, 1479, 1475, 1471, 1467, 1462, 1462, 1458, 1453}) "Table of measured speed data";
  parameter Real ctable[:] = {0.085, 0.327, 0.506, 0.636, 0.741, 0.797, 0.831, 0.857, 0.875, 0.887, 0.896, 0.896, 0.902, 0.906} "Table of measured power factor data";
  parameter Real etable[:] = {0, 0.7250, 0.8268, 0.8698, 0.8929, 0.9028, 0.9064, 0.9088, 0.9089, 0.9070, 0.9044, 0.9043, 0.9008, 0.8972} "Table of measured efficiency data";
public
  output Modelica.Units.SI.Power Pmech = powerSensor.power "Mechanical output";
  output Modelica.Units.SI.Power Ps_sim = sqrt(3) * VNominal * I_sim * pf_sim "Simulated stator power";
  output Modelica.Units.SI.Power Ps_meas = sqrt(3) * VNominal * I_meas * pf_meas "Simulated stator power";
  output Modelica.Units.SI.Power loss_sim = Ps_sim - Pmech "Simulated total losses";
  output Modelica.Units.SI.Power loss_meas = Ps_meas - Pmech "Measured total losses";
  output Modelica.Units.SI.Current I_sim = currentQuasiRMSSensor.I "Simulated current";
  output Modelica.Units.SI.Current I_meas = combiTable1Ds.y[1] "Measured current";
  output Modelica.Units.SI.AngularVelocity w_sim(displayUnit = "rev/min") = aimc.wMechanical "Simulated speed";
  output Modelica.Units.SI.AngularVelocity w_meas(displayUnit = "rev/min") = combiTable1Ds.y[2] "Measured speed";
  output Real pf_sim = if noEvent(Sel > Modelica.Constants.small) then Pel / Sel else 0 "Simulated power factor";
  output Real pf_meas = combiTable1Ds.y[3] "Measured power factor";
  output Real eff_sim = if noEvent(abs(Pel) > Modelica.Constants.small) then Pmech / Pel else 0 "Simulated efficiency";
  output Real eff_meas = combiTable1Ds.y[4] "Measured efficiency";
  Modelica.Magnetic.FundamentalWave.BasicMachines.InductionMachines.IM_SquirrelCage aimc(p = aimcData.p, fsNominal = aimcData.fsNominal, TsRef = aimcData.TsRef, alpha20s(displayUnit = "1/K") = aimcData.alpha20s, Jr = aimcData.Jr, Js = aimcData.Js, frictionParameters = aimcData.frictionParameters, phiMechanical(fixed = true), statorCoreParameters = aimcData.statorCoreParameters, strayLoadParameters = aimcData.strayLoadParameters, TrRef = aimcData.TrRef, TsOperational = TempNominal, TrOperational = TempNominal, wMechanical(fixed = true, start = 2 * pi * aimcData.fsNominal / aimcData.p), Rs = aimcData.Rs * m / 3, Lssigma = aimcData.Lssigma * m / 3, Lszero = aimcData.Lszero * m / 3, Lm = aimcData.Lm * m / 3, Lrsigma = aimcData.Lrsigma * m / 3, Rr = aimcData.Rr * m / 3, effectiveStatorTurns = aimcData.effectiveStatorTurns, alpha20r = aimcData.alpha20r) ;
  Modelica.Electrical.Machines.Utilities.TerminalBox terminalBox(terminalConnection = "D") ;
  Modelica.Electrical.Machines.Sensors.ElectricalPowerSensor electricalPowerSensor ;
  Modelica.Electrical.Machines.Sensors.CurrentQuasiRMSSensor currentQuasiRMSSensor ;
  Modelica.Electrical.Polyphase.Sources.SineVoltage sineVoltage(final m = m, f = fill(fNominal, m), V = fill(sqrt(2 / 3) * VNominal, m)) ;
  Modelica.Electrical.Polyphase.Basic.Star star(final m = m) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Mechanics.Rotational.Sensors.PowerSensor powerSensor ;
  Modelica.Mechanics.Rotational.Components.Inertia loadInertia(J = aimcData.Jr) ;
  Modelica.Mechanics.Rotational.Sources.Torque torque ;
  Modelica.Blocks.Math.Gain gain(k = -1) ;
  Modelica.Blocks.Continuous.PI PI(k = 0.01, T = 0.01, initType = Modelica.Blocks.Types.Init.InitialState) ;
  Modelica.Blocks.Math.Feedback feedback ;
  Modelica.Blocks.Sources.Ramp ramp(height = 1.2 * PNominal, offset = 0, startTime = 4.5, duration = 5.5) ;
  Modelica.Blocks.Tables.CombiTable1Ds combiTable1Ds(table = array({Ptable[j], Itable[j], wtable[j], ctable[j], etable[j]} for j in 1:size(Ptable, 1)), smoothness = Modelica.Blocks.Types.Smoothness.ContinuousDerivative) ;
  parameter Modelica.Electrical.Machines.Utilities.ParameterRecords.IM_SquirrelCageData aimcData(statorCoreParameters(PRef = 410, VRef = 387.9), Jr = 0.12, Rs = 0.56, alpha20s(displayUnit = "1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Copper, Lssigma = 1.52 / (2 * pi * fNominal), frictionParameters(PRef = 180, wRef = wNominal), strayLoadParameters(PRef = 0.005 * sqrt(3) * VNominal * INominal * pfNominal, IRef = INominal / sqrt(3), wRef = wNominal), Lm = 66.4 / (2 * pi * fNominal), Lrsigma = 2.31 / (2 * pi * fNominal), Rr = 0.42, alpha20r(displayUnit = "1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Aluminium) "Induction machine data" ;
initial equation
  sum(aimc.is) = 0;
  der(aimc.airGap.V_msr.re) = 0;
  der(aimc.airGap.V_msr.im) = 0;
  der(aimc.airGap.V_mrr.re) = 0;
