modelica://Modelica.Magnetic/SMEE_LoadDu:
Modelica.Magnetic: SMEE_LoadDump (model)

An electrically excited synchronous generator is started with a speed ramp, then driven with constant speed. Voltage is controlled, the set point depends on speed. After start-up the generator is loaded, the load is rejected.  
Simulate for 10 seconds and plot:  
voltageQuasiRMSSensor.V smee.tauElectrical smee.ie  
Default machine parameters are used

Code:
model SMEE_LoadDump "Test example: ElectricalExcitedSynchronousMachine with voltage controller"
  extends Modelica.Icons.Example;
  import Modelica.Constants.pi;
  constant Integer m = 3 "Number of phases";
  parameter Modelica.Units.SI.AngularVelocity wNominal = 2 * pi * smeeData.fsNominal / smee.p "Nominal speed";
  parameter Modelica.Units.SI.Impedance ZNominal = 3 * smeeData.VsNominal ^ 2 / smeeData.SNominal "Nominal load impedance";
  parameter Real powerFactor(min = 0, max = 1) = 0.8 "Load power factor";
  parameter Modelica.Units.SI.Resistance RLoad = ZNominal * powerFactor "Load resistance";
  parameter Modelica.Units.SI.Inductance LLoad = ZNominal * sqrt(1 - powerFactor ^ 2) / (2 * pi * smeeData.fsNominal) "Load inductance";
  parameter Modelica.Units.SI.Voltage Ve0 = smee.IeOpenCircuit * Modelica.Electrical.Machines.Thermal.convertResistance(smee.Re, smee.TeRef, smee.alpha20e, smee.TeOperational) "No load excitation voltage";
  parameter Real k = 2 * Ve0 / smeeData.VsNominal "Voltage controller: gain";
  parameter Modelica.Units.SI.Time Ti = smeeData.Td0Transient / 2 "Voltage controller: integral time constant";
  output Real controlError = (setPointGain.y - voltageQuasiRMSSensor.V) / smeeData.VsNominal;
  Modelica.Magnetic.FundamentalWave.BasicMachines.SynchronousMachines.SM_ElectricalExcited smee(fsNominal = smeeData.fsNominal, TsRef = smeeData.TsRef, Lrsigmad = smeeData.Lrsigmad, Lrsigmaq = smeeData.Lrsigmaq, Rrd = smeeData.Rrd, Rrq = smeeData.Rrq, TrRef = smeeData.TrRef, VsNominal = smeeData.VsNominal, IeOpenCircuit = smeeData.IeOpenCircuit, Re = smeeData.Re, TeRef = smeeData.TeRef, sigmae = smeeData.sigmae, useDamperCage = true, p = 2, Jr = 0.29, Js = 0.29, statorCoreParameters(VRef = 100), strayLoadParameters(IRef = 100), brushParameters(ILinear = 0.01), Rs = smeeData.Rs * m / 3, Lssigma = smeeData.Lssigma * m / 3, Lmd = smeeData.Lmd * m / 3, Lmq = smeeData.Lmq * m / 3, TsOperational = 293.15, alpha20s = smeeData.alpha20s, effectiveStatorTurns = smeeData.effectiveStatorTurns, alpha20r = smeeData.alpha20r, TrOperational = 293.15, TeOperational = 293.15, alpha20e = smeeData.alpha20e) ;
  parameter Modelica.Electrical.Machines.Utilities.SynchronousMachineData smeeData(SNominal = 30e3, VsNominal = 100, fsNominal = 50, IeOpenCircuit = 10, x0 = 0.1, xd = 1.6, xq = 1.6, xdTransient = 0.1375, xdSubtransient = 0.121428571, xqSubtransient = 0.148387097, Ta = 0.014171268, Td0Transient = 0.261177343, Td0Subtransient = 0.006963029, Tq0Subtransient = 0.123345081, TsSpecification = 293.15, TsRef = 293.15, alpha20s(displayUnit = "1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero, TrSpecification = 293.15, TrRef = 293.15, alpha20r(displayUnit = "1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero, TeSpecification = 293.15, TeRef = 293.15, alpha20e(displayUnit = "1/K") = Modelica.Electrical.Machines.Thermal.Constants.alpha20Zero) "Synchronous machine data" ;
  Modelica.Electrical.Machines.Utilities.TerminalBox terminalBox(terminalConnection = "Y") ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Mechanics.Rotational.Sources.Speed speed ;
  Modelica.Blocks.Sources.Ramp speedRamp(height = wNominal, duration = 1) ;
  Modelica.Mechanics.Rotational.Sensors.SpeedSensor speedSensor ;
  Modelica.Blocks.Math.Gain setPointGain(k = smeeData.VsNominal / wNominal) ;
  Modelica.Electrical.Machines.Sensors.VoltageQuasiRMSSensor voltageQuasiRMSSensor(ToSpacePhasor1(y(each start = 1E-3, each fixed = true))) ;
  Modelica.Blocks.Continuous.LimPID voltageController(controllerType = Modelica.Blocks.Types.SimpleController.PI, k = k, Ti = Ti, yMax = 2.5 * Ve0, yMin = 0, initType = Modelica.Blocks.Types.Init.InitialState, Td = 0.001) ;
  Modelica.Electrical.Analog.Sources.SignalVoltage excitationVoltage ;
  Modelica.Electrical.Analog.Basic.Ground groundExcitation ;
