  Modelica.Magnetic.FundamentalWave.Components.PolyphaseElectroMagneticConverter electroMagneticConverter(final m = m, final effectiveTurns = fill(effectiveTurns, m), final orientation = Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m)) "Symmetric winding" ;
  Modelica.Electrical.Polyphase.Basic.ZeroInductor zeroInductor(final m = m, final Lzero = Lzero) if mBase <> 2 "Zero sequence inductance of winding" ;
  Modelica.Electrical.Polyphase.Ideal.Short short(final m = m) if mBase == 2 ;
