  parameter Modelica.Units.SI.Resistance RRef "Winding resistance per phase at TRef";
  parameter Modelica.Units.SI.Temperature TRef(start = 293.15) "Reference temperature of winding";
  parameter Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20 alpha20(start = 0) "Temperature coefficient of winding at 20 degC";
  final parameter Modelica.Units.SI.LinearTemperatureCoefficient alphaRef = Modelica.Electrical.Machines.Thermal.convertAlpha(alpha20, TRef, 293.15) "Temperature coefficient of winding at reference temperature";
  parameter Modelica.Units.SI.Temperature TOperational(start = 293.15) "Operational temperature of winding" ;
  parameter Modelica.Units.SI.Inductance Lsigma "Cage stray inductance";
  parameter Real effectiveTurns = 1 "Effective number of turns";
  final parameter Integer nBase = Modelica.Electrical.Polyphase.Functions.numberOfSymmetricBaseSystems(m) "Number of base systems";
  Modelica.Units.SI.Current i[m] = electroMagneticConverter.i "Cage currents";
  Modelica.Magnetic.FundamentalWave.Components.PolyphaseElectroMagneticConverter electroMagneticConverter(final m = m, final effectiveTurns = fill(effectiveTurns, m), final orientation = Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m)) "Symmetric winding" ;
  Modelica.Electrical.Polyphase.Basic.Resistor resistor(final useHeatPort = useHeatPort, final m = m, final R = fill(RRef, m), final T_ref = fill(TRef, m), final alpha = fill(alphaRef, m), final T = fill(TOperational, m)) ;
  Modelica.Electrical.Polyphase.Basic.Star star(final m = nBase) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPortWinding if useHeatPort "Heat ports of winding resistor" ;
  Modelica.Thermal.HeatTransfer.Components.ThermalCollector thermalCollector(final m = m) if useHeatPort "Connector of thermal rotor resistance heat ports" ;
  Modelica.Magnetic.FundamentalWave.Components.Reluctance strayReluctance(final R_m(d = m * effectiveTurns ^ 2 / 2 / Lsigma, q = m * effectiveTurns ^ 2 / 2 / Lsigma)) "Stray reluctance equivalent to ideally coupled stray inductances" ;
  Modelica.Electrical.Polyphase.Basic.MultiStar multiStar(final m = m) ;
equation
  connect(port_p, electroMagneticConverter.port_p) ;
  connect(electroMagneticConverter.port_n, port_n) ;
  connect(ground.p, star.pin_n) ;
  connect(thermalCollector.port_a, resistor.heatPort) ;
  connect(thermalCollector.port_b, heatPortWinding) ;
  connect(strayReluctance.port_p, port_p) ;
  connect(strayReluctance.port_n, port_n) ;
  connect(electroMagneticConverter.plug_p, resistor.plug_p) ;
  connect(electroMagneticConverter.plug_n, multiStar.plug_p) ;
  connect(multiStar.starpoints, star.plug_p) ;
  connect(resistor.plug_n, multiStar.plug_p) ;

end SymmetricPolyphaseCageWinding;

