Code:
partial model Machine "Base model of machines"
  constant Modelica.Units.SI.Angle pi = Modelica.Constants.pi;
  extends Modelica.Electrical.Machines.Icons.FundamentalWaveMachine;
  parameter Integer m(min = 3) = 3 "Number of stator phases" ;
  // Mechanical parameters
  parameter Modelica.Units.SI.Inertia Jr(start = 0.29) "Rotor inertia";
  parameter Boolean useSupport = false "Enable / disable (=fixed stator) support" ;
  parameter Modelica.Units.SI.Inertia Js(start = Jr) "Stator inertia" ;
  parameter Boolean useThermalPort = false "Enable / disable (=fixed temperatures) thermal port" ;
  parameter Integer p(min = 1, start = 2) "Number of pole pairs (Integer)";
  parameter Modelica.Units.SI.Frequency fsNominal(start = 50) "Nominal frequency";
  parameter Modelica.Units.SI.Temperature TsOperational(start = 293.15) "Operational temperature of stator resistance" ;
  parameter Modelica.Units.SI.Resistance Rs(start = 0.03) "Stator resistance per phase at TRef" ;
  parameter Modelica.Units.SI.Temperature TsRef(start = 293.15) "Reference temperature of stator resistance" ;
  parameter Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20 alpha20s(start = 0) "Temperature coefficient of stator resistance at 20 degC" ;
  parameter Real effectiveStatorTurns = 1 "Effective number of stator turns";
  parameter Modelica.Units.SI.Inductance Lssigma(start = 3 * (1 - sqrt(1 - 0.0667)) / (2 * pi * fsNominal)) "Stator stray inductance" ;
  parameter Modelica.Units.SI.Inductance Lszero = Lssigma "Stator zero inductance" ;
  parameter Modelica.Magnetic.FundamentalWave.Types.SalientInductance L0(d(start = 1), q(start = 1)) "Salient inductance of an unchorded coil" ;
  parameter Modelica.Electrical.Machines.Losses.FrictionParameters frictionParameters(wRef = 2 * pi * fsNominal / p) "Friction loss parameter record" ;
  parameter Modelica.Electrical.Machines.Losses.CoreParameters statorCoreParameters(final m = m, wRef = 2 * pi * fsNominal / p, VRef(start = 100)) "Stator core loss parameter record; all parameters refer to stator side" ;
  parameter Modelica.Electrical.Machines.Losses.StrayLoadParameters strayLoadParameters(IRef(start = 100), wRef = 2 * pi * fsNominal / p) "Stray load loss parameter record" ;
  // Mechanical quantities
  output Modelica.Units.SI.Angle phiMechanical(start = 0) = flange.phi - internalSupport.phi "Mechanical angle of rotor against stator";
  output Modelica.Units.SI.AngularVelocity wMechanical(start = 0, displayUnit = "rev/min") = der(phiMechanical) "Mechanical angular velocity of rotor against stator";
  output Modelica.Units.SI.Torque tauElectrical = inertiaRotor.flange_a.tau "Electromagnetic torque";
  output Modelica.Units.SI.Torque tauShaft = -flange.tau "Shaft torque";
  replaceable output Modelica.Electrical.Machines.Interfaces.InductionMachines.PartialPowerBalanceInductionMachines powerBalance(final powerStator = Modelica.Electrical.Polyphase.Functions.activePower(vs, is), final powerMechanical = wMechanical * tauShaft, final powerInertiaStator = inertiaStator.J * inertiaStator.a * inertiaStator.w, final powerInertiaRotor = inertiaRotor.J * inertiaRotor.a * inertiaRotor.w, final lossPowerStatorWinding = sum(stator.resistor.resistor.LossPower), final lossPowerStatorCore = stator.core.lossPower, final lossPowerStrayLoad = strayLoad.lossPower, final lossPowerFriction = friction.lossPower) "Power balance";
  // Stator voltages and currents
  output Modelica.Units.SI.Voltage vs[m] = plug_sp.pin.v - plug_sn.pin.v "Stator instantaneous voltages";
  output Modelica.Units.SI.Current is[m] = plug_sp.pin.i "Stator instantaneous currents";
  Modelica.Mechanics.Rotational.Interfaces.Flange_a flange "Shaft" ;
  Modelica.Mechanics.Rotational.Components.Inertia inertiaRotor(final J = Jr) ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a support if useSupport "Support at which the reaction torque is acting" ;
  Modelica.Mechanics.Rotational.Components.Inertia inertiaStator(final J = Js) ;
  Modelica.Mechanics.Rotational.Components.Fixed fixed if not useSupport ;
  Modelica.Electrical.Polyphase.Interfaces.PositivePlug plug_sp(final m = m) "Positive plug of stator" ;
  Modelica.Electrical.Polyphase.Interfaces.NegativePlug plug_sn(final m = m) "Negative plug of stator" ;
  Modelica.Magnetic.FundamentalWave.BasicMachines.Components.SymmetricPolyphaseWinding stator(final useHeatPort = true, final m = m, final RRef = Rs, final TRef = TsRef, final Lsigma = Lssigma, final effectiveTurns = effectiveStatorTurns, final TOperational = TsOperational, final GcRef = statorCoreParameters.GcRef, final alpha20 = alpha20s, final Lzero = Lszero) "Symmetric stator winding including resistances, zero and stray inductances and core losses" ;
  replaceable Modelica.Electrical.Machines.Interfaces.InductionMachines.PartialThermalAmbientInductionMachines thermalAmbient(final useTemperatureInputs = false, final Ts = TsOperational, final m = m) if not useThermalPort ;
  replaceable Modelica.Electrical.Machines.Interfaces.InductionMachines.PartialThermalPortInductionMachines thermalPort(final m = m) if useThermalPort "Thermal port of induction machines" ;
  Modelica.Magnetic.FundamentalWave.Components.Ground groundS "Ground of stator magnetic circuit" ;
  Modelica.Magnetic.FundamentalWave.BasicMachines.Components.RotorSaliencyAirGap airGap(final p = p, final L0 = L0) ;
  Modelica.Magnetic.FundamentalWave.Components.Ground groundR "Ground of rotor magnetic circuit" ;
  /* previously used: state selection, now commented
  FundamentalWave.Interfaces.StateSelector stateSelectorS(
    final m=m,
    final xi=is,
    final gamma=p*phiMechanical) "State selection of stator currents"

  */
  Modelica.Electrical.Machines.Losses.InductionMachines.StrayLoad strayLoad(final strayLoadParameters = strayLoadParameters, final useHeatPort = true, final m = m) ;
  Modelica.Electrical.Machines.Losses.Friction friction(final frictionParameters = frictionParameters, final useHeatPort = true) ;
  replaceable Modelica.Electrical.Machines.Interfaces.InductionMachines.PartialThermalPortInductionMachines internalThermalPort(final m = m) ;
  Modelica.Mechanics.Rotational.Interfaces.Support internalSupport ;
initial algorithm
  assert(not Modelica.Math.isPowerOf2(m), String(m) + " phases are currently not supported in this version of FundametalWave");
equation
  connect(stator.plug_n, plug_sn) ;
  connect(inertiaRotor.flange_b, flange) ;
  connect(internalSupport, inertiaStator.flange_a) ;
  connect(internalSupport, fixed.flange) ;
  connect(inertiaStator.flange_b, support) ;
  connect(airGap.flange_a, inertiaRotor.flange_a) ;
  connect(airGap.support, internalSupport) ;
  connect(groundR.port_p, airGap.port_rn) ;
  connect(stator.plug_p, strayLoad.plug_n) ;
  connect(plug_sp, strayLoad.plug_p) ;
  connect(strayLoad.support, internalSupport) ;
  connect(strayLoad.heatPort, internalThermalPort.heatPortStrayLoad) ;
  connect(friction.support, internalSupport) ;
  connect(strayLoad.flange, inertiaRotor.flange_b) ;
  connect(friction.flange, inertiaRotor.flange_b) ;
  connect(friction.heatPort, internalThermalPort.heatPortFriction) ;
  connect(groundS.port_p, airGap.port_sp) ;
  connect(stator.port_n, airGap.port_sp) ;
  connect(stator.port_p, airGap.port_sn) ;
  connect(stator.heatPortWinding, internalThermalPort.heatPortStatorWinding) ;
  connect(stator.heatPortCore, internalThermalPort.heatPortStatorCore) ;
  connect(thermalAmbient.thermalPort, internalThermalPort) ;
  connect(internalThermalPort, thermalPort) ;

end Machine;

