  Modelica.Electrical.QuasiStatic.SinglePhase.Basic.Ground electricGround1 ;
  Modelica.Electrical.QuasiStatic.SinglePhase.Sources.VariableCurrentSource currentSource(gamma(fixed = true, start = 0)) ;
