  port_p.reference.gamma = port_n.reference.gamma;
  omega = der(port_p.reference.gamma);

end Source;

modelica://Modelica.Magnetic/FixedShape-:
Modelica.Magnetic: FixedShape (model)

Please refer to the description of the subpackage  Shapes.FixedShape  for utilisation of this partial model.

Code:
partial model FixedShape "Base class for flux tubes with fixed shape during simulation"
  extends Modelica.Magnetic.QuasiStatic.FluxTubes.Interfaces.TwoPort;
  parameter Modelica.Units.SI.RelativePermeability mu_rConst = 1 "Constant relative permeability";
  Modelica.Units.SI.Reluctance R_m "Magnetic reluctance";
  Modelica.Units.SI.Permeance G_m "Magnetic permeance";
  Modelica.Units.SI.ComplexMagneticFluxDensity B "Magnetic flux density (normal component)";
  Modelica.Units.SI.MagneticFluxDensity abs_B = Modelica.ComplexMath.abs(B) "Magnitude of complex magnetic flux density";
  Modelica.Units.SI.Angle arg_B = Modelica.ComplexMath.arg(B) "Argument of complex magnetic flux density";
  Modelica.Units.SI.CrossSection A "Area of cross section penetrated by magnetic flux";
  Modelica.Units.SI.ComplexMagneticFieldStrength H "Magnetic field strength (normal component)";
  Modelica.Units.SI.MagneticFieldStrength abs_H = Modelica.ComplexMath.abs(H) "Magnitude of complex magnetic field strength";
  Modelica.Units.SI.Angle arg_H = Modelica.ComplexMath.arg(H) "Argument of complex magnetic field strength";
  Modelica.Units.SI.RelativePermeability mu_r "Relative magnetic permeability";
equation
  mu_r = mu_rConst;
  R_m = 1 / G_m;
  V_m = Phi * R_m;
  B = Phi / A;
  H = B / (mu_0 * mu_r);

end FixedShape;

