  output Modelica.Units.SI.Angle phi = Modelica.Math.wrapAngle(phi_v - phi_i, positiveRange) "Angle between voltage and current";
  output Modelica.Units.SI.Angle epsilon = Modelica.Math.wrapAngle(phi - theta, positiveRange) "Current angle";
  parameter Modelica.Electrical.Machines.Utilities.ParameterRecords.SM_PermanentMagnetData smpmData(useDamperCage = false, effectiveStatorTurns = 64, fsNominal = fNominal, Lmd = 0.1 / (2 * pi * fNominal), Lmq = 0.3 / (2 * pi * fNominal), TsRef = 373.15) "Synchronous machine data" ;
