Code:
model EddyCurrent "Constant loss model under sinusoidal magnetic conditions"
  import Modelica.Constants.pi;
  constant Complex j = Complex(0, 1);
  extends Modelica.Magnetic.QuasiStatic.FundamentalWave.Interfaces.TwoPort;
  parameter Modelica.Units.SI.Conductance G(min = 0) "Equivalent symmetric loss conductance";
  extends Modelica.Thermal.HeatTransfer.Interfaces.PartialElementaryConditionalHeatPort(final T = 273.15);
  Modelica.Units.SI.AngularVelocity omega = der(port_p.reference.gamma) "Angular velocity";
equation
  lossPower = pi / 2 * Modelica.ComplexMath.imag(omega * V_m * Modelica.ComplexMath.conj(Phi));
  // Alternative calculation of loss power
  // lossPower = -(pi/2)*Modelica.ComplexMath.real(j*omega*V_m*Modelica.ComplexMath.conj(Phi));
  if G > 0 then
    pi / 2 * V_m = j * omega * G * Phi;
  else
    V_m = Complex(0, 0);
  end if;

end EddyCurrent;

