  Modelica.Units.SI.ActivePower P_total = sum(P) "Total active power";
  Modelica.Units.SI.ReactivePower Q[m] = array(Modelica.ComplexMath.imag(v[k] * Modelica.ComplexMath.conj(i[k])) for k in 1:m) "Reactive power";
  Modelica.Units.SI.ReactivePower Q_total = sum(Q) "Total reactive power";
  Modelica.Units.SI.ApparentPower S[m] = array(Modelica.ComplexMath.abs(v[k] * Modelica.ComplexMath.conj(i[k])) for k in 1:m) "Magnitude of complex apparent power";
  Modelica.Units.SI.ApparentPower S_total = sqrt(P_total ^ 2 + Q_total ^ 2) "Magnitude of total complex apparent power";
  Real pf[m] = array(cos(Modelica.ComplexMath.arg(Complex(P[k], Q[k]))) for k in 1:m) "Power factor";
  // Local electromagnetic fundamental wave quantities
  Modelica.Units.SI.ComplexMagneticPotentialDifference V_m "Complex magnetic potential difference";
  Modelica.Units.SI.MagneticPotentialDifference abs_V_m = Modelica.ComplexMath.abs(V_m) "Magnitude of complex magnetic potential difference";
  Modelica.Units.SI.Angle arg_V_m = Modelica.ComplexMath.arg(V_m) "Argument of complex magnetic potential difference";
  Modelica.Units.SI.ComplexMagneticFlux Phi "Complex magnetic flux";
  Modelica.Units.SI.MagneticPotentialDifference abs_Phi = Modelica.ComplexMath.abs(Phi) "Magnitude of complex magnetic flux";
  Modelica.Units.SI.Angle arg_Phi = Modelica.ComplexMath.arg(Phi) "Argument of complex magnetic flux";
  Modelica.Units.SI.AngularVelocity omega = der(port_p.reference.gamma);
  // A technical solution with a rotator cannot be applied to the equations below
  final parameter Complex N = effectiveTurns * Modelica.ComplexMath.exp(Complex(0, orientation)) "Complex effective number of turns";
  Modelica.Units.SI.ComplexVoltage vSymmetricalComponent[m] "Symmetrical components of voltages";
  Modelica.Units.SI.ComplexCurrent iSymmetricalComponent[m] "Symmetrical components of currents";
protected
  final parameter Complex sTM[m, m] = Modelica.Electrical.Polyphase.Functions.symmetricTransformationMatrix(m);
  final parameter Integer indexNonPos[:] = Modelica.Electrical.Polyphase.Functions.indexNonPositiveSequence(m) "Indices of all non positive sequence components";
  final parameter Integer indexPos[:] = Modelica.Electrical.Polyphase.Functions.indexPositiveSequence(m) "Indices of all positive sequence components";
equation
  // Symmetrical components (preferred): vSymmetricalComponent = sTM*v; iSymmetricalComponent = sTM*i;
  for j in 1:m loop
    vSymmetricalComponent[j] = Complex(sum(array(sTM[j, k].re * v[k].re - sTM[j, k].im * v[k].im for k in 1:m)), sum(array(sTM[j, k].re * v[k].im + sTM[j, k].im * v[k].re for k in 1:m)));
    iSymmetricalComponent[j] = Complex(sum(array(sTM[j, k].re * i[k].re - sTM[j, k].im * i[k].im for k in 1:m)), sum(array(sTM[j, k].re * i[k].im + sTM[j, k].im * i[k].re for k in 1:m)));
  end for;
  // Magnetic flux and flux balance of the magnetic ports
  port_p.Phi = Phi;
  port_p.Phi + port_n.Phi = Complex(0, 0);
  // Magnetic potential difference of the magnetic ports
  port_p.V_m - port_n.V_m = V_m;
  // Voltage drop between the electrical plugs
  v = plug_p.pin.v - plug_n.pin.v;
  // Current and current balance of the electric plugs
  i = plug_p.pin.i;
  plug_p.pin.i + plug_n.pin.i = array(Complex(0, 0) for k in 1:m);
  V_m.re = sqrt(2) * (2.0 / pi) * Modelica.ComplexMath.real(N * iSymmetricalComponent[1]) * m / 2;
  V_m.im = sqrt(2) * (2.0 / pi) * Modelica.ComplexMath.imag(N * iSymmetricalComponent[1]) * m / 2;
  for k in 1:size(indexNonPos, 1) loop
    iSymmetricalComponent[indexNonPos[k]] = Complex(0, 0);
  end for;
  for k in 2:size(indexPos, 1) loop
    vSymmetricalComponent[indexPos[1]] = vSymmetricalComponent[indexPos[k]];
  end for;
  // Induced voltages from complex magnetic flux, number of turns
  // and angles of orientation of winding
  -sqrt(2) * Complex(Modelica.ComplexMath.real(vSymmetricalComponent[indexPos[1]]), Modelica.ComplexMath.imag(vSymmetricalComponent[indexPos[1]])) = Modelica.ComplexMath.conj(N) * j * omega * Phi;
  // Potential roots are not used; instead the reference angle is handled
  // by means of Connections.branch between electric plug_p and magnetic port_p
  // It has to be checked whether this Modelica compliant
  //   Connections.potentialRoot(plug_p.reference);
  //   Connections.potentialRoot(port_p.reference);
  Connections.branch(port_p.reference, port_n.reference);
  port_p.reference.gamma = port_n.reference.gamma;
  Connections.branch(plug_p.reference, plug_n.reference);
  plug_p.reference.gamma = plug_n.reference.gamma;
  Connections.branch(plug_p.reference, port_p.reference);
  plug_p.reference.gamma = port_p.reference.gamma;

end PolyphaseElectroMagneticConverter;

